                ],
                "pronunciationAudios": [
                    {
                        "gender": "female",
                        "pronunciation": "\u305f\u3044\u3057\u305f",
                        "voiceActorId": 1,
                        "voiceActorName": "Kyoko",
                        "voiceDescription": "Tokyo accent",
                        "file": "27949-subject-2501.ogg"
                    },
                    {
                        "gender": "male",
                        "pronunciation": "\u305f\u3044\u3057\u305f",
                        "voiceActorId": 2,
                        "voiceActorName": "Kenichi",
                        "voiceDescription": "Tokyo accent",
                        "file": "2955-subject-2501.ogg"
                    }
                ],
                "mnemonic": "\n{splitParent}The reading for the {span:lang=ja:\u5927} part is actually the on'yomi reading you learned when learning its kanji. So, as long as you remember that (and remember to use that reading), you can read this word as well. {span:lang=ja:\u5927\u3057\u305f} = {span:lang=ja:\u305f\u3044\u3057\u305f}.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u305d\u308c\u306f\u5927\u3057\u305f\u3053\u3068\u306f\u306a\u3044\u3002",
                    "en": "It\u2019s not a big deal."
                },
                {
                    "ja": "\u307e\u3063\u305f\u304f\u5927\u3057\u305f\u5973\u3060\u3088\u3002",
                    "en": "She is such a great woman."
                },
                {
                    "ja": "\u30de\u30af\u30c9\u30ca\u30eb\u30c9\u306e\u3057\u3083\u3061\u3087\u3046\u306b\u306a\u308c\u308c\u3070\u5927\u3057\u305f\u3082\u306e\u3060\u3002",
                    "en": "Being the president of McDonald\u2019s would be a big deal."
                }
            ],
            "collocations": []
        }

{
            "mnemonic": "A vocab made of a single kanji all alone with no okurigana (hiragana attached to the kanji) usually has the same exact meaning as the kanji it's made from. So by that you know that this vocab's meaning is {tooltip:Vocabulary:mountain}.",
            "hints": "",
            "meanings": {
