                ],
                "pronunciationAudios": [
                    {
                        "gender": "male",
                        "pronunciation": "\u3084\u307e",
                        "voiceActorId": 2,
                        "voiceActorName": "Kenichi",
                        "voiceDescription": "Tokyo accent",
