                {
                    "ja": "\u30c6\u30ec\u30d3\u306e\u5927\u304d\u3055\u306f\u4e09\u5341\u4e8c\u30a4\u30f3\u30c1\u3067\u3059\u3002",
                    "en": "The size of the TV is 32 inches."
                },
                {
