                "mnemonic": "To remember the reading for this kanji, we use the word {tooltip:Reading:Chew}bacca to pull up {span:lang=ja:\u3061\u3085\u3046} in our memory. "
            }
        }

{
            "mnemonic": "The {tooltip:Kanji:moon} kanji is made up of the {tooltip:Radical:moon} radical.",
            "hints": "This should be EZPZ as long as you know the radicals already!",
            "meanings": {
                "Primary": "Moon",
                "Alternative": "Month"
            },
            "kanjiReadings": {
                "readings": [
