                        "reading": "\u308d\u304f",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u3080",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Sing along with the monster, if it helps you to remember the reading of this kanji.",
                "mnemonic": "Whenever we need to remember the reading {span:lang=ja:\u308d\u304f} we just use the word {tooltip:Reading:rock}. "
            }
        }

{
