                    }
                ],
                "mnemonic": "\n{splitParent}This is a jukugo word, which usually means on'yomi readings from the kanji. That is true with this word as well. Make sure to take note that {span:lang=ja:\u6708} is using the {span:lang=ja:\u304c\u3064} reading and not the {span:lang=ja:\u3052\u3064} one. This is true for all \"month words\" in Japanese.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u4e8c\u6708\u4e09\u65e5\u306b\u3051\u3063\u3053\u3093\u3057\u307e\u3057\u305f\u3002",
                    "en": "I got married on February third."
                },
                {
                    "ja": "\u4e8c\u6708\u306f\u3001\u65e5\u672c\u3044\u304d\u306e\u30c1\u30b1\u30c3\u30c8\u304c\u3068\u3066\u3082\u3084\u3059\u3044\u3067\u3059\u3002",
                    "en": "In February, air tickets to Japan are very cheap."
                },
                {
                    "ja": "\u304d\u3087\u306d\u3093\u306e\u4e8c\u6708\u306b\u3001\u308f\u305f\u3057\u305f\u3061\u306e\u3075\u308a\u3093\u306f\u306f\u3058\u307e\u3063\u305f\u306e\u3002",
                    "en": "Our affair began in February of last year."
                }
            ],
            "collocations": []
        }

{
