            },
            "contextSentences": [
                {
                    "ja": "\u30c8\u30e0\u3055\u3093\u306f\u3001\u30b3\u30f3\u30d3\u30cb\u3067\u304a\u306b\u304e\u308a\u3092\u4e94\u3053\u304b\u3044\u307e\u3057\u305f\u3002",
                    "en": "Tom bought five onigiri at the convenience store."
                },
                {
                    "ja": "\u308f\u305f\u3057\u306e\u3068\u3082\u3060\u3061\u306f\u3057\u3087\u3046\u308f\u4e94\u5341\u4e94\u306d\u3093\u4e94\u6708\u3044\u3064\u304b\u3046\u307e\u308c\u3067\u3059\u3002",
                    "en": "My friend was born on May 5th in the 55th year of Showa."
                },
                {
                    "ja": "\u3080\u304b\u3057\u3080\u304b\u3057\u3001\u4e94\u3072\u304d\u306e\u5b50\u3076\u305f\u3092\u3046\u3093\u3060\u306f\u306f\u3076\u305f\u304c\u3044\u307e\u3057\u305f\u3002",
                    "en": "Once upon a time, there was a mother pig with five baby pigs."
                }
