            "meanings": {
                "Primary": "Five Things",
                "Word Type": "numeral"
            },
            "vocabReadings": {
                "readings": [
                    {
                        "primary": true,
                        "reading": "\u3044\u3064\u3064"
                    }
                ],
                "pronunciationAudios": [
                    {
