                    }
                ],
                "mnemonic": "\n{splitParent}The reading of this word is the kun'yomi reading of the kanji {tooltip:Kanji:\u4e94}, meaning you didn't learn it when you learned the parent kanji reading. To remember this word, think of it this way:\n{splitParent}You have {tooltip:Vocabulary:five things}. What do you have to do with them? You need to {tooltip:Reading:eat} ({span:lang=ja:\u3044\u3064}) them. If you come up with something crazy you have to eat, and focus on the fact that you must eat five of these things, it will help a lot too.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u308f\u305f\u3057\u306f\u4e94\u3064\u3082\u304a\u3082\u3061\u3092\u305f\u3079\u307e\u3057\u305f\u3002",
