{
            "mnemonic": "This vocab word has the same meaning as its parent kanji (single alone kanji usually do that!), meaning it means {tooltip:Vocabulary:four}.",
            "hints": "",
            "meanings": {
                "Primary": "Four",
                "Word Type": "numeral"
            },
            "vocabReadings": {
                "readings": [
                    {
                        "primary": true,
                        "reading": "\u3088\u3093"
                    },
                    {
                        "primary": false,
                        "reading": "\u3057"
