            },
            "contextSentences": [
                {
                    "ja": "\u308f\u305f\u3057\u306f\u4e00\u6708\u306b\u304b\u3093\u3058\u3092\u5343\u3053\u304a\u307c\u3048\u307e\u3057\u305f\u3002",
