                        "pronunciation": "\u3064\u304d",
                        "voiceActorId": 1,
                        "voiceActorName": "Kyoko",
                        "voiceDescription": "Tokyo accent",
                        "file": "30492-subject-2542.ogg"
                    },
                    {
                        "gender": "male",
