                ],
                "mnemonic": "\n{splitParent}Since this word is made up of a single kanji, it should use the kun'yomi reading. When you learned the kanji that makes up this word, all you learned was the kun'yomi reading, so you should be good to go.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u3042\u3057\u305f\u306f\u304b\u305e\u304f\u307f\u3093\u306a\u3067\u7530\u3092\u305f\u304c\u3084\u3057\u307e\u3059\u3002",
                    "en": "Tomorrow we\u2019re tilling the rice field with the whole family."
                },
                {
                    "ja": "\u305d\u306e\u30d5\u30e9\u30f3\u30b9\u4eba\u306f\u56db\u5341\u30e6\u30fc\u30ed\u3067\u7530\u3092\u4e00\u3064\u304b\u3044\u307e\u3057\u305f\u3002",
                    "en": "That French person purchased a rice field for 40 euros."
                },
                {
                    "ja": "\u308f\u305f\u3057\u306e\u30d5\u30a1\u30fc\u30b9\u30c8\u30ad\u30b9\u306f\u3001\u7530\u3093\u307c\u306e\u304b\u304b\u3057\u306b\u3046\u3070\u308f\u308c\u305f\u3002",
                    "en": "My first kiss was stolen by a scarecrow in a rice paddy."
                }
            ],
            "collocations": []
