                    }
                ],
                "mnemonic": "\n{splitParent}Words that count days use an exceptional reading. Even though this is a jukugo word, it uses kun'yomi readings for both the kanji. Think about this word this way:\n{splitParent}You've been stuck inside working for {tooltip:Vocabulary:seven days} and today you finally have a day off. Your friend asks you if you want to go for a drive but you say, \"{tooltip:Reading:Nah, no car} today\" ({span:lang=ja:\u306a\u306e\u304b}), because you've been cooped up long enough. Seven days is too long to be inside.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u304b\u305c\u3067\u3001\u4e03\u65e5\u304b\u3093\u3082\u306d\u3053\u3093\u3067\u3044\u307e\u3057\u305f\u3002",
                    "en": "I was in bed for seven whole days because of a cold."
                },
                {
                    "ja": "\u307e\u3044\u6708\u4e03\u65e5\u306b\u3001\u304a\u306f\u304b\u307e\u3044\u308a\u3092\u3057\u307e\u3059\u3002",
                    "en": "I visit our family grave on the 7th of every month."
                },
                {
                    "ja": "\u305f\u3063\u305f\u4e03\u65e5\u3067\u304b\u3044\u3057\u3083\u3092\u3084\u3081\u305f\u3002",
                    "en": "I left the company after only seven days."
                }
            ],
            "collocations": []
        }

