            "contextSentences": [
                {
                    "ja": "\u5c71\u672c\u3055\u3093\u306e\u3067\u3093\u308f\u3070\u3093\u3054\u3046\u306f\u3001\u516d\u4e00\u4e8c\u306e\u4e03\u4e03\u4e09\u516d\u3067\u3059\u306d\uff1f",
                    "en": "Is Yamamoto\u2019s phone number 612-7736?"
                },
                {
                    "ja": "\u516d\u3058\u306b\u3075\u3058\u5c71\u3067\u3042\u3044\u307e\u3057\u3087\u3046\u3002",
                    "en": "Let's meet at Mt. Fuji at six o'clock."
