                    }
                ],
                "mnemonic": "\n{splitParent}Words that count days use an exceptional reading. Even though this is a jukugo word, it uses kun'yomi readings for both the kanji. Think about this word this way:\n{splitParent}{tooltip:Vocabulary:Ten days} is just {tooltip:Reading:TOO} ({span:lang=ja:\u3068\u304a}) long from now. Why do you have to wait until the {tooltip:Vocabulary:tenth day}? Maybe fewer would have been okay, but ten is too many.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u3053\u306e\u304f\u3059\u308a\u3092\u3001\u5341\u65e5\u304b\u3093\u306e\u3093\u3067\u304f\u3060\u3055\u3044\u3002",
                    "en": "Please take this medicine for ten days."
                },
                {
                    "ja": "\u5341\u65e5\u3067\u304b\u3093\u305b\u3044\u3055\u305b\u3066\u304f\u3060\u3055\u3044\u3002",
                    "en": "Please complete it within ten days."
