                },
                {
                    "ja": "\u30b5\u30b1\u304c\u5ddd\u3092\u4e0a\u3063\u3066\u3044\u308b\u306e\u3092\u307f\u305f\u3002",
                    "en": "I saw a salmon swimming upstream."
                }
            ],
            "collocations": []
        }

