                    "ja": "\u738b\u5b50\u306f\u307e\u3061\u304c\u3044\u3092\u6b63\u3055\u308c\u3066\u30d7\u30e9\u30a4\u30c9\u304c\u304d\u305a\u3064\u3044\u305f\u3002",
