{
            "mnemonic": "Think of someone holding out their hand at shoulder level. Anything above that equals \"skillful.\" Everything below that equals \"{tooltip:Reading:unskillful}. So, in the case of this word, \"below hand\" means \"unskillful.\"",
            "hints": "",
            "meanings": {
                "Primary": "Unskillful",
                "Alternatives": "Unskilled, Bad At, Not Good At, Not Skilled",
                "Word Type": "noun, \u306a adjective"
            },
            "vocabReadings": {
                "readings": [
                    {
                        "primary": true,
                        "reading": "\u3078\u305f"
                    }
                ],
                "pronunciationAudios": [
                    {
