                    }
                ],
                "mnemonic": "\n{splitParent}Since this word is made up of a single kanji, it should use the kun'yomi reading. When learning the kanji, you didn't learn that reading, so here's a mnemonic to help you with this word: \n{splitParent}Be sure you always carry water when visiting the {tooltip:Reading:me zoo} ({span:lang=ja:\u307f\u305a}). That's a zoo with rows and rows of cages of... me. And I'm thirsty!\n"
            },
            "contextSentences": [
                {
                    "ja": "\u6c34\u304b\u304a\u3061\u3083\u3092\u3082\u3089\u3048\u307e\u3059\u304b\u3002",
                    "en": "Can I have some water or tea?"
                },
                {
                    "ja": "\u3075\u3058\u5c71\u306b\u306e\u307c\u308b\u3068\u304d\u306f\u3001\u6c34\u3092\u308f\u3059\u308c\u306a\u3044\u3088\u3046\u306b\u3057\u307e\u3057\u3087\u3046\u3002",
                    "en": "Don't forget to bring water when you climb Mt. Fuji."
                },
                {
                    "ja": "\u30b3\u30c3\u30d7\u4e00\u3071\u3044\u306e\u6c34\u3068\u3042\u3044\u3092\u304f\u3060\u3055\u3044\u3002",
                    "en": "Give me a cup of water and some love, please."
                }
            ],
            "collocations": []
        }

{
