                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "None",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Watch in horror as Godzilla's giant foot crushes all the kids and their slide at exactly noon. You'd better go...",
                "mnemonic": "{tooltip:Kanji:Noon} also happens to be the time {tooltip:Reading:Go}dzilla ({span:lang=ja:\u3054}) decided to attack for the same reasons: it's dry and kids are using the slide."
            }
        }

{
            "mnemonic": "Balance a {tooltip:Radical:spoon} on your pointed {tooltip:Radical:fingers} and it will always point {tooltip:Kanji:north}. The spoon is like a compass needle and your fingers guide the knowledge your body already has and uses it to point north. That's science, friends!",
            "hints": "Imagine taking a spoon and balancing it on your fingers. Now watch the spoon spin spin spin until it stops and ultimately points north.",
            "meanings": {
                "Primary": "North"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u307b\u304f",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u304d\u305f",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Imagine walking out of a pawn shop after hocking your fingers and spoon and realizing that you don't know where you are. Oh, if only you could tell where north was...",
                "mnemonic": "You realize that this ability to find {tooltip:Kanji:north} is probably really valuable, so you go to the nearest pawn shop and {tooltip:Reading:hock} ({span:lang=ja:\u307b\u304f}) it. Even your fingers."
            }
        }

{
            "mnemonic": "The kanji and the radical are the same, so remembering the meaning of this kanji is as simple as making sure you know the radical for {tooltip:Radical:now} first! If you know the radical, you know this kanji means {tooltip:Kanji:now} as well.",
            "hints": "Make sure you know those radicals, yo!",
            "meanings": {
                "Primary": "Now"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u3053\u3093",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u3044\u307e",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Go outside right now and do something to save the condors. If you don't do something right now there won't be enough time left!",
                "mnemonic": "Right {tooltip:Kanji:now} the {tooltip:Reading:con}dors ({span:lang=ja:\u3053\u3093}) are in danger! Not next week, not next year, right now! Haven't you heard that deforestation and pollution are killing all of the condors?!"
            }
        }

{
            "mnemonic": "The kanji and the radical are the same, so remembering the meaning of this kanji is as simple as making sure you know the radical for {tooltip:Radical:old} first! If you know the radical, you know this kanji means {tooltip:Kanji:old} as well.",
            "hints": "Make sure you know those radicals, yo!",
            "meanings": {
                "Primary": "Old"
            },
            "kanjiReadings": {
                "readings": [
                    {
