                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u3075\u308b",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Imagine a {span:lang=ja:\u5b50} looking at old things. A record player. A gameboy. A cassette player. Kids just don't get old things.{splitParent}Note: When you see the ({span:lang=ja:\u53e4}) radical in a kanji, there's a good chance it will use the reading {span:lang=ja:\u3053}.",
                "mnemonic": "{tooltip:Kanji:Old} things are misunderstood by the {span:lang=ja:\u5b50}s ({span:lang=ja:\u3053}) of the world."
            }
        }

{
            "mnemonic": "The {tooltip:Radical:origin} radical and the {tooltip:Kanji:origin} kanji are the same!",
            "hints": "Know your radicals!",
            "meanings": {
                "Primary": "Origin"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u3052\u3093, \u304c\u3093",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u3082\u3068",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
