                    "ja": "\u304d\u3087\u3046\u3068\u306e\u5e02\u30d0\u30b9\u306e\u4e2d\u3067\u3001\u306f\u3044\u3066\u3057\u307e\u3063\u305f\u3002",
                    "en": "I puked on a Kyoto city bus."
                }
            ],
            "collocations": []
        }

{
            "mnemonic": "The kanji and the word are the same. This word is a bit broader than {tooltip:Vocabulary:cow} though, and can also be used to be {tooltip:Vocabulary:bull} and {tooltip:Vocabulary:ox}.",
            "hints": "",
            "meanings": {
                "Primary": "Cow",
                "Alternatives": "Bull, Ox",
                "Word Type": "noun"
            },
            "vocabReadings": {
                "readings": [
                    {
                        "primary": true,
                        "reading": "\u3046\u3057"
                    }
                ],
                "pronunciationAudios": [
                    {
                        "gender": "male",
                        "pronunciation": "\u3046\u3057",
                        "voiceActorId": 2,
                        "voiceActorName": "Kenichi",
                        "voiceDescription": "Tokyo accent",
