                    }
                ],
                "mnemonic": "\n{splitParent}This is the kun'yomi reading of the kanji (because it's a single kanji, all alone with hiragana attached). The part you have to remember is the {span:lang=ja:\u3075\u3068} portion. Let's use a mnemonic. \n{splitParent}The {tooltip:Vocabulary:fat} guy looked down and couldn't see his {tooltip:Reading:foot} ({span:lang=ja:\u3075\u3068}).\n"
            },
            "contextSentences": [
                {
                    "ja": "\u5c71\u7530\u3055\u3093\u306e\u307e\u3086\u3052\u306f\u3068\u3066\u3082\u592a\u3044\u3067\u3059\u3002",
