                {
                    "ja": "\u3053\u306e\u304a\u307f\u305b\u306e\u3081\u3093\u306f\u304a\u3082\u3063\u305f\u3088\u308a\u592a\u304b\u3063\u305f\u3067\u3059\u3002",
                    "en": "This shop's noodles are thicker than I expected."
                },
                {
                    "ja": "\u304a\u308c\u306e\u6bcd\u3061\u3083\u3093\u306f\u3001\u3061\u3087\u3046\u592a\u3044\u3093\u3060\u305c\u3002",
                    "en": "My mom is so fat."
                }
            ],
