                "mnemonic": "\n{splitParent}The reading for this word is the same as the one you learned when learning the kanji.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u7236\u304c\u3044\u308b\u304b\u3089\u3001\u3055\u3073\u3057\u304f\u3042\u308a\u307e\u305b\u3093\u3002",
                    "en": "I\u2019m not lonely because my father is here."
