                {
                    "ja": "\u308f\u305f\u3057\u306e\u7236\u306f\u3001\u30c9\u30a4\u30c4\u4eba\u3067\u3059\u3002",
                    "en": "My father is German."
                },
                {
                    "ja": "\u7236\u306f\u3046\u3057\u306e\u3061\u3061\u3092\u3057\u307c\u308b\u306e\u304c\u3046\u307e\u3044\u3002",
                    "en": "My father is very good at milking cows."
                }
            ],
