                    "ja": "\u5927\u5207\u306a\u3057\u3087\u308b\u3044\u3068\u304d\u304f\u3068\u3001\u3044\u3064\u3082\u4e2d\u307f\u3092\u307f\u305f\u304f\u306a\u308b\u3002",
