                        "voiceDescription": "Tokyo accent",
                        "file": "32852-subject-2639.ogg"
                    }
                ],
                "mnemonic": "\n{splitParent}The reading is the kun'yomi reading, but this is the reading you learned with the kanji. Just remember, your {tooltip:Vocabulary:mother} is a terrible person and won't stop laughing at you: \"{tooltip:Reading:HA HA} HA HA HA!\"\n"
            },
            "contextSentences": [
                {
                    "ja": "\u6bcd\u306f\u30bf\u30af\u30b7\u30fc\u306b\u306e\u308a\u307e\u3057\u305f\u3002",
