            "contextSentences": [
                {
                    "ja": "\u305d\u307c\u306f\u5e02\u7acb\u3073\u3087\u3046\u3044\u3093\u306b\u5165\u3044\u3093\u3057\u3066\u3044\u307e\u3059\u3002",
                    "en": "My grandmother is hospitalized at the municipal hospital."
                },
                {
                    "ja": "\u5e02\u7acb\u3068\u3057\u3087\u304b\u3093\u307e\u3067\u306e\u307f\u3061\u3092\u304a\u3057\u3048\u3066\u304f\u3060\u3055\u3044\u3002",
                    "en": "Please tell me the direction to the municipal library."
