                ],
                "mnemonic": "\n{splitParent}The reading is the {span:lang=ja:\u306b\u3093} reading of this kanji. Just think of a {tooltip:Vocabulary:number of people}, all {tooltip:Reading:nin}jas, standing there as you count them out.\n"
            },
            "contextSentences": [
