                },
                {
                    "ja": "\u308f\u305f\u3057\u306f\u4e09\u4eba\u5b50\u3069\u3082\u304c\u3044\u307e\u3059\u3002",
                    "en": "I have three children."
                }
            ],
            "collocations": []
        }

