                        "reading": "\u30c6\u30fc\u30d6\u30eb\u306e\u3046\u3048"
                    }
                ],
                "pronunciationAudios": [
                    {
                        "gender": "female",
                        "pronunciation": "\u3066\u30fc\u3076\u308b\u306e\u3046\u3048",
                        "voiceActorId": 1,
                        "voiceActorName": "Kyoko",
                        "voiceDescription": "Tokyo accent",
                        "file": "44543-subject-8959.ogg"
                    },
                    {
                        "gender": "male",
                        "pronunciation": "\u3066\u30fc\u3076\u308b\u306e\u3046\u3048",
