                        "voiceActorName": "Kenichi",
                        "voiceDescription": "Tokyo accent",
                        "file": "44131-subject-8959.ogg"
                    }
                ],
                "mnemonic": "\n{splitParent}In this phrase, {span:lang=ja:\u4e0a} is a standalone word, so it uses the same reading that you learned when you learned the vocabulary. Easy to stay on top of that one, right?\n"
            },
            "contextSentences": [
                {
                    "ja": "\u672c\u306f\u30c6\u30fc\u30d6\u30eb\u306e\u4e0a\u306b\u3042\u308a\u307e\u3059\u3002",
                    "en": "The book is on the table."
                },
                {
                    "ja": "\u30c6\u30fc\u30d6\u30eb\u306e\u4e0a\u306b\u30b0\u30e9\u30b9\u3092\u4e09\u3064\u304a\u3044\u3066\u304f\u3060\u3055\u3044\u3002",
                    "en": "Please put three glasses on the table."
                },
                {
                    "ja": "\u3055\u3063\u304d\u3001\u30c6\u30fc\u30d6\u30eb\u306e\u4e0a\u3092\u304d\u308c\u3044\u306b\u3057\u305f\u3088\u3002",
                    "en": "I cleaned the table earlier."
                }
            ],
            "collocations": []
        }

