                },
                {
                    "ja": "\u3042\u3061\u3089\u306e\u65b9\u306b\u884c\u3063\u3066\u304f\u3060\u3055\u3044 \u3002",
                    "en": "Please go that direction."
                },
                {
                    "ja": "\u304b\u306e\u5973\u306e\u308f\u3089\u3044\u65b9\u304c\u304d\u3089\u3044\u3060\u3002",
                    "en": "I don\u2019t like the way she laughs."
                }
            ],
            "collocations": []
        }

{
