                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u304b\u3044",
                        "primary": true
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Imagine rowing your kayak out into the ocean to collect shellfish. Imagine the color and shape of the kayak. Feel the spray of the salt water and the taste of some fresh shellfish, right out of the ocean.",
                "mnemonic": "To get some {tooltip:Kanji:shellfish}, all you have to do is hop in your {tooltip:Reading:kay}ak ({span:lang=ja:\u304b\u3044}) and get some. Shellfish live in the water."
            }
        }

{
            "mnemonic": "The {tooltip:Radical:stone} radical and {tooltip:Kanji:stone} kanji are the same thing!",
            "hints": "Know your radicals and therefore know your kanji. It's just that simple.",
