                {
                    "ja": "\u305d\u3089\u304c\u3042\u304a\u3044\u306e\u306f\u3001\u3061\u304d\u3085\u3046\u306e\u5927\u6c17\u306e\u5206\u5b50\u304c\u3042\u304a\u3068\u307f\u3069\u308a\u306e\u3072\u304b\u308a\u3092\u3055\u3093\u3089\u3093\u3059\u308b\u304b\u3089\u3067\u3059\u3002",
