                    "ja": "\u3053\u306e\u304a\u306f\u3057\u306f\u7af9\u3067\u3067\u304d\u3066\u3044\u307e\u3059\u3002",
                    "en": "These chopsticks are made of bamboo."
                },
                {
                    "ja": "\u7af9\u306f\u3001\u4e00\u30e1\u30fc\u30c8\u30eb\u3050\u3089\u3044\u306e\u305f\u304b\u3055\u307e\u3067\u5207\u3063\u3066\u3057\u307e\u3046\u3068\u3001\u306d\u307e\u3067\u304b\u308c\u3066\u3057\u307e\u3044\u307e\u3059\u3002",
