                },
                {
                    "ja": "\u3060\u308c\u304b\u8eca\u51fa\u3057\u3066\u304f\u308c\u306a\u3044\u304b\u306a\uff1f",
                    "en": "I wonder if somebody could give us a ride."
                },
                {
                    "ja": "\u79c1\u306e\u8eca\u306f\u3001\u30d5\u30ed\u30ea\u30c0\u307e\u3067\u3082\u305f\u306a\u3044\u3060\u308d\u3046\u3002",
