                    "ja": "\u307e\u3060\u5c0f\u5b66\u4e00\u5e74\u751f\u304c\u5b66\u3076\u6f22\u5b57\u3067\u3059\u3089\u77e5\u308a\u307e\u305b\u3093\u3002",
