            "contextSentences": [
                {
                    "ja": "\u4e09\u6708\u307e\u3064\u307e\u3067\u306b\u3001\u304b\u3093\u5b57\u3092\u4e94\u767e\u3053\u304a\u307c\u3048\u3066\u304f\u3060\u3055\u3044\u3002",
