            "contextSentences": [
                {
                    "ja": "\u304d\u306e\u3046\u3001\u3054\u4e3b\u4eba\u3068\u3069\u3053\u304b\u3078\u3044\u304d\u307e\u3057\u305f\u304b\uff1f",
