            "contextSentences": [
                {
                    "ja": "\u4f11\u65e5\u306f\u3001\u3048\u3044\u304c\u3092\u898b\u308b\u3053\u3068\u304c\u304a\u304a\u3044\u3067\u3059\u3002",
                    "en": "I watched a bunch of movies over the holiday."
                },
                {
                    "ja": "\u305f\u306e\u3057\u3044\u4f11\u65e5\u3092\u3059\u3054\u3057\u3066\u304f\u3060\u3055\u3044\u306d\u3002",
