{
            "mnemonic": "You have only {tooltip:Kanji:one} {tooltip:Kanji:book} {tooltip:Kanji:energy}. No other books cross your mind. Only this one book. Why? Because you have such a {tooltip:Vocabulary:one track mind}.",
            "hints": "",
            "meanings": {
                "Primary": "One Track Mind",
                "Alternative": "Single Mindedness",
                "Word Type": "noun, \u306a adjective"
            },
            "vocabReadings": {
                "readings": [
                    {
                        "primary": true,
                        "reading": "\u3044\u3063\u307d\u3093\u304e"
                    }
                ],
                "pronunciationAudios": [
                    {
                        "gender": "male",
                        "pronunciation": "\u3044\u3063\u307d\u3093\u304e",
                        "voiceActorId": 2,
                        "voiceActorName": "Kenichi",
                        "voiceDescription": "Tokyo accent",
                        "file": "15374-subject-2679.ogg"
                    },
                    {
                        "gender": "female",
                        "pronunciation": "\u3044\u3063\u307d\u3093\u304e",
                        "voiceActorId": 1,
                        "voiceActorName": "Kyoko",
                        "voiceDescription": "Tokyo accent",
                        "file": "35271-subject-2679.ogg"
                    }
                ],
                "mnemonic": "\n{splitParent}The reading is based off the on'yomi readings for everything, though every reading is slightly altered. {span:lang=ja:\u3044\u3061} getting shortened to {span:lang=ja:\u3044\u3063}, {span:lang=ja:\u307b\u3093} changing to {span:lang=ja:\u307d\u3093}, and {span:lang=ja:\u304d} gets changed to {span:lang=ja:\u304e}. They're based off the readings you know already, though, so making this shift shouldn't be too hard... that is, unless you have an {span:lang=ja:\u4e00\u672c\u6c17}, ammiright?\n"
            },
            "contextSentences": [
                {
                    "ja": "\u304b\u308c\u306f\u3001\u3068\u3066\u3082\u4e00\u672c\u6c17\u306a\u305b\u3044\u304b\u304f\u3067\u3059\u3002",
                    "en": "He has a really single-minded personality."
                },
                {
                    "ja": "\u30e2\u30c6\u306a\u3044\u3060\u3093\u5b50\u306b\u306f\u3001\u3058\u3085\u3093\u3058\u3087\u3046\u3067\u4e00\u672c\u6c17\u306a\u304a\u3068\u3053\u304c\u304a\u304a\u3044\u6c17\u304c\u3059\u308b\u3002",
                    "en": "I feel that many men who are not popular among girls are naive and single-minded."
                },
                {
                    "ja": "\u4ffa\u306e\u89aa\u53cb\u306f\u3001\u3068\u3066\u3082\u4e00\u672c\u6c17\u306a\u7537\u3067\u300190\u6b73\u306b\u306a\u3063\u305f\u4eca\u3067\u3082\u521d\u604b\u306e\u5973\u3092\u601d\u3044\u7d9a\u3051\u3066\u3044\u308b\u3002",
                    "en": "My best friend has a one-track mind; he\u2019s 90 years old and still has feelings for his first love."
                }
            ],
            "collocations": []
        }

{
