            "contextSentences": [
                {
                    "ja": "\u308f\u305f\u3057\u306e\u5927\u3059\u304d\u306a\u30d0\u30f3\u30c9\u304c\u3001\u304b\u3064\u3069\u3046\u3092\u4f11\u6b62\u3057\u307e\u3057\u305f\u3002",
