            "contextSentences": [
                {
                    "ja": "\u304b\u304d\u6c37\u306f\u3001\u3042\u3064\u3044\u306a\u3064\u306b\u3088\u304f\u305f\u3079\u3089\u308c\u307e\u3059\u3002",
