                },
                {
                    "ja": "\u3053\u306e\u8d64\u3044\u30b7\u30ed\u30c3\u30d7\u304c\u304b\u304b\u3063\u305f\u304b\u304d\u6c37\u306f\u30c8\u30de\u30c8\u3042\u3058\u3067\u3059\u3002",
                    "en": "This shaved ice with red syrup is tomato flavored."
                },
                {
                    "ja": "\u4e16\u754c\u3067\u4e00\u756a\u3044\u3044\u6c17\u5206\u306b\u306a\u308b\u6642\u306f\u3001\u5acc\u3044\u306a\u3084\u3064\u306b\u51b7\u305f\u3044\u304b\u304d\u6c37\u3092\u3076\u3061\u307e\u3051\u3066\u3084\u3063\u305f\u6642\u3060\u3088\u3002",
