                    "ja": "\u5973\u306e\u5b50\u306f\u3001\u304a\u3053\u3063\u3066\u53e3\u3092\u4e00\u6587\u5b57\u306b\u3080\u3059\u3073\u307e\u3057\u305f\u3002",
