            "contextSentences": [
                {
                    "ja": "\u30b5\u30ef\u30fc\u30af\u30ea\u30fc\u30e0\u3092\u30e8\u30fc\u30b0\u30eb\u30c8\u3067\u4ee3\u7528\u3057\u307e\u3057\u305f\u3002",
