                    "en": "Hello? Hanako?"
                },
                {
                    "ja": "\u3042\u306e\u3001\u7533\u3057\u7533\u3057\uff1f\u304d\u3044\u3066\u3044\u307e\u3059\u304b\uff1f\uff1f\uff1f",
