                ],
                "mnemonic": "\n{splitParent}Since this word consists of a kanji with hiragana attached, you can bet that it will use the kun'yomi reading. You learned this reading when you learned {span:lang=ja:\u51fa\u308b}, so if you can remember that, you should be able to remember this one too!\n"
            },
            "contextSentences": [
                {
                    "ja": "\u6bcd\u306f\u3001\u30c7\u30d1\u30fc\u30c8\u3078\u304b\u3044\u3082\u306e\u306b\u51fa\u304b\u3051\u307e\u3057\u305f\u3002",
                    "en": "Mom went out shopping at the department store."
                },
                {
                    "ja": "\u304a\u3063\u3068\u304c\u5b50\u3069\u3082\u3092\u3064\u308c\u3066\u51fa\u304b\u3051\u305f\u306e\u3067\u3001\u4eca\u65e5\u306f\u30c9\u30e9\u30af\u30a8\u4e09\u307e\u3044\u3067\u3059\u3002",
                    "en": "Since my husband went out with kids, I can play Dragon Quest as much as I want."
                },
                {
                    "ja": "\u65e5\u66dc\u65e5\u306f\u5bb6\u65cf\u3067\u6d77\u306b\u51fa\u304b\u3051\u308b\u306e\u3002",
                    "en": "I\u2019m going out to the beach with my family on Sunday."
                }
