                },
                {
                    "ja": "\u4e00\u65e5\u3067\u4f11\u3080\u3053\u3068\u304c\u3067\u304d\u308b\u306e\u306f\u3001\u30c8\u30a4\u30ec\u306b\u5ea7\u3063\u3066\u3044\u308b\u6642\u3060\u3051\u3060\u3002",
