                {
                    "ja": "\u60b2\u89b3\u4e3b\u7fa9\u8005\u306f\u300c\u3082\u3046\u30b3\u30c3\u30d7\u534a\u5206\u3057\u304b\u306a\u3044\u300d\u3068\u8a00\u3046\u304c\u3001\u305d\u306e\u6751\u4eba\u306f\u300c\u304a\u304b\u308f\u308a\uff01\u300d\u3068\u8a00\u3063\u3066\u79c1\u3092\u9a5a\u304b\u305b\u305f\u3002",
