                {
                    "ja": "\u3056\u3093\u306d\u3093\u3060\u3051\u3069\u3001\u5e73\u65e5\u3060\u304b\u3089\u305f\u3076\u3093\u3044\u3051\u306a\u3044\u306a\u3041\u3002",
