                },
                {
                    "ja": "\u79c1\u306f\u6599\u7406\u4eba\u3067\u3001\u5e73\u65e5\u306f\u4ed5\u4e8b\u3067\u5fd9\u3057\u3044\u306e\u3067\u3001\u5bb6\u5ead\u3067\u306f\u3075\u3060\u3093\u6599\u7406\u3092\u3057\u307e\u305b\u3093\u3002",
