                {
                    "ja": "\u6697\u6bba\u8005\u306f\u5225\u306b\u3057\u3066\u3001\u30b9\u30ba\u30e1\u8702\u307b\u3069\u6016\u3044\u3082\u306e\u306f\u3053\u306e\u4e16\u306e\u4e2d\u306b\u306a\u3044\u3002",
                    "en": "Other than assassins, nothing in this world is scarier than wasps."
                }
            ],
