                    "ja": "\u3053\u306e\u306f\u3044\u3086\u3046\u306f\u3001\u4e07\u4eba\u306b\u4eba\u6c17\u304c\u3042\u308b\u3002",
                    "en": "That actor is popular with everyone."
                },
                {
                    "ja": "\u30bb\u30ad\u30bb\u30a4\u30a4\u30f3\u30b3\u306e\u306b\u304a\u3044\u306f\u4e07\u4eba\u306b\u3046\u3051\u308b\u306b\u304a\u3044\u3089\u3057\u3044\u3002",
