            "contextSentences": [
                {
                    "ja": "\u308f\u305f\u3057\u306f\u3001\u65e5\u672c\u306e\u8003\u53e4\u5b66\u306b\u304d\u3087\u3046\u307f\u304c\u3042\u308a\u307e\u3059\u3002",
