                {
                    "ja": "\u4eca\u6708\u672b\u3067\u3053\u306e\u8003\u53e4\u5b66\u306e\u3057\u3054\u3068\u3092\u3084\u3081\u308b\u3093\u3067\u3059\u3002",
                    "en": "I'm going to quit this archeology job at the end of the month."
