                {
                    "ja": "\u53bb\u5e74\u3001\u3048\u3044\u3053\u304f\u3055\u3093\u725b\u8089\u306e\u3086\u5165\u304c\u3055\u3044\u304b\u3044\u3055\u308c\u307e\u3057\u305f\u3002",
