                    "ja": "\u308f\u305f\u3057\u306f\u65e5\u672c\u4eba\u3067\u3059\u304c\u3001\u751f\u307e\u308c\u306f\u30b5\u30f3\u30d5\u30e9\u30f3\u30b7\u30b9\u30b3\u3067\u3059\u3002",
