                "mnemonic": "\n{splitParent}The most common reading for this word has the on'yomi reading for {span:lang=ja:\u6bce} plus the kun'yomi reading for {span:lang=ja:\u6708}. That makes it {span:lang=ja:\u307e\u3044\u3064\u304d}. But it can be read {span:lang=ja:\u307e\u3044\u3052\u3064} using both on'yomi readings too. You can use either!\n"
            },
            "contextSentences": [
                {
                    "ja": "\u3046\u3061\u306e\u5b66\u3053\u3046\u3067\u306f\u3001\u6bce\u6708\u30c6\u30b9\u30c8\u304c\u3042\u308a\u307e\u3059\u3002",
