            "contextSentences": [
                {
                    "ja": "\u5c0f\u3068\u308a\u306f\u3001\u7fbd\u3092\u30d1\u30bf\u30d1\u30bf\u3046\u3054\u304b\u3057\u307e\u3057\u305f\u3002",
