            "contextSentences": [
                {
                    "ja": "\u91d1\u306e\u30cd\u30c3\u30af\u30ec\u30b9\u3092\u30d7\u30ec\u30bc\u30f3\u30c8\u3057\u307e\u3057\u305f\u3002",
