            "contextSentences": [
                {
                    "ja": "\u307e\u3063\u305f\u304f\u76ae\u8089\u306a\u3082\u306e\u3067\u3059\u306d\u3002",
                    "en": "That\u2019s really ironic, isn\u2019t it?"
