                {
                    "ja": "\u3042\u306e\u8089\u3084\u3055\u3093\u306f\u3001\u5927\u3057\u305f\u76ae\u8089\u3084\u3060\u3088\u3002",
                    "en": "That butcher is a such a sarcastic person."
                },
                {
                    "ja": "\u300cIronic\u300d\u3068\u3044\u3046\u66f2\u306e\u4e2d\u306b\u3001\u3046\u307e\u3044\u76ae\u8089\u306f\u3072\u3068\u3064\u3082\u898b\u5f53\u305f\u3089\u306a\u304b\u3063\u305f\u3002",
