            "contextSentences": [
                {
                    "ja": "\u6587\u5b66\u3092\u3088\u3080\u3044\u307f\u3068\u306f\u4f55\u3060\u308d\u3046\u304b\u3002",
                    "en": "What\u2019s the significance of reading literature?"
                },
                {
                    "ja": "\u308f\u305f\u3057\u306f\u5927\u5b66\u3067\u3001\u30a4\u30ae\u30ea\u30b9\u6587\u5b66\u3092\u305b\u3093\u3053\u3046\u3057\u3066\u3044\u307e\u3057\u305f\u3002",
                    "en": "I was majoring in English literature in university."
                },
                {
                    "ja": "\u6751\u4e0a\u6625\u6a39\u306e\u4f5c\u54c1\u306f\u3001\u7d14\u6587\u5b66\u306e\u3075\u308a\u3092\u3057\u305f\u5927\u8846\u6587\u5b66\u3060\u3068\u601d\u3044\u307e\u3059\u3002",
