            "contextSentences": [
                {
                    "ja": "\u305d\u306e\u3088\u308b\u306f\u3001\u6708\u5149\u304c\u3068\u3066\u3082\u304d\u308c\u3044\u3067\u3057\u305f\u3002",
                    "en": "The moonlight was very beautiful that night."
                },
                {
                    "ja": "\u4e00\u308a\u3093\u306e\u767d\u3044\u82b1\u306b\u3001\u6708\u5149\u304c\u3055\u3048\u3056\u3048\u3068\u3075\u308a\u305d\u305d\u3044\u3067\u3044\u305f\u3002",
                    "en": "The bright moonlight was beaming down onto a white flower."
