                },
                {
                    "ja": "\u30d5\u30a7\u30a4\u30b9\u30d6\u30c3\u30af\u306e\u30a2\u30ab\u30a6\u30f3\u30c8\u3092\u3075\u304f\u3059\u3046\u4f5c\u308b\u65b9\u307b\u3046\u3092\u304a\u3057\u3048\u3066\u304f\u3060\u3055\u3044\u3002",
                    "en": "Can you teach me how to create multiple Facebook accounts, please?"
                },
                {
                    "ja": "\u30c6\u30b9\u30e9\u30fb\u30b3\u30a4\u30eb\u3092\u3069\u3046\u3084\u3063\u3066\u4f5c\u308b\u306e\u304b\u3092\u77e5\u3063\u3066\u3044\u305f\u3089\u826f\u304b\u3063\u305f\u3093\u3060\u3051\u3069\u306a\u3002",
