            "contextSentences": [
                {
                    "ja": "\u3073\u3087\u3046\u3044\u3093\u306e\u897f\u306e\u305f\u3066\u3082\u306e\u304c\u308f\u305f\u3057\u306e\u30a2\u30d1\u30fc\u30c8\u3067\u3059\u3002",
                    "en": "The building on the west side of the hospital is my apartment."
                },
                {
                    "ja": "\u30c0\u30ea\u30f3\u306f\u3001\u897f\u306b\u3080\u304b\u3063\u3066\u3044\u307e\u3059\u3002",
                    "en": "Darin is heading west."
