                {
                    "ja": "\u3046\u3093\u3061\u3092\u3059\u308b\u3068\u304d\u306b\u304a\u3057\u308a\u304b\u3089\u8840\u304c\u51fa\u308b\u306e\u306f\u306a\u305c\u306a\u3093\u3060\uff01",
