                        "file": "39619-subject-2717.ogg"
                    },
                    {
                        "gender": "male",
                        "pronunciation": "\u3057\u304b\u305f\u304c\u306a\u3044",
                        "voiceActorId": 2,
                        "voiceActorName": "Kenichi",
                        "voiceDescription": "Tokyo accent",
                        "file": "19715-subject-2717.ogg"
                    }
                ],
                "mnemonic": "\n{splitParent}The readings for the kanji portion are in line with the readings you learned with the individual kanji, so as long as you know those you should be able to read this word as well.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u304b\u308c\u304c\u304a\u3053\u308b\u306e\u306f\u3001\u4ed5\u65b9\u304c\u306a\u3044\u3088\u3002",
                    "en": "If he\u2019s angry, it can\u2019t be helped."
                },
                {
                    "ja": "\u6ce3\u3044\u3066\u3070\u304b\u308a\u3044\u3066\u3082\u4ed5\u65b9\u304c\u306a\u3044\u3088\u3002",
                    "en": "There's no use in just crying."
                },
                {
                    "ja": "\u304a\u524d\u306f\u672c\u5f53\u306b\u4ed5\u65b9\u304c\u306a\u3044\u3084\u3064\u3060\uff01",
                    "en": "You\u2019re really hopeless!"
                }
            ],
            "collocations": []
        }

{
            "mnemonic": "This is a single kanji with an {span:lang=ja:\u3044} on the end, meaning you know it's probably an adjective. What's the adjective form of {tooltip:Kanji:cheap}? It's also {tooltip:Vocabulary:cheap}. Time to go to a 100{span:lang=ja:\u5186} shop and get some {span:lang=ja:\u5b89\u3044} goods, ammiright?",
            "hints": "",
            "meanings": {
                "Primary": "Cheap",
                "Alternative": "Inexpensive",
                "Word Type": "\u3044 adjective"
            },
            "vocabReadings": {
                "readings": [
                    {
                        "primary": true,
                        "reading": "\u3084\u3059\u3044"
                    }
                ],
                "pronunciationAudios": [
