                        "file": "19690-subject-3439.ogg"
                    }
                ],
                "mnemonic": "\n{splitParent}Remember how body parts often change even jukugo words to kun'yomi readings? That's what happened here too. Both readings are kun'yomi, making this one {span:lang=ja:\u306f\u3084\u304f\u3061}. \n"
            },
            "contextSentences": [
                {
                    "ja": "\u308f\u305f\u3057\u306e\u5144\u306f\u3001\u3068\u3066\u3082\u65e9\u53e3\u3067\u3059\u3002",
                    "en": "My older brother is a really fast talker."
                },
                {
                    "ja": "\u304a\u524d\u306e\u3053\u3068\u304c\u4e00\u3070\u3093\u5927\u3059\u304d\u3060\u3088\u3063\u3066\u3001\u4f55\u3067\u305d\u3093\u306a\u306b\u65e9\u53e3\u3067\u8a00\u3063\u305f\u306e\uff1f",
                    "en": "Why did you say that you love me the most so quickly?"
                },
                {
                    "ja": "\u3053\u3093\u306a\u306b\u65e9\u53e3\u306e\u8d64\u3093\u574a\u306a\u3093\u3066\u898b\u305f\u3053\u3068\u306a\u3044\u3088\u3002",
