            "contextSentences": [
                {
                    "ja": "\u308f\u305f\u3057\u305f\u3061\u306f\u307e\u3060\u5916\u56fd\u306b\u884c\u3063\u305f\u3053\u3068\u304c\u3042\u308a\u307e\u305b\u3093\u3002",
