            "contextSentences": [
                {
                    "ja": "\u3068\u3046\u306a\u3093\u30a2\u30b8\u30a2\u3092\u3001\u56db\u5341\u4e8c\u65e5\u304b\u3093\u308a\u3087\u3053\u3046\u3057\u307e\u3057\u305f\u3002",
                    "en": "I took a forty-two day trip around Southeast Asia."
                },
                {
                    "ja": "\u30d5\u30e9\u30f3\u30b9\u4eba\u30b0\u30eb\u30e1\u306f\u4e94\u6708\u3060\u3051\u3067\u3055\u3089\u3046\u3069\u3093\u3092\u56db\u5341\u4e8c\u3055\u3089\u305f\u3079\u305f\u3002",
                    "en": "The French gourmet had 42 plates of Sara udon in May only."
                },
                {
                    "ja": "\u305d\u307c\u304c\u30c8\u30a4\u30ec\u30c3\u30c8\u30da\u30fc\u30d1\u30fc\u3092\u56db\u5341\u4e8c\u30ed\u30fc\u30eb\u3082\u304b\u3063\u3066\u304d\u305f\u3002",
                    "en": "My grandma bought forty-two rolls of toilet paper."
                }
