            "contextSentences": [
                {
                    "ja": "\u30e1\u30fc\u30ea\u30f3\u30b0\u30ea\u30b9\u30c8\u304b\u3089\u79c1\u3092\u5916\u3057\u3066\u304f\u3060\u3055\u3044\u3002",
                    "en": "Please remove me from your email list."
