                {
                    "ja": "\u79c1\u304c\u3048\u3044\u304e\u3087\u3046\u90e8\u306e\u305b\u304d\u306b\u3093\u8005\u3067\u3059\u3002",
                    "en": "I'm the director of the sales division."
