                "mnemonic": "\n{splitParent}This is a jukugo word, which usually means on'yomi readings from the kanji. If you know the readings of your kanji you'll know how to read this as well.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u30a2\u30e1\u30ea\u30ab\u3068\u65e5\u672c\u306e\u751f\u6d3b\u306e\u3061\u304c\u3044\u3092\u304a\u3057\u3048\u3066\u304f\u3060\u3055\u3044\u3002",
                    "en": "Please tell me the difference between American and Japanese life?"
                },
                {
                    "ja": "\u3042\u306a\u305f\u3068\u306e\u751f\u6d3b\u3092\u3082\u3046\u4e00\u3069\u3084\u308a\u76f4\u3057\u305f\u3044\u3093\u3067\u3059\u3002",
                    "en": "I want to get back together and live with you again."
