                {
                    "ja": "\u6bce\u65e5\u306e\u751f\u6d3b\u3067\u30a2\u30cb\u30e1\u3092\u898b\u306a\u304c\u3089\u30de\u30b7\u30e5\u30de\u30ed\u3092\u98df\u3079\u308b\u3053\u3068\u304c\u3067\u304d\u305f\u3089\u3001\u3068\u3066\u3082\u5e78\u305b\u3067\u3059\u3002",
