                },
                {
                    "ja": "\u3053\u306e\u30d0\u30b9\u30c4\u30a2\u30fc\u306e\u6b21\u306e\u76ee\u7684\u5730\u306f\u3001\u30de\u30a4\u30b1\u30eb\u30fb\u30b8\u30e3\u30af\u30bd\u30f3\u306e\u5bb6\u3067\u3059\u3002",
