                    }
                ],
                "mnemonic": "\n{splitParent}The reading is the same as {span:lang=ja:\u8db3\u308a\u308b} ({span:lang=ja:\u305f\u308a\u308b}) which you should have seen in Level 4.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u304a\u91d1\u304c\u5341\u5186\u8db3\u308a\u306a\u3044\u3093\u3067\u3059\u3002",
