            },
            "contextSentences": [
                {
                    "ja": "\u3069\u3046\u3076\u3064\u3048\u3093\u3067\u3001\u7f8a\u306b\u3048\u3055\u3092\u3084\u308a\u307e\u3057\u305f\u3002",
