                "mnemonic": "\n{splitParent}The reading is the on'yomi reading, just like you learned with the kanji.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u308f\u305f\u3057\u306f\u304a\u8336\u3092\u306e\u307f\u307e\u305b\u3093\u3067\u3057\u305f\u3002",
                    "en": "I didn\u2019t drink tea."
                },
                {
                    "ja": "\u6b7b\u306c\u524d\u306b\u3001\u30d9\u30fc\u30b3\u30f3\u306e\u304a\u8336\u3065\u3051\u304c\u98df\u3079\u305f\u3044\u3002",
                    "en": "I want to eat bacon rice covered in tea before I die."
                },
                {
                    "ja": "\u4f55\u6545\u304b\u304a\u306a\u3089\u304c\u3057\u305f\u304f\u306a\u308b\u306e\u3067\u3001\u3082\u3046\u304a\u8336\u3092\u98f2\u3080\u3053\u3068\u306f\u3067\u304d\u306a\u3044\u3002",
                    "en": "I can\u2019t drink tea anymore because it makes me fart."
                }
            ],
            "collocations": []
