                },
                {
                    "ja": "\u3048\uff1f\u5bdd\u308b\u6642\u3001\u7389\u306d\u304e\u3092\u6795\u306b\u3057\u305f\u306e\uff1f\u3042\u3093\u305f\u306e\u8a00\u3063\u3066\u308b\u3053\u3068\u3001\u610f\u5473\u4e0d\u660e\u306a\u3093\u3060\u3051\u3069\u3002",
