{
            "mnemonic": "You have {tooltip:Kanji:big} {tooltip:Kanji:writing} {tooltip:Kanji:letters}. What do you think these are? THAT WOULD HAVE TO BE {tooltip:Vocabulary:UPPERCASE LETTERS}, RIGHT? Whoops, sorry, caps lock was on for a moment, there.",
            "hints": "",
            "meanings": {
                "Primary": "Uppercase Letters",
                "Alternatives": "Capital Letters, Uppercase",
                "Word Type": "noun"
            },
            "vocabReadings": {
                "readings": [
                    {
                        "primary": true,
                        "reading": "\u304a\u304a\u3082\u3058"
