                {
                    "ja": "\u79c1\u304c\u5f7c\u306b\u3001\u4f55\u304b\u30bb\u30af\u30b7\u30fc\u306a\u8a00\u8449\u3092\u8033\u6253\u3061\u3057\u3066\u3068\u3044\u3046\u3068\u3001\u5f7c\u306f\u300c\u30c6\u30fc\u30d7\u3084CD\u306f\u597d\u304d\u304b\u3044\uff1f\u300d\u3068\u56c1\u3044\u3066\u304f\u308c\u305f\u3002",
                    "en": "I told him to whisper something sexy in my ear and he said, \"Do you like tapes and CDs?\""
                }
            ],
            "collocations": []
        }

{
            "mnemonic": "The {tooltip:Kanji:winter} {tooltip:Kanji:rest}! Wait, nobody calls it that. This is a {tooltip:Vocabulary:winter holiday} or {tooltip:Vocabulary:winter break}.",
