            "contextSentences": [
                {
                    "ja": "\u3082\u308a\u7530\u3055\u3093\u306b\u306f\u3001\u5e74\u4e0b\u306e\u304b\u306e\u5973\u304c\u3044\u307e\u3059\u3002",
