                "mnemonic": "\n{splitParent}Since this word consists of a kanji with hiragana attached, you can bet that it will use the kun'yomi reading. You didn't learn that reading with this kanji, so here's a mnemonic to help you: \n{splitParent}If you think about an {tooltip:Vocabulary:area} that you're in, it's the place you're {tooltip:Reading:at} ({span:lang=ja:\u3042\u305f}).\n"
            },
            "contextSentences": [
                {
                    "ja": "\u8fba\u308a\u306f\u3057\u30fc\u3093\u3068\u3057\u305a\u307e\u308a\u304b\u3048\u3063\u3066\u3044\u305f\u3002",
                    "en": "The area fell silent."
                },
                {
                    "ja": "\u305d\u3046\u3060\u3001\u3061\u3087\u3063\u3068\u8a00\u3044\u308f\u3059\u308c\u3066\u3044\u305f\u3093\u3060\u3051\u3069\u3001\u3053\u306e\u8fba\u308a\u306b\u3048\u304d\u306f\u306a\u3044\u304b\u3089\u306d\u3002",
                    "en": "Oh, I forgot to tell you that there is no station in this neighborhood."
                },
                {
                    "ja": "\u5f7c\u306e\u30c8\u30a4\u30ec\u306f\u3053\u306e\u8fba\u308a\u306b\u9055\u3044\u306a\u3044\u3002",
