            },
            "contextSentences": [
                {
                    "ja": "\u3042\u306e\u30d4\u30a8\u30ed\u304c\u3001\u98a8\u8239\u3067\u72ac\u3092\u4f5c\u3063\u3066\u304f\u308c\u305f\u3093\u3060\u3002",
