                {
                    "ja": "\u3072\u884c\u304d\u306b\u3088\u3063\u305f\u3070\u5408\u306f\u3001\u3053\u306e\u98a8\u8239\u3092\u30a8\u30c1\u30b1\u30c3\u30c8\u3076\u304f\u308d\u306e\u4ee3\u308f\u308a\u306b\u3054\u3057\u3088\u3046\u304f\u3060\u3055\u3044\u3002",
