                "mnemonic": "\n{splitParent}This jukugo word uses the on'yomi readings, except the {span:lang=ja:\u65e5} ({span:lang=ja:\u306b\u3061}) is shortened with a small {span:lang=ja:\u3063}, making the reading {span:lang=ja:\u306b\u3063\u304d}.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u3042\u306a\u305f\u306e\u65e5\u8a18\u3082\u3001\u3053\u306e\u672c\u3068\u4e00\u3057\u3087\u306b\u3053\u3053\u306b\u304a\u3044\u3066\u304a\u304d\u307e\u3059\u3002",
