                {
                    "ja": "\u6628\u65e5\u306e\u591c\u3001\u30d5\u30b0\u306e\u65e5\u8a18\u3092\u8aad\u3093\u3060\u3093\u3060\u3051\u3069\u3055\u3001\u5b9f\u306f\u3068\u3066\u3082\u60b2\u3057\u3044\u65e5\u8a18\u3060\u3063\u305f\u3093\u3060\u3088\u306d\u3002",
