                {
                    "ja": "\u3053\u3053\u3001\u30d6\u30e9\u30c3\u30af\u304d\u304e\u3087\u3046\u3059\u304e\u308b\u304b\u3089\u3001\u6708\u672b\u306b\u306b\u3052\u51fa\u3059\u308f\u3002",
