                    "ja": "\u3054\u3055\u3093\u8003\u307e\u3067\u306b\u3001\u308f\u305f\u3057\u306e\u6c0f\u540d\u306f\u3001\u9ad8 \u4e00\u5b50\u3067\u3059\u3002",
