            },
            "contextSentences": [
                {
                    "ja": "\u30bf\u30a4\u30e0\u30b9\u30ea\u30c3\u30d7\u3067\u304d\u308b\u306a\u3089\u3001\u672a\u6765\u306b\u884c\u304d\u305f\u3044\u306a\u3002",
