                        "primary": true,
                        "reading": "\u3066\u3065\u304f\u308a"
                    }
                ],
                "pronunciationAudios": [
                    {
                        "gender": "female",
                        "pronunciation": "\u3066\u3065\u304f\u308a",
                        "voiceActorId": 1,
                        "voiceActorName": "Kyoko",
                        "voiceDescription": "Tokyo accent",
