                {
                    "ja": "\u30a2\u30a4\u30ea\u3061\u3083\u3093\u306f\u5927\u7a7a\u306b\u3046\u304b\u3076\u304a\u661f\u3055\u307e\u306b\u306a\u3063\u305f\u3093\u3060\u3088\u3002",
                    "en": "Airi became a star in the firmament."
                },
                {
                    "ja": "\u9df2\u304c\u5927\u7a7a\u3092\u60a0\u3005\u3068\u98db\u3093\u3067\u3044\u305f\u3002",
                    "en": "The eagle flew leisurely in the heavens."
                }
