            },
            "contextSentences": [
                {
                    "ja": "\u5916\u56fd\u306b\u624b\u7d19\u3092\u51fa\u3057\u307e\u3057\u305f\u3002",
                    "en": "I sent a letter to a foreign country."
                },
                {
                    "ja": "\u305d\u306e\u91d1\u6b63\u65e5\u304b\u3089\u306e\u624b\u7d19\u3001\u30cd\u30c3\u30c8\u30aa\u30fc\u30af\u30b7\u30e7\u30f3\u306b\u51fa\u3057\u3061\u3083\u3048\u3070\uff1f\u304d\u3063\u3068\u3060\u308c\u304b\u3057\u3089\u304b\u3046\u3068\u601d\u3046\u3088\u3002",
                    "en": "Why don't you put up the letter from Kim Jong Il for online auction? I think somebody would buy it."
                },
                {
                    "ja": "\u79c1\u306f\u30b3\u30ab\u30b3\u30fc\u30e9\u5b9b\u306b\u3001\u5fc3\u306e\u3053\u3082\u3063\u305f\u624b\u7d19\u3092\u66f8\u3044\u3066\u3001\u3069\u3046\u3057\u3066\u5f7c\u3089\u306e\u88fd\u54c1\u306b\u305f\u304f\u3055\u3093\u7802\u7cd6\u304c\u5165\u3063\u3066\u3044\u308b\u306e\u304b\u306b\u3064\u3044\u3066\u5c0b\u306d\u305f\u3044\u3068\u601d\u3044\u307e\u3059\u3002",
                    "en": "I\u2019m going to write a very heated letter to Coca-Cola and ask why there is so much sugar in their products."
                }
            ],
            "collocations": []
        }

