            },
            "contextSentences": [
                {
                    "ja": "\u4e8c\u4eba\u3068\u3082\u3001\u3069\u3046\u3057\u3066\u5c0f\u58f0\u3067\u306f\u306a\u3057\u3066\u3044\u308b\u306e\uff1f",
