                    "ja": "\u306d\u3053\u306e\u5fc3\u7406\u3092\u601d\u3046\u304c\u307e\u307e\u306b\u3042\u3084\u3064\u308c\u308b\u3088\u3046\u306b\u306a\u308a\u305f\u3044\u3002",
