                        "voiceActorName": "Kenichi",
                        "voiceDescription": "Tokyo accent",
                        "file": "19932-subject-7734.ogg"
                    }
                ],
                "mnemonic": "\n{splitParent}This is a jukugo word that uses the on'yomi readings of the kanji. You should be able to read this on your own. Just watch out because {span:lang=ja:\u3044\u3061} is shortened to {span:lang=ja:\u3044\u3063} here!\n"
            },
            "contextSentences": [
                {
                    "ja": "\u4e00\u4f53\u3069\u3046\u306a\u3063\u3066\u3044\u308b\u3093\u3060\u3002",
                    "en": "What the heck is going on?"
                },
                {
                    "ja": "\u300c\u3042\u3044\u3068\u306b\u304f\u3057\u307f\u306f\u3072\u3087\u3046\u308a\u4e00\u4f53\u300d\u3063\u3066\u3001\u4e00\u4f53\u5168\u4f53\u3069\u3046\u3044\u3046\u3044\u307f\u306a\u3093\u3060\uff01\uff1f",
                    "en": "What the heck does, \"There's a thin line between love and hate,\" mean?"
                },
                {
                    "ja": "\u4e00\u4f53\u4ffa\u304c\u4f55\u3092\u3057\u305f\u3063\u3066\u8a00\u3046\u3093\u3060\u3088\uff1f",
                    "en": "What the heck did you say I did?"
                }
            ],
            "collocations": []
        }

