            "contextSentences": [
                {
                    "ja": "\u308c\u3044\u307c\u3046\u3092\u3064\u3051\u308b\u6642\u306f\u3001\u767d\u3044\u30dc\u30bf\u30f3\u3092\u304a\u3057\u3066\u304f\u3060\u3055\u3044\u3002",
