            "contextSentences": [
                {
                    "ja": "\u305d\u306e\u3048\u3044\u304c\u306e\u304b\u3044\u3048\u3093\u6642\u304b\u3093\u306f\u4e8c\u6642\u534a\u3067\u3059\u3002",
