                    "ja": "\u4eca\u56de\u306e\u53f0\u98a8\u306f\u5f31\u3044\u306e\u3067\u3001\u3042\u307e\u308a\u5fc3\u3071\u3044\u3057\u306a\u304f\u3066\u3082\u3088\u3055\u305d\u3046\u3067\u3059\u3002",
