                    "ja": "\u3059\u307f\u307e\u305b\u3093\u304c\u3001\u5e74\u672b\u306f\u3001\u3061\u3087\u3063\u3068\u30d0\u30bf\u30d0\u30bf\u3057\u3066\u3058\u304b\u3093\u304c\u3068\u308c\u306a\u3055\u305d\u3046\u3067\u3059\u3002",
