                    }
                ],
                "hints": "Keep repeating this pattern over and over, continually focusing in on how you need \"more\" trees to make this forest. For some reason the person working with you only goes up by one at a time, though, so you have to say it a lot (it'll help you to remember, anyways!).",
                "mnemonic": "One tree? No. Two trees? Not enough. I want {tooltip:Reading:more} ({span:lang=ja:\u3082\u308a}) trees, please!"
            }
        }

{
            "mnemonic": "With {tooltip:Radical:top hat} {tooltip:Radical:power}, you're able to {tooltip:Kanji:help} anyone.",
            "hints": "Imagine putting on your top hat and getting power from it. Then, you use that power to help someone. It's important to make the association that it's the top hat giving you the power to help that person. You're basically Frosty the Snow Man.",
            "meanings": {
                "Primary": "Help"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u3058\u3087",
