                    "ja": "\u3042\u306a\u305f\u306e\u52a9\u8a00\u3001\u305c\u3093\u305c\u3093\u5f79\u306b\u7acb\u305f\u306a\u304b\u3063\u305f\u3093\u3060\u3051\u3069\u3002",
