            },
            "contextSentences": [
                {
                    "ja": "\u3053\u308c\u306f\u3001\u5168\u7c73\u304c\u306a\u307f\u3060\u3057\u305f\u3001\u5927\u30d2\u30c3\u30c8\u30c1\u30e7\uff5e\u5927\u4f5c\u3048\u3044\u304c\u3067\u3059\u3002",
                    "en": "This is a mega-hit blockbuster that brought all of America to tears."
                },
                {
                    "ja": "\u307e\u3064\u5c71\u3072\u3067\u304d\u306f\u30012017\u5e74\u306e\u5168\u7c73\u30aa\u30fc\u30d7\u30f3\u3067\u4e8c\u3044\u306b\u5165\u3063\u305f\u3002",
                    "en": "Hideki Matsuyama finished second at the 2017 U.S. Open."
