                {
                    "ja": "\u5168\u7c73\u30d2\u30c3\u30c8\u30c1\u30e3\u30fc\u30c8\u3067\u4eca\u4e00\u4f4d\u306e\u66f2\u306f\u4f55\u3067\u3059\u304b\uff1f",
                    "en": "What's the No. 1 song on the U.S. hit chart now?"
                }
            ],
