            "contextSentences": [
                {
                    "ja": "\u3048\u304d\u306e\u6771\u53e3\u3067\u5927\u9053\u3052\u3044\u3092\u3057\u3066\u3044\u308b\u4eba\u304c\u3044\u305f\u3088\u3002",
