                {
                    "ja": "\u6bce\u3070\u3093\u3001\u30d9\u30fc\u30b3\u30f3\u5de5\u5834\u306e\u305b\u3058\u3087\u3046\u3092\u3059\u308b\u306e\u306f\u3001\u308f\u305f\u3057\u306e\u4e3b\u4eba\u306e\u5f79\u76ee\u3067\u3059\u3002",
