            },
            "contextSentences": [
                {
                    "ja": "\u30dd\u30fc\u30c8\u30e9\u30f3\u30c9\u306e\u304b\u3093\u5149\u540d\u6240\u3092\u6559\u3048\u3066\u304f\u3060\u3055\u3044\u3002",
                    "en": "Can you tell me about some Portland tourist spots?"
                },
                {
                    "ja": "\u540d\u6240\u3081\u3050\u308a\u306e\u65e5\u306b\u3061\u304c\u8fd1\u304f\u306a\u3063\u3066\u304d\u305f\u3089\u3001\u307e\u305f\u308c\u3093\u3089\u304f\u3059\u308b\u306d\u3002",
                    "en": "I'll get in touch with you when we get closer to the day we're visiting famous places."
                },
                {
                    "ja": "\u79c1\u306f\u3001\u30b9\u30bf\u30fc\u30d0\u30c3\u30af\u30b9\u3084\u30c7\u30cb\u30fc\u30ba\u3001\u305d\u308c\u304b\u3089\u30cb\u30e5\u30fc\u30e8\u30fc\u30af\u90f5\u4fbf\u5c40\u306a\u3069\u6570\u3005\u306e\u540d\u6240\u3092\u898b\u308b\u305f\u3081\u306b\u3001\u30cb\u30e5\u30fc\u30e8\u30fc\u30af\u3078\u884c\u304d\u307e\u3059\u3002",
                    "en": "I\u2019m going to New York to see all the famous places like Starbucks, Denny\u2019s, and the New York City post office."
                }
            ],
            "collocations": []
