{
            "mnemonic": "Something is {tooltip:Kanji:versus} the {tooltip:Kanji:outside}. Back in the day, everything was a battle with the outside. You had the Mongols... the rebels... and the foreigners. So, when you say something is \"versus the outside\" you're just saying it's something compared to where you are right now. It's something that's {tooltip:Vocabulary:foreign} or from {tooltip:Vocabulary:overseas}.",
            "hints": "",
            "meanings": {
                "Primary": "Foreign",
                "Alternative": "Overseas",
                "Word Type": "noun"
            },
            "vocabReadings": {
                "readings": [
                    {
                        "primary": true,
                        "reading": "\u305f\u3044\u304c\u3044"
                    }
                ],
                "pronunciationAudios": [
                    {
                        "gender": "female",
                        "pronunciation": "\u305f\u3044\u304c\u3044",
                        "voiceActorId": 1,
