{
            "mnemonic": "The kanji and the word are exactly the same. That means they share meanings as well. ",
            "hints": "",
            "meanings": {
                "Primary": "Interval",
                "Alternatives": "Interval Of Time, Time Interval, Between, Room",
                "Word Type": "noun"
            },
            "vocabReadings": {
                "readings": [
