            "contextSentences": [
                {
                    "ja": "\u304a\u524d\u306f\u672c\u5f53\u306b\u3057\u3093\u305d\u3046\u3092\u7a76\u660e\u3059\u308b\u3064\u3082\u308a\u304c\u3042\u308b\u306e\u304b\uff1f",
                    "en": "Are you really going to investigate the truth?"
                },
                {
                    "ja": "\u30b3\u30a6\u30a4\u30c1\u306e\u304a\u304b\u3057\u306a\u8a00\u3069\u3046\u306e\u3057\u3093\u306e\u3069\u3046\u304d\u306f\u307e\u3060\u7a76\u660e\u3055\u308c\u3066\u3044\u306a\u3044\u3002",
                    "en": "The true motive behind Koichi's strange words and deeds have not yet been brought to light."
