            "contextSentences": [
                {
                    "ja": "\u7814\u7a76\u306b\u306d\u3063\u4e2d\u3057\u3059\u304e\u3066\u3001\u6c17\u304c\u3064\u3044\u305f\u308912\u6642\u3092\u3059\u304e\u3066\u3044\u307e\u3057\u305f\u3002",
