            "contextSentences": [
                {
                    "ja": "\u5ddd\u4e0b\u3055\u3093\u306f\u3001\u77f3\u7530\u4e2d\u5b66\u6821\u3067\u6570\u5b66\u306e\u5148\u751f\u3092\u3057\u3066\u3044\u307e\u3059\u3002",
