                    "ja": "\u3055\u3044\u8fd1\u3001\u5730\u4e2d\u6d77\u308a\u3087\u3046\u308a\u306b\u30cf\u30de\u3063\u3066\u3044\u308b\u3093\u3067\u3059\u3088\u306d\u3002",
