            "contextSentences": [
                {
                    "ja": "\u3053\u3093\u306a\u5f53\u305f\u308a\u524d\u306e\u3053\u3068\u3001\u3069\u3046\u3057\u3066\u5206\u304b\u3089\u306a\u3044\u306e\uff1f",
