                {
                    "ja": "\u3067\u3082\u3001\u3053\u308c\u304c\u5f53\u305f\u308a\u524d\u306e\u3053\u3068\u3060\u3068\u306f\u601d\u308f\u306a\u3044\u3067\u304f\u3060\u3055\u3044\u306d\u3002",
