                    }
                ],
                "mnemonic": "\n{splitParent}This word consists of the on'yomi reading for {span:lang=ja:\u756a} and the kun'yomi reading for {span:lang=ja:\u7d44}. You've learned them both so as long as you remember the rendaku, you should be able to read this word too!\n"
            },
            "contextSentences": [
                {
                    "ja": "\u3053\u306e\u756a\u7d44\u306f\u304a\u3082\u767d\u304f\u3042\u308a\u307e\u305b\u3093\u3067\u3057\u305f\u304c\u3001\u308f\u305f\u3057\u306e\u3059\u304d\u306a\u306f\u3044\u3086\u3046\u304c\u51fa\u3066\u3044\u307e\u3057\u305f\u3002",
                    "en": "This TV program wasn\u2019t interesting, but my favorite actor was in it."
                },
                {
                    "ja": "\u304d\u306e\u3046\u306e\u756a\u7d44\u3067\u3001\u3042\u306e\u4e8c\u4eba\u306f\u3064\u3044\u306b\u4e21\u3057\u3083\u304c\u306a\u3063\u3068\u304f\u3059\u308b\u3060\u304d\u3087\u3046\u3042\u3093\u306b\u305f\u3069\u308a\u3064\u3044\u305f\u3088\u3002",
                    "en": "In yesterday's program, those two finally managed to work out a compromise."
                },
                {
                    "ja": "\u6700\u8fd1\u306f\u30d0\u30e9\u30a8\u30c6\u30a3\u756a\u7d44\u3057\u304b\u898b\u307e\u305b\u3093\u3002",
