                {
                    "ja": "\u3069\u3046\u3057\u3066\u81ea\u3066\u3093\u8eca\u304c\u6b69\u9053\u3092\u8d70\u3063\u3066\u306f\u3044\u3051\u306a\u3044\u3093\u3067\u3059\u304b\uff1f",
