            "meanings": {
                "Primary": "Soon",
                "Alternatives": "Before Long, In A Short Time, Shortly, Momentarily",
                "Word Type": "adverb"
            },
            "vocabReadings": {
                "readings": [
                    {
                        "primary": true,
                        "reading": "\u307e\u3082\u306a\u304f"
                    }
                ],
                "pronunciationAudios": [
