                    "ja": "\u3053\u306e\u3082\u3093\u3060\u3044\u306b\u3001\u3058\u3057\u3087\u3092\u3064\u304b\u3063\u3066\u7b54\u3048\u3066\u304f\u3060\u3055\u3044\u3002",
