                        "file": "20305-subject-3461.ogg"
                    }
                ],
                "mnemonic": "\n{splitParent}The reading is a combination of the readings from {span:lang=ja:\u51fa\u6765\u308b} and {span:lang=ja:\u4e0a\u304c\u308b}. So long as you were paying attention in lessons past, you should be able to read this word as well just by combining those other words.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u304a\u3044\u3057\u3044\u30ab\u30ec\u30fc\u304c\u51fa\u6765\u4e0a\u304c\u308a\u307e\u3057\u305f\u3002",
                    "en": "The delicious curry was finished."
                },
                {
                    "ja": "\u65e5\u672c\u308a\u3087\u884c\u306e\u3051\u3044\u304b\u304f\u306f\u3001\u30ae\u30ea\u30ae\u30ea\u306b\u306a\u3063\u3066\u3088\u3046\u3084\u304f\u51fa\u6765\u4e0a\u304c\u308a\u307e\u3057\u305f\u3002",
                    "en": "Our Japan travel plans were finished at the last minute."
                },
                {
                    "ja": "\u8c46\u8150\u3068\u6cb3\u8c5a\u306e\u30cf\u30f3\u30d0\u30fc\u30ac\u30fc\u304c\u51fa\u6765\u4e0a\u304c\u308a\u307e\u3057\u305f\u3002",
                    "en": "The tofu and fugu hamburgers are done!"
                }
