                        "file": "20247-subject-3463.ogg"
                    }
                ],
                "mnemonic": "\n{splitParent}The reading is the same as with {span:lang=ja:\u4ea4\u305c\u308b}. So long as you know the {span:lang=ja:\u307e} portion of that word's reading, you'll be able to read this word as well.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u7a7a\u3068\u6d77\u304c\u4ea4\u3058\u308b\u3068\u3053\u308d\u304c\u3001\u4e16\u304b\u3044\u306e\u306f\u3066\u306a\u306e\u3055\u3002",
                    "en": "The place where the sky and the sea meet is the edge of the world."
