            "contextSentences": [
                {
                    "ja": "\u65e5\u672c\u3054\u306e\u3079\u3093\u5f37\u306e\u5f79\u306b\u7acb\u3064\u30b5\u30a4\u30c8\u3092\u898b\u3064\u3051\u307e\u3057\u305f\u3002",
