            "contextSentences": [
                {
                    "ja": "\u305f\u307e\u3054\u306e\u767d\u8eab\u306e\u9ec4\u8eab\u306b\u5bfe\u3059\u308b\u308f\u308a\u5408\u306f\u3001\uff12\u5bfe\uff11\u3067\u3059\u3002",
