                    {
                        "gender": "male",
                        "pronunciation": "\u307f\u306a\u304a\u3059",
                        "voiceActorId": 2,
                        "voiceActorName": "Kenichi",
                        "voiceDescription": "Tokyo accent",
                        "file": "20133-subject-3453.ogg"
                    }
                ],
                "mnemonic": "\n{splitParent}The readings are all kun'yomi readings, like the vocab you've seen already. This is like two vocab words put together, which is why it's using the kun'yomi reading. The hiragana on the end is a hint!\n"
            },
            "contextSentences": [
                {
                    "ja": "\u3082\u3046\u4e00\u3069\u3001\u3051\u3044\u304b\u304f\u3092\u898b\u76f4\u3057\u307e\u3057\u3087\u3046\u3002",
                    "en": "Let\u2019s look at the plans one more time."
                },
                {
                    "ja": "\u3053\u306e\u9593\u306e\u306f\u3044\u3072\u3093\u56de\u3057\u3085\u3046\u306e\u65e5\u3001\u4e3b\u4eba\u304c\u601d\u3063\u305f\u3088\u308a\u305f\u3088\u308a\u306b\u306a\u3063\u3066\u3001\u3061\u3087\u3063\u3068\u898b\u76f4\u3057\u3061\u3083\u3063\u305f\u3002",
                    "en": "On the last junk removal day, my husband was much more dependable than I expected and it made me look at him differently."
                },
                {
