            },
            "contextSentences": [
                {
                    "ja": "\u30cb\u30c3\u30ab\u306f\u3044\u3064\u3082\u30aa\u30d5\u30a3\u30b9\u5185\u3092\u8d70\u308a\u56de\u3063\u3066\u3044\u307e\u3059\u3002",
                    "en": "Nikka is always running around the office."
