            },
            "contextSentences": [
                {
                    "ja": "\u308f\u305f\u3057\u3001\u5168\u8eab\u6bdb\u3080\u304f\u3058\u3083\u3089\u306e\u30ef\u30a4\u30eb\u30c9\u306a\u7537\u305b\u3044\u304c\u3059\u304d\u306a\u3093\u3067\u3059\u3002",
