                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "You put your soul into an envelope, stick a stamp on it, and hand it off to be sent to heaven. Bye bye! I hope this doesn't have any negative effects on your body!",
                "mnemonic": "You want to {tooltip:Kanji:send} your {tooltip:Reading:sou}l ({span:lang=ja:\u305d\u3046}) to heaven. I mean, you don't want it to go to some of those other places you've heard of, so why not send your soul?"
            }
        }

{
            "mnemonic": "{tooltip:Radical:Old} {tooltip:Radical:flowers} are {tooltip:Kanji:suffering} because they're old.",
            "hints": "Old things go through a lot of suffering because their bodies are breaking down. Flowers are no different from you and me.",
            "meanings": {
                "Primary": "Suffering"
            },
            "kanjiReadings": {
