                        "primary": true
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Picture yourself swimming in the tsunami with everyone else. You can't really talk to them, you're too busy swimming for your life, so you just shout \"Oy!\" to them and they shout it back.",
                "mnemonic": "{tooltip:Reading:Oy} ({span:lang=ja:\u304a\u3088})! Oy, stop daydreaming about {tooltip:Kanji:swim}ming and actually do it!"
            }
