            },
            "contextSentences": [
                {
                    "ja": "\u5927\u3057\u304d\u3085\u3046\u3001\u3078\u3093\u3057\u3085\u3046\u90e8\u306e\u90e8\u9577\u3092\u3088\u3093\u3067\u304f\u308c\u306a\u3044\u304b\u3002",
                    "en": "Could you call the head of the editorial department ASAP?"
                },
                {
                    "ja": "\u4e2d\u5b66\u306e\u6642\u306f\u3001\u3051\u3093\u9053\u90e8\u3067\u3057\u305f\u3002",
