                ],
                "mnemonic": "\n{splitParent}This is a jukugo word, which usually means on'yomi readings from the kanji. If you know the readings of your kanji you'll know how to read this as well. The {span:lang=ja:\u3057\u3085\u3064} gets shortened and {span:lang=ja:\u306f\u3064} changes to {span:lang=ja:\u3071\u3064}. No wonder you want to make a departure, you want to get away from crazy readings like this.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u51fa\u767a\u307e\u3067\u4e94\u5206\u3067\u3059\u3002",
                    "en": "There are five minutes until departure."
                },
                {
                    "ja": "\u4e8c\u9031\u9593\u5f8c\u306b\u3001\u6771\u4eac\u306b\u51fa\u767a\u3059\u308b\u4e88\u5b9a\u3067\u3059\u3002",
                    "en": "I'm going to leave for Tokyo in two weeks."
                },
                {
                    "ja": "\u307b\u3068\u3093\u3069\u558b\u3063\u305f\u3053\u3068\u306e\u306a\u3044\u540c\u50da\u306e\u51fa\u767a\u306e\u9580\u51fa\u3092\u795d\u3046\u98f2\u307f\u4f1a\u306b\u304a\u8a98\u3044\u9802\u304d\u3001\u3069\u3046\u3082\u6709\u96e3\u3046\u5fa1\u5ea7\u3044\u307e\u3059\u3002",
