            },
            "contextSentences": [
                {
                    "ja": "\u5206\u304b\u3089\u306a\u3044\u304b\u3093\u5b57\u306e\u4e0b\u306b\u3001\u4e8c\u91cd\u305b\u3093\u3092\u5f15\u3044\u3066\u304f\u3060\u3055\u3044\u3002",
                    "en": "Please draw double lines under kanji you don\u2019t know."
                },
                {
                    "ja": "\u65e5\u672c\u306f\u4e8c\u91cd\u56fd\u305b\u304d\u3092\u307f\u3068\u3081\u3066\u3044\u307e\u305b\u3093\u3002",
                    "en": "Japan doesn't allow dual citizenship."
                },
                {
                    "ja": "\u300c\u305d\u308c\u3067\u306f\u3001\u4e16\u9593\u8a71\u306f\u305d\u308c\u3050\u3089\u3044\u306b\u3057\u3066\u3001\u672c\u984c\u306b\u5165\u308d\u3046\u3002\u4eca\u65e5\u306e\u8b70\u984c\u306f\u4f55\u3060\u3063\u305f\u304b\u306a\uff1f\u300d\u300c\u4eca\u65e5\u306f\u3042\u306a\u305f\u306e\u4e8c\u91cd\u3042\u3054\u306b\u3064\u3044\u3066\u8a71\u3057\u3092\u3059\u308b\u3053\u3068\u306b\u306a\u3063\u3066\u3044\u307e\u3059\u3002\u300d\u300c\u305d\u3046\u3060\u3063\u305f\u306a\u3002\u305d\u308c\u3067\u306f\u59cb\u3081\u3088\u3046\u304b\u3002\u300d",
                    "en": "\"Well, let\u2019s stop the small talk and cut to the chase. What was the topic of today\u2019s meeting?\" \"We were going to talk about your double chin, sir.\" \"Right, right. Let\u2019s get started.\""
                }
            ],
