                {
                    "ja": "\u3053\u306e\u9b5a\u5c4b\u306e\u3086\u304b\u306f\u3059\u3079\u308a\u3084\u3059\u3044\u304b\u3089\u6c17\u3092\u4ed8\u3051\u3066\u306d\u3002",
