            "contextSentences": [
                {
                    "ja": "\u3053\u306e\u590f\u3001Tofugu\u304b\u3089\u3001\u300c\u30d9\u30fc\u30b3\u30f3\u3068\u304a\u3053\u306e\u307f\u3084\u304d\u306e\u30c1\u30fc\u30ba\u30bf\u30eb\u30c8\u300d\u304c\u767a\u58f2\u3055\u308c\u308b\u3053\u3068\u304c\u6c7a\u5b9a\u3057\u307e\u3057\u305f\uff01",
                    "en": "We\u2019ve decided to sell bacon and okonomiyaki cheese tarts from Tofugu this summer."
                },
                {
                    "ja": "\u30b3\u30a6\u30a4\u30c1\u306e\u3064\u3081\u306e\u3042\u304b\u3092\u305b\u3093\u3058\u305f\u30dd\u30fc\u30c8\u30e9\u30f3\u30c9\u540d\u7269\u30c8\u30fc\u30d5\u30b0\u8336\u304c\u30c8\u30fc\u30d5\u30b0\u306e\u30a6\u30a7\u30d6\u30b5\u30a4\u30c8\u3067\u3067\u305c\u3063\u3055\u3093\u767a\u58f2\u4e2d\u3067\u3059\uff01",
                    "en": "Portland's famous Tofugu tea, with the dirt of Koichi's nails, is now on sale on the Tofugu website!"
                },
                {
                    "ja": "Tofugu\u306e\u30c7\u30fc\u30c8\u7528\u62b1\u304d\u307e\u304f\u3089\u304c\u767a\u58f2\u3055\u308c\u308b\u306e\u304c\u5f85\u3061\u9060\u3057\u3044\u3002",
                    "en": "I can\u2019t wait until the Tofugu dating pillows are on sale."
                }
            ],
            "collocations": []
        }

{
            "mnemonic": "This is the noun version of the kanji {tooltip:Kanji:express}. If you want to understand what something is trying to {tooltip:Kanji:express} you usually look at its {tooltip:Vocabulary:front} or its {tooltip:Vocabulary:exterior}. This word is usually used for the exterior face of buildings.",
            "hints": "",
            "meanings": {
                "Primary": "Front",
                "Alternatives": "Surface, Exterior, Face, Outside, Appearance",
                "Word Type": "independent noun"
            },
            "vocabReadings": {
                "readings": [
                    {
                        "primary": true,
                        "reading": "\u304a\u3082\u3066"
                    }
                ],
                "pronunciationAudios": [
                    {
                        "gender": "male",
                        "pronunciation": "\u304a\u3082\u3066",
                        "voiceActorId": 2,
                        "voiceActorName": "Kenichi",
