            },
            "contextSentences": [
                {
                    "ja": "\u5927\u3059\u304d\u306a\u30a2\u30a4\u30c9\u30eb\u3068\u3001\u308d\u5929\u3076\u308d\u4ed8\u306e\u5ba2\u5ba4\u306b\u3068\u307e\u308b\u3053\u3068\u304c\u3086\u3081\u306a\u3093\u3067\u3059\u3002",
                    "en": "My dream is to stay in a guest room attached to an open air bath with the idol I love."
                },
                {
                    "ja": "\u3053\u306e\u30db\u30c6\u30eb\u3067\u306f\u5168\u3066\u306e\u5ba2\u5ba4\u306b\u30b3\u30f3\u30b7\u30a7\u30eb\u30b8\u30e5\u30b5\u30fc\u30d3\u30b9\u304c\u4ed8\u3044\u3066\u304d\u307e\u3059\u3002",
                    "en": "In this hotel, all the guest rooms have concierge service."
                },
