            "meanings": {
                "Primary": "Heart Shaped",
                "Word Type": "noun"
            },
            "vocabReadings": {
                "readings": [
                    {
                        "primary": true,
                        "reading": "\u306f\u30fc\u3068\u304c\u305f"
                    },
                    {
                        "primary": false,
                        "reading": "\u30cf\u30fc\u30c8\u304c\u305f"
                    }
                ],
                "pronunciationAudios": [
                    {
                        "gender": "male",
                        "pronunciation": "\u306f\u30fc\u3068\u304c\u305f",
                        "voiceActorId": 2,
                        "voiceActorName": "Kenichi",
                        "voiceDescription": "Tokyo accent",
                        "file": "41904-subject-2823.ogg"
                    },
                    {
                        "gender": "female",
                        "pronunciation": "\u306f\u30fc\u3068\u304c\u305f",
                        "voiceActorId": 1,
                        "voiceActorName": "Kyoko",
                        "voiceDescription": "Tokyo accent",
                        "file": "40336-subject-2823.ogg"
                    }
                ],
                "mnemonic": "\n{splitParent}The reading for the kanji portion uses the kun'yomi reading. This is kind of like the reading you already learned for {span:lang=ja:\u5f62} just without the {span:lang=ja:\u3061} part. And rendaku happens too, so it becomes {span:lang=ja:\u304c\u305f}. If you can remember that, you should be able to remember this reading too!\n"
            },
            "contextSentences": [
                {
                    "ja": "\u30cd\u30a4\u30eb\u7528\u306b\u3001\u30cf\u30fc\u30c8\u5f62\u306e\u30b9\u30c8\u30fc\u30f3\u3092\u3055\u304c\u3057\u3066\u3044\u307e\u3059\u3002",
                    "en": "I\u2019m looking for a heart shaped stone to use on my fake nails."
                },
                {
                    "ja": "\u30af\u30ea\u30b9\u30c6\u30a3\u30f3\u306f\u3001\u304f\u304e\u3092\u304f\u308f\u3048\u306a\u304c\u3089\u3001\u30cf\u30fc\u30c8\u5f62\u306e\u30cf\u30f3\u30de\u30fc\u3092\u3075\u308a\u56de\u3057\u3066\u3044\u305f\u3002",
                    "en": "Kristen was swinging a heart shaped hammer around while holding nails in her mouth."
                },
                {
                    "ja": "\u30d5\u30e9\u30df\u30f3\u30b4\u304c\u30ad\u30b9\u3092\u3059\u308b\u6642\u3001\u4e8c\u7fbd\u306e\u982d\u3068\u9996\u304c\u30cf\u30fc\u30c8\u5f62\u3092\u63cf\u304f\u3002",
                    "en": "When flamingos kiss, their heads and necks form a heart shape."
                }
            ],
            "collocations": []
        }

{
            "mnemonic": "This is a single kanji with an {span:lang=ja:\u3044} on the end, meaning you know it's probably an adjective. What's the adjective form of {tooltip:Kanji:heavy}? It's also {tooltip:Vocabulary:heavy}.",
            "hints": "",
            "meanings": {
