            "contextSentences": [
                {
                    "ja": "\u4eca\u65e5\u306f\u3001\u9ad8\u6821\u751f\u305f\u3061\u304c\u3001\u3053\u306e\u30d1\u30f3\u5de5\u5834\u306e\u898b\u5b66\u306b\u6765\u307e\u3059\u3002",
                    "en": "Today, high school students are coming to this bread factory on a field trip."
