            "contextSentences": [
                {
                    "ja": "\u4eba\u751f\u306b\u306f\u672c\u5f53\u306b\u5927\u5207\u306a\u3057\u3085\u3093\u9593\u304c\u4f55\u5ea6\u304b\u304a\u3068\u305a\u308c\u308b\u3002",
