                    "ja": "\u305d\u308c\u3088\u308a\u3001\u4e2d\u5b66\u6821\u306e\u524d\u3067\u3068\u3063\u305f\u5199\u3057\u3093\u304c\u3044\u3044\u3088\u3002",
