                },
                {
                    "ja": "\u3061\u3087\u3063\u3068\u307e\u3063\u3066\u3066\u3002\u305d\u306e\u4e2d\u5b66\u6821\u306e\u3070\u6240\u3092\u4eca\u3057\u3089\u3079\u3066\u3042\u3052\u308b\u3002",
