                },
                {
                    "ja": "\u3048\u3048\u3063\u3068\u3001\u79c1\u306f\u4e2d\u5b66\u6821\u306e\u6559\u5e2b\u3067\u3059\u3088\u306d\u3002\u305d\u3053\u3067\u3001\u6642\u9593\u3092\u7121\u99c4\u306b\u3057\u306a\u3044\u305f\u3081\u306b\u3082\u3001\u3068\u308a\u3042\u3048\u305a\u79c1\u306f\u7d76\u5bfe\u306b\u9593\u9055\u3063\u305f\u3053\u3068\u3092\u8a00\u308f\u306a\u3044\u3001\u3068\u3044\u3046\u3053\u3068\u306b\u3057\u3066\u304a\u3044\u3066\u304f\u3060\u3055\u3044\u3002",
