                },
                {
                    "ja": "\u4ed8\u8fd1\u306b\u306f\u3001\u5916\u56fd\u4eba\u898b\u7269\u5ba2\u3082\u305f\u304f\u3055\u3093\u3044\u307e\u3057\u305f\u3002",
                    "en": "There were many foreign viewers nearby as well."
                },
