                {
                    "ja": "\u6620\u753b\u300c\u6c34\u306e\u4e16\u754c\u300d\u306f\u3001\u5b9f\u306f\u3001\u6d77\u306e\u5e95\u306b\u4f4f\u3093\u3067\u3044\u308b\u8d85\u982d\u306e\u3044\u3044\u9b5a\u306b\u3088\u3063\u3066\u66f8\u304b\u308c\u305f\u4f5c\u54c1\u3060\u3002",
