                },
                {
                    "ja": "\u3082\u3057\u864e\u3068\u4e03\u9762\u9ce5\u304c\u6226\u4e89\u3059\u308b\u3053\u3068\u306b\u306a\u3063\u305f\u3089\u3001\u305d\u308c\u306f\u3082\u3046\u864e\u306e\u5fc5\u52dd\u306b\u306a\u308b\u3060\u308d\u3046\u306d\u3002\u305d\u308c\u304b\u3089\u3001\u3064\u3044\u3067\u306b\u3001\u990a\u9d8f\u6240\u3067\u50cd\u304f\u4eba\u3082\u559c\u3076\u3060\u308d\u3046\u306d\u3002",
