                    {
                        "gender": "male",
                        "pronunciation": "\u307e\u304c\u308b",
                        "voiceActorId": 2,
                        "voiceActorName": "Kenichi",
                        "voiceDescription": "Tokyo accent",
                        "file": "20081-subject-3429.ogg"
                    }
                ],
                "mnemonic": "\n{splitParent}Since this word consists of a kanji with hiragana attached, you can bet that it will use the kun'yomi reading. You didn't learn that reading with this kanji, so here's a mnemonic to help you: \n{splitParent}Something, let's say a road, starts out straight. But, with some {tooltip:Reading:ma}gic, a witch causes it {tooltip:Vocabulary:to curve}.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u4e09\u3064\u76ee\u306e\u3057\u3093\u3054\u3046\u3092\u3001\u53f3\u306b\u66f2\u304c\u3063\u3066\u304f\u3060\u3055\u3044\u3002",
                    "en": "Please turn right at the third light."
                },
                {
                    "ja": "\u305d\u306e\u30ab\u30ec\u30fc\u8272\u306e\u30cd\u30af\u30bf\u30a4\u3001\u3061\u3087\u3063\u3068\u66f2\u304c\u3063\u3066\u308b\u3088\u3002",
                    "en": "Your curry colored necktie is a bit crooked."
                },
                {
                    "ja": "\u91ce\u7403\u306e\u30dc\u30fc\u30eb\u304c\u5f53\u305f\u3063\u3066\u304b\u3089\u3001\u50d5\u306e\u5c0f\u6307\u306f\u3061\u3087\u3063\u3068\u3060\u3051\u5de6\u306b\u66f2\u304c\u3063\u3066\u3044\u307e\u3059\u3002",
                    "en": "Since getting hit with a baseball my pinky finger bends slightly to the left."
                }
            ],
            "collocations": []
        }

