                "mnemonic": "\n{splitParent}The readings come from {span:lang=ja:\u898b\u308b} and {span:lang=ja:\u4ed8\u3051\u308b}. If you use those readings, you'll be able to read this word too.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u3080\u3057\u3055\u3055\u308c\u3063\u3066\u3001\u898b\u4ed8\u3051\u308b\u3068\u3068\u305f\u3093\u306b\u304b\u3086\u304f\u306a\u308b\u3088\u306a\u3002",
                    "en": "The moment you find a bug bite it makes you itchy, don't you think?"
                },
                {
                    "ja": "\u3053\u306e\u307c\u3046\u5b50\u306f\u3001\u30b3\u30a6\u30a4\u30c1\u306e\u304b\u3064\u3089\u3092\u898b\u4ed8\u3051\u308b\u305f\u3081\u306e\u624b\u304c\u304b\u308a\u306b\u306a\u308b\u304b\u3082\u3057\u308c\u307e\u305b\u3093\u3002",
                    "en": "This hat might help us find Koichi's wig."
                },
                {
                    "ja": "\u79c1\u306f\u4eca\u671d\u3001\u8679\u306e\u7aef\u306b\u3042\u308b\u3068\u8a00\u308f\u308c\u3066\u3044\u308b\u91d1\u306e\u58fa\u3092\u898b\u4ed8\u3051\u308b\u305f\u3081\u306b\u56db\u6642\u9593\u4ee5\u4e0a\u3082\u8cbb\u3084\u3057\u307e\u3057\u305f\u3002",
                    "en": "I spent over four hours this morning trying to find the pot of gold that they say is at the end of the rainbow."
                }
            ],
