            },
            "contextSentences": [
                {
                    "ja": "\u30d0\u30b9\u306b\u4e57\u3063\u3066\u3001\u6d77\u3078\u884c\u304d\u307e\u3057\u305f\u3002",
                    "en": "I took a bus to go to the sea."
                },
                {
                    "ja": "\u6771\u4eac\u30fb\u3057\u306a\u5ddd\u65b9\u3081\u3093\u884c\u304d\u3067\u306f\u306a\u304f\u3066\u3001\u4e0a\u91ce\u30fb\u6c60\u3076\u304f\u308d\u65b9\u3081\u3093\u884c\u304d\u306b\u4e57\u3063\u3066\u304f\u3060\u3055\u3044\u3002",
                    "en": "Make sure you take the train headed to Ueno and Ikebukuro and not Tokyo and Shinagawa."
                },
                {
                    "ja": "\u30b8\u30a7\u30c3\u30c8\u30b3\u30fc\u30b9\u30bf\u30fc\u306b\u4e57\u308b\u306e\u306f\u5927\u597d\u304d\u306a\u3093\u3060\u3051\u3069\u3001\u3069\u306e\u5e2d\u3082\u3044\u3064\u3082\u30b2\u30ed\u81ed\u3044\u3093\u3060\u3088\u306d\u3002",
                    "en": "I love to ride on roller coasters but they always smell like vomit."
