            "contextSentences": [
                {
                    "ja": "\u5b9f\u306f\u3001\u308f\u305f\u3057\u3001\u3053\u3046\u307f\u3048\u3066\u3082\u30aa\u30ea\u30f3\u30d4\u30c3\u30af\u306b\u51fa\u305f\u3053\u3068\u304c\u3042\u308b\u3093\u3067\u3059\u3002",
                    "en": "Well actually, even though I don\u2019t look like it, I used to be an Olympian."
                },
                {
                    "ja": "\u5b9f\u306e\u3068\u3053\u308d\u3001\u304a\u308c\u305f\u3061\u306f\u304a\u524d\u306e\u5b9f\u306e\u304a\u3084\u3058\u3083\u306a\u3044\u3093\u3060\u3088\u3002",
                    "en": "To tell you the truth, we are not your real parents."
                },
                {
                    "ja": "\u3059\u307e\u306a\u3044\u3001\u304a\u524d\u3002\u5b9f\u306f\u3001\u4ffa\u9054\u306e\u8caf\u91d1\u3092\u5168\u90e8\u3001\u30d7\u30ed\u91ce\u7403\u30ab\u30fc\u30c9\u3068\u98a8\u8239\u30ac\u30e0\u306b\u306f\u305f\u3044\u3061\u307e\u3063\u305f\u3093\u3060\u3002",
                    "en": "I\u2019m sorry, Honey. The truth is I spent all of our savings on baseball cards and bubblegum."
                }
            ],
