            },
            "contextSentences": [
                {
                    "ja": "\u3046\u3061\u306e\u304a\u5e97\u306f\u3001\u30a6\u30a7\u30b9\u30bf\u30f3\u901a\u308a\u304b\u3089\u3001\u5c11\u3057\u8def\u5730\u306b\u5165\u3063\u305f\u3068\u3053\u308d\u306b\u3042\u308a\u307e\u3059\u3002",
