            "contextSentences": [
                {
                    "ja": "\u307f\u3093\u306a\u304b\u3089\u96c6\u91d1\u3057\u3066\u3001\u82b1\u305f\u3070\u3068\u8272\u7d19\u3092\u8cb7\u3044\u307e\u3057\u305f\u3002",
