            "contextSentences": [
                {
                    "ja": "\u30e1\u30cb\u30a8\u30fc\u30eb\u75c5\u3092\u308f\u305a\u3089\u3063\u3066\u3044\u308b\u306e\u3067\u3001\u3088\u304f\u3081\u307e\u3044\u304c\u8d77\u304d\u308b\u3093\u3067\u3059\u3002",
