            "contextSentences": [
                {
                    "ja": "\u65e5\u306b\u65e5\u306b\u9032\u5316\u3057\u3066\u308b\u306e\u304c\u5b9f\u304b\u3093\u3067\u304d\u3066\u3001\u3046\u308c\u3057\u3044\u3067\u3059\u3002",
