            "contextSentences": [
                {
                    "ja": "\u3053\u306e\u3053\u308d\u306e\u305f\u3048\u5b50\u3061\u3083\u3093\u306f\u3001\u307e\u3060\u9854\u4ed8\u304d\u304c\u5b50\u3069\u3082\u3063\u307d\u3044\u306d\u3002",
