                },
                {
                    "ja": "\u3042\u306e\u30df\u30cb\u30c1\u30e5\u30a2\u30cf\u30b9\u30ad\u30fc\u306f\u3001\u3068\u3066\u3082\u308a\u308a\u3057\u3044\u9854\u4ed8\u304d\u3092\u3057\u3066\u3044\u308b\u306d\u3002",
