                {
                    "ja": "\u3046\u308f\u3041\u3001\u3059\u3063\u304b\u308a\u5927\u304d\u304f\u306a\u3063\u305f\u306d\uff01\u9854\u4ed8\u304d\u306f\u304a\u7236\u3055\u3093\u305d\u3063\u304f\u308a\u305d\u306e\u307e\u307e\u3060\u3002",
