            "contextSentences": [
                {
                    "ja": "\u3052\u3093\u3056\u3044\u306e\u4e2d\u56fd\u8a9e\u3067\u306f\u3001\u305f\u304f\u3055\u3093\u306e\u65e5\u672c\u8a9e\u304c\u5916\u6765\u8a9e\u3068\u3057\u3066\u4f7f\u308f\u308c\u3066\u3044\u307e\u3059\u3002",
                    "en": "Many Japanese words are used as loanwords in modern day Chinese."
                },
                {
                    "ja": "\u30ea\u30e5\u30c3\u30af\u30b5\u30c3\u30af\u306f\u3001\u5916\u6765\u8a9e\u3067\u3059\u304b\uff1f\u305d\u308c\u3068\u3082\u548c\u305b\u3044\u3048\u3044\u8a9e\u3067\u3059\u304b\uff1f",
                    "en": "Is rucksack a foreign word, or Engrish?"
                },
                {
                    "ja": "\u306d\u3048\u3001\u7159\u8349\u3063\u3066\u5916\u6765\u8a9e\u306a\u306e\u306b\u6f22\u5b57\u304c\u3042\u308b\u3063\u3066\u77e5\u3063\u3066\u305f\uff1f",
                    "en": "Hey, did you know that there's kanji for the word tobacco even though it\u2019s a loanword?"
