            "contextSentences": [
                {
                    "ja": "\u3044\u3064\u3082\u89aa\u5207\u306b\u3057\u3066\u3044\u305f\u3060\u3044\u3066\u3001\u3042\u308a\u304c\u3068\u3046\u3054\u3056\u3044\u307e\u3059\u3002",
