            "contextSentences": [
                {
                    "ja": "\u5927\u3059\u304d\u306a\u30c9\u30e9\u30de\u306e\u6700\u7d42\u56de\u3092\u898b\u306e\u304c\u3057\u3066\u6ce3\u3044\u305f\u3002",
