            },
            "contextSentences": [
                {
                    "ja": "\u96fb\u8eca\u3067\u3070\u304f\u3059\u3044\u3057\u3066\u3057\u307e\u3063\u3066\u3001\u7d42\u70b9\u3067\u3046\u3093\u8ee2\u624b\u3055\u3093\u306b\u8d77\u3053\u3055\u308c\u305f\u3053\u3068\u306f\u3088\u304f\u3042\u308a\u307e\u3059\u306d\u3002",
                    "en": "I often fall asleep on the train and have to be woken up by the driver at the last stop."
                },
                {
                    "ja": "\u3053\u306e\u30b7\u30ab\u30b4\u767a\u306e\u30a2\u30e0\u30c8\u30e9\u30c3\u30af\u306e\u7d42\u70b9\u306e\u99c5\u306f\u4f55\u3066\u8a00\u3046\u540d\u524d\u3067\u3059\u304b\u3002",
                    "en": "What's the name of the last stop on the Amtrak leaving from Chicago?"
                },
                {
                    "ja": "\u304a\u9858\u3044\u304c\u3042\u308b\u306e\u3002\u79c1\u304c\u305f\u3068\u3048\u4f55\u3068\u8a00\u3063\u3066\u3082\u3001\u4f55\u3092\u3057\u3088\u3046\u3068\u3082\u3001\u7d42\u70b9\u306b\u7740\u304f\u307e\u3067\u79c1\u304c\u96fb\u8eca\u304b\u3089\u964d\u308a\u306a\u3044\u3088\u3046\u306b\u3057\u3066\u3002\u5206\u304b\u3063\u305f\uff1f",
                    "en": "You have to do me a favor. No matter what I say, no matter what I do, please do not let me get out of the train until it gets to the last stop. Okay?"
