{
            "mnemonic": "You've seen the word {span:lang=ja:\u697d\u3057\u3044}, which means \"fun.\" This is obviously very similar looking, though this one means {tooltip:Vocabulary:looking forward to}. Why? Because it has a {span:lang=ja:\u307f} on the end, saying \"who is going to have fun? It's {tooltip:Reading:me}! That's why I'm looking forward to it!\"",
            "hints": "",
            "meanings": {
                "Primary": "Looking Forward To",
                "Alternatives": "Hope, Expectation, Anticipation, Pleasure, Enjoyment",
                "Word Type": "noun, \u306a adjective"
            },
            "vocabReadings": {
                "readings": [
                    {
                        "primary": true,
                        "reading": "\u305f\u306e\u3057\u307f"
                    }
                ],
                "pronunciationAudios": [
