                "mnemonic": "\n{splitParent}The reading for the kanji in this vocab is the same as the one you learned with the kanji, meaning you should be able to read this.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u6700\u8fd1\u307f\u3087\u3046\u306b\u904b\u304c\u3044\u3044\u3093\u3060\u3088\u306a\u3002",
                    "en": "I\u2019ve been really lucky lately for some reason."
                },
                {
                    "ja": "\u3053\u3093\u306a\u7f8e\u4eba\u306e\u3088\u3081\u3055\u3093\u3082\u3089\u3063\u3066\u3001\u304a\u524d\u3063\u3066\u672c\u5f53\u306b\u904b\u304c\u3044\u3044\u306a\u3002",
                    "en": "You are so lucky to have such a beautiful wife."
                },
                {
                    "ja": "\u65e5\u672c\u8a9e\u306e\u6388\u696d\u3067A\u304c\u53d6\u308c\u305f\u3093\u3060\u3051\u3069\u3001\u305f\u3060\u5358\u306b\u904b\u304c\u3088\u304b\u3063\u305f\u3060\u3051\u3060\u3068\u601d\u3046\u306e\u3002",
