                "mnemonic": "\n{splitParent}This is a jukugo word, which usually means on'yomi readings from the kanji. If you know the readings of your kanji you'll know how to read this as well.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u7236\u306f\u3001\u6bce\u671d\u65b0\u805e\u3092\u8aad\u307f\u307e\u3059\u3002",
                    "en": "My father reads the newspaper every morning."
                },
                {
                    "ja": "\u4eca\u671d\u306e\u5730\u5143\u306e\u65b0\u805e\u306e\u4e00\u3081\u3093\u3067\u30c8\u30fc\u30d5\u30b0\u3068\u3069\u30fc\u3082\u541b\u304c\u30b3\u30e9\u30dc\u3057\u3066\u3044\u305f\u3088\u3002",
                    "en": "Tofugu and Domo-kun were collaborating on the front page of the local newspaper this morning."
                },
                {
                    "ja": "\u3053\u306e\u65b0\u805e\u3059\u3063\u3052\u30fc\u5c02\u9580\u7528\u8a9e\u3060\u3089\u3051\u3058\u3083\u3093\u3002\u30b9\u30b3\u30c3\u30c8\u304c\u3053\u306e\u65b0\u805e\u3092\u4f55\u56de\u3082\u8aad\u307e\u306a\u304d\u3083\u3044\u3051\u306a\u3044\u306e\u306f\u5f53\u7136\u3060\u306a\u3002",
                    "en": "This newspaper is so highbrow. No wonder Scott had to read it so many times."
                }
            ],
            "collocations": []
        }

