        }

{
            "mnemonic": "The kanji and the word are exactly the same. That means they share meanings as well.",
            "hints": "",
            "meanings": {
                "Primary": "Parent",
                "Word Type": "noun"
            },
            "vocabReadings": {
                "readings": [
                    {
                        "primary": true,
                        "reading": "\u304a\u3084"
                    }
                ],
                "pronunciationAudios": [
                    {
                        "gender": "male",
                        "pronunciation": "\u304a\u3084",
                        "voiceActorId": 2,
                        "voiceActorName": "Kenichi",
                        "voiceDescription": "Tokyo accent",
                        "file": "3612-subject-3223.ogg"
                    },
                    {
                        "gender": "female",
                        "pronunciation": "\u304a\u3084",
                        "voiceActorId": 1,
                        "voiceActorName": "Kyoko",
                        "voiceDescription": "Tokyo accent",
                        "file": "28173-subject-3223.ogg"
                    }
                ],
                "mnemonic": "\n{splitParent}Since this word is made up of a single kanji, it should use the kun'yomi reading. When learning the kanji, you didn't learn that reading, so here's a mnemonic to help you with this word: \n{splitParent}Just imagine your parents saying {tooltip:Reading:oh yah} ({span:lang=ja:\u304a\u3084}) over and over at you. What did you do at school today? I beat up this kid. \"Oh yah?\"\n"
            },
            "contextSentences": [
                {
                    "ja": "\u308f\u305f\u3057\u306e\u89aa\u306f\u3001\u5148\u9031\u75c5\u9662\u306e\u8fd1\u304f\u306b\u5f15\u3063\u3053\u3057\u307e\u3057\u305f\u3002",
                    "en": "My parents moved near the hospital last week."
                },
                {
                    "ja": "\u3046\u3061\u306e\u89aa\u3001\u304b\u307b\u3054\u3059\u304e\u308b\u3068\u601d\u3046\u3093\u3060\u3088\u306d\u3002",
                    "en": "I think my parents are overprotective."
                },
                {
                    "ja": "\u3053\u308c\u3063\u3066\u3001\u3059\u3054\u304f\u4e0d\u516c\u5e73\u3060\u308f\uff01 \u30df\u30c9\u30ea\u306f\u79c1\u304c\u6b32\u3057\u3044\u3082\u306e\u3092\u5168\u90e8\u624b\u306b\u5165\u308c\u3066\u3001\u305d\u306e\u4e0a\u79c1\u306e\u30d1\u30d1\u3068\u30de\u30de\u304c\u89aa\u3058\u3083\u306a\u3044\u306a\u3093\u3066\uff01",
                    "en": "This is so unfair! Midori gets everything that I want. And, on top of that, she doesn\u2019t have my mom and dad for parents."
                }
            ],
            "collocations": []
        }

