                        "file": "28237-subject-3216.ogg"
                    }
                ],
                "mnemonic": "\n{splitParent}The readings are the kun'yomi readings, but they're the readings you've learned with the kanji. {span:lang=ja:\u65b9} is like many other words you've come across as well, such as {span:lang=ja:\u898b\u65b9} or {span:lang=ja:\u4f5c\u308a\u65b9}.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u697d\u3075\u306e\u8aad\u307f\u65b9\u3092\u77e5\u3089\u306a\u3044\u3002",
                    "en": "I can\u2019t read sheet music."
                },
                {
                    "ja": "\u4e09\u3060\u3093\u3089\u304f\u76ee\u306e\u4e03\u884c\u76ee\u306e\u3053\u306e\u305f\u3093\u8a9e\u306e\u8aad\u307f\u65b9\u306f\u3001\u306a\u3093\u3067\u3059\u304b\uff1f",
