                "mnemonic": "\n{splitParent}This is a jukugo word, which usually means on'yomi readings from the kanji. If you know the readings of your kanji you'll know how to read this as well.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u5730\u4e0b\u9244\u306b\u4e57\u3063\u3066\u884c\u304d\u307e\u3059\u3002",
                    "en": "I\u2019ll go on the subway."
                },
                {
                    "ja": "\u6771\u4eac\u306e\u5730\u4e0b\u9244\u306f\u304b\u306a\u308a\u3075\u304f\u3056\u3064\u3067\u3059\u3002",
                    "en": "Tokyo's subway is extremely complex."
                },
                {
                    "ja": "\u3042\u3042\u3001\u3088\u304b\u3063\u305f\uff01\u5730\u4e0b\u9244\u306b\u4e57\u308a\u9045\u308c\u3061\u3083\u3046\u304b\u3068\u601d\u3063\u305f\u3088\u3002",
                    "en": "What a relief! I thought I missed the subway train."
                }
