            "contextSentences": [
                {
                    "ja": "\u307e\u3060\u52a9\u304b\u308b\u898b\u3053\u307f\u306f\u3042\u308b\u3093\u3067\u3059\u304b\u3002",
                    "en": "Is there still a chance it will be saved?"
