                "mnemonic": "\n{splitParent}This is a jukugo word, which usually means on'yomi readings from the kanji. If you know the readings of your kanji you'll know how to read this as well.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u6240\u3068\u304f\u305c\u3044\u304c\u304f\u3092\u7b97\u5b9a\u3059\u308b\u305f\u3081\u306e\u3051\u3044\u3055\u3093\u3057\u304d\u3092\u77e5\u3063\u3066\u3044\u307e\u3059\u304b\u3002",
                    "en": "Do you know the equation to calculate your income tax?"
                },
                {
                    "ja": "\u30ef\u30cb\u30ab\u30cb\u306e\u30e6\u30fc\u30b6\u30fc\u306e\u305e\u3046\u3052\u3093\u3092\u7b97\u5b9a\u3059\u308bAI\u3092\u3084\u3068\u3044\u307e\u3057\u305f\u3002",
                    "en": "We hired an AI that can calculate WaniKani user increases and decreases."
                },
                {
                    "ja": "\u3053\u306e\u30d7\u30ed\u30b0\u30e9\u30e0\u306f\u3001\u8a72\u5f53\u30e6\u30fc\u30b6\u30fc\u306b\u9078\u629e\u3055\u308c\u305f\u30d0\u30ca\u30fc\u5e83\u544a\u306e\u63b2\u793a\u6570\u306b\u5fdc\u3058\u3066\u3001\u5e83\u544a\u8cbb\u7528\u3092\u7b97\u5b9a\u3059\u308b\u3093\u3060\u3002",
                    "en": "This program calculates the advertising cost corresponding to the number of times a banner advertisement is selected by the user."
                }
            ],
            "collocations": []
        }

