                    "ja": "\u3053\u306e\u30d1\u30fc\u30c6\u30a3\u30fc\u30de\u30b8\u3067\u3064\u307e\u3093\u306a\u3044\u3002\u9053\u3067\u30c6\u30a3\u30b7\u30e5\u3067\u3082\u914d\u3063\u3066\u308b\u65b9\u304c\u30de\u30b7\u3060\u3088\u3002",
