                {
                    "ja": "\u4e09\u6bb5\u8179\u3092\u7121\u304f\u3059\u305f\u3081\u306b\u3001\u6bce\u671d\u8d77\u304d\u305f\u3089\u3059\u3050\u306b100\u56de\u8179\u7b4b\u3092\u3057\u307e\u3059\u3002",
