                ],
                "mnemonic": "\n{splitParent}This word uses the on'yomi reading for the first kanji and the kun'yomi reading for the second kanji. That's all you have to remember, though, because you've seen both of these readings before!\n"
            },
            "contextSentences": [
                {
                    "ja": "\u5f79\u5834\u3067\u3057\u3087\u3046\u660e\u3057\u3087\u3092\u3082\u3089\u3063\u3066\u304d\u3066\u304f\u3060\u3055\u3044\u3002",
