                "mnemonic": "\n{splitParent}This is a jukugo word, which usually means on'yomi readings from the kanji. If you know the readings of your kanji you'll know how to read this as well.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u305d\u306e\u30e1\u30fc\u30eb\u3001\u79c1\u306b\u3082\u8ee2\u9001\u3057\u3066\u304f\u308c\u306a\u3044\uff1f",
                    "en": "Could you forward that email to me?"
                },
                {
                    "ja": "\u6d77\u5916\u306b\u4f4f\u3093\u3067\u3044\u308b\u65e5\u672c\u4eba\u306f\u3001\u3088\u304f\u65e5\u672c\u306e\u30a6\u30a7\u30d6\u30b5\u30a4\u30c8\u304b\u3089\u7269\u3092\u8cb7\u3063\u3066\u3001\u6d77\u5916\u306e\u4f4f\u6240\u306b\u8ee2\u9001\u3057\u3066\u3044\u307e\u3059\u3002",
                    "en": "Japanese people who reside overseas often buy things from Japanese websites and have them forwarded to the foreign addresses."
                },
                {
                    "ja": "\u90f5\u4fbf\u7269\u3092\u3053\u3061\u3089\u4f4f\u6240\u306e\u65b9\u3078\u8ee2\u9001\u3057\u3066\u9802\u304d\u305f\u3044\u3093\u3067\u3059\u304c\u3002",
