                    "ja": "\u30d3\u30a8\u30c8\u3001\u4eca\u65e5\u306f\u3061\u3087\u3063\u3068\u4e0d\u826f\u306a\u611f\u3058\u306e\u304b\u307f\u304c\u305f\u3060\u306d\u3002",
