                {
                    "ja": "\u3042\u3044\u3064\u3089\u3001\u3082\u3046\u3061\u3087\u3063\u3068\u843d\u3061\u7740\u3044\u305f\u65b9\u304c\u3044\u3044\u3088\u3002\u4e8c\u4eba\u5171\u8ca0\u3051\u305a\u5acc\u3044\u306e\u304f\u305b\u306b\u3001\u3044\u3063\u3064\u3082\u4e8c\u4eba\u3067\u7af6\u4e89\u3057\u3066\u308b\u3093\u3060\u305c\u3002",
