            "contextSentences": [
                {
                    "ja": "\u30b3\u30a6\u30a4\u30c1\u306f\u304a\u9152\u3092\u6b62\u3081\u3066\u304b\u3089\u3001\u3059\u3063\u304b\u308a\u5225\u4eba\u306b\u306a\u3063\u305f\u306d\u3002",
