            "contextSentences": [
                {
                    "ja": "\u4f55\u4e8b\u3082\u5fc3\u6301\u3061\u6b21\u3060\u3044\u3060\u3068\u601d\u3046\u3093\u3060\u3088\u306d\u3002",
