                {
                    "ja": "\u4eca\u65e5\u3042\u3063\u305f\u7537\u306b\u5fc3\u6301\u3061\u307b\u306d\u3063\u307d\u3044\u306d\u3063\u3066\u8a00\u308f\u308c\u305f\u3093\u3060\u3051\u3069\u3001\u4f55\u306a\u306e\u30a2\u30a4\u30c4\u3002",
