                {
                    "ja": "\u305d\u306e\u8001\u4eba\u306f\u3001\u4e21\u30c1\u30fc\u30e0\u306e\u9996\u4f4d\u4e89\u3044\u306b\u306f\u5168\u304f\u8208\u5473\u304c\u7121\u3044\u3088\u3046\u3060\u3063\u305f\u3002",
