            "contextSentences": [
                {
                    "ja": "\u4e00\u4f4d\u306b\u306a\u3063\u305f\u3089\u3001\u4e00\u9031\u9593\u6bce\u65e5\u304b\u3089\u3042\u3052\u3092\u4f5c\u3063\u3066\u3042\u3052\u308b\u3002",
