            "contextSentences": [
                {
                    "ja": "\u3053\u308c\u306f\u65e5\u672c\u306e\u6614\u8a71\u3067\u3059\u304b\u3002",
                    "en": "Is this a Japanese folk tale?"
                },
                {
                    "ja": "\u307e\u308b\u3067\u6614\u8a71\u306e\u4e2d\u306b\u51fa\u3066\u304f\u308b\u304a\u3072\u3081\u3055\u307e\u307f\u305f\u3044\u306d\u3002",
