            },
            "contextSentences": [
                {
                    "ja": "\u3053\u306e\u305d\u3046\u3058\u304d\u306f\u3001\u4e00\u5e74\u9593\u306e\u307b\u3057\u3087\u3046\u3057\u3087\u4ed8\u304d\u3067\u3059\u3088\u3002",
                    "en": "This vacuum cleaner comes with one year warranty."
                },
                {
                    "ja": "\u4e00\u3071\u304f\u4e8c\u98df\u4ed8\u304d\u306e\u308a\u3087\u304b\u3093\u3092\u3055\u304c\u3057\u3066\u3044\u307e\u3059\u3002",
                    "en": "I'm looking for a Japanese style hotel that includes dinner and breakfast."
