            "contextSentences": [
                {
                    "ja": "\u3053\u306e\u8fba\u308a\u3067\u306f\u3001\u8eca\u3092\u6301\u3063\u3066\u3044\u306a\u3044\u3068\u304b\u306a\u308a\u4e0d\u4fbf\u3067\u3059\u3088\u3002",
