                "mnemonic": "\n{splitParent}If you know the reading for {span:lang=ja:\u4e01\u5ea6} you'll know the reading for this too. Your knowledge should be {tooltip:Vocabulary:just right}, as they say inside my head.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u3042\u30fc\u3063\u4e01\u5ea6\u3044\u3044\u6240\u306b\uff01",
                    "en": "Wow! Speak of the devil!"
                },
                {
                    "ja": "\u5927\u304d\u3059\u304e\u305a\u3001\u5c0f\u3055\u3059\u304e\u305a\u3001\u672c\u5f53\u306b\u4e01\u5ea6\u3044\u3044\u30b5\u30a4\u30ba\u3067\u3059\u3002",
                    "en": "It's not too big or too small. It's just the right size."
