                {
                    "ja": "\u3053\u306e\u3050\u3089\u3044\u306e\u6e29\u5ea6\u304c\u4e01\u5ea6\u3044\u3044\u3067\u3059\u306d\u3002",
                    "en": "This temperature is just right."
                }
            ],
            "collocations": []
