                {
                    "ja": "\u4ffa\u306b\u306f\u4f55\u304c\u5fc5\u8981\u304b\u77e5\u3063\u3066\u308b\u304b\u3044\uff1f\u8da3\u5473\u306e\u90e8\u5c4b\u3068\u65b0\u3057\u3044\u8eca\u3060\u3088\u3002\u52b4\u50cd\u306e\u5bfe\u4fa1\u3092\u304d\u3061\u3093\u3068\u53d7\u3051\u53d6\u308b\u5fc5\u8981\u304c\u3042\u308b\u3060\u308d\uff1f",
