            "contextSentences": [
                {
                    "ja": "\u30b3\u30a6\u30a4\u30c1\u306e\u3042\u306e\u610f\u5473\u3042\u308a\u6c17\u306a\u304b\u304a\u3092\u898b\u3066\u3002",
