{
            "mnemonic": "This is the adjective version of the kanji {tooltip:Kanji:new}, so it means {tooltip:Vocabulary:new} too.",
            "hints": "",
            "meanings": {
                "Primary": "New",
                "Alternatives": "Fresh, Novel, Newly, Freshly",
                "Word Type": "adverb, \u306a adjective"
            },
            "vocabReadings": {
                "readings": [
                    {
                        "primary": true,
                        "reading": "\u3042\u3089\u305f"
                    }
                ],
                "pronunciationAudios": [
