            "contextSentences": [
                {
                    "ja": "\u5e74\u672b\u30b8\u30e3\u30f3\u30dc\u305f\u304b\u3089\u304f\u3058\u306f\u307e\u3060\u767a\u58f2\u4e2d\u3067\u3059\u304b\uff1f",
                    "en": "Is the Year-End Jumbo Draw Lottery still for sale?"
                },
                {
                    "ja": "\u3053\u308c\u306f\u3001\u30c8\u30fc\u30d5\u30b0\u30b9\u30c8\u30a2\u3067\u767a\u58f2\u4e2d\u306e\u624b\u306c\u3050\u3044\u3067\u3059\u3002",
