                "mnemonic": "\n{splitParent}This is a jukugo word, which usually means on'yomi readings from the kanji. If you know the readings of your kanji you'll know how to read this as well.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u30b9\u30bf\u30d0\u306e\u6ce8\u6587\u306e\u4ed5\u65b9\u304c\u3044\u307e\u3044\u3061\u3088\u304f\u5206\u304b\u3089\u306a\u3044\u3093\u3060\u3051\u3069\u3002",
                    "en": "I don't really understand how to order at Starbucks."
                },
                {
                    "ja": "\u307e\u3055\u304b\u6ce8\u6587\u3059\u308b\u306e\u3092\u308f\u3059\u308c\u3066\u305f\u308a\u3057\u306a\u3044\u3088\u306d\u3002",
                    "en": "You didn't forget to place an order, did you?"
                },
