                    "ja": "\u30b3\u30a6\u30a4\u30c1\u738b\u306e\u547d\u4ee4\u306b\u306f\u5168\u3066\u3057\u305f\u304c\u308f\u306a\u304f\u3066\u306f\u3044\u3051\u306a\u3044\u3002",
