            "contextSentences": [
                {
                    "ja": "\u4e07\u304c\u4e00\u306e\u6642\u306b\u305d\u306a\u3048\u3066\u3001\u30de\u30c3\u30c1\u3068\u308d\u3046\u305d\u304f\u3092\u7528\u610f\u3057\u307e\u3057\u305f\u3002",
