            "contextSentences": [
                {
                    "ja": "\u307c\u3046\u516c\u5171\u3057\u305b\u3064\u3067\u30dc\u30e9\u30f3\u30c6\u30a3\u30a2\u3092\u3057\u3066\u3044\u305f\u3053\u3068\u304c\u3042\u308a\u307e\u3059\u3002",
                    "en": "I used to volunteer at a public facility."
                },
                {
                    "ja": "\u516c\u5171\u3068\u306f\u4e00\u4f53\u4f55\u306a\u306e\u304b\u3001\u4eca\u4e00\u5ea6\u8003\u3048\u76f4\u3057\u3066\u307f\u3066\u307b\u3057\u3044\u3002",
                    "en": "Once again, I want you to think about what public actually means."
