                "Alternatives": "Rich, Wealthy",
                "Word Type": "noun"
            },
            "vocabReadings": {
                "readings": [
                    {
                        "primary": true,
                        "reading": "\u304b\u306d\u3082\u3061"
                    }
                ],
                "pronunciationAudios": [
                    {
                        "gender": "female",
                        "pronunciation": "\u304b\u306d\u3082\u3061",
                        "voiceActorId": 1,
                        "voiceActorName": "Kyoko",
                        "voiceDescription": "Tokyo accent",
