            },
            "contextSentences": [
                {
                    "ja": "\u898b\u4e8b\u306a\u307e\u3064\u306e\u6728\u3067\u3059\u306d\u3002",
                    "en": "It\u2019s a splendid pine tree, isn\u2019t it?"
                },
                {
                    "ja": "\u304a\u898b\u4e8b\uff01\u3044\u3084\u30fc\u3001\u5b9f\u306b\u898b\u4e8b\u306a\u30b7\u30e5\u30fc\u30c8\u3060\u3063\u305f\uff01",
                    "en": "Splendid! Wow, that was such a beautiful shoot!"
                },
                {
                    "ja": "\u6c17\u6301\u3061\u3044\u3044\u3050\u3089\u3044\u898b\u4e8b\u306b\u30d5\u30e9\u308c\u305f\u3088\u3002",
                    "en": "She rejected me magnificently clearly."
                }
            ],
            "collocations": []
