            "contextSentences": [
                {
                    "ja": "\u3046\u3061\u306e\u5e02\u3067\u306f\u3001\u30b4\u30df\u3057\u3085\u3046\u96c6\u8eca\u306e\u4ee3\u308f\u308a\u306b\u6226\u8eca\u304c\u4f7f\u308f\u308c\u308b\u3053\u3068\u306b\u306a\u308a\u307e\u3057\u305f\u3002",
