            "contextSentences": [
                {
                    "ja": "\u30df\u30fc\u30c6\u30a3\u30f3\u30b0\u306e\u5834\u6240\u306f\u3001\u304a\u5ba2\u3055\u307e\u304c\u6307\u5b9a\u3057\u307e\u3057\u305f\u3002",
                    "en": "The meeting place was designated by the client."
                },
                {
                    "ja": "\u30a6\u30a7\u30d6\u3067\u30c1\u30b1\u30c3\u30c8\u3092\u4e88\u3084\u304f\u3057\u3066\u3082\u3001\u81ea\u5206\u3067\u305b\u304d\u3092\u6307\u5b9a\u3059\u308b\u3053\u3068\u306f\u3067\u304d\u307e\u3059\u304b\u3002",
                    "en": "If I book a ticket on the web, can I still choose my seat?"
                },
                {
                    "ja": "\u5411\u3053\u3046\u306b\u6307\u5b9a\u3055\u308c\u305f\u55ab\u7159\u30a8\u30ea\u30a2\u304c\u3042\u308b\u304b\u3089\u3001\u79c1\u306b\u3058\u3083\u306a\u304f\u3066\u305d\u3053\u306b\u884c\u3063\u3066\u55ab\u7159\u8005\u304c\u3069\u308c\u3060\u3051\u81ed\u3044\u304b\u306b\u3064\u3044\u3066\u6587\u53e5\u3092\u8a00\u3063\u305f\u65b9\u304c\u3044\u3044\u3093\u3058\u3083\u306a\u3044\u3002",
