                    {
                        "gender": "female",
                        "pronunciation": "\u304b\u3048\u308b",
                        "voiceActorId": 1,
                        "voiceActorName": "Kyoko",
                        "voiceDescription": "Tokyo accent",
                        "file": "28411-subject-3490.ogg"
                    }
                ],
                "mnemonic": "\n{splitParent}The reading is the same as {span:lang=ja:\u8fd4\u3059}, so as long as you know that you'll be able to apply it here to learn the reading of this word as well.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u308f\u308c\u306b\u8fd4\u308b\u3068\u3001\u304b\u308c\u306f\u30c8\u30fc\u30d5\u30b0\u30aa\u30d5\u30a3\u30b9\u306e\u30bd\u30d5\u30a1\u30fc\u306b\u6a2a\u305f\u308f\u3063\u3066\u3044\u305f\u3002",
                    "en": "When he came to, he was lying on the sofa in the Tofugu office."
                },
                {
                    "ja": "\u5931\u304f\u3057\u305f\u3068\u601d\u3063\u3066\u3044\u305f\u5927\u4e8b\u306a\u6bcd\u306e\u5f62\u898b\u306e\u30da\u30f3\u30c0\u30f3\u30c8\u304c\u6c17\u3065\u3044\u305f\u3089\u624b\u5143\u306b\u8fd4\u3063\u3066\u304d\u3066\u3044\u305f\u3002",
                    "en": "The precious keepsake pendant from my mom that I thought I'd lost was returned to me before I knew it."
                },
                {
                    "ja": "\u8cb8\u3057\u305f\u304a\u91d1\u304c\u3061\u3083\u3093\u3068\u8fd4\u3063\u3066\u304f\u308b\u3068\u601d\u3063\u305f\u3089\u5927\u9593\u9055\u3044\u3088\u3002",
                    "en": "Thinking my money would be returned properly was a huge mistake."
                }
            ],
            "collocations": []
        }

{
