                "mnemonic": "\n{splitParent}You've learned this reading already, so you should know how to read this word!\n"
            },
            "contextSentences": [
                {
                    "ja": "\u65e5\u672c\u306b\u306f\u3001\u4e8c\u3068\u3092\u8ffd\u3046\u3082\u306e\u306f\u4e00\u3068\u3092\u3082\u3048\u305a\u3001\u3068\u3044\u3046\u3053\u3068\u308f\u3056\u304c\u3042\u308a\u307e\u3059\u3002",
                    "en": "In Japan, there is a proverb that says, \"If you chase after two hares, you will catch neither.\""
                },
                {
                    "ja": "\u30b3\u30a6\u30a4\u30c1\u306f\u3001\u3044\u3064\u3082\u6700\u65b0\u306e\u308a\u3085\u3046\u884c\u3092\u8ffd\u3063\u3066\u3044\u308b\u3002",
                    "en": "Koichi is always following the latest trends."
                },
                {
                    "ja": "\u3069\u3093\u306a\u306b\u5927\u5909\u3067\u3082\u3001\u79c1\u306f\u81ea\u5206\u306e\u5922\u3092\u8ffd\u3044\u7d9a\u3051\u308b\u3064\u3082\u308a\u306a\u306e\u3002",
                    "en": "I will keep following my dreams, no matter how hard it gets."
                }
