            "contextSentences": [
                {
                    "ja": "\u307f\u3093\u306a\u304c\u96c6\u4e2d\u3059\u308c\u3070\u3053\u306e\u4ed5\u4e8b\u306f\u4e94\u6642\u307e\u3067\u306b\u7d42\u308f\u308b\u306f\u305a\u3060\u3088\u3002",
                    "en": "This work should be done by five if everyone concentrates."
                },
                {
                    "ja": "\u4eca\u306f\u3001\u4e00\u756a\u5927\u4e8b\u306a\u4ed5\u4e8b\u306b\u6ce8\u610f\u3092\u96c6\u4e2d\u3055\u305b\u305f\u65b9\u304c\u3044\u3044\u3088\u3002",
