            },
            "contextSentences": [
                {
                    "ja": "\u30b3\u30a6\u30a4\u30c1\u306e\u8d64\u3061\u3083\u3093\u306e\u540d\u524d\u304c\u6c7a\u5b9a\u3057\u305f\u3089\u3001\u3059\u3050\u306b\u304a\u77e5\u3089\u305b\u3057\u307e\u3059\u306d\u3002",
                    "en": "Once they've decided on a name for Koichi's baby I'll let you know right away."
                },
                {
                    "ja": "\u30b3\u30a6\u30a4\u30c1\u306f\u3001\u3058\u3085\u3046\u696d\u3044\u3093\u306e\u304d\u3085\u3046\u308a\u3087\u3046\u3092\u6c7a\u5b9a\u3059\u308b\u3051\u3093\u5229\u3092\u6301\u3063\u3066\u3044\u308b\u3002",
                    "en": "Koichi has the right to decide his employee's salaries."
                },
                {
                    "ja": "\u30af\u30bd\u30ef\u30ed\u30bfwww\u3053\u306e\u30c6\u30ec\u30d3\u756a\u7d44\u30af\u30bd\u307b\u3069\u9762\u767d\u3044\u3058\u3083\u306d\u30fc\u304b\u3088\u3002\u4ffa\u306e\u4e00\u756a\u597d\u304d\u306a\u756a\u7d44\u306b\u6c7a\u5b9a\u3057\u305f\u308f\u3002",
                    "en": "ROFL! This TV show is hilarious, man. I\u2019ve decided that this is now my new favorite show."
                }
            ],
