            },
            "contextSentences": [
                {
                    "ja": "\u3078\u3092\u3053\u304f\u6642\u306f\u4fbf\u6240\u306b\u884c\u3051\u3088\u3002",
                    "en": "You should go to the bathroom when you fart."
                },
                {
                    "ja": "\u30b5\u30c8\u30b7\u3001\u3088\u3046\u3084\u304f\u4fbf\u6240\u305d\u3046\u3058\u306e\u30b9\u30a4\u30c3\u30c1\u304c\u5165\u3063\u305f\u307f\u305f\u3044\u3060\u306d\u3002",
                    "en": "It seems that Satoshi finally got serious about cleaning the bathroom."
                },
                {
                    "ja": "\u3088\u3063\u3057\u3083\uff01\u5b8c\u74a7\u306a\u30b7\u30e5\u30fc\u30c8\u304c\u6c7a\u307e\u3063\u305f\u305c\uff01\u4ffa\u3001\u3053\u3053\u306e\u4fbf\u6240\u306e\u30d0\u30b9\u30b1\u30c3\u30c8\u30b4\u30fc\u30eb\u4ed8\u304d\u306e\u30b4\u30df\u7bb1\u3081\u3063\u3061\u3083\u597d\u304d\u3060\u308f\u3002",
                    "en": "Oh yeah! Nothing but net! I really love that this restroom\u2019s trashcan has a basketball net on it."
                }
            ],
            "collocations": []
        }

