            "contextSentences": [
                {
                    "ja": "\u30a4\u30e1\u30fc\u30b8\u30c8\u30ec\u30fc\u30cb\u30f3\u30b0\u3068\u3058\u3085\u3093\u3073\u3046\u3093\u3069\u3046\u306f\u6b20\u304b\u3059\u306a\uff01",
