                {
                    "ja": "\u3069\u306e\u793e\u3044\u3093\u3082\u307f\u3093\u306a\u3001\u30c8\u30fc\u30d5\u30b0\u306b\u3068\u3063\u3066\u6b20\u304b\u3059\u3053\u3068\u306e\u3067\u304d\u306a\u3044\u793e\u3044\u3093\u3067\u3059\u3002",
