                        "primary": true,
                        "reading": "\u3064\u305f\u3048\u308b"
                    }
                ],
                "pronunciationAudios": [
                    {
                        "gender": "male",
                        "pronunciation": "\u3064\u305f\u3048\u308b",
                        "voiceActorId": 2,
                        "voiceActorName": "Kenichi",
