            "contextSentences": [
                {
                    "ja": "\u4e57\u308a\u7269\u306e\u4e2d\u3067\u30bf\u30d0\u30b3\u3092\u3059\u308f\u306a\u3044\u3067\u304f\u3060\u3055\u3044\u3002",
