                },
                {
                    "ja": "\u5927\u3078\u3093\u3060\uff01\u30b3\u30a6\u30a4\u30c1\u304c\u6ce2\u306b\u98f2\u307f\u3053\u307e\u308c\u305f\u305e\u30fc\uff01",
                    "en": "OMG! Koichi has been swallowed by a wave!"
                },
                {
                    "ja": "\u6ce2\u306b\u3086\u3089\u3086\u3089\u63fa\u3089\u308c\u308b\u306e\u304c\u6c17\u6301\u3061\u3044\u3044\u3002",
