            "contextSentences": [
                {
                    "ja": "\u5b50\u3069\u3082\u306e\u304f\u305b\u306b\u30b9\u30eb\u30e1\u304c\u3059\u304d\u3060\u306a\u3093\u3066\u3001\u3053\u308a\u3083\u3041\u3053\u306e\u5b50\u306f\u3057\u3087\u3046\u6765\u9152\u98f2\u307f\u306b\u306a\u308b\u306d\u3047\u3002",
