                        "primary": true,
                        "reading": "\u304b\u3063\u3066"
                    }
                ],
                "pronunciationAudios": [
                    {
                        "gender": "male",
                        "pronunciation": "\u304b\u3063\u3066",
                        "voiceActorId": 2,
                        "voiceActorName": "Kenichi",
                        "voiceDescription": "Tokyo accent",
                        "file": "4407-subject-3567.ogg"
