            },
            "contextSentences": [
                {
                    "ja": "\u304a\u305d\u3046\u3057\u304d\u306e\u5f8c\u306b\u3001\u8840\u65cf\u306e\u96c6\u307e\u308a\u304c\u3042\u308a\u307e\u3059\u3002",
