                    "ja": "\u79c1\u306e\u7236\u306f\u8840\u65cf\u3058\u3083\u306a\u3044\u304c\u3001\u305d\u308c\u3067\u3082\u672c\u5f53\u306e\u7236\u306e\u3088\u3046\u306b\u601d\u3063\u3066\u3044\u308b\u3002",
