                        "voiceActorId": 1,
                        "voiceActorName": "Kyoko",
                        "voiceDescription": "Tokyo accent",
                        "file": "28636-subject-3323.ogg"
                    }
                ],
                "mnemonic": "\n{splitParent}Since this word is made up of a single kanji, it should use the kun'yomi reading. When learning the kanji, you didn't learn that reading, so here's a mnemonic to help you with this word: You smell someone's {tooltip:Reading:icky} ({span:lang=ja:\u3044\u304d}) {tooltip:Vocabulary:breath}. It's gross. Your skin crawls and your eyes roll back in your head from the icky, icky smell. You might die.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u3042\u3093\u305f\u306e\u606f\u3001\u6b7b\u306c\u307b\u3069\u304f\u3055\u3044\u3088\u3002",
                    "en": "Your breath is so stinky that I could die."
                },
                {
                    "ja": "\u3073\u3063\u304f\u308a\u3057\u3059\u304e\u3066\u3001\u606f\u304c\u6b62\u307e\u308b\u304b\u3068\u601d\u3063\u305f\u3088\u3002",
                    "en": "You knocked the breath out of me!"
                },
                {
                    "ja": "\u6c34\u4e2d\u3067\u606f\u306f\u3057\u306a\u3044\u3067\u304f\u3060\u3055\u3044\u3002",
                    "en": "Please do not breathe underwater."
                }
            ],
            "collocations": []
        }

