            "contextSentences": [
                {
                    "ja": "\u4e00\u3057\u3087\u306b\u5546\u58f2\u3057\u3066\u4e00\u3082\u3046\u3051\u3057\u3088\u3046\u305c\uff01",
                    "en": "Let's go into business and make a fortune together!"
                },
                {
                    "ja": "\u6700\u8fd1\u306f\u3042\u306e\u30b3\u30f3\u30d3\u30cb\u306e\u305b\u3044\u3067\u3001\u5546\u58f2\u3042\u304c\u3063\u305f\u308a\u3060\u306d\u3002",
                    "en": "My business has dried up recently because of that convenience store."
