{
            "mnemonic": "The {tooltip:Kanji:action}s and {tooltip:Kanji:things} you have to {span:lang=ja:\u5fc3\u914d} about are your {tooltip:Vocabulary:cares} and {tooltip:Vocabulary:worries}.",
