            "contextSentences": [
                {
                    "ja": "\u7b2c\u4e00\u7ae0\u306f\u304a\u3082\u3057\u308d\u304b\u3063\u305f\u3051\u3069\u3001\u7b2c\u4e8c\u7ae0\u306f\u3044\u307e\u3044\u3061\u3060\u3063\u305f\u3002",
