                {
                    "ja": "\u65e5\u672c\u8a9e\u306e\u97f3\u8aad\u307f\u3068\u8a13\u8aad\u307f\u306e\u9055\u3044\u306f\u4f55\u3067\u3059\u304b\uff1f",
