            "mnemonic": "The {tooltip:Kanji:leaf} that {tooltip:Kanji:fall}s are {tooltip:Vocabulary:fallen leaves}.",
            "hints": "",
            "meanings": {
                "Primary": "Fallen Leaves",
                "Alternative": "Fallen Leaf",
                "Word Type": "noun, \u306e adjective"
            },
            "vocabReadings": {
                "readings": [
