                ],
                "pronunciationAudios": [
                    {
                        "gender": "male",
                        "pronunciation": "\u304b\u305e\u304f",
                        "voiceActorId": 2,
                        "voiceActorName": "Kenichi",
                        "voiceDescription": "Tokyo accent",
                        "file": "4726-subject-3361.ogg"
                    },
                    {
                        "gender": "female",
                        "pronunciation": "\u304b\u305e\u304f",
                        "voiceActorId": 1,
                        "voiceActorName": "Kyoko",
                        "voiceDescription": "Tokyo accent",
                        "file": "28678-subject-3361.ogg"
                    }
                ],
                "mnemonic": "\n{splitParent}This is a jukugo word, which usually means on'yomi readings from the kanji. If you know the readings of your kanji you'll know how to read this as well.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u308f\u305f\u3057\u306e\u5bb6\u65cf\u306f\u3001\u5ead\u3067\u30ad\u30e5\u30a6\u30ea\u3084\u30c8\u30de\u30c8\u3001\u30ba\u30c3\u30ad\u30fc\u30cb\u306a\u3069\u305f\u304f\u3055\u3093\u306e\u91ce\u3055\u3044\u3092\u80b2\u3066\u3066\u3044\u307e\u3059\u3002",
                    "en": "My family grows a lot of vegetables in our garden, things like cucumbers, tomatoes, and zucchinis."
                },
                {
                    "ja": "\u5bb6\u65cf\u304c\u306a\u304f\u306a\u3063\u305f\u5834\u5408\u3001\u305d\u306e\u3058\u3085\u3046\u696d\u3044\u3093\u306f\u6b7b\u4ea1\u767a\u751f\u65e5\u306e\u6b21\u306e\u51fa\u304d\u3093\u65e5\u304b\u3089\u4e09\u65e5\u9593\u3051\u3044\u3061\u3087\u3046\u4f11\u304b\u3092\u53d6\u5f97\u3067\u304d\u307e\u3059\u3002",
                    "en": "When a member of an employee's immediate family dies, the employee is entitled to leave on any normal working day that falls within the three-day period immediately following the day the death occurred."
                },
                {
                    "ja": "\u4eca\u5ea6\u3001\u4ffa\u306e\u65e5\u672c\u3078\u306e\u5bb6\u65cf\u65c5\u884c\u306e\u3053\u3068\u3092\u541b\u306b\u8a71\u3057\u305f\u3044\u306a\u3002",
                    "en": "I wanna tell you about my family vacation in Japan some time."
                }
            ],
            "collocations": []
        }

