            "hints": "",
            "meanings": {
                "Primary": "Festival",
                "Word Type": "noun"
            },
            "vocabReadings": {
                "readings": [
                    {
                        "primary": true,
                        "reading": "\u307e\u3064\u308a"
                    }
                ],
                "pronunciationAudios": [
                    {
                        "gender": "male",
                        "pronunciation": "\u307e\u3064\u308a",
