                        "file": "28623-subject-3372.ogg"
                    }
                ],
                "mnemonic": "\n{splitParent}The reading is on'yomi because it's a jukugo kanji. Be careful of the {span:lang=ja:\u4e00} though. It gets shortened and has a little {span:lang=ja:\u3063} in there.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u30d8\u30d3\u305f\u3061\u306f\u4e00\u968e\u3067\u304b\u3063\u3066\u3044\u308b\u3093\u3067\u3059\u304b\uff1f",
                    "en": "Do you have those snakes on the first floor?"
                },
                {
                    "ja": "\u4e00\u968e\u306f\u307e\u3060\u307e\u3060\u3073\u3061\u3087\u3073\u3061\u3087\u3060\u3088\u3002",
                    "en": "The ground floor is still wet."
                },
                {
                    "ja": "\u300c\u8377\u7269\u306f\u3069\u3053\u306b\u7f6e\u3044\u305f\u3089\u3044\u3044\u304b\u306a\uff1f\u300d\u300c\u4e00\u968e\u3067\u3082\u3001\u4e8c\u968e\u3067\u3082\u3001\u4e0b\u3067\u3082\u3001\u3069\u3053\u3067\u3082\u3002\u3042\u306a\u305f\u306e\u597d\u304d\u306a\u3068\u3053\u308d\u306b\u7f6e\u3044\u3066\u304f\u308c\u3066\u3044\u3044\u3088\u3002\u300d\u300c\u308f\u304b\u3063\u305f\u308f\u3002\u6709\u96e3\u3046\u3002\u300d",
                    "en": "\"Where should I put my stuff?\" \"Here, the first floor, the second floor, anywhere. You can put them any place you\u2019d like.\" \"Okay. Thank you.\""
                }
            ],
            "collocations": []
        }

