            "contextSentences": [
                {
                    "ja": "\u30c8\u30fc\u30d5\u30b0\u306f\u30e6\u30cb\u30fc\u30af\u306a\u65e5\u672c\u8a9e\u5b66\u7fd2\u6559\u3056\u3044\u3068\u3057\u3066\u3001\u4e94\u5e74\u308c\u3093\u305e\u304f\u7b2c\u4e00\u4f4d\u306e\u3056\u3092\u304b\u304f\u3068\u304f\u3057\u3066\u3044\u307e\u3059\u3002",
