                    "ja": "\u30b3\u30a6\u30a4\u30c1\u306f\u3001\u4e5d\u5341\u4e5d\u968e\u3060\u3066\u306e\u30de\u30f3\u30b7\u30e7\u30f3\u306e\u6700\u4e0a\u968e\u306b\u4f4f\u3093\u3067\u3044\u307e\u3059\u3002",
