{
            "mnemonic": "The {tooltip:Kanji:mother} {tooltip:Kanji:parent} is the {tooltip:Vocabulary:mother}.",
            "hints": "",
            "meanings": {
                "Primary": "Mother",
                "Alternative": "Mom",
