            "contextSentences": [
                {
                    "ja": "\u6614\u3001\u3042\u306e\u5e97\u54e1\u306e\u5f1f\u306b\u5bb6\u5ead\u6559\u3057\u306e\u30d0\u30a4\u30c8\u3067\u82f1\u8a9e\u3092\u6559\u3048\u3066\u3044\u307e\u3057\u305f\u3002",
                    "en": "I used to have a part time job where I taught English to the younger brother of that clerk."
                },
                {
                    "ja": "\u3042\u306e\u5e97\u54e1\u3055\u3093\u3001\u3068\u3063\u3066\u3082\u304a\u8336\u76ee\u3060\u3063\u305f\u306d\u3002",
                    "en": "That shop employee was a real kidder, wasn't he?"
                },
                {
                    "ja": "\u3048\u3063\u3068\u3001\u30ec\u30b8\u306e\u9806\u756a\u5f85\u3061\u306e\u5217\u306b\u4e26\u3093\u3067\u3044\u308b\u6642\u306b\u3001\u3042\u308b\u5e97\u54e1\u3055\u3093\u304c\u300c\u4e07\u5f15\u304d\u3067\u3059\uff01\u6355\u307e\u3048\u3066\uff01\u300d\u3068\u53eb\u3076\u306e\u304c\u805e\u3053\u3048\u305f\u306e\u3067\u3001\u5f7c\u3092\u6355\u307e\u3048\u305f\u3093\u3067\u3059\u3002",
