                "mnemonic": "\n{splitParent}This word uses on'yomi readings of the kanji you learned, twice. You should be able to read this on your own.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u305d\u306e\u4f1a\u793e\u54e1\u306f\u3001\u3044\u3064\u3082\u7740\u3005\u3068\u4ed5\u4e8b\u3092\u3053\u306a\u3057\u3066\u3044\u305f\u3002",
                    "en": "That office worker always got tasks done steadily."
                },
                {
                    "ja": "\u30d7\u30ed\u30b8\u30a7\u30af\u30c8\u306f\u7740\u3005\u9032\u3093\u3067\u3044\u308b\u3088\u3046\u3060\u306d\u3002",
                    "en": "It seems like you're making steady progress on the project."
                },
                {
                    "ja": "\u624b\u306f\u305a\u306f\u7740\u3005\u3068\u6574\u3063\u3066\u3044\u307e\u3059\u3088\u3002",
                    "en": "The arrangements for it have been moving along steadily."
                }
            ],
            "collocations": []
        }

{
            "mnemonic": "{tooltip:Kanji:Hot water}'s {tooltip:Kanji:energy} isn't the hot water itself, it's what comes out of it (when it's boiling, for example). This is the {tooltip:Vocabulary:steam} and {tooltip:Vocabulary:vapor}.",
            "hints": "",
            "meanings": {
                "Primary": "Steam",
                "Alternative": "Vapor",
                "Word Type": "noun"
            },
            "vocabReadings": {
                "readings": [
                    {
                        "primary": true,
                        "reading": "\u3086\u3052"
