            "contextSentences": [
                {
                    "ja": "\u30a2\u30e1\u30ea\u30ab\u4eba\u3068\u65e5\u672c\u4eba\u3063\u3066\u3001\u6e29\u5ea6\u306e\u304b\u3093\u3058\u65b9\u304c\u3061\u304c\u3046\u3068\u601d\u3044\u307e\u3059\u304b\uff1f",
                    "en": "Do you think American and Japanese people feel temperature differently?"
                },
                {
                    "ja": "\u30a8\u30a2\u30b3\u30f3\u306e\u6e29\u5ea6\u3092\u4e8c\u5341\u56db\u5ea6\u307e\u3067\u4e0a\u3052\u3066\u3082\u3089\u3048\u307e\u305b\u3093\u304b\uff1f",
                    "en": "Can you raise the temperature on the AC up to 24\u2103?"
