            "contextSentences": [
                {
                    "ja": "\u30ef\u30cb\u30ab\u30cb\u306e\u30ec\u30d3\u30e5\u30fc\u306e\u6570\u304c\u56db\u500d\u306b\u306a\u3063\u3066\u3057\u307e\u3063\u305f\u3002",
