            "contextSentences": [
                {
                    "ja": "\u3053\u306e\u9577\u304f\u3066\u304d\u3085\u3046\u306a\u3055\u304b\u3092\u767b\u308b\u306e\u306f\u304b\u306a\u308a\u30ad\u30c4\u30a4\u3063\u3059\u306d\u3002",
                    "en": "Going up this long, steep slope is really tough, eh?"
                },
