                    "ja": "\u4e00\u751f\u306e\u5185\u3001\u5c11\u306a\u304f\u3068\u3082\u4e00\u5ea6\u306f\u5bcc\u58eb\u5c71\u306b\u767b\u308b\u3053\u3068\u304c\u5922\u306a\u3093\u3067\u3059\u3002",
