                    "ja": "\u3053\u308c\u4ee5\u4e0a\u3001\u79c1\u3092\u82e6\u3057\u3081\u306a\u3044\u3067\uff01",
                    "en": "Don't hurt me anymore!"
                },
                {
                    "ja": "\u7c73\u4e0d\u8db3\u304c\u5168\u65e5\u672c\u306e\u56fd\u6c11\u3092\u82e6\u3057\u3081\u3066\u3044\u308b\u3002",
