                    }
                ],
                "mnemonic": "\n{splitParent}You haven't learned this reading for {span:lang=ja:\u690d} yet, so here's a mnemonic to help you:\n{splitParent}You decided {tooltip:Vocabulary:to plant} an {tooltip:Reading:u}ni ({span:lang=ja:\u3046}) tree in your backyard. That's right, you can plant uni and they'll grow like fruit off a really spiky tree. Just picture it. And then you'll get to eat all the uni you want!\n"
            },
            "contextSentences": [
                {
                    "ja": "\u30c8\u30fc\u30d5\u30b0\u30aa\u30d5\u30a3\u30b9\u306e\u5c4b\u4e0a\u306b\u306f\u30b5\u30dc\u30c6\u30f3\u304c\u690d\u3048\u3066\u3042\u308a\u307e\u3059\u3002",
                    "en": "There are some cacti planted on the rooftop of the Tofugu office."
                },
                {
                    "ja": "\u30c1\u30e5\u30fc\u30ea\u30c3\u30d7\u3001\u3061\u3087\u3063\u3068\u690d\u3048\u3059\u304e\u306a\u3050\u3089\u3044\u690d\u3048\u305f\u3093\u3058\u3083\u306a\u3044\uff1f",
                    "en": "I think you've planted more than enough tulips."
