                    }
                ],
                "mnemonic": "\n{splitParent}You want to find a pet {tooltip:Vocabulary:to suit} your personal style, so you get matched with an {tooltip:Reading:a}ardvark ({span:lang=ja:\u3042}). An aardvark will match the ant mounds you use for chairs and couches, it's the perfect match.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u8089\u308a\u3087\u3046\u308a\u306b\u306f\u8d64\u30ef\u30a4\u30f3\u304c\u5408\u3044\u307e\u3059\u3002",
                    "en": "Red wine pairs well with meat dishes."
                },
                {
                    "ja": "\u5408\u3046\u304b\u3069\u3046\u304b\u3001\u3057\u3061\u3083\u304f\u3057\u3066\u304b\u304f\u306b\u3093\u3057\u305f\u65b9\u304c\u3044\u3044\u3088\u3002",
                    "en": "You should try it on to see if it suits you."
                },
                {
                    "ja": "\u30a2\u30e1\u30ea\u30ab\u306e\u30a4\u30f3\u30c9\u6599\u7406\u306f\u3001\u30a2\u30e1\u30ea\u30ab\u4eba\u306e\u53e3\u306b\u5408\u3046\u3088\u3046\u3001\u5b9f\u969b\u306e\u30a4\u30f3\u30c9\u3067\u306e\u8abf\u7406\u65b9\u6cd5\u3068\u306f\u304b\u306a\u308a\u9055\u3063\u305f\u65b9\u6cd5\u3067\u4f5c\u3089\u308c\u3066\u3044\u308b\u3002",
                    "en": "Indian cuisine in America is altered quite a bit from how it\u2019s prepared in India to suit American tastes."
                }
            ],
