                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "None",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Genghis Khan's horse and sword materialize out of your feelings and you ride toward the drunkard who made you feel these things.",
                "mnemonic": "This {tooltip:Kanji:feeling} wells up in you and bursts forth. You feel mad, you feel like you want revenge, you feel like Genghis {tooltip:Reading:Khan} ({span:lang=ja:\u304b\u3093}) reborn! And you will have your revenge on this drunkard."
            }
        }

{
            "mnemonic": "A {tooltip:Radical:sheep} in the {tooltip:Radical:water} by a {tooltip:Radical:tree} has the {tooltip:Kanji:formal name title} of Sir Wilburt Coddington III. When he\u2019s not in his castle, Sir Wilburt Coddington III enjoys playing in water and by trees. He\u2019s a royal sheep. ",
            "hints": "Picture how Sir Wilburt Coddington III obtained his formal name title. He must have done some pretty amazing things, even for a sheep. Just imagine the feats he must have accomplished.",
            "meanings": {
                "Primary": "Formal Name Title",
                "Alternatives": "Formal Name Ender, Manner"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u3088\u3046",
                        "primary": false
                    },
                    {
                        "name": "Kun\u2019yomi",
