                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "None",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Picture this cult leader gathering a hundred million people into Oklahoma. It\u2019d be awfully crowded. Imagine yourself being stifled by the bodies of a hundred million other people.",
                "mnemonic": "The cult leader has his headquarters in {tooltip:Reading:Ok}lahoma ({span:lang=ja:\u304a\u304f}). Are there a {tooltip:Kanji:hundred million} people in Oklahoma? No, probably not. But hey, this leader is shooting for the stars. First Oklahoma, then the universe!"
            }
        }

{
            "mnemonic": "There's {tooltip:Radical:treasure} in this {tooltip:Radical:tree} so you take out your {tooltip:Radical:weapon} and {tooltip:Kanji:kill} it.",
