            },
            "contextSentences": [
                {
                    "ja": "\u98df\u3079\u653e\u984c\u306b\u884c\u304f\u3068\u3044\u3064\u3082\u98df\u3079\u3059\u304e\u3066\u3057\u307e\u3044\u307e\u3059\u3002",
                    "en": "Every time I go to an all-you-can-eat restaurant, I end up eating too much."
                },
                {
                    "ja": "\u30ab\u30e9\u30aa\u30b1\u306b\u884c\u304f\u306a\u3089\u3001\u671d\u307e\u3067\u6b4c\u3044\u653e\u984c\u306e\u30d7\u30e9\u30f3\u306b\u3057\u3088\u3046\u3088\u3002",
