            "contextSentences": [
                {
                    "ja": "\u30b3\u30a6\u30a4\u30c1\u304c\u672c\u5f53\u306b\u8089\u3092\u98df\u3079\u3089\u308c\u306a\u3044\u304b\u306f\u7591\u554f\u3067\u3059\u3002",
