                        "file": "5183-subject-3614.ogg"
                    },
                    {
                        "gender": "female",
                        "pronunciation": "\u306d\u3063\u3057\u3093",
                        "voiceActorId": 1,
                        "voiceActorName": "Kyoko",
                        "voiceDescription": "Tokyo accent",
                        "file": "28917-subject-3614.ogg"
                    }
                ],
                "mnemonic": "\n{splitParent}This is a jukugo word, which usually means on'yomi readings from the kanji. If you know the readings of your kanji you'll know how to read this as well. Be careful of the {span:lang=ja:\u306d\u3063} portion (normally is {span:lang=ja:\u306d\u3064}).\n"
            },
            "contextSentences": [
                {
                    "ja": "\u5b50\u3069\u3082\u306f\u71b1\u5fc3\u306b\u5e73\u4eee\u540d\u3092\u304b\u3044\u3066\u3044\u305f\u3002",
                    "en": "The child was practicing hiragana with zeal."
                },
                {
                    "ja": "\u304b\u308c\u304c\u6bce\u671d\u99c5\u524d\u3067\u30b9\u30ad\u30c3\u30d7\u306e\u7df4\u7fd2\u3092\u3057\u3066\u3044\u308b\u71b1\u5fc3\u306a\u3059\u304c\u305f\u306b\u5fc3\u6253\u305f\u308c\u307e\u3057\u305f\u3002",
                    "en": "My heart was struck by how he practiced skipping enthusiastically every morning in front of the station."
                },
                {
                    "ja": "\u30c8\u30fc\u30d5\u30b0\u306e\u65b0\u5165\u793e\u54e1\u306f\u307f\u3093\u306a\u3001\u4ed5\u4e8b\u306b\u3084\u308b\u6c17\u3092\u898b\u305b\u308b\u3053\u3068\u306b\u71b1\u5fc3\u3067\u3001\u5bdd\u3066\u3082\u3044\u3044\u6642\u9593\u3067\u3055\u3048\u3082\u3001\u4ed5\u4e8b\u3092\u3057\u3066\u3044\u305f\u3002",
