            "contextSentences": [
                {
                    "ja": "\u30de\u30ea\u30a2\u3063\u3066\u3001\u5de6\u306e\u5c0f\u6307\u306e\u6307\u5148\u306e\u30db\u30af\u30ed\u304c\u30bb\u30af\u30b7\u30fc\u3060\u3088\u306d\uff1f",
