                {
                    "ja": "\u30b3\u30a6\u30a4\u30c1\u69d8\u306f\u3001\u4f55\u3082\u304b\u3082\u304c\u81ea\u5206\u306e\u601d\u3044\u901a\u308a\u306b\u306a\u3089\u306a\u3044\u3068\u6c17\u304c\u3059\u307e\u306a\u3044\u3093\u3067\u3059\u3088\u3002",
