                {
                    "ja": "\u65e5\u672c\u3067\u624b\u7d19\u3092\u9001\u308b\u6642\u306b\u306f\u76f8\u624b\u306e\u540d\u524d\u306b\u69d8\u3092\u3064\u3051\u306a\u3044\u3068\u5931\u793c\u306b\u306a\u308a\u307e\u3059\u3002",
