            "vocabReadings": {
                "readings": [
                    {
                        "primary": true,
                        "reading": "\u3048\u304d\u307e\u3048"
                    }
                ],
                "pronunciationAudios": [
                    {
                        "gender": "male",
                        "pronunciation": "\u3048\u304d\u307e\u3048",
                        "voiceActorId": 2,
                        "voiceActorName": "Kenichi",
