            "contextSentences": [
                {
                    "ja": "\u3053\u306e\u30d0\u30f3\u30c9\u306e\u30dc\u30fc\u30ab\u30eb\u306f\u3001\u798f\u5cf6\u306e\u51fa\u8eab\u3067\u3059\u3002",
                    "en": "This band's vocalist is from Fukushima."
                },
                {
                    "ja": "\u798f\u5cf6\u306e\u5b50\u3069\u3082\u305f\u3061\u304c\u304b\u3044\u305f\u7d75\u306e\u4e2d\u306e\u3001\u3053\u306e\u9280\u8272\u306e\u661f\u7a7a\u3092\u898b\u3066\u4e0b\u3055\u3044\u3002",
                    "en": "Look at the silver, starry sky in this drawing from a kid in Fukushima."
