{
            "mnemonic": "The {tooltip:Kanji:signpost} you have your {tooltip:Kanji:eye} on is your {tooltip:Vocabulary:goal}, {tooltip:Vocabulary:target} and {tooltip:Vocabulary:objective}. Just imagine looking at this signpost in the distance. You know you have to get to it from where you are. That is the goal of your journey.",
            "hints": "",
            "meanings": {
                "Primary": "Goal",
                "Alternatives": "Target, Objective",
                "Word Type": "noun"
            },
            "vocabReadings": {
                "readings": [
                    {
                        "primary": true,
                        "reading": "\u3082\u304f\u3072\u3087\u3046"
                    }
                ],
                "pronunciationAudios": [
                    {
                        "gender": "male",
                        "pronunciation": "\u3082\u304f\u3072\u3087\u3046",
                        "voiceActorId": 2,
                        "voiceActorName": "Kenichi",
                        "voiceDescription": "Tokyo accent",
                        "file": "5046-subject-3603.ogg"
                    },
                    {
                        "gender": "female",
                        "pronunciation": "\u3082\u304f\u3072\u3087\u3046",
                        "voiceActorId": 1,
                        "voiceActorName": "Kyoko",
                        "voiceDescription": "Tokyo accent",
                        "file": "28857-subject-3603.ogg"
                    }
                ],
                "mnemonic": "\n{splitParent}You've had the on'yomi reading of {span:lang=ja:\u76ee} with {span:lang=ja:\u76ee\u6b21} way back in level 6. For this vocab, you're trying to get to your {tooltip:Vocabulary:goal}, that signpost in the distance. As you're trekking towards it there are people standing to the side {tooltip:Reading:mock}ing you, telling you you'll never make it to your goal. Imagine this happening.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u5ddd\u6751\u3055\u3093\u306e\u4eba\u751f\u306e\u76ee\u6a19\u306f\u306a\u3093\u3067\u3059\u304b\u3002",
                    "en": "Mr. Kawamura, what is your life's goal?"
                },
                {
                    "ja": "\u4e94\u5341\u30e1\u30fc\u30c8\u30eb\u5148\u306e\u76ee\u6a19\u306b\u5411\u304b\u3063\u3066\u77e2\u3092\u653e\u3061\u307e\u3057\u305f\u3002",
                    "en": "I fired an arrow toward the target 50m ahead of me."
