                {
                    "ja": "\u3042\u306e\u4e8c\u4eba\u3001\u4ef2\u826f\u3057\u306a\u3075\u308a\u3092\u3057\u3066\u3044\u308b\u3060\u3051\u3067\u3001\u672c\u5f53\u306f\u4ef2\u304c\u60aa\u3044\u3068\u601d\u3046\u3088\u3002",
