                    "ja": "\u306a\u306a\u3081\u304b\u3089\u898b\u3066\u308b\u304b\u3089\u3001\u5bbf\u984c\u306e\u7b54\u3048\u304c\u898b\u3048\u3065\u3089\u3044\u3093\u3060\u3088\u306d\u3002",
