            "contextSentences": [
                {
                    "ja": "\u3053\u306e\u795e\u793e\u306b\u306f\u795e\u98a8\u304c\u3075\u3044\u3066\u3044\u307e\u3059\u3002",
                    "en": "Divine winds blow on this shrine."
