            "contextSentences": [
                {
                    "ja": "\u306a\u305c\u304b\u3044\u3064\u3082\u5de6\u5229\u304d\u306e\u5973\u305b\u3044\u306b\u3072\u304b\u308c\u308b\u3093\u3067\u3059\u3002",
