                    "ja": "\u306a\u3093\u3067\u30b0\u30e9\u30b9\u3067\u98f2\u307f\u7269\u3092\u98f2\u3080\u6642\u306b\u5c0f\u6307\u3092\u7acb\u3066\u308b\u306e\uff1f",
