                {
                    "ja": "\u5341\u5e74\u524d\u306b\u305d\u3053\u3092\u304a\u3068\u305a\u308c\u305f\u6642\u306b\u306f\u3001\u3053\u3093\u306a\u5bbf\u306f\u5168\u304f\u3042\u308a\u307e\u305b\u3093\u3067\u3057\u305f\u3002",
