                    "ja": "\u672c\u9928\u306b\u306f\u3001\u3088\u3046\u3058\u6559\u5ba4\u306e\u90e8\u5c4b\u304c\u3078\u3044\u305b\u3064\u3055\u308c\u3066\u3044\u307e\u3059\u3002",
