            },
            "contextSentences": [
                {
                    "ja": "\u6d77\u9b5a\u306e\u4f53\u304c\u5927\u304d\u3044\u307b\u3069\u4f53\u5185\u306b\u305f\u304f\u3055\u3093\u6c34\u9280\u304c\u305f\u307e\u3063\u3066\u3044\u307e\u3059\u3002",
