                {
                    "ja": "\u6c34\u661f\u3068\u6c34\u9280\u306f\u3048\u3044\u8a9e\u3067\u5171\u306b\u30de\u30fc\u30ad\u30e5\u30ea\u30fc\u3068\u8a00\u3044\u307e\u3059\u304c\u3001\u3053\u308c\u306f\u3050\u3046\u7136\u3067\u3057\u3087\u3046\u304b\u3002",
