                {
                    "ja": "\u6614\u306f\u307f\u3093\u306a\u6c34\u9280\u4f53\u6e29\u8a08\u3092\u304a\u5c3b\u306b\u5dee\u3057\u8fbc\u3093\u3067\u3044\u305f\u3093\u3060\u3088\u306d\u3002\u3081\u3063\u3061\u3083\u3046\u3051\u308b\u3002",
