            "contextSentences": [
                {
                    "ja": "\u3082\u3046\u30b8\u30d6\u30ea\u306e\u6700\u65b0\u6620\u753b\u306f\u898b\u307e\u3057\u305f\u304b\u3002",
                    "en": "Have you already watched the latest Ghibli movie?"
                },
                {
                    "ja": "\u308f\u305f\u3057\u306f\u30ed\u30de\u30f3\u30b9\u6620\u753b\u304c\u597d\u304d\u306a\u306e\u306b\u3001\u4e3b\u4eba\u306f\u6226\u4e89\u6620\u753b\u3070\u3063\u304b\u308a\u898b\u305f\u304c\u308b\u3093\u3067\u3059\u3002",
                    "en": "Even though I like romantic films, my husband only wants to watch war movies."
                },
                {
                    "ja": "\u300c\u50d5\u306f\u6620\u753b\u30b9\u30bf\u30fc\u306b\u306a\u3063\u3066\u3001\u81ea\u5bb6\u7528\u30b8\u30a7\u30c3\u30c8\u6a5f\u3092\u8cb7\u3046\u3088\u3002\u305d\u308c\u304b\u3089\u3001\u541b\u306f\u50d5\u306e\u304a\u5ac1\u3055\u3093\u306b\u306a\u308b\u3093\u3060\u3002\u300d \u300c\u304a\u3058\u3044\u3061\u3083\u3093\u3001\u4f55\u5bdd\u307c\u3051\u305f\u3053\u3068\u8a00\u3063\u3066\u3093\u306e\u3002\u300d",
                    "en": "\"I\u2019m going to be a movie star, buy a private jet, and you will be my wife.\" \"Yeah, dream on, grandpa.\""
                }
