            "contextSentences": [
                {
                    "ja": "\u30b3\u30a6\u30a4\u30c1\u306f\u6771\u4eac\u306b\u4e00\u5104\u5186\u306e\u30de\u30f3\u30b7\u30e7\u30f3\u3092\u6301\u3063\u3066\u3044\u307e\u3059\u3002",
