                {
                    "ja": "\u300c\u3055\u3063\u304d\u4e00\u5104\u5186\u304c\u5165\u3063\u305f\u30b9\u30fc\u30c4\u30b1\u30fc\u30b9\u3092\u7121\u304f\u3057\u3061\u3083\u3063\u305f\u3093\u3060\u3051\u3069\u3002\u300d\u300c\u3048\u3047\u3063\uff01\u898b\u3064\u304b\u308b\u3068\u3044\u3044\u306d\u3002\u300d",
