                    }
                ],
                "mnemonic": "\n{splitParent}The reading is the same as the kanji as well! You are so happy that you could write a poem all about this...\n{splitParent}The vocab reading\n{linebreak}Is the same as the kanji\n{linebreak}Crabigator love\n{splitParent}How was that?\n"
            },
            "contextSentences": [
                {
                    "ja": "\u8a69\u304c\u5927\u597d\u304d\u3067\u3001\u6bce\u65e5\u8a69\u3092\u8aad\u3093\u3067\u3044\u307e\u3059\u3002",
                    "en": "I like poems a lot, so I read them every day."
                },
                {
                    "ja": "\u308f\u305f\u3057\u306e\u5fc3\u306e\u3084\u307f\u3092\u8a69\u3067\u8868\u3052\u3093\u3057\u3066\u307f\u305f\u3093\u3060\u3051\u3069\u3001\u3061\u3087\u3063\u3068\u8aad\u3093\u3067\u307f\u3066\u304f\u308c\u306a\u3044\uff1f",
                    "en": "I expressed the darkness of my mind in a poem. Can you take a look?"
                },
                {
                    "ja": "\u4eca\u65e5\u306e\u5bbf\u984c\u306f\u3001\u65e5\u672c\u8a9e\u3067\u8a69\u3092\u66f8\u304f\u3053\u3068\u3067\u3059\u3002",
