            "contextSentences": [
                {
                    "ja": "\u30b5\u30fc\u30e2\u30f3\u306f\u4eca\u4e16\u7d00\u3092\u4ee3\u8868\u3059\u308b\u8a69\u4eba\u3067\u3059\u3002",
