                    "ja": "\u541b\u306f\u8a69\u4eba\u3067\u3001\u6697\u55a9\u3092\u4f7f\u3046\u3053\u3068\u304c\u597d\u304d\u306a\u306e\u304b\u3082\u3057\u308c\u306a\u3044\u3051\u3069\u3001\u3082\u3063\u3068\u5206\u304b\u308a\u3084\u3059\u304f\u8a71\u3055\u306a\u3044\u3068\u76f8\u624b\u306f\u308f\u304b\u3089\u306a\u3044\u3088\u3002",
