            "contextSentences": [
                {
                    "ja": "\u3053\u306e\u6620\u753b\u306e\u3053\u306e\u56de\u60f3\u306e\u30b7\u30fc\u30f3\u304c\u3059\u3054\u304f\u3059\u304d\u306a\u3093\u3060\u3088\u306d\u3002",
