            "contextSentences": [
                {
                    "ja": "\u3053\u306e\u65b0\u5bbf\u306e\u30db\u30c6\u30eb\u306e\u30b7\u30e3\u30ef\u30fc\u306f\u3001\u6c34\u304b\u306c\u308b\u307e\u6e6f\u3057\u304b\u51fa\u306a\u3044\u3002",
