            "contextSentences": [
                {
                    "ja": "\u3059\u304d\u306a\u30a2\u30a4\u30c9\u30eb\u304c\u4e00\u65e5\u99c5\u9577\u306b\u3048\u3089\u3070\u308c\u307e\u3057\u305f\u3002",
                    "en": "My favorite idol was selected to be a one-day train station master."
                },
                {
                    "ja": "\u99c5\u9577\u3068\u5ddd\u7530\u3055\u3093\u306f\u89aa\u53cb\u3060\u304b\u3089\u3053\u3063\u305d\u308a\u3068\u5207\u3077\u4ee3\u3092\u308f\u308a\u5f15\u3057\u3066\u3082\u3089\u3063\u3066\u3044\u308b\u3093\u3060\u3063\u3066\u3002",
                    "en": "Because the stationmaster and Mr. Kawada are best friends, I heard that he secretly gets discount on fares."
                },
                {
                    "ja": "\u3046\u308f\u3063\uff01\u3042\u306e\u99c5\u9577\u3001\u4eca\u96fb\u8eca\u306b\u553e\u306f\u304b\u306a\u304b\u3063\u305f\u304b\uff1f\u304a\u524d\u3001\u898b\u305f\u304b\uff1f",
