                        "reading": "\u3054\u304b\u3093"
                    }
                ],
                "pronunciationAudios": [
                    {
                        "gender": "male",
                        "pronunciation": "\u3054\u304b\u3093",
                        "voiceActorId": 2,
                        "voiceActorName": "Kenichi",
                        "voiceDescription": "Tokyo accent",
                        "file": "4879-subject-3546.ogg"
                    },
                    {
