            "contextSentences": [
                {
                    "ja": "\u4eca\u3001\u6210\u7530\u7a7a\u6e2f\u306b\u7740\u304d\u307e\u3057\u305f\u3002",
                    "en": "I've just arrived at Narita Airport."
                },
                {
                    "ja": "\u7740\u304f\u6642\u9593\u304c\u5206\u304b\u3063\u305f\u3089\u3001\u307e\u305f\u308c\u3093\u3089\u304f\u3057\u3066\u3002",
