            "contextSentences": [
                {
                    "ja": "\u30d3\u30a8\u30c8\u3068\u30b3\u30a6\u30a4\u30c1\u306f\u3001\u30aa\u30d5\u30a3\u30b9\u3067\u91ce\u3055\u3044\u3092\u80b2\u3066\u308b\u306e\u304c\u5927\u597d\u304d\u3067\u3059\u3002",
