                    },
                    {
                        "gender": "female",
                        "pronunciation": "\u3042\u305f\u305f\u3081\u308b",
                        "voiceActorId": 1,
                        "voiceActorName": "Kyoko",
                        "voiceDescription": "Tokyo accent",
                        "file": "29203-subject-3888.ogg"
                    }
                ],
                "mnemonic": "\n{splitParent}The kanji reading is the same as {span:lang=ja:\u6e29\u304b\u3044}. As long as you know that word, you should be able to associate that reading with this word. \n"
            },
            "contextSentences": [
                {
                    "ja": "\u305d\u306e\u5668\u306f\u96fb\u5b50\u30ec\u30f3\u30b8\u3067\u6e29\u3081\u306a\u3044\u3067\u304f\u3060\u3055\u3044\u3002",
                    "en": "Please don't heat that bowl in the microwave."
                },
                {
                    "ja": "\u591c\u306d\u308b\u524d\u306b\u725b\u4e73\u3092\u6e29\u3081\u3066\u30db\u30c3\u30c8\u30df\u30eb\u30af\u306b\u3057\u3066\u98f2\u3080\u306e\u304c\u597d\u304d\u3067\u3059\u3002",
                    "en": "Before I go to bed, I like to heat up milk and drink it."
                },
                {
                    "ja": "\u6c34\u306b\u5165\u308c\u3066\u6e29\u3081\u308b\u3068\u3001\u6606\u5e03\u306e\u3046\u307e\u307f\u6210\u5206\u304c\u3057\u307f\u51fa\u3066\u304d\u307e\u3059\u3002",
                    "en": "Kombu seaweed releases its sweet flavor when it\u2019s soaked in water and heated up."
                }
            ],
            "collocations": []
        }

