                {
                    "ja": "\u30b3\u30a6\u30a4\u30c1\u306f\u4ed5\u4e8b\u4e2d\u3001\u305f\u307e\u306b\u60f3\u50cf\u3067\u304d\u306a\u3044\u3088\u3046\u306a\u52d5\u304d\u3092\u3059\u308b\u3002",
