                "mnemonic": "\n{splitParent}The readings are just {span:lang=ja:\u898b} and the vocab word {span:lang=ja:\u8fd4\u308b}, combined together. So long as you know both of those you should be able to combine them into the reading for this word.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u304b\u53bb\u3092\u898b\u8fd4\u3063\u3066\u308b\u3072\u307e\u306f\u306a\u3044\u3093\u3060\u3088\u3002",
