            "contextSentences": [
                {
                    "ja": "\u305d\u306e\u99c5\u54e1\u306e\u9ed2\u76ee\u306f\u666e\u901a\u306e\u4eba\u3088\u308a\u3082\u5927\u304d\u3044\u3068\u601d\u3044\u307e\u3059\u3002",
