                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "None",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Poor, old dad. His back hurts so his daughter has to walk on his back with cleats to make it feel better. But if she isn't gentle enough, she'll just make it worse.",
                "mnemonic": "Actually, the person she's being {tooltip:Kanji:gentle} with is her {tooltip:Reading:da}d ({span:lang=ja:\u3060}). No one would ever want to hurt their dad, especially if he's asked you to walk gently on his back as a way of giving him a massage."
            }
        }

{
            "mnemonic": "A {tooltip:Radical:person} puts a {tooltip:Radical:lid} on their {tooltip:Radical:cross} after they {tooltip:Kanji:graduate}. It\u2019s a symbolic gesture, putting the lid over the cross, but it\u2019s just what you do when you graduate around these parts.",
