            },
            "contextSentences": [
                {
                    "ja": "\u30b4\u30dc\u30a6\u306f\u5730\u4e0a\u7d04\uff12\u30e1\u30fc\u30c8\u30eb\u307e\u3067\u306e\u3073\u307e\u3059\u3002",
