            "contextSentences": [
                {
                    "ja": "\u304a\u304b\u672c\u592a\u308d\u3046\u306f\u3001\u300c\u82b8\u8853\u306f\u3070\u304f\u767a\u3060\u300d\u3063\u3066\u8a00\u3063\u3066\u305f\u3051\u3069\u3001\u3042\u308c\u3063\u3066\u3069\u3046\u3044\u3046\u610f\u5473\uff1f",
