                {
                    "ja": "\u30c8\u30fc\u30d5\u30b0\u30aa\u30d5\u30a3\u30b9\u306e\u96f0\u56f2\u6c17\u3063\u3066\u304b\u306a\u308a\u304f\u3064\u308d\u3052\u308b\u3063\u3066\u611f\u3058\u3060\u3088\u306d\u3002",
