                "mnemonic": "\n{splitParent}This is a jukugo word, which usually means on'yomi readings from the kanji. If you know the readings of your kanji you'll know how to read this as well.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u30dc\u30fc\u30ca\u30b9\u3067\u3001\u5168\u81ea\u52d5\u306e\u30d5\u30ed\u30f3\u30c8\u30ed\u30fc\u30c9\u3057\u304d\u306e\u305b\u3093\u305f\u304f\u304d\u3092\u8cb7\u3046\u4e88\u5b9a\u3067\u3059\u3002",
                    "en": "I'm planning to buy a fully-automatic front loading washing machine with my bonus."
                },
                {
                    "ja": "\u30b9\u30de\u30db\u3067\u3068\u3063\u305f\u5199\u3057\u3093\u306f\u3001\u5168\u3066\u81ea\u52d5\u3067\u30af\u30e9\u30a6\u30c9\u306b\u30a2\u30c3\u30d7\u30ed\u30fc\u30c9\u3057\u3066\u307b\u305e\u3093\u3055\u308c\u308b\u3088\u3046\u306b\u305b\u3063\u5b9a\u3057\u3066\u3044\u307e\u3059\u3002",
                    "en": "I set up my smartphone to automatically upload every single photo to the cloud."
                },
                {
                    "ja": "Tofugu\u306e\u65b9\u91dd\u3067\u3001\u8a31\u53ef\u7121\u304f\u30b3\u30a6\u30a4\u30c1\u306e\u30d9\u30fc\u30b3\u30f3\u3092\u98df\u3079\u305f\u793e\u54e1\u306f\u3001\u81ea\u52d5\u7684\u306b\u9000\u8077\u51e6\u5206\u3068\u306a\u308b\u3002",
