                        "file": "29224-subject-3882.ogg"
                    }
                ],
                "mnemonic": "\n{splitParent}The readings come from the words {span:lang=ja:\u6c17\u6301\u3061} and {span:lang=ja:\u60aa\u3044}. Hopefully you've seen both and can combine them together to know the reading automatically. No bad feelings with this word, right?\n"
            },
            "contextSentences": [
                {
                    "ja": "\u4e8c\u65e5\u3088\u3044\u3067\u3001\u982d\u306f\u30ac\u30f3\u30ac\u30f3\u3059\u308b\u3057\u3001\u3081\u3063\u3061\u3083\u6c17\u6301\u3061\u60aa\u3044\u3057\u3001\u6700\u60aa\u3060\u3088\u3002",
                    "en": "I'm hungover, I have a bad headache, and I feel terrible. This is awful."
                },
                {
                    "ja": "\u30b3\u30a6\u30a4\u30c1\u306f\u6c17\u6301\u3061\u60aa\u3044\u30cd\u30b3\u306a\u3067\u58f0\u3067\u3001\u30d3\u30a8\u30c8\u3092\u3088\u3093\u3060\u3002",
                    "en": "Koichi called out to Viet with his sickly sweet voice."
                },
                {
                    "ja": "\u3061\u3087\u3063\u3068\u3001\u305d\u3093\u306a\u98a8\u306b\u8155\u3092\u66f2\u3052\u308b\u306e\u3084\u3081\u3066\u304f\u308c\u306a\u3044\uff1f\u3081\u3061\u3083\u304f\u3061\u3083\u6c17\u6301\u3061\u60aa\u3044\u3093\u3060\u3051\u3069\u3002",
                    "en": "Stop bending your arms like that. It\u2019s seriously weirding me out."
                }
            ],
            "collocations": []
        }

{
