            "contextSentences": [
                {
                    "ja": "\u5468\u308a\u304c\u30ae\u30b6\u30ae\u30b6\u306b\u306a\u3063\u3066\u3044\u308b\u30b3\u30a4\u30f3\u3092\u96c6\u3081\u3066\u3044\u307e\u3059\u3002",
