            "contextSentences": [
                {
                    "ja": "\u3075\u308a\u5b50\u306e\u5468\u671f\u306b\u3064\u3044\u3066\u306e\u304a\u8fd4\u4e8b\u3001\u304a\u5f85\u3061\u3044\u305f\u3057\u3066\u304a\u308a\u307e\u3059\u3002",
                    "en": "I await your response regarding the cycle of a pendulum."
