                {
                    "ja": "\u5b9f\u306f\u3055\u3041\u3001\u30af\u30ea\u30b9\u30c6\u30f3\u306b\u304d\u3044\u3066\u3082\u3089\u3044\u305f\u304f\u3066\u3001\u300c\u6708\u306e\u5468\u671f\u300d\u3063\u3066\u3044\u3046\u66f2\u3092\u7df4\u7fd2\u3057\u3066\u308b\u3093\u3060\u3088\u306d\u3002",
