{
            "mnemonic": "An {tooltip:Kanji:attempt} to {tooltip:Kanji:join} together isn't just any get together. Imagine two people boxing. They attempt to knock each other out when they join together. That's why this word is {tooltip:Vocabulary:game} or {tooltip:Vocabulary:match}. Did you watch the {span:lang=ja:\u8a66\u5408} today? No! Don't tell me what happened, I recorded it on the VHS.",
            "hints": "",
            "meanings": {
                "Primary": "Game",
                "Alternative": "Match",
                "Word Type": "noun, \u3059\u308b verb"
            },
            "vocabReadings": {
                "readings": [
                    {
                        "primary": true,
                        "reading": "\u3057\u3042\u3044"
                    }
                ],
                "pronunciationAudios": [
                    {
                        "gender": "male",
                        "pronunciation": "\u3057\u3042\u3044",
