                ],
                "mnemonic": "\n{splitParent}The reading is a bit strange using kun'yomi readings. Luckily, we taught you these already, so go put on that kimono of yours and relax at the {span:lang=ja:\u6e29\u6cc9} for a bit.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u30ab\u30aa\u30ea\u3055\u3093\u306f\u3001\u7740\u7269\u306e\u3069\u3053\u304c\u3059\u304d\u3067\u3059\u304b\uff1f",
                    "en": "What do you like about kimono, Kaori?"
                },
                {
                    "ja": "\u304a\u7740\u7269\u304c\u6c5a\u308c\u3066\u3044\u307e\u3059\u3088\u3002",
                    "en": "Your clothes got a bit dirty."
                },
                {
                    "ja": "\u6bcd\u89aa\u306b\u3001\u65e2\u5a5a\u5973\u6027\u304b\u672a\u5a5a\u5973\u6027\u304b\u3067\u7740\u7269\u306e\u7a2e\u985e\u304c\u7570\u306a\u308b\u3068\u6559\u3048\u3066\u3082\u3089\u3044\u307e\u3057\u305f\u3002",
