            "contextSentences": [
                {
                    "ja": "\u305d\u306e\u677e\u8cb7\u3046\u306e\u306b\u3001\u4e8c\u5341\u5206\u9593\u3082\u5f85\u3063\u305f\u3093\u3060\u3088\u3002",
