            "contextSentences": [
                {
                    "ja": "\u304b\u3093\u305d\u3046\u3057\u305f\u677e\u8449\u304c\u4e00\u672c\u79c1\u306e\u90e8\u5c4b\u306e\u3086\u304b\u306b\u843d\u3061\u3066\u3044\u307e\u3057\u305f\u3002",
                    "en": "One dried pine needle was laying on the floor of my room."
                },
                {
                    "ja": "\u305d\u306e\u677e\u8449\u306f\u3001\u30af\u30eb\u30af\u30eb\u3068\u5341\u56de\u8ee2\u3057\u305f\u5f8c\u3001\u6c34\u305f\u307e\u308a\u3078\u843d\u3061\u307e\u3057\u305f\u3002",
                    "en": "The pine needle spun ten times and fell into a puddle."
