            "contextSentences": [
                {
                    "ja": "\u3069\u306e\u6d41\u884c\u8a9e\u304c\u3001\u4eca\u5e74\u306e\u6d41\u884c\u8a9e\u5927\u8cde\u306b\u3048\u3089\u3070\u308c\u308b\u3068\u601d\u3046\uff1f",
                    "en": "Which popular phrase do you think will be chosen for this year's buzzword of the year?"
