            "contextSentences": [
                {
                    "ja": "\u4eca\u6642\u306f\u300c\u6d41\u884c\u308a\u306e\u6b4c\u300d\u3063\u3066\u8a00\u3046\u3088\u306d\u3002\u300c\u6d41\u884c\u6b4c\u300d\u3063\u3066\u3044\u3046\u3068\u306a\u3093\u304b\u3057\u3087\u3046\u548c\u306e\u6b4c\u3088\u3046\u66f2\u3063\u3066\u611f\u3058\u304c\u3059\u308b\u3002",
                    "en": "We say \"pop song\" these days, so when I hear \"popular song,\" it reminds me of popular songs from the Showa period."
                },
                {
                    "ja": "\u30c4\u30a4\u30c3\u30bf\u30fc\u3067\u30d5\u30a9\u30ed\u30fc\u3057\u3066\u3001\u6700\u65b0\u306e\u6d41\u884c\u6b4c\u60c5\u307b\u3046\u3092\u30c1\u30a7\u30c3\u30af\u3057\u3066\u306d\u3002",
                    "en": "Follow our Twitter for updates on the latest popular songs."
                },
                {
                    "ja": "\u79c1\u306f\u3001\u6d41\u884c\u6b4c\u3067\u306f\u306a\u3044\u3051\u3069\u826f\u3044\u66f2\u3092\u898b\u3064\u3051\u308b\u306e\u304c\u597d\u304d\u3067\u3059\u3002",
