                "mnemonic": "\n{splitParent}This is a jukugo word that uses the on'yomi readings of the kanji. You should be able to read this on your own.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u304a\u9152\u3092\u98f2\u307f\u3059\u304e\u3066\u3001\u5b8c\u5168\u306b\u7406\u6027\u3092\u5931\u3063\u3066\u3057\u307e\u3063\u3066\u3044\u307e\u3057\u305f\u3002",
                    "en": "I had too much drink and I lost all sense of reason."
