            "contextSentences": [
                {
                    "ja": "\u3046\u3061\u306e\u5b66\u6821\u306e\u6587\u5316\u796d\u306b\u3082\u3042\u305d\u3073\u306b\u6765\u3066\u304f\u3060\u3055\u3044\u306d\u3002",
                    "en": "Please come visit my school\u2019s culture festival!"
                },
                {
                    "ja": "\u300c\u6587\u5316\u796d\u306e\u7df4\u7fd2\u3001\u4f55\u6642\u306b\u3059\u308b\uff1f\u300d\u300c\u304a\u308c\u306f\u4e00\u65e5\u4e2d\u3072\u307e\u3060\u304b\u3089\u3001\u305d\u3063\u3061\u306e\u90fd\u5408\u306e\u826f\u3044\u6642\u306a\u3089\u4f55\u6642\u3067\u3082\u3044\u3044\u3088\u3002\u300d",
                    "en": "\"What time should we start the school festival rehearsal?\" \"I'm available all day long, so anytime that suits you best.\""
                },
                {
                    "ja": "\u6587\u5316\u796d\u306e\u7ba1\u7406\u8af8\u7d4c\u8cbb\u306f\u5168\u4f53\u306e\u7d04\u4e09\u5341\u4e94\u30d1\u30fc\u30bb\u30f3\u30c8\u306b\u306a\u308b\u3068\u898b\u7a4d\u3063\u3066\u3044\u307e\u3059\u3002",
                    "en": "We've assessed administrative and overhead fees at about 35 percent of the total culture festival costs."
                }
            ],
            "collocations": []
        }

{
