            },
            "contextSentences": [
                {
                    "ja": "\u3053\u307e\u3063\u3066\u308b\u3093\u3060\u3063\u305f\u3089\u3001\u6027\u75c5\u3061\u308a\u3087\u3046\u306e\u304a\u91d1\u3001\u5c11\u3057\u3060\u3063\u305f\u3089\u90fd\u5408\u3057\u3066\u3042\u3052\u3089\u308c\u308b\u3088\u3002",
                    "en": "I could lend you some money for the STD treatment, if you're hard up."
                },
                {
                    "ja": "\u5168\u304f\u90fd\u5408\u306e\u60aa\u3044\u6642\u306b\u6027\u75c5\u306b\u304b\u304b\u3063\u305f\u3082\u3093\u3060\u3088\u3002",
