            "contextSentences": [
                {
                    "ja": "\u6298\u89d2\u6771\u4eac\u307e\u3067\u884c\u3063\u305f\u306e\u306b\u3001\u82b8\u80fd\u754c\u306b\u306f\u5165\u308c\u306a\u304b\u3063\u305f\u3002",
