                {
                    "ja": "\u308f\u305f\u3057\u306b\u3001\u58f2\u308a\u304b\u8cb7\u3044\u304b\u306e\u5408\u56f3\u306e\u51fa\u3057\u65b9\u3092\u304a\u3057\u3048\u3066\u304f\u308c\u307e\u305b\u3093\u304b\uff1f",
