                "Word Type": "\u3059\u308b verb"
            },
            "vocabReadings": {
                "readings": [
                    {
                        "primary": true,
                        "reading": "\u304d\u305f\u3044\u3059\u308b"
                    }
                ],
                "pronunciationAudios": [
