            "meanings": {
                "Primary": "To Fold",
                "Word Type": "transitive verb, godan verb"
            },
            "vocabReadings": {
                "readings": [
                    {
                        "primary": true,
                        "reading": "\u304a\u308b"
                    }
                ],
                "pronunciationAudios": [
                    {
                        "gender": "male",
