            "contextSentences": [
                {
                    "ja": "\u53cb\u3060\u3061\u306e\u307b\u3068\u3093\u3069\u304c\u3001\u30c8\u30e9\u30c3\u30af\u3092\u624b\u3067\u304a\u3057\u3066\u52d5\u304b\u3059\u3053\u3068\u304c\u3067\u304d\u308b\u3088\u3002",
                    "en": "Almost all of my friends can push and move a truck with their hands."
