                {
                    "ja": "\u30b3\u30a6\u30a4\u30c1\u3063\u305f\u3089\u3001\u6025\u306b\u3080\u304f\u3063\u3068\u8d77\u304d\u4e0a\u304c\u3063\u3066\u3001\u306d\u307c\u3051\u3066\u3042\u306e\u304d\u3087\u5927\u306a\u30b0\u30e9\u30f3\u30c9\u30d4\u30a2\u30ce\u3092\u52d5\u304b\u305d\u3046\u3068\u3057\u3060\u3057\u305f\u3093\u3060\u3088\u3002",
