                {
                    "ja": "\u30de\u30a4\u30b1\u30eb\u306f\u3001\u3075\u308c\u305a\u306b\u305d\u306e\u30dc\u30fc\u30eb\u3092\u56de\u8ee2\u3055\u305b\u308b\u3053\u3068\u304c\u3067\u304d\u307e\u3059\u3002",
