            },
            "contextSentences": [
                {
                    "ja": "\u81ea\u8ee2\u8eca\u306e\u30ec\u30fc\u30b9\u306e\u5f8c\u3001\u30d3\u30a8\u30c8\u306e\u9854\u3092\u3042\u305b\u304c\u305f\u304d\u306e\u3088\u3046\u306b\u6d41\u308c\u3066\u3044\u307e\u3057\u305f\u3002",
                    "en": "After the bicycle race, sweat was streaming down Viet's face."
                },
                {
                    "ja": "\u3053\u306e\u5ddd\u306f\u3001\u3069\u306e\u5730\u3044\u304d\u3092\u6d41\u308c\u3066\u3044\u308b\u3093\u3067\u3059\u304b\uff1f",
                    "en": "Which area does this river flow through?"
                },
                {
                    "ja": "\u6d41\u308c\u308b\u6c34\u306e\u97f3\u304c\u597d\u304d\u306a\u306e\u3067\u3001\u6d99\u304c\u541b\u306e\u982c\u3092\u6d41\u308c\u308b\u307e\u307e\u306b\u3057\u3066\u304a\u3044\u3066\u304f\u308c\u3088\u3002\u307b\u3089\u3001\u3068\u3066\u3082\u7f8e\u3057\u3044\u3088\u3002",
                    "en": "I like the sound of flowing water, so just let your tears stream down your cheeks. See? It\u2019s so beautiful."
                }
            ],
