                    "ja": "\u6bce\u65e5\u30ef\u30cb\u30ab\u30cb\u306b\u30ed\u30b0\u30a4\u30f3\u3057\u3066\u304b\u3093\u5b57\u3092\u52c9\u5f37\u3059\u308b\u3053\u3068\u304c\u5927\u4e8b\u3067\u3059\u3002",
