                {
                    "ja": "\u52c9\u5f37\u3059\u308b\u3053\u3068\u306f\u597d\u304d\u306a\u3093\u3067\u3059\u304c\u3001\u672c\u3092\u8aad\u3080\u3053\u3068\u306f\u304d\u3089\u3044\u306a\u3093\u3067\u3059\u3002",
