                {
                    "ja": "\u3061\u3087\u3063\u3068\u5fd9\u3057\u904e\u304e\u3066\u3001\u30a2\u30a4\u30f3\u30b7\u30e5\u30bf\u30a4\u30f3\u306e\u76f8\u5bfe\u6027\u7406\u8ad6\u306b\u3064\u3044\u3066\u52c9\u5f37\u3059\u308b\u6642\u9593\u304c\u306a\u3044\u3060\u3051\u306a\u3093\u3067\u3059\u3002",
