            "meanings": {
                "Primary": "To Surround",
                "Alternative": "To Enclose",
                "Word Type": "transitive verb, godan verb"
            },
            "vocabReadings": {
                "readings": [
                    {
                        "primary": true,
                        "reading": "\u304b\u3053\u3080"
                    }
                ],
                "pronunciationAudios": [
                    {
                        "gender": "male",
                        "pronunciation": "\u304b\u3053\u3080",
                        "voiceActorId": 2,
                        "voiceActorName": "Kenichi",
                        "voiceDescription": "Tokyo accent",
                        "file": "5343-subject-3666.ogg"
