                },
                {
                    "ja": "\u5168\u3066\u306e\u4e0b\u7740\u306e\u6ce8\u6587\u3072\u3093\u3092\u3001\u304d\u65e5\u901a\u308a\u306b\u767a\u9001\u3057\u306a\u3044\u3068\u3044\u3051\u307e\u305b\u3093\u3002",
                    "en": "We must ship all of the underwear orders on time."
                },
                {
                    "ja": "\u3069\u306e\u4e0b\u7740\u304c\u6b32\u3057\u3044\uff1f\u690d\u7269\u67c4\uff1f\u305d\u308c\u3068\u3082\u30a2\u30cb\u30de\u30eb\u67c4\uff1f\u597d\u304d\u306a\u3082\u306e\u3092\u9078\u3093\u3067\u3044\u3044\u3088\u3002",
