            "contextSentences": [
                {
                    "ja": "\u606f\u5b50\u304c\u6298\u89d2\u30b3\u30c4\u30b3\u30c4\u305f\u3081\u305f\u304a\u91d1\u306f\u3001\u5354\u4f1a\u3072\u306e\u652f\u306f\u3089\u3044\u306b\u6d88\u3048\u3066\u3057\u307e\u3044\u307e\u3057\u305f\u3002",
                    "en": "All the money my son worked so hard to slowly save up was used to pay his union membership fees."
                },
                {
                    "ja": "\u660e\u65e5\u306f\u5354\u4f1a\u306e\u96c6\u307e\u308a\u304c\u3042\u308b\u306e\u3067\u3001\u516d\u6642\u306b\u8d77\u3053\u3057\u3066\u304f\u3060\u3055\u3044\u3002",
