            "contextSentences": [
                {
                    "ja": "\u6298\u89d2\u3067\u3059\u304c\u3001\u3053\u308c\u4ee5\u4e0a\u59a5\u5354\u3059\u308b\u3053\u3068\u306f\u51fa\u6765\u304b\u306d\u307e\u3059\u3002",
