            "meanings": {
                "Primary": "Shallow"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u305b\u3093",
                        "primary": false
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u3042\u3055",
                        "primary": true
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
