{
            "mnemonic": "{tooltip:Kanji:Drink}ing {tooltip:Kanji:as much as you want} is nice and all, but don't get sick. When you see this word, you know you're at an {tooltip:Vocabulary:all you can drink} place. Tip: Usually there's a time limit, so drink up!",
            "hints": "",
            "meanings": {
                "Primary": "All You Can Drink",
                "Word Type": "expression, \u306e adjective"
            },
            "vocabReadings": {
                "readings": [
                    {
                        "primary": true,
                        "reading": "\u306e\u307f\u307b\u3046\u3060\u3044"
                    }
                ],
                "pronunciationAudios": [
                    {
                        "gender": "male",
                        "pronunciation": "\u306e\u307f\u307b\u3046\u3060\u3044",
                        "voiceActorId": 2,
                        "voiceActorName": "Kenichi",
                        "voiceDescription": "Tokyo accent",
