                    "ja": "\u79cb\u3068\u8a00\u3048\u3070\u4f55\u3092\u601d\u3044\u3046\u304b\u3079\u307e\u3059\u304b\u3002\u308f\u305f\u3057\u306f\u3084\u3063\u3071\u308a\u98df\u3088\u304f\u306e\u79cb\u3067\u3059\u306d\u3002",
