            "contextSentences": [
                {
                    "ja": "\u4ecf\u6559\u3068\u30d2\u30f3\u30c9\u30a5\u30fc\u6559\u306e\u3061\u304c\u3044\u3092\u6b63\u304b\u304f\u306b\u305b\u3064\u660e\u3067\u304d\u307e\u3059\u304b\uff1f",
                    "en": "Can you explain the differences between Buddhism and Hinduism accurately?"
                },
                {
                    "ja": "\u305d\u3093\u306a\u306b\u4fe1\u5fc3\u6df1\u3044\u4eba\u9593\u3058\u3083\u306a\u3044\u3093\u3067\u3059\u304c\u3001\u4e00\u304a\u3046\u795e\u9053\u3068\u4ecf\u6559\u3092\u4fe1\u3053\u3046\u3057\u3066\u3044\u307e\u3059\u3002",
                    "en": "I\u2019m not a deeply religious person, but I practice both Shintoism and Buddhism."
                },
                {
                    "ja": "\u4ecf\u6559\u306b\u4f34\u3063\u3066\u3001\u304a\u9999\u306f\u516d\u4e16\u7d00\u306b\u65e5\u672c\u306b\u4f1d\u6765\u3057\u307e\u3057\u305f\u3002",
