                    "ja": "\u4e88\u307b\u3046\u306f\u300c\u6674\u308c\u5f8c\u304f\u3082\u308a\u300d\u3060\u3057\u3001\u304b\u3055\u306f\u3044\u3089\u306a\u3044\u3093\u3058\u3083\u306a\u3044\uff1f",
