                {
                    "ja": "\u6765\u6708\u304b\u3089\u3001\u3053\u306e\u5730\u533a\u306e\u305f\u3093\u5f53\u8005\u304c\u5909\u308f\u308b\u306e\u3067\u3001\u3042\u3089\u304b\u3058\u3081\u304a\u77e5\u3089\u305b\u3055\u305b\u3066\u3044\u305f\u3060\u304d\u307e\u3059\u3002",
