{
            "mnemonic": "This word is made of {tooltip:Kanji:now} and {tooltip:Kanji:night} with the hiragana {span:lang=ja:\u306f} at the end. The {span:lang=ja:\u306f} here is pronounced as {span:lang=ja:\u308f} (the old pronunciation). When you say \"now night!\" you're really saying {tooltip:Vocabulary:good evening}.",
            "hints": "",
            "meanings": {
                "Primary": "Good Evening",
                "Word Type": "expression"
            },
            "vocabReadings": {
                "readings": [
                    {
                        "primary": true,
                        "reading": "\u3053\u3093\u3070\u3093\u306f"
                    }
                ],
                "pronunciationAudios": [
                    {
                        "gender": "male",
                        "pronunciation": "\u3053\u3093\u3070\u3093\u306f",
