                ],
                "mnemonic": "\n{splitParent}This is a jukugo word, which usually means on'yomi readings from the kanji. If you know the readings of your kanji you'll know how to read this as well. The {span:lang=ja:\u307b\u3046} changes to {span:lang=ja:\u307d\u3046}.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u65e5\u672c\u8a9e\u306e\u6587\u6cd5\u306e\u672c\u3092\u3055\u304c\u3057\u3066\u3044\u307e\u3059\u3002",
                    "en": "I'm looking for a Japanese grammar book."
                },
                {
                    "ja": "\u6587\u6cd5\u3092\u5b66\u3079\u3070\u5b66\u3076\u307b\u3069\u3001\u6587\u7ae0\u3092\u304b\u304f\u306e\u304c\u4e0a\u624b\u306b\u306a\u308a\u307e\u3059\u3088\u3002",
                    "en": "The more grammar you learn, the better your writing will become."
                },
                {
                    "ja": "\u79c1\u306e\u4e0a\u53f8\u3001\u898b\u305f\u76ee\u306f\u3067\u304d\u308b\u7537\u306a\u306e\u306b\u3001\u3044\u3064\u3082\u9593\u9055\u3063\u305f\u6587\u6cd5\u3092\u4f7f\u3046\u306e\u304c\u6b8b\u5ff5\u3059\u304e\u308b\u3088\u3002",
                    "en": "My boss looks like a smart person, so it\u2019s too bad that he always makes grammar mistakes."
                }
            ],
            "collocations": []
