            "contextSentences": [
                {
                    "ja": "\u30e6\u30cb\u30af\u30ed\u3067\u3001\u4e03\u5206\u4e08\u306e\u30d1\u30f3\u30c4\u3092\u8cb7\u3044\u307e\u3057\u305f\u3002",
