                },
                {
                    "ja": "\u5c11\u3057\u898b\u306a\u3044\u3046\u3061\u306b\u3001\u305a\u3044\u3076\u3093\u4e08\u304c\u306e\u3073\u305f\u306a\uff01",
                    "en": "You've grown a lot taller since I saw you last!"
                },
                {
                    "ja": "\u8a71\u3092\u5909\u3048\u308b\u8a33\u3058\u3083\u306a\u3044\u3093\u3060\u3051\u3069\u3001\u305d\u306e\u30b9\u30ab\u30fc\u30c8\u306f\u3061\u3087\u3063\u3068\u4e08\u304c\u9577\u904e\u304e\u308b\u3093\u3058\u3083\u306a\u3044\u304b\u3057\u3089\uff1f",
                    "en": "Not to change the subject, but isn\u2019t that skirt just a little too long for you?"
                }
            ],
            "collocations": []
        }

