            },
            "contextSentences": [
                {
                    "ja": "\u305d\u306e\u5b50\u732b\u306f\u3001\u3048\u3060\u304b\u3089\u3048\u3060\u3092\u8efd\u304b\u3044\u306b\u3068\u3073\u3046\u3064\u308a\u307e\u3057\u305f\u3002",
