                {
                    "ja": "\u30b7\u30e3\u30fc\u30ed\u30c3\u30af\u30fb\u30db\u30fc\u30e0\u30ba\u3063\u3066\u3001\u53e4\u3073\u305f\u72af\u7f6a\u8abf\u67fb\u65b9\u6cd5\u3092\u4f7f\u3063\u3066\u3044\u308b\u3088\u306d\uff1f",
