            },
            "contextSentences": [
                {
                    "ja": "\u60c5\u3051\u306a\u3044\u3067\u3059\u304c\u3001\u3059\u3050\u306b\u4eba\u3092\u4fe1\u3058\u308b\u6027\u683c\u306a\u306e\u3067\u3001\u3088\u304f\u3060\u307e\u3055\u308c\u308b\u3093\u3067\u3059\u3002",
                    "en": "It's sad, but I have a very trusting nature, so I often get duped."
                },
                {
                    "ja": "\u30c4\u30c6\u3067\u3057\u3085\u3046\u3057\u3087\u304f\u3059\u308b\u306a\u3093\u3066\u3001\u60c5\u3051\u306a\u3044\u3002\u5b9f\u529b\u3067\u52dd\u8ca0\u3057\u308d\u3088\u3002",
