                {
                    "ja": "\u308c\u3093\u4f11\u3082\u7d42\u308f\u3063\u305f\u3057\u3001\u3042\u306e\u6620\u753b\u9928\u591a\u5206\u3057\u3070\u3089\u304f\u30ac\u30e9\u30ac\u30e9\u3060\u308d\u3046\u306d\u3002",
