            "contextSentences": [
                {
                    "ja": "\u4eba\u6bba\u3057\u3092\u3057\u305f\u3089\u3001\u5211\u52d9\u6240\u306b\u884c\u304b\u306a\u3051\u308c\u3070\u306a\u308a\u307e\u305b\u3093\u3002",
