                },
                {
                    "ja": "\u6628\u65e5\u3001\u3053\u306e\u8fd1\u6240\u3067\u4eba\u6bba\u3057\u304c\u3042\u3063\u305f\u305d\u3046\u3067\u3059\u3002",
                    "en": "I heard there was a murder in this neighborhood yesterday."
                },
                {
                    "ja": "\u8a08\u7b97\u305a\u304f\u306e\u4eba\u751f\u306a\u3093\u3066\u3064\u307e\u3089\u306a\u3044\u3068\u601d\u3063\u3066\u597d\u304d\u52dd\u624b\u3057\u3066\u3044\u305f\u3089\u3001\u3044\u3064\u306e\u9593\u306b\u304b\u4eba\u6bba\u3057\u306b\u306a\u3063\u3066\u305f\u3093\u3060\u3002",
