                {
                    "ja": "\u96fb\u8a71\u306b\u51fa\u308c\u306a\u304f\u3066\u3054\u3081\u3093\u3002\u4fe1\u3058\u3089\u308c\u306a\u3044\u304b\u3082\u3057\u308c\u306a\u3044\u3051\u3069\u3001\u5b9f\u306f\u4eca\u6d77\u8ecd\u306e\u8239\u306e\u4e0a\u306a\u3093\u3060\u3088\u306d\u3002\u964d\u308a\u305f\u3089\u96fb\u8a71\u3059\u308b\u306d\u3002",
