            "contextSentences": [
                {
                    "ja": "\u6bd2\u30ac\u30b9\u306f\u7b2c\u4e00\u6b21\u4e16\u754c\u5927\u6226\u3067\u4f7f\u308f\u308c\u59cb\u3081\u305f\u3089\u3057\u3044\u3067\u3059\u3002",
