            },
            "contextSentences": [
                {
                    "ja": "\u308f\u305f\u3057\u306f\u866b\u304c\u82e6\u624b\u3060\u304b\u3089\u6625\u306f\u304d\u3089\u3044\u3067\u3059\u3002",
                    "en": "I don't like bugs, so I don't like spring."
                },
                {
                    "ja": "\u300c\u304a\u524d\u306e\u30c1\u30fc\u30e0\u3001\u6625\u306e\u5927\u4f1a\u3067\u306f\u3069\u3046\u3060\u3063\u305f\u306e\uff1f\u300d\u300c\u3078\u3078\u3002\u5927\u52dd\u3057\u305f\u3063\u3066\u306e\uff01\u300d",
                    "en": "\"How did your team do in the spring tournament?\" \"Hehe. Epic win.\""
                },
                {
                    "ja": "\u6625\u5dfb\u304d\u3068\u3044\u3046\u6599\u7406\u306b\u300c\u6625\u300d\u306e\u5b57\u304c\u4f7f\u308f\u308c\u3066\u3044\u308b\u306e\u306f\u3001\u6625\u306b\u82bd\u304c\u51fa\u308b\u91ce\u83dc\u3092\u4f7f\u3063\u3066\u4f5c\u308b\u98df\u3079\u7269\u3060\u304b\u3089\u3089\u3057\u3044\u3067\u3059\u3088\u3002",
                    "en": "I heard the reason the character for \"spring\" is used for spring roll is because people used to make spring rolls with vegetables that sprout in spring."
                }
            ],
            "collocations": []
        }

