            "contextSentences": [
                {
                    "ja": "\u6625\u4f11\u307f\u30ad\u30e3\u30f3\u30da\u30fc\u30f3\u671f\u9593\u4e2d\u306f\u3001\u5b66\u751f\u306e\u5165\u5834\u6599\u306f\u4e00\u308a\u3064\u5343\u5186\u3067\u3059\u3002",
                    "en": "During the spring holiday promotion, admission is only 1,000 yen for students."
                },
                {
                    "ja": "\u6625\u4f11\u307f\u4e2d\u3060\u3063\u305f\u3089\u3001\u3053\u306e\u6642\u9593\u305f\u3044\u306f\u7a7a\u3044\u3066\u307e\u3059\u3002",
                    "en": "Any of these times during spring vacation would work for me."
                },
                {
                    "ja": "\u305d\u308d\u305d\u308d\u98a8\u90aa\u6cbb\u3063\u305f\uff1f\u6625\u4f11\u307f\u306b\u98a8\u90aa\u5f15\u304f\u306a\u3093\u3066\u6700\u60aa\u3060\u3088\u306d\u3002\u3082\u3057\u307e\u3060\u8f9b\u3044\u306a\u3089\u3001\u591c\u66f4\u304b\u3057\u3057\u3061\u3083\u3060\u3081\u3060\u3088\u3002\u65e9\u304f\u826f\u304f\u306a\u3063\u3066\u306d\u3002",
                    "en": "Are you over your cold yet? It sucks having a cold during spring break, eh? If it\u2019s still bad, don\u2019t stay up late. Get well soon."
                }
            ],
            "collocations": []
