{
            "mnemonic": "Something with a {tooltip:Kanji:beauty} {tooltip:Kanji:taste} is something that is really {tooltip:Vocabulary:tasty} / {tooltip:Vocabulary:good tasting} / {tooltip:Vocabulary:delicious}. Mmmm, yum!",
