            "meanings": {
                "Primary": "Tasty",
                "Alternatives": "Good Tasting, Delicious",
                "Word Type": "\u3044 adjective"
            },
            "vocabReadings": {
                "readings": [
                    {
                        "primary": true,
                        "reading": "\u304a\u3044\u3057\u3044"
                    }
                ],
                "pronunciationAudios": [
