            "contextSentences": [
                {
                    "ja": "\u6628\u591c\u3001\u3042\u306e\u304a\u5bfa\u3067\u5909\u6b7b\u4f53\u304c\u767a\u898b\u3055\u308c\u305f\u3089\u3057\u3044\u3088\u3002",
