                {
                    "ja": "\u30c8\u30fc\u30d5\u30b0\u306e\u793e\u9577\u306b\u306a\u3063\u3066\u3001\u30b3\u30a6\u30a4\u30c1\u3092\u898b\u8fd4\u3057\u3066\u3084\u308b\u305e\uff01",
