                {
                    "ja": "\u6628\u65e5\u3001\u8089\u3063\u3066\u8a00\u8449\u306e\u767a\u97f3\u3092\u516d\u6642\u9593\u3082\u7df4\u7fd2\u3057\u305f\u3093\u3060\u305c\u3002",
