                {
                    "ja": "\u300c\u304a\u3093\u3092\u3042\u3060\u3067\u8fd4\u3059\u3088\u3046\u306a\u5b50\u306b\u80b2\u3066\u305f\u304a\u307c\u3048\u306f\u306a\u3044\u3088\uff01\u300d\u3068\u3044\u3046\u3057\u3070\u3044\u306e\u30bb\u30ea\u30d5\u3092\u8a00\u3046\u306e\u3092\u7df4\u7fd2\u3057\u3066\u3044\u307e\u3059\u3002",
