                "mnemonic": "\n{splitParent}The reading is the same as {span:lang=ja:\u6620\u308b}. So long as you know the reading of {span:lang=ja:\u6620\u308b} you should be able to read this one too.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u30b9\u30af\u30ea\u30fc\u30f3\u306b\u30b9\u30e9\u30a4\u30c9\u3092\u6620\u3057\u59cb\u3081\u3066\u3082\u3089\u3048\u307e\u3059\u304b\uff1f",
