            "contextSentences": [
                {
                    "ja": "\u8d64\u4fe1\u53f7\u3067\u6b62\u307e\u3063\u3066\u3001\u9752\u4fe1\u53f7\u3067\u308f\u305f\u308b\u306e\u3088\u3002",
