                    "ja": "\u30b3\u30a6\u30a4\u30c1\u304b\u3089\u306e\u624b\u7d19\u3092\u8aad\u3093\u3067\u3001\u6599\u7406\u4eba\u306b\u306a\u308b\u6c7a\u610f\u3092\u56fa\u3081\u307e\u3057\u305f\u3002",
