            "contextSentences": [
                {
                    "ja": "\u30d3\u30a8\u30c8\u306f\u4ed5\u4e8b\u3092\u6b8b\u3057\u305f\u307e\u307e\u3001\u5192\u967a\u306b\u51fa\u304b\u3051\u305f\u3002",
                    "en": "Viet left the work unfinished and went on an adventure."
                },
                {
                    "ja": "\u660e\u65e5\u304b\u3089\u306e\u5192\u967a\u306e\u305f\u3081\u306b\u3001\u529b\u3092\u6b8b\u3057\u3066\u304a\u3044\u305f\u65b9\u304c\u3044\u3044\u3088\u3002",
                    "en": "We should reserve our energy for our adventure tomorrow."
