            },
            "contextSentences": [
                {
                    "ja": "\u3042\u306e\u81ea\u52d5\u8eca\u30c7\u30a3\u30fc\u30e9\u30fc\u306b\u3046\u3089\u5207\u3089\u308c\u305f\u6c17\u5206\u3067\u3059\u3002",
