                    "ja": "\u3053\u306e\u7bb1\u5ead\u306e\u4f5c\u54c1\u306f\u3001\u30de\u30c3\u30c1\u7bb1\u3067\u4f5c\u3089\u308c\u3066\u3044\u307e\u3059\u3002",
