            "contextSentences": [
                {
                    "ja": "\u79c1\u306e\u304b\u3070\u3093\u306e\u4e2d\u306b\u306f\u3001\u3055\u3044\u3075\u3068\u3001\u5f01\u5f53\u3068\u3001\u30bf\u30d0\u30b3\u304c\u4e00\u7bb1\u5165\u3063\u3066\u3044\u307e\u3059\u3002",
                    "en": "In my bag, there's a wallet, a bento, and a pack of cigarettes."
                },
                {
                    "ja": "\u304a\u5f01\u5f53\u306e\u304a\u304b\u305a\u3092\u5c11\u3057\u6b8b\u3057\u3066\u304a\u3044\u3066\u3001\u5b50\u732b\u306b\u3042\u3052\u307e\u3057\u305f\u3002",
                    "en": "I left some sides in my box lunch and gave them to a kitten."
                },
                {
                    "ja": "\u660e\u65e5\u3042\u306a\u305f\u306b\u304a\u5f01\u5f53\u4f5c\u3063\u3066\u3042\u3052\u3088\u3046\u3068\u601d\u3046\u3093\u3060\u3051\u3069\u3001\u4f55\u304b\u82e6\u624b\u306a\u3082\u306e\u3068\u304b\u3042\u308b\u306e\uff1f",
                    "en": "I think I\u2019ll make a bento box for you tomorrow. Is there anything you\u2019d prefer not to have?"
                }
            ],
