            "contextSentences": [
                {
                    "ja": "\u305d\u306e\u4ecf\u5178\u306f\u3053\u306e\u7bb1\u306e\u4e2d\u306b\u3057\u307e\u3063\u3066\u3082\u3089\u3048\u307e\u3059\u304b\uff1f",
                    "en": "Can you put the Buddhist scriptures in this box?"
                },
                {
                    "ja": "\u3053\u3093\u3056\u3064\u6642\u306f\u3001\u3086\u305a\u308a\u5408\u3063\u3066\u4ecf\u5178\u3092\u3054\u5229\u7528\u304f\u3060\u3055\u3044\u3002",
                    "en": "During peak hours, please be considerate of others waiting to use the Buddhist writings."
                },
                {
                    "ja": "\u4ecf\u5178\u304c\u3069\u306e\u3088\u3046\u306b\u3057\u3066\u30b5\u30f3\u30b9\u30af\u30ea\u30c3\u30c8\u8a9e\u304b\u3089\u6f22\u8a9e\u306b\u8a33\u3055\u308c\u305f\u306e\u304b\u3054\u5b58\u3058\u3067\u3059\u304b\uff1f",
