                },
                {
                    "ja": "\u3068\u3064\u7136\u5927\u96e8\u306b\u306a\u3063\u305f\u306e\u3067\u3001\u624b\u3067\u3082\u3063\u3066\u3044\u305f\u5b57\u5178\u304c\u3073\u3057\u3087\u306c\u308c\u306b\u306a\u3063\u3061\u3083\u3063\u305f\u3093\u3067\u3059\u3002",
