                {
                    "ja": "\u30d3\u30a8\u30c8\u306f\u30e4\u30af\u30b6\u3060\u304c\u3001\u305d\u306e\u306f\u3093\u3056\u3044\u306b\u306f\u95a2\u4fc2\u3057\u3066\u306a\u3044\u3068\u3060\u3093\u8a00\u3067\u304d\u307e\u3059\u3002",
