            "contextSentences": [
                {
                    "ja": "\u65e5\u672c\u8a9e\u3067\u4e00\u756a\u9762\u767d\u3044\u65b9\u8a00\u306f\u6771\u5317\u5f01\u3067\u3057\u3087\u3046\u304b\uff1f",
                    "en": "Is Tohoku dialect the most interesting Japanese dialect?"
                },
                {
                    "ja": "\u79c1\u306f\u65e5\u672c\u8a9e\u306e\u5171\u901a\u8a9e\u3082\u95a2\u897f\u5f01\u3082\u8a71\u305b\u308b\u304b\u3089\u30d0\u30a4\u30ea\u30f3\u30ac\u30eb\u306a\u3093\u3067\u3059\u3088\u3002",
                    "en": "I am bilingual because I can speak standard Japanese as well as the Kansai dialect."
                },
                {
                    "ja": "\u535a\u591a\u5f01\u3067\u558b\u308b\u5973\u6027\u306f\u3068\u3066\u3082\u53ef\u611b\u3044\u3068\u601d\u3044\u307e\u3059\u3002",
