            "contextSentences": [
                {
                    "ja": "\u5352\u696d\u5f0f\u306e\u5f8c\u3067\u3001\u6a4b\u306e\u4e0a\u3067\u4e00\u3057\u3087\u306b\u5199\u771f\u3092\u3068\u308d\u3046\u3088\uff01",
                    "en": "After the graduation ceremony, let's take a photo on the bridge together!"
                },
                {
                    "ja": "\u306f\u3042\uff1f\u5352\u696d\u5f0f\u306b\u30d3\u30e8\u30f3\u30bb\u304c\u6765\u3066\u6b4c\u3092\u6b4c\u3063\u3066\u304f\u308c\u305f\uff1f\u307e\u3055\u304b\uff01\u5197\u8ac7\u3067\u3057\u3087\u3046\uff1f",
                    "en": "Huh? Did you say that Beyonc\u00e9 came to the graduation and sang for you guys? No way! You must be joking!"
                },
                {
                    "ja": "\u5352\u696d\u5f0f\u306e\u5f8c\u306e\u65c5\u884c\u8d85\u697d\u3057\u307f\u3060\u3088\u301c\uff01\u3086\u3063\u304f\u308a\u9732\u5929\u98a8\u5442\u306b\u5165\u3063\u3066\u3001\u5c71\u306e\u5e78\u3092\u3044\u3063\u3071\u3044\u98df\u3079\u5c3d\u304f\u305d\u3046\u306d\u3002\u3068\u3053\u308d\u3067\u3001\u5ff5\u306e\u305f\u3081\u78ba\u8a8d\u3060\u3051\u3069\u3001\u5bbf\u306e\u4e88\u7d04\u3057\u3066\u304f\u308c\u305f\u3093\u3060\u3088\u306d\uff1f",
                    "en": "I\u2019m so excited for the trip after our graduation ceremony! Let\u2019s relax in the hot springs and eat a lot of local delicious food. By the way, just making sure but you made a reservation at the cottage, right?"
                }
            ],
