            "contextSentences": [
                {
                    "ja": "\u3069\u3046\u3057\u3066\u65e5\u672c\u3067\u306f\u3001\u5973\u6027\u304c\u4fdd\u967a\u306e\u5916\u4ea4\u3092\u3059\u308b\u3053\u3068\u304c\u591a\u3044\u3093\u3067\u3059\u304b\uff1f",
                    "en": "Why is it more common for women to do insurance sales in Japan?"
                },
                {
                    "ja": "\u4fdd\u967a\u306b\u304b\u5165\u3059\u308b\u306e\u306b\u3001\u51fa\u751f\u8a3c\u660e\u66f8\u306f\u5fc5\u8981\u3067\u3059\u304b\uff1f",
                    "en": "Do I need a birth certificate to get insurance?"
                },
                {
                    "ja": "\u3057\u307e\u3063\u305f\u3002\u307e\u305f\u5bb6\u306b\u5065\u5eb7\u4fdd\u967a\u8a3c\u3092\u5fd8\u308c\u3066\u304d\u3061\u3083\u3063\u305f\u3002",
                    "en": "Oh no, I left my health insurance card at home again."
                }
            ],
