{
            "mnemonic": "A {tooltip:Kanji:luggage} {tooltip:Kanji:thing} is your {tooltip:Vocabulary:luggage}. It's also your {tooltip:Vocabulary:baggage} and {tooltip:Vocabulary:load} too.",
