                {
                    "ja": "\u308f\u3041\u3001\u3073\u3063\u304f\u308a\u3057\u305f\uff01\u4f55\u3067\u4eee\u9762\u306a\u3093\u3066\u304b\u3076\u3063\u3066\u308b\u306e\uff1f",
                    "en": "Ah, you startled me! Why are you wearing that mask?"
                },
                {
                    "ja": "\u30f4\u30a7\u30cd\u30c4\u30a3\u30a2\u306e\u4eee\u9762\u821e\u8e0f\u4f1a\u306b\u884c\u3063\u3066\u767d\u99ac\u306e\u738b\u5b50\u69d8\u306b\u4f1a\u3046\u3053\u3068\u304c\u79c1\u306e\u5922\u3067\u3059\u3002",
