        }

{
            "mnemonic": "It\u2019s the era of {tooltip:Kanji:Bright} {tooltip:Kanji:Rule}! If this doesn't make sense, don't worry about it. Focus more on the reading, which is {span:lang=ja:\u3081\u3044\u3058}. Sound familiar? This is the famous {tooltip:Vocabulary:Meiji Era} or {tooltip:Vocabulary:Meiji Emperor}. If you don't know about it consider reading up, it's interesting history!",
            "hints": "",
            "meanings": {
                "Primary": "Meiji Era",
                "Alternatives": "Meiji Emperor, Meiji",
                "Word Type": "noun"
            },
            "vocabReadings": {
                "readings": [
                    {
                        "primary": true,
                        "reading": "\u3081\u3044\u3058"
                    }
                ],
                "pronunciationAudios": [
                    {
                        "gender": "male",
                        "pronunciation": "\u3081\u3044\u3058",
