                    },
                    {
                        "gender": "female",
                        "pronunciation": "\u3081\u3044\u3058",
                        "voiceActorId": 1,
                        "voiceActorName": "Kyoko",
                        "voiceDescription": "Tokyo accent",
                        "file": "29562-subject-3848.ogg"
                    }
                ],
                "mnemonic": "\n{splitParent}This is a jukugo word, which usually means on'yomi readings from the kanji. If you know the readings of your kanji you'll know how to read this as well.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u660e\u6cbb\u751f\u307e\u308c\u306e\u305d\u6bcd\u306f\u3001\u751f\u524d\u306f\u4ecf\u6559\u306e\u6559\u3048\u3092\u3061\u3085\u3046\u5b9f\u306b\u5b88\u3063\u3066\u3044\u307e\u3057\u305f\u3002",
                    "en": "My grandmother was born in the Meiji era, and she devotedly practiced the Buddhist teachings when she was alive."
                },
                {
                    "ja": "\u660e\u6cbb\u3044\u65b0\u306b\u3064\u3044\u3066\u306e\u308d\u3093\u6587\u3092\u66f8\u3044\u3066\u3044\u307e\u3059\u3002",
                    "en": "I'm writing a paper about the Meiji Restoration."
                },
                {
                    "ja": "\u660e\u6cbb\u6642\u4ee3\u306e\u751f\u6d3b\u3092\u63cf\u3044\u305f\u30c9\u30e9\u30de\u3092\u898b\u3066\u3044\u308b\u3093\u3067\u3059\u304c\u3001\u5f53\u6642\u306f\u4e00\u4e07\u5186\u304c\u5927\u91d1\u3060\u3063\u305f\u3068\u3044\u3046\u3053\u3068\u306b\u9a5a\u304d\u307e\u3057\u305f\u3002",
                    "en": "I was watching a drama series about life in the Meiji period and I was surprised that ten thousand yen was a large amount of money back then."
                }
            ],
            "collocations": []
        }

