            "contextSentences": [
                {
                    "ja": "\u30ef\u30cb\u30ab\u30cb\u306f\u3001\u30c8\u30fc\u30d5\u30b0\u306e\u30d2\u30c3\u30c8\u5546\u54c1\u3067\u3059\u3002",
