                },
                {
                    "ja": "\u3042\u306e\u4f1a\u793e\u306e\u5546\u54c1\u306b\u306f\u3044\u3064\u3082\u4fdd\u8a3c\u304c\u3064\u3044\u3066\u308b\u304b\u3089\u3001\u79c1\u306f\u305d\u3053\u3067\u8cb7\u3046\u3053\u3068\u304c\u591a\u3044\u304b\u306a\u3002",
