            "contextSentences": [
                {
                    "ja": "\u30b3\u30a6\u30a4\u30c1\u306f\u771f\u3063\u9ed2\u306a\u30cb\u30f3\u30cb\u30af\u304c\u597d\u304d\u3067\u3001\u3088\u304f\u3057\u305f\u304b\u3089\u8840\u304c\u51fa\u308b\u307e\u3067\u98df\u3079\u3066\u3044\u307e\u3059\u3002",
                    "en": "Koichi loves pitch black garlic and he often eats it so much that his tongue bleeds."
