            "contextSentences": [
                {
                    "ja": "\u3064\u307e\u304c\u8377\u7269\u3092\u307e\u3068\u3081\u3066\u51fa\u3066\u3044\u304f\u5834\u9762\u304c\u81ea\u5206\u306b\u304b\u3055\u306a\u308a\u3064\u3089\u304f\u306a\u308a\u307e\u3057\u305f\u3002",
