                },
                {
                    "ja": "\u3053\u306e\u30d5\u30ec\u30fc\u30ba\u306f\u3001\u30d3\u30b8\u30cd\u30b9\u306e\u5834\u9762\u3067\u6709\u52b9\u3067\u3059\u3002",
