            },
            "contextSentences": [
                {
                    "ja": "\u305a\u3063\u3068\u30b3\u30f3\u30d4\u30e5\u30fc\u30bf\u30fc\u306e\u753b\u9762\u3070\u304b\u308a\u898b\u3066\u3044\u308b\u3068\u76ee\u304c\u60aa\u304f\u306a\u308b\u3088\u3002",
                    "en": "If you stare at computer screens for a long time, your eyesight will get worse."
                },
                {
                    "ja": "\u6700\u8fd1\u3001\u3088\u304f\u72ac\u306e\u30a8\u30c3\u30c1\u306a\u753b\u50cf\u304c\u81ea\u52d5\u3067\u753b\u9762\u306b\u51fa\u3066\u304f\u308b\u304b\u3089\u307f\u3093\u306a\u3053\u307e\u3063\u3066\u3044\u308b\u3093\u3060\u3088\u306d\u3002",
                    "en": "Lately, an obscene image of dogs keeps automatically appearing on our monitor, so yeah, we're having some issues."
                },
                {
                    "ja": "\u5909\u306a\u3093\u3060\u3088\u3002\u30d3\u30a8\u30c8\u306f\u3044\u3064\u3082\u901a\u308a\u753b\u9762\u306b\u91d8\u4ed8\u3051\u306b\u306a\u3063\u3066\u4f55\u6642\u9593\u3082\u5ea7\u3063\u305f\u307e\u307e\u3067\u3044\u308b\u3093\u3060\u3051\u3069\u3001\u809d\u5fc3\u306e\u753b\u9762\u306f\u4eca\u671d\u304b\u3089\u771f\u3063\u9ed2\u306a\u3093\u3060\u3088\u306d\u3002",
