{
            "mnemonic": "A {tooltip:Kanji:laugh}ing {tooltip:Kanji:face} is a {tooltip:Vocabulary: smiling face} (or just a {tooltip:Vocabulary:smile}!). {span:lang=ja:\u7b11\u9854s} all around!",
