                "mnemonic": "\n{splitParent}This is a jukugo word that uses the on'yomi readings of the kanji. You should be able to read this on your own.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u305d\u306e\u65e5\u672c\u8a9e\u306e\u6559\u79d1\u66f8\u306f\u9ad8\u3059\u304e\u3066\u8cb7\u3048\u307e\u305b\u3093\u3002",
                    "en": "I can't buy the Japanese textbook because it's too expensive."
                },
                {
                    "ja": "\u6559\u79d1\u66f8\u306f\u30b7\u30a7\u30a2\u3057\u306a\u3044\u3067\u4e00\u4eba\u4e00\u3055\u3064\u8cb7\u3063\u3066\u304f\u3060\u3055\u3044\u306d\u3002",
                    "en": "Please don't share the textbook. Each person must buy their own."
                },
                {
                    "ja": "\u6559\u79d1\u66f8\u3092\u6301\u3063\u3066\u304f\u308b\u306e\u3092\u5fd8\u308c\u305f\u305b\u3044\u3067\u3001\u653e\u8ab2\u5f8c\u4e00\u6642\u9593\u5b66\u6821\u306b\u6b8b\u3055\u308c\u307e\u3057\u305f\u3002",
                    "en": "I forgot to bring my textbook and I was kept an hour after school."
                }
            ],
            "collocations": []
