                        "reading": "\u304b\u305f\u3081\u308b"
                    }
                ],
                "pronunciationAudios": [
                    {
                        "gender": "male",
                        "pronunciation": "\u304b\u305f\u3081\u308b",
                        "voiceActorId": 2,
                        "voiceActorName": "Kenichi",
