{
            "mnemonic": "The hiragana ends with an {span:lang=ja:\u3046} sound, so you know this is a verb. The kanji itself means {tooltip:Kanji:return}, and this verb is transitive, meaning it takes a direct object. You send someone back. You send them home. And tell them to never come near you again. So this means {tooltip:Vocabulary:to send someone back} or {tooltip:Vocabulary:to send someone home}.",
            "hints": "",
            "meanings": {
                "Primary": "To Send Someone Back",
                "Alternative": "To Send Someone Home",
                "Word Type": "transitive verb, godan verb"
            },
            "vocabReadings": {
                "readings": [
                    {
                        "primary": true,
                        "reading": "\u304b\u3048\u3059"
                    }
                ],
                "pronunciationAudios": [
                    {
                        "gender": "female",
                        "pronunciation": "\u304b\u3048\u3059",
                        "voiceActorId": 1,
                        "voiceActorName": "Kyoko",
                        "voiceDescription": "Tokyo accent",
                        "file": "43725-subject-8947.ogg"
                    },
                    {
                        "gender": "male",
                        "pronunciation": "\u304b\u3048\u3059",
                        "voiceActorId": 2,
                        "voiceActorName": "Kenichi",
                        "voiceDescription": "Tokyo accent",
                        "file": "43047-subject-8947.ogg"
                    }
                ],
                "mnemonic": "\n{splitParent}The reading for this word is the same as the one you learned with the kanji. Yay! But since this word has a pair verb, let's think of a way to remember the ending:\n{splitParent}What's the most surefire way to send someone home? Threaten to {tooltip:Reading:sue} ({span:lang=ja:\u3059}) them if they don't!\n"
            },
            "contextSentences": [
                {
                    "ja": "\u4eca\u65e5\u306f\u5c11\u3057\u65e9\u304f\u904b\u8ee2\u624b\u3092\u5e30\u3057\u305f\u3002",
                    "en": "I sent my driver home a little early today."
                },
                {
                    "ja": "\u4f5c\u696d\u304c\u5168\u90e8\u7d42\u308f\u3089\u306a\u3044\u3068\u5e30\u3057\u3066\u3082\u3089\u3048\u306a\u3044\u3088\u3002",
                    "en": "They won't send you home unless you finish all the work."
                },
                {
                    "ja": "\u3053\u306e\u9b5a\u3092\u65e9\u304f\u6d77\u306b\u5e30\u3057\u3066\u3042\u3052\u305f\u3044\u3093\u3067\u3059\u3002",
                    "en": "I want to send this fish back to the ocean quickly."
                }
            ],
            "collocations": []
        }

{
