                {
                    "ja": "\u771f\u5b9f\u306e\u3042\u3044\u3092\u898b\u3064\u3051\u305f\u3044\u3068\u3044\u3046\u79c1\u306e\u5e0c\u671b\u306f\u6253\u3061\u304f\u3060\u304b\u308c\u3066\u3057\u307e\u3044\u307e\u3057\u305f\u3002",
