                    "ja": "\u307e\u308b\u3067\u4e0d\u5e78\u306e\u3069\u3093\u5e95\u306e\u3088\u3046\u306b\u3044\u308b\u3088\u3046\u306a\u9854\u3092\u3057\u3066\u308b\u3051\u3069\u3001\u5927\u4e08\u592b\uff1f",
