            }
        }

{
            "mnemonic": "The {tooltip:Radical:sun} is {tooltip:Radical:correct}, {tooltip:Kanji:absolutely}. The mighty sun is never wrong. It is absolutely correct, always.",
            "hints": "Imagine the sun in the sky. Its rays blind you as it corrects all of the errors you\u2019ve made.",
            "meanings": {
                "Primary": "Absolutely"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u305c",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "None",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Imagine the sun being so absolutely consumed with rage that it catches a zeppelin on fire and crashes it. Feel the heat from the grounded zeppelin as it smolders.",
                "mnemonic": "Then, a {tooltip:Reading:ze}ppelin ({span:lang=ja:\u305c}) flies in front of the sun, blocking it out. {tooltip:Kanji:Absolutely}, the sun cannot ignore this transgression. Therefore, the sun corrects the zeppelin\u2019s evil ways by frying it with sunshine and bringing it to the ground."
            }
        }

{
            "mnemonic": "You use a {tooltip:Radical:thread} for {tooltip:Radical:good luck} by {tooltip:Kanji:bind}ing two fingers together. You {tooltip:Kanji:tie} them nice and tight.",
            "hints": "Tying two fingers together with a good luck thread is very common where you're from.",
            "meanings": {
                "Primary": "Bind",
                "Alternative": "Tie"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u3051\u3064",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u3080\u3059, \u3086",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "This ketsup is exactly what you were looking for, but now it won't stop. You need to get out of this bind by untying the thread on your finger. But it won't budge. It's covered in ketsup. Help! You're going to drown!",
                "mnemonic": "After you {tooltip:Kanji:bind} your fingers, the good luck starts pouring in. Literally. Suddenly {tooltip:Reading:ketsu}p ({span:lang=ja:\u3051\u3064}) starts pouring down from the heavens."
            }
        }

{
            "mnemonic": "Under a {tooltip:Radical:canopy} your {tooltip:Radical:clan} digs in the {tooltip:Radical:ground}, trying to get to the {tooltip:Kanji:bottom}. They want to build a nice home your entire clan can live in, but they need to get to the bottom before they'll start building.",
            "hints": "Picture all of the people in your clan under this canopy digging with all their might, trying to find the bottom. \"Isn't there... no bottom though?\" you think to yourself.",
            "meanings": {
                "Primary": "Bottom"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u3066\u3044",
                        "primary": false
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u305d\u3053",
                        "primary": true
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "The bottom is full of water, and everyone and everything down there is soaked through now.",
                "mnemonic": "Suddenly someone down in the hole shouts that they've reached the {tooltip:Kanji:bottom}, but it's full of water and they're all {tooltip:Reading:soak}ed ({span:lang=ja:\u305d\u3053})!"
            }
        }

{
            "mnemonic": "Your {tooltip:Radical:big} {tooltip:Radical:mouth} is the {tooltip:Kanji:cause} of all your problems.",
            "hints": "Imagine all the dumb things you blabber about with your mouth open big and wide. Saying things you shouldn't say... causing drama and stuff. Shame on you.",
            "meanings": {
                "Primary": "Cause"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u3044\u3093",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u3088",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Who knew you could cause people to live in an inn instead of their own homes with your big mouth...",
                "mnemonic": "Your big mouth {tooltip:Kanji:cause}s all of your friends and family to move to an {tooltip:Reading:inn} ({span:lang=ja:\u3044\u3093}) so they don't have to live near you and hear you talk anymore. "
            }
        }

{
            "mnemonic": "They {tooltip:Radical:say} {tooltip:Radical:sheep} are {tooltip:Kanji:detailed} creatures. I mean, I never thought sheep were very detailed, but that\u2019s what they say.",
            "hints": "Imagine getting really close to a sheep and seeing all the tiny detailed curls in their wool. There are hidden patterns you'd never noticed before now!",
            "meanings": {
                "Primary": "Detailed"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u3057\u3087\u3046",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u304f\u308f",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Picture the Shougun, leaning in close to inspect the detailed patterns all over the sheep. His nose is so close, he can probably smell all the little detailed nuances of the sheep's musk too.",
                "mnemonic": "The reason these sheep are so {tooltip:Kanji:detailed} is that they are trying to impress the {tooltip:Reading:Shou}gun ({span:lang=ja:\u3057\u3087\u3046}). If they're fancy enough, perhaps the Shougun won\u2019t kill them for their meat and make their wool into clothing."
            }
        }

{
            "mnemonic": "If you {tooltip:Radical:sound} like a {tooltip:Radical:drunkard} when you {tooltip:Radical:say} things, people will not think of you as a {tooltip:Kanji:discerning} person. \"AWh yeah, that game is greatttt,\" you say in your drunken slurs. But, really, it sounds like you think all games are great, which isn't all that {tooltip:Kanji:discriminating} of you at all.",
            "hints": "Picture yourself as a drunkard. What sort of discerning things are you saying? What are you trying to discern? Do you know?",
            "meanings": {
                "Primary": "Discerning",
                "Alternatives": "Discriminating, Know"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u3057\u304d",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "None",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Imagine him saying some very (in your eyes) discerning things about everything around him. Color yourself impressed (and feel the impressed-ness)!",
                "mnemonic": "So, we've figured out that your drunken utterances are not very {tooltip:Kanji:discerning}. But let's think about someone who is discerning. You're sitting next to a {tooltip:Reading:Sheikh} ({span:lang=ja:\u3057\u304d}) (an Arabic leader), and boy do they sound like they know what they are talking about. Maybe it's because he's not drunk like you. He has such discerning taste, that one!"
            }
        }

{
            "mnemonic": "A {tooltip:Radical:tiger} kills a {tooltip:Radical:pig} with a {tooltip:Radical:knife} in this new {tooltip:Kanji:drama} about the animal kingdom! The tiger and pig used to be friends when they were younger, but now they're bitter enemies and the tiger just stabbed the pig right in the chest with a knife.",
            "hints": "Picture this scene from the drama as dramatically as you can. The pig stares into the tiger's eyes, \"Tiger, you wouldn't\u2013uh!\" The pig's eyes slowly lower to see the knife sticking into its gut, the tiger's hand still holding it. \"This is what you get, you pig,\" the tiger spits back, twisting.",
            "meanings": {
                "Primary": "Drama"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u3052\u304d",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "None",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Picture Gecki acting out the part of the tiger and the pig in this drama. It's so intense, you're moved to tears. Bravo Gecki, bravo!",
                "mnemonic": "This {tooltip:Kanji:drama} is being put on by {tooltip:Reading:Gecki} ({span:lang=ja:\u3052\u304d}), your childhood pet gecko. Gecki is playing all the parts, because as true drama fans know, one-gecko-shows are the highest form of art."
            }
        }

{
            "mnemonic": "The {tooltip:Radical:dry} radical and the {tooltip:Kanji:dry} kanji are the same!",
            "hints": "Know your radicals, yo!",
            "meanings": {
                "Primary": "Dry"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u304b\u3093",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u307b, \u3072",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Imagine keeping Genghis Khan completely dry all day every day. He won't even get wet to bathe. Instead he makes you rub his body with dry sand and salts.",
                "mnemonic": "You need to {tooltip:Kanji:dry} Genghis {tooltip:Reading:Khan} ({span:lang=ja:\u304b\u3093}). He hates being wet, all of the Mongols do, so your job is to dry his entire body. And his clothes, and his horse. In fact, when it rains, you have to ride next to him keeping him dry by holding an umbrella above his head."
            }
        }

{
            "mnemonic": "A {tooltip:Radical:shellfish} that can't live in {tooltip:Radical:winter} is a {tooltip:Kanji:failure}. Any proper shellfish would survive through the winter, but there are always a few failures every year.",
            "hints": "Imagine you're a shellfish in the cold, cold winter. The water is freezing but you must tough it out so no one will say you're a failure in spring when they find your dead shellfish body.",
            "meanings": {
                "Primary": "Failure",
                "Alternative": "Fail"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u306f\u3044",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u3084\u3076",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Imagine being a shellfish freezing in the cold winter water, but you avoid failure by muttering haiku over and over to keep you warm and determined.",
                "mnemonic": "The best way to avoid {tooltip:Kanji:failure} is to say a little {tooltip:Reading:hai}ku ({span:lang=ja:\u306f\u3044}) to distract you from the cold. In fact, this can work in any situation where you're afraid of failure. Say a haiku aloud, it will calm your nerves and warm you from the inside."
            }
        }

{
            "mnemonic": "A {tooltip:Radical:tsunami} is coming, and you want to {tooltip:Radical:walk} over it, so you have to {tooltip:Kanji:ford} it. Think about it \u2013 you ford a river, you ford anything that\u2019s water, unless you\u2019re Jesus \u2013 you\u2019re not Jesus. You don\u2019t walk across a tsunami, you ford it.",
            "hints": "Imaging taking your shoes off, hiking up your pants, and holding all of your things above your head as you ford across the tsunami.",
            "meanings": {
                "Primary": "Ford"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u3057\u3087\u3046",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u308f\u305f",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Your new fording techniques have increased the Shougun's military power! Congrats, I guess.",
                "mnemonic": "Your ability to {tooltip:Kanji:ford} this tsunami impresses everyone who witnesses it, especially the {tooltip:Reading:Shou}gun ({span:lang=ja:\u3057\u3087\u3046}). Now that you've taught him a tsunami can be forded, he's going to start sending his troops through them instead of waiting for them to pass."
            }
        }

{
            "mnemonic": "The {tooltip:Radical:fruit} radical and the {tooltip:Kanji:fruit} kanji are exactly the same! Bodacious!",
            "hints": "",
            "meanings": {
                "Primary": "Fruit"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u304b",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
