                        "primary": true
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Breathe the smell of the {span:lang=ja:\u82b1} in deeply through your nose. How convenient that they share the same reading!",
                "mnemonic": "You get to the last of the twenty rice paddies and you open up your {tooltip:Kanji:nose}. Something smells like {tooltip:Reading:\u82b1} ({span:lang=ja:\u306f\u306a}). Oh! The {span:lang=ja:\u82b1} are in bloom! How lovely."
            }
        }

{
