                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u3064\u306d",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "When you ask Jourm about his Viking mouth towel, he just tells you, \"It's ordinary for everyone to have mouth towels. Totally normal.\" Now that you think about it, he is a really messy dude, he probably needs it.",
                "mnemonic": "It's {tooltip:Kanji:ordinary} for a viking to have a mouth towel, but your sloppy farmhand friend {tooltip:Reading:Jou}rm ({span:lang=ja:\u3058\u3087\u3046}) has a mouth towel too. That's a habit that's only {tooltip:Kanji:normal} for vikings, so why does he have one?"
            }
