            }
        }

{
            "mnemonic": "The {tooltip:Radical:leader} of the {tooltip:Radical:shellfish} has a {tooltip:Radical:knife} in its {tooltip:Kanji:side}. It's fine though, don't worry, it's just a reminder that he won the great shellfish war back when they were trying to choose the new leader.",
            "hints": "Picture the shellfish leader in your mind and make sure to pay special attention to the knife that's sticking out of his side. It's right in the groove of his shell.",
            "meanings": {
                "Primary": "Side"
            },
            "kanjiReadings": {
                "readings": [
