            }
        }

{
            "mnemonic": "A {tooltip:Radical:tiger}, clad in {tooltip:Radical:spikes}, exists in the {tooltip:Kanji:void}. This tiger is from another dimension where tigers rule the earth, clad in armor with spikes. The void has allowed this tiger to cross dimensional planes.",
            "hints": "Tigers are pretty intimidating just on their own, let alone with spikey armor. Imagine this tiger, covered in spikes. It\u2019s roaring at you. Pretty scary, huh?",
            "meanings": {
                "Primary": "Void"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u304d\u3087, \u3053",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u3080\u306a",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Picture this grand match taking place in Little Kyoto. Actual tigers versus the Hanshin Tigers. It\u2019s truly a sight to behold. The void tigers are armed with their spikes and the Hanshin Tigers are armed with their bats. Hear the crack of wood and the roar of tigers in the air as the battle commences.",
                "mnemonic": "The aforementioned {tooltip:Kanji:void} has opened up in Little {tooltip:Reading:Kyo}to ({span:lang=ja:\u304d\u3087}). The spiked void tigers chose to come here in order to face off against the Hanshin Tigers baseball team in battle. It will be a vicious match here in Little Kyoto. Since this is taking place in Little Kyoto and not Japan itself, the Hanshin Tigers won't have the home field advantage. Who will win?"
            }
        }

{
