                    "ja": "\u304a\u7236\u3055\u3093\u3001\u3042\u3093\u305f\u304c\u5efa\u7bc9\u5bb6\u306b\u306a\u3063\u305f\u304b\u3089\u3001\u9f3b\u304c\u9ad8\u3044\u306e\u3088\u3002",
