            "contextSentences": [
                {
                    "ja": "\u76f8\u5909\u308f\u3089\u305a\u304b\u3063\u3053\u3044\u3044\u9f3b\u8f2a\u3092\u3064\u3051\u3066\u308b\u306d\u3002\u3067\u3082\u3001\u4eca\u65e5\u306f\u9f3b\u6bdb\u304c\u51fa\u3066\u308b\u3088\u3002",
