            "contextSentences": [
                {
                    "ja": "\u3057\u3087\u3046\u6765\u306f\u3001\u539f\u5b50\u30a8\u30cd\u30eb\u30ae\u30fc\u306e\u52c9\u5f37\u3092\u3057\u305f\u3044\u3068\u601d\u3063\u3066\u3044\u307e\u3059\u3002",
