            },
            "contextSentences": [
                {
                    "ja": "\u7533\u3057\u308f\u3051\u3042\u308a\u307e\u305b\u3093\u304c\u3001\u51fa\u5e2d\u306f\u4e0d\u5b9a\u671f\u306b\u306a\u308b\u3068\u601d\u3044\u307e\u3059\u3002",
                    "en": "I'm afraid that my attendance will probably be irregular."
