            "contextSentences": [
                {
                    "ja": "\u9053\u3092\u308f\u305f\u308b\u524d\u306b\u3001\u8eca\u304c\u6765\u3066\u306a\u3044\u3053\u3068\u3092\u304b\u304f\u306b\u3093\u3059\u308b\u3088\u3046\u610f\u8b58\u3057\u3066\u304f\u3060\u3055\u3044\u3002",
