            },
            "contextSentences": [
                {
                    "ja": "\u30b3\u30a6\u30a4\u30c1\u306e\u4e0d\u6cbb\u306e\u75c5\u304c\u6cbb\u3063\u3066\u3001\u5fc3\u5e95\u3046\u308c\u3057\u3044\u3088\u3002",
