                {
                    "ja": "\u30b3\u30a6\u30a4\u30c1\u306b\u306f\u5fc3\u5e95\u304b\u3089\u304d\u3089\u308f\u308c\u3066\u3044\u308b\u3068\u601d\u3044\u307e\u3059\u3002",
