            "contextSentences": [
                {
                    "ja": "\u3053\u306e\u98df\u5802\u306e\u5e97\u4e3b\u306f\u3001\u53e4\u304f\u3055\u3044\u7537\u3067\u3001\u7537\u306f\u5bb6\u5ead\u306e\u3053\u3068\u306b\u5e72\u6e09\u3059\u3079\u304d\u3067\u306f\u306a\u3044\u3068\u4e3b\u3061\u3087\u3046\u3059\u308b\u3093\u3067\u3059\u3002",
