                },
                {
                    "ja": "\u3055\u3063\u304d\u30c8\u30fc\u30d5\u30b0\u98df\u5802\u306b\u884c\u3063\u305f\u3093\u3060\u3051\u3069\u3001\u7121\u540d\u306e\u6b4c\u624b\u304c\u7121\u6599\u306e\u30ef\u30f3\u30de\u30f3\u30e9\u30a4\u30d6\u3092\u3057\u3066\u305f\u3088\u3002",
