            },
            "contextSentences": [
                {
                    "ja": "\u304e\u308a\u306e\u6bcd\u304b\u3089\u3001\u6bcd\u89aa\u3068\u3057\u3066\u306e\u81ea\u899a\u304c\u7121\u3044\u3063\u3066\u8a00\u308f\u308c\u3066\u3001\u3059\u3063\u3054\u304f\u306f\u3089\u304c\u7acb\u3061\u307e\u3057\u305f\u3002",
