        }

{
            "mnemonic": "You've seen that {span:lang=ja:\u6ce3\u304f} is to cry, so you can probably guess that {span:lang=ja:\u6ce3\u304d} is just \"cry.\" You've also seen how {span:lang=ja:\u866b} is rarely a nice thing to call someone. So what's a mean thing you can call someone who cries? How about a {tooltip:Vocabulary:crybaby}?",
            "hints": "",
            "meanings": {
                "Primary": "Crybaby",
                "Word Type": "noun"
            },
            "vocabReadings": {
                "readings": [
                    {
                        "primary": true,
                        "reading": "\u306a\u304d\u3080\u3057"
