                    {
                        "gender": "female",
                        "pronunciation": "\u306a\u304d\u3080\u3057",
                        "voiceActorId": 1,
                        "voiceActorName": "Kyoko",
                        "voiceDescription": "Tokyo accent",
                        "file": "29870-subject-3937.ogg"
                    }
                ],
                "mnemonic": "\n{splitParent}The readings come from {span:lang=ja:\u6ce3\u304f} and {span:lang=ja:\u866b}. So long as you're okay with those two words you should be able to read this one too.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u6ce3\u304d\u866b\u30b3\u30a6\u3061\u3083\u30fc\u3093\u3001\u307b\u3089\u3001\u30b3\u30a6\u3061\u3083\u3093\u306e\u597d\u304d\u306a\u30c8\u30f3\u30cd\u30eb\u3060\u3088\u30fc\u3063\uff01",
                    "en": "Hey, crybaby Ko-chan. Here comes a tunnel you like."
                },
                {
                    "ja": "\u30b3\u30a6\u30a4\u30c1\u3060\u3051\u304c\u30d3\u30a8\u30c8\u304c\u6ce3\u304d\u866b\u3060\u3068\u3044\u3046\u3053\u3068\u3092\u77e5\u3063\u3066\u3044\u308b\u3002",
                    "en": "Only Koichi knows Viet is a crybaby."
                },
                {
                    "ja": "\u5a18\u306e\u9ad8\u71b1\u304c\u4e2d\u3005\u4e0b\u304c\u308a\u307e\u305b\u3093\u3002\u666e\u6bb5\u306f\u6ce3\u304d\u866b\u306a\u3093\u3067\u3059\u304c\u3001\u4eca\u306f\u6ce3\u304f\u5143\u6c17\u3082\u7121\u3044\u3088\u3046\u3067\u3001\u5fc3\u914d\u3067\u3059\u3002",
                    "en": "My daughter's high fever doesn't seem to be coming down. She is usually a crybaby, but it seems like she doesn't even have energy to cry now and I'm worried."
                }
            ],
            "collocations": []
        }

{
