            "meanings": {
                "Primary": "Empty",
                "Alternatives": "Vacant, Futile, Vain",
                "Word Type": "\u3044 adjective"
            },
            "vocabReadings": {
                "readings": [
                    {
                        "primary": true,
                        "reading": "\u3080\u306a\u3057\u3044"
                    }
                ],
                "pronunciationAudios": [
                    {
                        "gender": "male",
                        "pronunciation": "\u3080\u306a\u3057\u3044",
                        "voiceActorId": 2,
                        "voiceActorName": "Kenichi",
                        "voiceDescription": "Tokyo accent",
                        "file": "7093-subject-7758.ogg"
