            },
            "contextSentences": [
                {
                    "ja": "\u30d5\u30b0\u306f\u3044\u304f\u3064\u306b\u306a\u3063\u3066\u3082\u5e7b\u60f3\u306e\u4e16\u754c\u306e\u4f4f\u4eba\u306a\u3093\u3060\u306a\u3002",
