                },
                {
                    "ja": "\u6642\u3005\u3001\u30b3\u30a6\u30a4\u30c1\u304c\u81ea\u5206\u306e\u606f\u5b50\u3060\u3068\u3044\u3046\u3042\u307e\u3044\u5e7b\u60f3\u3092\u3044\u3060\u3044\u3066\u3044\u307e\u3059\u3002",
