                    "ja": "\u4eca\u56de\u3001\u52dd\u5229\u306e\u6804\u5149\u306b\u304b\u304c\u3084\u3044\u305f\u306e\u306f\u3001\u30c8\u30fc\u30d5\u30b0\u30c1\u30fc\u30e0\u3067\u3059\uff01",
