                {
                    "ja": "\u307a\u3061\u3083\u3093\u3053\u306e\u8d64\u3044\u9f3b\u304c\u539f\u56e0\u3067\u3001\u5931\u604b\u3057\u307e\u3057\u305f\u3002",
