                {
                    "ja": "\u3042\u3079\u3055\u3093\u306b\u30a4\u30f3\u30bf\u30d3\u30e5\u30fc\u3055\u305b\u3066\u3044\u305f\u3060\u3051\u308b\u3053\u3068\u3092\u3068\u3066\u3082\u5149\u6804\u306b\u601d\u3063\u3066\u3044\u307e\u3059\u3002",
