                {
                    "ja": "Tofugu\u306e\u672c\u793e\u3067\u52e4\u52d9\u3059\u308b\u6a5f\u4f1a\u3092\u9802\u3044\u305f\u3053\u3068\u3092\u3001\u3068\u3066\u3082\u5149\u6804\u306b\u601d\u3044\u307e\u3059\u3002\u7686\u3055\u3093\u306e\u304a\u5f79\u306b\u7acb\u3066\u308b\u3088\u3046\u7cbe\u4e00\u676f\u9811\u5f35\u308a\u307e\u3059\u306e\u3067\u3001\u3069\u3046\u305e\u3088\u308d\u3057\u304f\u304a\u9858\u3044\u3044\u305f\u3057\u307e\u3059\u3002",
