{
            "mnemonic": "When you {tooltip:Kanji:know} {tooltip:Kanji:nothing} (Jon Snow), you know nothing. This is {tooltip:Vocabulary:ignorance}, it's being {tooltip:Vocabulary:ignorant}.",
