            "contextSentences": [
                {
                    "ja": "\u5185\u56e0\u6027\u305c\u3093\u305d\u304f\u3060\u3068\u3057\u3093\u3060\u3093\u3055\u308c\u307e\u3057\u305f\u3002",
                    "en": "I was diagnosed with intrinsic asthma."
                },
                {
                    "ja": "\u30c8\u30e9\u30a6\u30de\u306b\u306a\u308b\u51fa\u6765\u4e8b\u304c\u8d77\u304d\u308b\u3068\u3001\u305d\u306e\u82e6\u3057\u307f\u3092\u548c\u3089\u3052\u308b\u305f\u3081\u306b\u3001\u5185\u56e0\u6027\u30aa\u30d4\u30aa\u30a4\u30c9\u3068\u3044\u3046\u306e\u3046\u5185\u307e\u85ac\u304c\u5206\u3074\u3064\u3055\u308c\u307e\u3059\u3002",
