            "contextSentences": [
                {
                    "ja": "\u30b3\u30a6\u30a4\u30c1\u3063\u3066\u3001\u77e5\u8b58\u306e\u307b\u3046\u3053\u307f\u305f\u3044\u306a\u3084\u3064\u3060\u3088\u306a\u3002",
