                "mnemonic": "\n{splitParent}The reading for this is vocab kun'yomi readings. Just take the vocab {span:lang=ja:\u5de6} and add it to {span:lang=ja:\u5074} to have yourself {span:lang=ja:\u3072\u3060\u308a\u304c\u308f}.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u3053\u306e\u30a8\u30b9\u30ab\u30ec\u30fc\u30bf\u30fc\u3067\u306f\u3001\u307f\u3093\u306a\u5de6\u5074\u306b\u7acb\u3063\u3066\u3044\u307e\u3059\u306d\u3002",
                    "en": "Everybody stands on the left side on this escalator I guess."
                },
                {
                    "ja": "\u65e5\u672c\u306f\u3001\u30a4\u30ae\u30ea\u30b9\u3068\u540c\u3058\u3067\u3001\u8eca\u306f\u5de6\u5074\u901a\u884c\u3067\u3059\u3088\u3002",
                    "en": "They drive on the left in Japan the same as they do in England."
                },
                {
                    "ja": "\u5bdd\u308b\u6642\u306f\u3001\u5de6\u5074\u3092\u4e0b\u306b\u3057\u3066\u6a2a\u306b\u306a\u308b\u65b9\u304c\u597d\u304d\u3067\u3059\u3002",
