                    "ja": "\u4e0b\u308a\u306e\u4e3b\u56e0\u306f\u304a\u305d\u3089\u304f\u3055\u3063\u304d\u98df\u3079\u305f\u30bd\u30d5\u30c8\u30af\u30ea\u30fc\u30e0\u3067\u3059\u3002",
