                    "ja": "\u306b\u304d\u3073\u304c\u6c17\u306b\u306a\u308b\u306e\u3067\u3001\u85ac\u7528\u306e\u77f3\u3051\u3093\u3067\u9854\u3092\u3042\u3089\u3046\u3088\u3046\u306b\u3057\u3066\u3044\u307e\u3059\u3002",
