                    "ja": "\u307c\u304f\u306e\u9f3b\u306e\u3053\u3068\u306b\u306f\u3075\u308c\u305a\u306b\u3001\u305d\u3063\u3068\u3057\u3066\u304a\u3044\u3066\u304f\u308c\u307e\u305b\u3093\u304b\uff1f",
