                        "file": "29783-subject-3941.ogg"
                    }
                ],
                "mnemonic": "\n{splitParent}The readings come from the words {span:lang=ja:\u304a\u9858\u3044} and {span:lang=ja:\u4e8b}. If you know how to read those you should be able to read this word too.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u3042\u306a\u305f\u306e\u9858\u3044\u4e8b\u306f\u3001\u304d\u3063\u3068\u3059\u3050\u306b\u304b\u306a\u3046\u3068\u601d\u3044\u307e\u3059\u3002",
                    "en": "I think your prayers will be answered soon."
                },
                {
                    "ja": "\u30b3\u30a6\u30a4\u30c1\u306f\u3044\u3064\u3082\u3001\u9858\u3044\u4e8b\u3092\u66f8\u3044\u305f\u7d19\u3092\u305d\u3070\u306b\u304a\u3044\u3066\u306d\u307e\u3059\u3002",
                    "en": "When Koichi goes to sleep he always keeps a piece of paper with his wishes written on it nearby."
                },
                {
                    "ja": "\u65e5\u672c\u4eba\u306f\u3001\u4eba\u751f\u306e\u7bc0\u76ee\u7bc0\u76ee\u306b\u3001\u9858\u3044\u4e8b\u3060\u3051\u3067\u306a\u304f\u611f\u8b1d\u306e\u6c17\u6301\u3061\u3092\u4f1d\u3048\u308b\u305f\u3081\u306b\u3001\u795e\u793e\u3092\u8a2a\u308c\u307e\u3059\u3002",
                    "en": "Japanese people visit shrines on important occasions not only to make wishes but also to offer thanks."
                }
            ],
            "collocations": []
        }

