                },
                {
                    "ja": "\u7a7a\u5e2d\u306e\u51fa\u305d\u3046\u306a\u3058\u3085\u696d\u304c\u3042\u308c\u3070\u6559\u3048\u3066\u3082\u3089\u3048\u307e\u305b\u3093\u304b\uff1f",
