            "contextSentences": [
                {
                    "ja": "\u5916\u5074\u306b\u958b\u304f\u3068\u601d\u3063\u305f\u3089\u3001\u5185\u5074\u306b\u958b\u304f\u30c9\u30a2\u3060\u3063\u305f\u3093\u3060\u306d\u3002",
                    "en": "I thought this door opened outward, but it actually opens inward, I guess."
