                {
                    "ja": "\u3044\u3064\u3082\u306f\u5916\u5074\u306e\u30dd\u30b1\u30c3\u30c8\u306b\u304b\u304e\u3092\u5165\u308c\u3066\u304a\u304f\u3093\u3067\u3059\u3051\u3069...\u304a\u304b\u3057\u3044\u306a\u3041\u3002",
                    "en": "I usually put the key in the outside pocket though....weird."
                },
                {
                    "ja": "\u30b5\u30fc\u30e2\u30f3\u306e\u30d5\u30e9\u30a4\u3092\u4f5c\u308d\u3046\u3068\u3057\u305f\u3093\u3060\u3051\u3069\u3001\u5916\u5074\u3060\u3051\u7126\u3052\u3061\u3083\u3063\u3066\u5185\u5074\u306f\u8840\u751f\u81ed\u3044\u30aa\u30ec\u30f3\u30b8\u8272\u306e\u307e\u307e\u306b\u306a\u3063\u3061\u3083\u3063\u305f\u3002\u6cb9\u304c\u3061\u3087\u3063\u3068\u71b1\u3059\u304e\u305f\u306e\u304b\u3082\u3002",
