                {
                    "ja": "\u611b\u56fd\u5fc3\u304c\u3084\u305f\u3089\u306b\u5f37\u3044\u7537\u304c\u3001\u30c8\u30fc\u30d5\u30b0\u306b\u5165\u793e\u3057\u307e\u3057\u305f\u3002",
