            "contextSentences": [
                {
                    "ja": "\u8b66\u5bdf\u7f72\u306b\u5165\u308b\u3068\u3001\u6885\u9152\u306e\u306b\u304a\u3044\u304c\u9f3b\u3092\u3064\u3044\u305f\u3002",
