                },
                {
                    "ja": "\u5b57\u304c\u304d\u305f\u306a\u3059\u304e\u3066\u3001\u85ac\u65b9\u306b\u4f55\u304c\u66f8\u3044\u3066\u3042\u308b\u306e\u304b\u3055\u3063\u3071\u308a\u5206\u304b\u308a\u307e\u305b\u3093\u3002",
