                {
                    "ja": "\u53e4\u3044\u85ac\u65b9\u306e\u4e2d\u306b\u306f\u3001\u5371\u967a\u3067\u3042\u308b\u3068\u3044\u3046\u3053\u3068\u3067\u73fe\u4ee3\u533b\u7642\u304b\u3089\u306f\u9664\u304b\u308c\u3066\u3044\u308b\u3082\u306e\u3082\u3042\u308b\u3002",
                    "en": "Some of the old prescriptions were considered to be dangerous and have been removed from use in modern medicine."
                }
            ],
            "collocations": []
