            },
            "contextSentences": [
                {
                    "ja": "\u3082\u3046\u5c11\u3057\u5869\u304c\u591a\u3044\u65b9\u304c\u826f\u3044\u304b\u3082\u3057\u308c\u307e\u305b\u3093\u306d\u3002",
                    "en": "It might be better with a little more salt."
                },
                {
                    "ja": "\u4e00\u624d\u306b\u306a\u308b\u307e\u3067\u8d64\u3061\u3083\u3093\u306b\u306f\u5869\u3092\u3042\u3052\u306a\u3044\u65b9\u304c\u3044\u3044\u3067\u3059\u3088\u3002",
                    "en": "Until your baby turns one, you shouldn't give them any salt."
                },
                {
                    "ja": "\u3051\u3057\u304b\u3089\u3093\uff01\u4e00\u4f53\u3069\u3046\u3084\u3063\u3066\u305d\u3093\u306a\u306b\u99ac\u9e7f\u306a\u3053\u3068\u304c\u51fa\u6765\u308b\u3093\u3060\uff1f\u7802\u7cd6\u3068\u5869\u3092\u5165\u308c\u66ff\u3048\u308b\u306a\u3093\u3066\u3001\u3044\u304f\u3089\u4eca\u65e5\u304c\u30a8\u30a4\u30d7\u30ea\u30eb\u30d5\u30fc\u30eb\u3060\u304b\u3089\u3068\u3044\u3063\u3066\u3082\u3001\u3061\u3063\u3068\u3082\u304a\u3082\u3057\u308d\u304f\u306a\u3044\u305e\u3002\u99ac\u9e7f\uff01",
                    "en": "Oh my God! I can\u2019t believe you could be so stupid! Switching the salt and the sugar is not funny at all, even if it\u2019s April Fool\u2019s Day today. You are the fool!"
                }
            ],
            "collocations": []
        }

