                    "ja": "\u6642\u7bc0\u67c4\u3001\u304a\u98a8\u90aa\u306a\u3069\u53ec\u3057\u307e\u305b\u306c\u3088\u3046\u3001\u304f\u308c\u3050\u308c\u3082\u5fa1\u81ea\u611b\u304f\u3060\u3055\u3044\u307e\u305b\u3002",
