                {
                    "ja": "\u7d30\u5247\u3092\u8aad\u307e\u305a\u306b\u5951\u7d04\u66f8\u306b\u7f72\u540d\u3057\u306a\u3044\u65b9\u304c\u826f\u304b\u3063\u305f\u3053\u3068\u306f\u5206\u304b\u3063\u3066\u305f\u3093\u3067\u3059\u304c\u3001\u4e00\u898b\u3057\u305f\u3068\u3053\u308d\u5927\u5bb6\u3055\u3093\u304c\u3044\u3044\u4eba\u305d\u3046\u3060\u3063\u305f\u306e\u3067\u3001\u3064\u3044\u3002",
