            "contextSentences": [
                {
                    "ja": "\u3053\u306e\u7cf8\u306f\u3061\u3087\u3063\u3068\u7d30\u3059\u304e\u307e\u3059\u306d\u3002",
                    "en": "I think this thread is a bit too thin."
