                    }
                ],
                "mnemonic": "\n{splitParent}The readings are the kun'yomi vocab readings. With {span:lang=ja:\u9f3b} you learned that with the kanji. With {span:lang=ja:\u5148} you learned that with the vocab. So, you should have all the pieces to be able to read this. Remember, body parts tend to change words into kun'yomi readings for some reason, no exception here.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u9f3b\u5148\u306b\u30de\u30b9\u30bf\u30fc\u30c9\u304c\u3064\u3044\u3066\u308b\u3088\u3002",
                    "en": "You got mustard at the tip of your nose."
                },
                {
                    "ja": "\u305d\u306e\u8b66\u5bdf\u72ac\u306f\u3001\u9f3b\u5148\u3092\u3072\u304f\u3072\u304f\u3055\u305b\u3066\u3001\u898b\u77e5\u3089\u306c\u4eba\u306e\u306b\u304a\u3044\u3092\u304b\u304e\u59cb\u3081\u305f\u3002",
                    "en": "That police dog started twitching the tip of its nose and sniffing at the stranger."
                },
                {
                    "ja": "\u30d5\u30b0\u306f\u30b5\u30fc\u30e2\u30f3\u306e\u9f3b\u5148\u304c\u8d64\u304f\u306a\u3063\u3066\u308b\u306e\u3092\u898b\u3066\u3001\u3068\u3066\u3082\u53ef\u611b\u3044\u3068\u611f\u3058\u305f\u3002",
