            "contextSentences": [
                {
                    "ja": "\u30b3\u30a6\u30a4\u30c1\u306f\u30c8\u30fc\u30d5\u30b0\u306e\u3053\u3068\u3092\u3068\u3066\u3082\u611b\u3057\u3066\u3044\u3066\u3001\u300c\u307c\u304f\u306e\u611b\u3059\u308b\u30c8\u30fc\u30d5\u30b0\u3061\u3083\u3093\u300d\u3068\u304b\u3063\u3066\u3088\u304f\u3064\u3076\u3084\u3044\u3066\u3044\u307e\u3059\u3002",
                    "en": "Koichi loves Tofugu very much and often murmurs things like, \"Oh my dear Tofugu-chan.\""
                },
                {
                    "ja": "\u611b\u3059\u308b\u4eba\u3092\u304d\u305a\u3064\u3051\u3066\u3057\u307e\u3063\u305f\u3002",
                    "en": "I hurt the person I love."
                },
                {
                    "ja": "\u4e3b\u4eba\u306f\u606f\u5b50\u306e\u3053\u3068\u306f\u611b\u3057\u3066\u3044\u307e\u3057\u305f\u304c\u3001\u611b\u60c5\u3092\u793a\u3057\u305f\u3053\u3068\u306f\u4e00\u5ea6\u3082\u3042\u308a\u307e\u305b\u3093\u3067\u3057\u305f\u3002\u304d\u3063\u3068\u3001\u3069\u3046\u3059\u308c\u3070\u826f\u3044\u306e\u304b\u5206\u304b\u3089\u306a\u304b\u3063\u305f\u3093\u3060\u3068\u601d\u3044\u307e\u3059\u3002",
                    "en": "My husband loved our son, but never showed him any affection. I don't think he knew how."
                }
