            },
            "contextSentences": [
                {
                    "ja": "\u305d\u306e\u6226\u3044\u306e\u52dd\u6557\u306a\u3089\u3001\u4e00\u6628\u65e5\u306e\u671d\u6c7a\u307e\u308a\u307e\u3057\u305f\u3088\u3002",
