                },
                {
                    "ja": "\u30b3\u30a6\u30a4\u30c1\u306e\u305d\u306e\u4e00\u8a00\u304c\u3001\u52dd\u6557\u306e\u5206\u304b\u308c\u76ee\u306b\u306a\u3063\u305f\u3093\u3067\u3059\u3002",
                    "en": "That one word Koichi said made the difference between victory and defeat."
                },
                {
                    "ja": "\u79c1\u306e\u4e21\u89aa\u306f\u3044\u3064\u3082\u3001\u5168\u529b\u3092\u5c3d\u304f\u3057\u3055\u3048\u3059\u308c\u3070\u3001\u52dd\u6557\u306f\u554f\u984c\u3067\u306f\u306a\u3044\u3068\u8a00\u3063\u3066\u3044\u305f\u3051\u308c\u3069\u3001\u79c1\u306f\u305d\u308c\u304c\u597d\u304d\u3058\u3083\u3042\u308a\u307e\u305b\u3093\u3067\u3057\u305f\u3002\u3082\u3061\u308d\u3093\u3001\u79c1\u306f\u52dd\u6557\u3092\u3068\u3066\u3082\u6c17\u306b\u3057\u307e\u3059\u3002\u3060\u3063\u3066\u3001\u30d9\u30b9\u30c8\u3092\u5c3d\u304f\u3057\u305f\u5f8c\u306b\u8ca0\u3051\u308b\u306a\u3093\u3066\u3001\u610f\u5473\u304c\u7121\u3044\u3058\u3083\u306a\u3044\u3067\u3059\u304b\u3002",
