                "mnemonic": "\n{splitParent}This is a jukugo word, which usually means on'yomi readings from the kanji. If you know the readings of your kanji you'll know how to read this as well.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u865a\u5f31\u306a\u5b50\u3069\u3082\u3092\u898b\u308b\u3068\u3001\u5fc3\u914d\u306b\u306a\u308a\u307e\u3059\u3002",
                    "en": "Whenever I see a weak child, I get worried."
                },
                {
                    "ja": "\u79c1\u306f\u3044\u3061\u3087\u3046\u304c\u865a\u5f31\u306a\u3093\u3067\u3059\u3002",
                    "en": "I have a weak stomach."
                },
                {
                    "ja": "\u79c1\u306e\u606f\u5b50\u306f\u751f\u307e\u308c\u3064\u304d\u865a\u5f31\u4f53\u8cea\u3067\u3001\u904b\u52d5\u306f\u3067\u304d\u307e\u305b\u3093\u3002",
                    "en": "My son was born with a weak constitution, so he can\u2019t exercise."
                }
            ],
            "collocations": []
        }

{
