            "hints": "",
            "meanings": {
                "Primary": "Advance Notice",
                "Alternatives": "Forward Notice, Prior Notice",
                "Word Type": "noun, \u3059\u308b verb"
            },
            "vocabReadings": {
                "readings": [
                    {
                        "primary": true,
                        "reading": "\u3088\u3053\u304f"
