                },
                {
                    "ja": "\u65e5\u672c\u306e\u5f13\u9053\u306e\u5f13\u3063\u3066\u3001\u3069\u3046\u3057\u3066\u305d\u3093\u306a\u306b\u5f37\u3044\u306e\uff1f",
