            "contextSentences": [
                {
                    "ja": "\u3053\u308c\u3067\u3001\u501f\u7528\u91d1\u304c\u767e\u4e07\u5186\u306b\u9054\u3057\u3066\u3057\u307e\u3063\u305f\u3002",
