            "contextSentences": [
                {
                    "ja": "\u81ea\u5206\u306e\u4f53\u306e\u3069\u3053\u304b\u3092\u5909\u3048\u3089\u308c\u308b\u3068\u3057\u305f\u3089\u3001\u305c\u3063\u5bfe\u306b\u8133\u307f\u305d\u3092\u5909\u3048\u308b\u306d\u3002",
                    "en": "If I could change anything about my body, it would definitely be my brains."
                },
                {
                    "ja": "\u4eca\u65e5\u306f\u3064\u304b\u308c\u3059\u304e\u3066\u8133\u307f\u305d\u304c\u5168\u7136\u50cd\u3044\u3066\u3044\u307e\u305b\u3093\u3002",
