                },
                {
                    "ja": "\u8eab\u5206\u8a3c\u660e\u66f8\u3092\u3054\u63d0\u793a\u9802\u3051\u307e\u3059\u304b\uff1f",
                    "en": "Could I check your ID?"
                }
            ],
            "collocations": []
