                        "gender": "female",
                        "pronunciation": "\u304a\u307e\u3082\u308a",
                        "voiceActorId": 1,
                        "voiceActorName": "Kyoko",
                        "voiceDescription": "Tokyo accent",
                        "file": "30026-subject-4093.ogg"
                    },
                    {
                        "gender": "male",
                        "pronunciation": "\u304a\u307e\u3082\u308a",
                        "voiceActorId": 2,
                        "voiceActorName": "Kenichi",
                        "voiceDescription": "Tokyo accent",
                        "file": "21082-subject-4093.ogg"
                    }
                ],
                "mnemonic": "\n{splitParent}The reading is like that of {span:lang=ja:\u5b88\u308b}, so if you know the reading of that word you should be able to read this one as well.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u3053\u306e\u304a\u5b88\u308a\u3001\u3069\u306e\u3050\u3089\u3044\u304a\u501f\u308a\u3057\u3066\u3044\u3066\u3082\u3044\u3044\u3067\u3059\u304b\uff1f",
                    "en": "How long can I have this charm for?"
                },
                {
                    "ja": "\u304a\u5b88\u308a\u3092\u5165\u308c\u308b\u306e\u3092\u5fd8\u308c\u3061\u3083\u3063\u305f\u307f\u305f\u3044\u3002",
                    "en": "It seems I forgot to pack my amulet."
                },
                {
                    "ja": "\u305f\u304f\u3055\u3093\u306e\u304a\u5b88\u308a\u3092\u540c\u6642\u306b\u4ed8\u3051\u306a\u3044\u65b9\u304c\u3044\u3044\u3067\u3059\u3088\u3002\u9006\u306b\u4e0d\u5e78\u3092\u3082\u305f\u3089\u3059\u304b\u3082\u3057\u308c\u306a\u3044\u3067\u3059\u304b\u3089\u306d\u3002",
                    "en": "You shouldn\u2019t wear multiple lucky amulets at the same time. It could bring you bad luck instead."
                }
            ],
            "collocations": []
        }

{
            "mnemonic": "The kanji and the word are exactly the same. That means they share meanings as well.",
            "hints": "",
            "meanings": {
                "Primary": "Chest",
                "Alternative": "Breasts",
                "Word Type": "noun"
            },
            "vocabReadings": {
