            "contextSentences": [
                {
                    "ja": "\u305d\u306e\u7559\u5b66\u751f\u306f\u3001\u304f\u3064\u3072\u3082\u3092\u7d50\u3076\u306e\u3092\u3044\u3064\u3082\u5fd8\u308c\u3066\u3057\u307e\u3044\u307e\u3059\u3002",
                    "en": "That international student always forgets to tie his shoes."
