                {
                    "ja": "\u9280\u5ea7\u306e\u4e00\u7b49\u5730\u306b\u30aa\u30d5\u30a3\u30b9\u3092\u304b\u307e\u3048\u308b\u306a\u3093\u3066\u3001\u3088\u3063\u307d\u3069\u3082\u3046\u3051\u3066\u308b\u3093\u3060\u306a\u3041\u3002",
