                        "reading": "\u3057\u306a\u3082\u306e"
                    }
                ],
                "pronunciationAudios": [
                    {
                        "gender": "male",
                        "pronunciation": "\u3057\u306a\u3082\u306e",
                        "voiceActorId": 2,
                        "voiceActorName": "Kenichi",
