                    }
                ],
                "mnemonic": "\n{splitParent}This is a jukugo word, which usually means on'yomi readings from the kanji. If you know the readings of your kanji you'll know how to read this as well.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u30b3\u30a6\u30a4\u30c1\u306e\u8a71\u304b\u3089\u3001\u3069\u3093\u306a\u6559\u8a13\u304c\u3048\u3089\u308c\u307e\u3057\u305f\u304b\uff1f",
                    "en": "What moral can you draw from Koichi's story?"
                },
                {
                    "ja": "\u3053\u306e\u6559\u8a13\u3092\u7121\u3060\u306b\u306f\u3057\u307e\u305b\u3093\u3002",
                    "en": "I'll keep this lesson in mind."
                },
                {
                    "ja": "\u524d\u8077\u304b\u3089\u5b66\u3093\u3060\u6700\u5927\u306e\u6559\u8a13\u3092\u6559\u3048\u3066\u304f\u3060\u3055\u3044\u3002",
                    "en": "Tell me about the biggest lesson you learned from your previous company."
                }
            ],
