{
            "mnemonic": "A {tooltip:Kanji:song} you sing to {tooltip:Kanji:protect} your {tooltip:Kanji:child} while they sleep is called a {tooltip:Vocabulary:lullaby}.",
            "hints": "",
            "meanings": {
                "Primary": "Lullaby",
                "Word Type": "noun"
            },
            "vocabReadings": {
                "readings": [
                    {
                        "primary": true,
                        "reading": "\u3053\u3082\u308a\u3046\u305f"
                    }
                ],
                "pronunciationAudios": [
                    {
                        "gender": "female",
                        "pronunciation": "\u3053\u3082\u308a\u3046\u305f",
                        "voiceActorId": 1,
