                    }
                ],
                "mnemonic": "\n{splitParent}This is a jukugo word, which usually means on'yomi readings from the kanji. If you know the readings of your kanji you'll know how to read this as well.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u4eba\u985e\u306e\u6700\u5927\u306e\u3066\u304d\u306f\u4f55\u3060\u3068\u601d\u3044\u307e\u3059\u304b\uff1f",
                    "en": "What do you think is the greatest enemy of mankind?"
                },
                {
                    "ja": "\u304a\u524d\u306f\u4eba\u985e\u306e\u306f\u3058\u3060\u3088\uff01",
                    "en": "You are a disgrace to the human race!"
                },
                {
                    "ja": "\u30a2\u30e4\u306f\u3001\u30d9\u30fc\u30b3\u30f3\u306f\u4eba\u985e\u304c\u5f8c\u4e16\u306b\u6b8b\u3059\u3079\u304d\u6700\u3082\u91cd\u8981\u306a\u907a\u7523\u306e\u4e00\u3064\u3060\u3068\u4e3b\u5f35\u3057\u305f\u3002",
                    "en": "Aya insisted that bacon is one of the most important things for humankind to hand down to future generations."
                }
            ],
            "collocations": []
        }

{
