{
            "mnemonic": "This is a day of the week. You know this because it has {span:lang=ja:\u66dc\u65e5} in it. But what day of the week is it? The \"{tooltip:Kanji:moon}\" day of the week is {tooltip:Vocabulary:monday}. Why? Because \"Moon\" is pretty much just \"Mon,\" right?",
            "hints": "",
            "meanings": {
                "Primary": "Monday",
                "Word Type": "noun"
            },
            "vocabReadings": {
                "readings": [
                    {
                        "primary": true,
                        "reading": "\u3052\u3064\u3088\u3046\u3073"
                    }
                ],
                "pronunciationAudios": [
