            },
            "contextSentences": [
                {
                    "ja": "\u540c\u308a\u3087\u3046\u9054\u306f\u3001\u307f\u3093\u306a\u305d\u306e\u5831\u9053\u306e\u3053\u3068\u3092\u3059\u3067\u306b\u77e5\u3063\u3066\u3044\u307e\u3057\u305f\u3002",
                    "en": "All of my coworkers knew about the news report already."
                },
                {
                    "ja": "\u4eca\u56de\u306e\u30c6\u30ed\u306e\u3053\u3068\u306f\u3001\u65e5\u672c\u3067\u306f\u3069\u306e\u3088\u3046\u306b\u5831\u9053\u3055\u308c\u3066\u3044\u307e\u3059\u304b\uff1f",
                    "en": "How will this terrorist attack be reported in Japan?"
                },
                {
