            "contextSentences": [
                {
                    "ja": "\u3053\u3053\u304c\u7981\u7159\u30b9\u30da\u30fc\u30b9\u3060\u3063\u3066\u3053\u3068\u3001\u5fd8\u308c\u3066\u308b\u308f\u3051\u306a\u3044\u3058\u3083\u306a\u3044\u3002",
