                {
                    "ja": "\u30b9\u30c6\u30c3\u30ab\u30fc\u306e\u679a\u6570\u306b\u3064\u3044\u3066\u306f\u3001\u4f55\u679a\u304f\u3089\u3044\u6ce8\u6587\u3067\u304d\u308b\u304b\u306f\u307e\u3060\u306f\u3063\u304d\u308a\u5206\u304b\u308a\u307e\u305b\u3093\u304c\u3001\u5c11\u306a\u304f\u3068\u3082\u767e\u679a\u306b\u306f\u306a\u308b\u3068\u601d\u3044\u307e\u3059\u3002",
