                        "voiceActorId": 2,
                        "voiceActorName": "Kenichi",
                        "voiceDescription": "Tokyo accent",
                        "file": "20730-subject-4106.ogg"
                    }
                ],
                "mnemonic": "\n{splitParent}If you know how to read {span:lang=ja:\u66f8\u304f} and {span:lang=ja:\u65b9} separately, you should be able to read this one too.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u3053\u306e\u6f22\u5b57\u306e\u66f8\u304d\u65b9\u304c\u601d\u3044\u51fa\u305b\u306a\u3044\u3002",
                    "en": "I can't remember how to write this kanji."
                },
                {
                    "ja": "\u30c8\u30fc\u30d5\u30b0\u306b\u306f\u3069\u3046\u3057\u3066\u66f8\u304d\u65b9\u3092\u6559\u3048\u308b\u30a2\u30d7\u30ea\u304c\u7121\u3044\u3093\u3067\u3059\u304b\uff1f",
                    "en": "Why doesn't Tofugu have an app to teach the ways of writing?"
                },
                {
                    "ja": "\u5e73\u4eee\u540d\u306e\u7dba\u9e97\u306a\u66f8\u304d\u65b9\u3092\u52c9\u5f37\u3059\u308b\u3053\u3068\u306b\u306f\u3001\u5fc3\u5e95\u98fd\u304d\u98fd\u304d\u3057\u3066\u308b\u3093\u3060\u3088\u306d\uff01",
                    "en": "I am bored out of my mind with studying hiragana penmanship."
                }
            ],
