            "contextSentences": [
                {
                    "ja": "\u30c8\u30fc\u30d5\u30b0\u306e\u6c7a\u7b97\u516c\u544a\u3001\u3082\u3046\u898b\u307e\u3057\u305f\u304b\u3002",
