            },
            "contextSentences": [
                {
                    "ja": "\u3053\u306e\u5ea7\u5e2d\u306e\u30af\u30c3\u30b7\u30e7\u30f3\u3001\u3081\u3063\u3061\u3083\u3044\u3044\u611f\u3058\u3002",
                    "en": "This seat's cushion is really comfy."
                },
                {
                    "ja": "\u5ea7\u5e2d\u306e\u4e88\u7d04\u304c\u5fc5\u8981\u3060\u3063\u305f\u3068\u306f\u3001\u77e5\u308a\u307e\u305b\u3093\u3067\u3057\u305f\u3002",
