            "contextSentences": [
                {
                    "ja": "\u3053\u306e\u6c7d\u8239\u306f\u3001\u3042\u306a\u305f\u306e\u56fd\u3067\u4f55\u756a\u76ee\u306b\u5927\u304d\u3044\u6c7d\u8239\u3067\u3059\u304b\uff1f",
