                {
                    "ja": "\u5f13\u9053\u3067\u306f\u3001\u77e2\u3092\u653e\u3064\u524d\u306b\u3001\u5f13\u3092\u5f15\u304d\u304d\u3063\u305f\u72b6\u614b\u3067\u4e00\u77ac\u9759\u6b62\u3059\u308b\u5fc5\u8981\u304c\u3042\u308a\u307e\u3059\u304c\u3001\u897f\u6d0b\u306e\u30a2\u30fc\u30c1\u30a7\u30ea\u30fc\u3082\u540c\u3058\u3067\u3059\u304b\uff1f",
