                    }
                ],
                "mnemonic": "\n{splitParent}This reading for this is a bit of an exception. You know the reading for {span:lang=ja:\u9054} is {span:lang=ja:\u305f\u3064}, but here it's shortened, to just {span:lang=ja:\u305f\u3063}. So make sure you remember.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u5c11\u3057\u304a\u304f\u308c\u305f\u304c\u3001\u7121\u4e8b\u306b\u76ee\u7684\u5730\u306b\u9054\u3057\u305f\u3002",
                    "en": "We were a little bit late, but we arrived safely at our destination."
                },
                {
                    "ja": "\u30b3\u30a6\u30a4\u30c1\u306e\u3072\u3052\u306f\u3001\u3064\u3044\u306b\u3053\u3057\u307e\u3067\u9054\u3057\u305f\u3002",
                    "en": "Koichi's beard finally reached his waist."
                },
                {
                    "ja": "\u76ee\u6a19\u4eba\u6570\u306b\u9054\u3059\u308b\u307e\u3067\u3001\u3042\u3068\u5c11\u3057\u3060\u3002",
                    "en": "Only a little longer until we attain the target number of people."
