            "contextSentences": [
                {
                    "ja": "\u30b3\u30a6\u30a4\u30c1\u306f\u3001\u305c\u3063\u5bfe\u306b\u516d\u6642\u307e\u3067\u306b\u914d\u9054\u3057\u3066\u307f\u305b\u308b\u3068\u8a00\u3063\u3066\u3001\u80f8\u3092\u305f\u305f\u304d\u307e\u3057\u305f\u3002",
