                    "ja": "\u3053\u306e\u82b1\u3092\u4eca\u65e5\u4e2d\u306b\u914d\u9054\u3057\u306a\u3051\u308c\u3070\u3044\u3051\u306a\u3044\u306e\u3092\u3001\u3059\u3063\u304b\u308a\u5fd8\u308c\u3066\u3044\u307e\u3057\u305f\u3002",
