                    "ja": "\u50d5\u306e\u304a\u7236\u3055\u3093\u306f\u30d4\u30b6\u306e\u914d\u9054\u4eba\u3067\u3059\u3002\u8ab0\u3088\u308a\u3082\u901f\u304f\u30d4\u30b6\u3092\u914d\u9054\u3059\u308b\u3053\u3068\u304c\u3067\u304d\u307e\u3059\u3002",
