            "contextSentences": [
                {
                    "ja": "\u3054\u3081\u3093\u306d\u3001\u30ab\u30ca\u30a8\u3061\u3083\u3093\u3002\u307f\u3093\u306a\u30ab\u30ca\u30a8\u3061\u3083\u3093\u304c\u3069\u308c\u3060\u3051\u52aa\u529b\u3057\u305f\u306e\u304b\u3059\u3063\u304b\u308a\u5fd8\u308c\u3061\u3083\u3063\u3066\u305f\u3093\u3060\u3002",
                    "en": "Sorry, Kanae. We all totally forgot about how much effort you put into it."
                },
                {
                    "ja": "\u5371\u3046\u304f\u30b3\u30a6\u30a4\u30c1\u306e\u9854\u3092\u5fd8\u308c\u308b\u6240\u3060\u3063\u305f\u3088\u3002",
                    "en": "I almost forgot Koichi's face."
                },
                {
                    "ja": "\u3082\u3046\u5fd8\u308c\u306a\u3063\u3066\u3002\u904e\u304e\u3066\u3057\u307e\u3063\u305f\u3053\u3068\u306f\u4eca\u3055\u3089\u3069\u3046\u306b\u3082\u306a\u3089\u306a\u3044\u3093\u3060\u304b\u3089\u3002",
