                        "voiceActorId": 1,
                        "voiceActorName": "Kyoko",
                        "voiceDescription": "Tokyo accent",
                        "file": "30059-subject-8710.ogg"
                    }
                ],
                "mnemonic": "\n{splitParent}This has the same reading as the kanji you learned, meaning you know the reading!\n"
            },
            "contextSentences": [
                {
                    "ja": "\u3053\u308c\u306f\u3001\u30b3\u30a6\u30a4\u30c1\u304c\u81ea\u5206\u306e\u7981\u3058\u3089\u308c\u305f\u604b\u306b\u3064\u3044\u3066\u66f8\u3044\u305f\u79c1\u5c0f\u8aac\u3067\u3059\u3002",
                    "en": "This is an autobiographical novel that Koichi wrote about his own forbidden love."
                },
                {
                    "ja": "\u533b\u8005\u306f\u3001\u306b\u3093\u3077\u306b\u30a2\u30eb\u30b3\u30fc\u30eb\u3068\u55ab\u7159\u3092\u7981\u3058\u305f\u3002",
                    "en": "The doctor forbade the pregnant woman from alcohol and cigarettes."
                },
                {
                    "ja": "\u3053\u306e\u90e8\u5c4b\u3067\u306f\u3001\u79c1\u8a9e\u3092\u7981\u3058\u308b\u3002",
                    "en": "In this room, whispering is prohibited."
                }
