                    },
                    {
                        "gender": "male",
                        "pronunciation": "\u307b\u3046\u3058\u308b",
                        "voiceActorId": 2,
                        "voiceActorName": "Kenichi",
                        "voiceDescription": "Tokyo accent",
                        "file": "21523-subject-4091.ogg"
                    }
                ],
                "mnemonic": "\n{splitParent}The reading doesn't seem like it's the kanji's on'yomi reading, but it is. What an oddity! Do you think it's worth doing a news report on it? Koichi, reporting in on this strange reading that is readable by you right now. Signing off.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u30b9\u30fc\u30d1\u30fc\u30de\u30f3\u306e\u6b7b\u53bb\u304c\u5831\u3058\u3089\u308c\u3001\u5168\u7c73\u304c\u6d99\u3057\u305f\u3002",
                    "en": "The entire United States wept when they broke the news that Superman had died."
                },
                {
                    "ja": "\u30b3\u30a6\u30a4\u30c1\u306e\u7121\u4e8b\u304c\u5831\u3058\u3089\u308c\u3066\u3001\u80f8\u3092\u306a\u3067\u4e0b\u308d\u3057\u307e\u3057\u305f\u3002",
                    "en": "I felt relieved when they reported that Koichi is safe."
                },
                {
                    "ja": "Tofugu\u306f\u3001\u521d\u97f3\u30df\u30af\u306e\u72ec\u5360\u53d6\u6750\u3092\u5831\u3058\u305f\u3002",
                    "en": "Tofugu covered an exclusive interview with Hatsune Miku."
                }
            ],
            "collocations": []
        }

{
            "mnemonic": "If you take your {tooltip:Kanji:writing} and {tooltip:Kanji:fix} it, you are taking your writing and rewriting it. This word means {tooltip:Vocabulary:to rewrite}, because the fixing is really heavy, so regular revisions won't do.",
            "hints": "",
            "meanings": {
                "Primary": "To Rewrite",
                "Word Type": "transitive verb, godan verb"
            },
            "vocabReadings": {
                "readings": [
