                        "primary": true,
                        "reading": "\u304b\u304d\u306a\u304a\u3059"
                    }
                ],
                "pronunciationAudios": [
                    {
                        "gender": "female",
                        "pronunciation": "\u304b\u304d\u306a\u304a\u3059",
                        "voiceActorId": 1,
                        "voiceActorName": "Kyoko",
