            "contextSentences": [
                {
                    "ja": "\u5bb6\u306b\u5e30\u3063\u305f\u3089\u624b\u3092\u6d17\u3063\u3066\u3046\u304c\u3044\u3092\u3057\u3066\u304f\u3060\u3055\u3044\u3002",
