            },
            "contextSentences": [
                {
                    "ja": "\u3044\u305d\u304c\u3057\u3059\u304e\u3066\u3001\u99c5\u5f01\u3092\u8cb7\u3046\u306e\u3092\u5fd8\u308c\u3066\u307e\u3057\u305f\u3002",
