            },
            "contextSentences": [
                {
                    "ja": "\u3042\u308b\u6674\u308c\u305f\u706b\u66dc\u65e5\u306e\u671d\u3001\u5bb6\u306e\u82b1\u306b\u6c34\u3084\u308a\u3092\u3057\u3066\u3044\u308b\u3068\u3001\u767d\u3044\u3072\u3052\u3092\u751f\u3084\u3057\u305f\u304a\u3058\u3044\u3055\u3093\u306b\u8a71\u3057\u304b\u3051\u3089\u308c\u307e\u3057\u305f\u3002",
                    "en": "On one sunny, Tuesday morning, an old man with a white beard started talking to me while I was watering my flowers."
                },
                {
                    "ja": "\u3059\u307f\u307e\u305b\u3093\u304c\u3001\u6765\u9031\u306e\u6708\u66dc\u65e5\u3068\u706b\u66dc\u65e5\u306f\u3044\u305d\u304c\u3057\u3044\u3093\u3067\u3059\u3002",
                    "en": "I'm sorry, but I am busy next Monday and Tuesday."
                },
                {
                    "ja": "\u706b\u66dc\u65e5\u306f\u91ce\u7403\u3067\u30b3\u30c6\u30f3\u30d1\u306b\u3084\u3089\u308c\u305f\u3088\u3002",
                    "en": "I got owned in baseball on Tuesday."
                }
            ],
            "collocations": []
        }

