            "contextSentences": [
                {
                    "ja": "\u4eca\u65e5\u306e\u5fd8\u5e74\u4f1a\u3067\u3042\u3063\u305f\u51fa\u6765\u4e8b\u306f\u3001\u5fd8\u308c\u308b\u4e8b\u306b\u3057\u307e\u3059\u3002",
