                {
                    "ja": "\u5143\u3005\u5fd8\u308c\u3063\u307d\u3044\u3093\u3067\u3001\u79c1\u306b\u306f\u300c\u5fd8\u5e74\u4f1a\u300d\u306f\u5fc5\u8981\u3042\u308a\u307e\u305b\u3093\u3002",
