            },
            "contextSentences": [
                {
                    "ja": "\u305d\u306e\u7985\u50e7\u306f\u3001\u3059\u304d\u3063\u3071\u3089\u306b\u4e0d\u5473\u3044\u3082\u306e\u306f\u7121\u3044\u3068\u3044\u3046\u8a00\u8449\u3092\u5b9f\u611f\u3057\u307e\u3057\u305f\u3002",
