{
            "mnemonic": "A {tooltip:Kanji:zen} {tooltip:Kanji:temple} is just what it sounds like, a {tooltip:Vocabulary:zen temple}. Sounds nice.",
            "hints": "",
            "meanings": {
                "Primary": "Zen Temple",
                "Word Type": "noun"
            },
            "vocabReadings": {
                "readings": [
                    {
                        "primary": true,
                        "reading": "\u305c\u3093\u3067\u3089"
                    },
                    {
                        "primary": false,
