                    }
                ],
                "pronunciationAudios": [
                    {
                        "gender": "male",
                        "pronunciation": "\u305c\u3093\u3058",
                        "voiceActorId": 2,
                        "voiceActorName": "Kenichi",
                        "voiceDescription": "Tokyo accent",
                        "file": "41776-subject-4127.ogg"
                    },
                    {
                        "gender": "female",
                        "pronunciation": "\u305c\u3093\u3058",
                        "voiceActorId": 1,
                        "voiceActorName": "Kyoko",
                        "voiceDescription": "Tokyo accent",
                        "file": "41419-subject-4127.ogg"
                    },
                    {
                        "gender": "female",
                        "pronunciation": "\u305c\u3093\u3067\u3089",
                        "voiceActorId": 1,
                        "voiceActorName": "Kyoko",
                        "voiceDescription": "Tokyo accent",
                        "file": "30038-subject-4127.ogg"
                    },
                    {
                        "gender": "male",
                        "pronunciation": "\u305c\u3093\u3067\u3089",
                        "voiceActorId": 2,
                        "voiceActorName": "Kenichi",
                        "voiceDescription": "Tokyo accent",
                        "file": "20616-subject-4127.ogg"
                    }
                ],
                "mnemonic": "\n{splitParent}The reading is the two words {span:lang=ja:\u7985} and {span:lang=ja:\u5bfa} put together. The {span:lang=ja:\u3066\u3089} gets changed to {span:lang=ja:\u3067\u3089}, though.\n{splitParent}In terms of when it's pronounced {span:lang=ja:\u305c\u3093\u3058}, if you put this word onto the end of the name of a {span:lang=ja:\u7985\u5bfa} the pronunciation changes to {span:lang=ja:\u305c\u3093\u3058}. It makes sense - it's more like a jukugo word that way (not that the original isn't, but you can see the separation of words coming together which gives the hint that it's a kun'yomi combo reading). Anyways, you may need a zen temple to keep your mind pure enough to remember this, but it's a good thing to keep in mind if you can.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u3042\u306e\u7985\u5bfa\u306e\u540d\u524d\u306f\u4f55\u3060\u3063\u3051\uff1f",
                    "en": "What's the name of that Zen temple, again?"
                },
                {
                    "ja": "\u3042\u306e\u7985\u5bfa\u3001\u3055\u3044\u3080\u3061\u3087\u3046\u304b\u306e\u4f1a\u793e\u306e\u304b\u3076\u306b\u6295\u3057\u3092\u3057\u3066\u3001\u75db\u3044\u76ee\u306b\u3042\u3063\u305f\u3089\u3057\u3044\u3088\u3002",
                    "en": "I read somewhere that that Zen temple invested in the stocks of a company with excessive liabilities and they had a dreadful experience."
                },
                {
                    "ja": "\u5929\u9f8d\u5bfa\u3068\u3044\u3046\u3001\u5341\u56db\u4e16\u7d00\u306b\u4eac\u90fd\u5e02\u897f\u90e8\u306b\u5efa\u3066\u3089\u308c\u305f\u7985\u5bfa\u304c\u597d\u304d\u3067\u3059\u3002",
                    "en": "The Tenry\u016b-ji is a Zen temple I like that was built in the 14th century in western Kyoto."
                }
            ],
            "collocations": []
        }

