            },
            "contextSentences": [
                {
                    "ja": "\u65e5\u672c\u3084\u304b\u3093\u56fd\u306f\u5b66\u6b74\u793e\u4f1a\u3067\u3059\u304c\u3001\u30a2\u30e1\u30ea\u30ab\u306f\u3061\u304c\u3046\u3093\u3067\u3059\u304b\uff1f",
                    "en": "Japan and Korea are academic background oriented societies, but isn't America like that?"
                },
                {
                    "ja": "\u5b66\u6b74\u306f\u307b\u3068\u3093\u3069\u7121\u3044\u3051\u3069\u3001\u7acb\u3071\u306a\u4eba\u3082\u3044\u308b\u3088\u3002",
                    "en": "There are praiseworthy people who've had very little academic history."
                },
                {
                    "ja": "\u300c\u304a\u6bcd\u3055\u3093\u3001\u79c1\u306d\u3001\u4eca\u65e5\u3082\u30c6\u30b9\u30c8\u3067\u6e80\u70b9\u3068\u3063\u305f\u306e\u3002\u300d\u300c\u305d\u308c\u304c\u3069\u3046\u3057\u305f\u306e\u3088\uff1f\u3042\u3093\u305f\u672c\u6c17\u3067\u5b66\u6b74\u304c\u5168\u3066\u3060\u3068\u601d\u3063\u3066\u308b\u308f\u3051\uff1f\u300d",
                    "en": "\"Hey, mom! I got a perfect score on my test again.\" \"So what? Do you really believe a person\u2019s academic record is everything?\""
                }
            ],
            "collocations": []
        }

{
