                    },
                    {
                        "gender": "male",
                        "pronunciation": "\u3054\u3058\u3085\u3046\u304a\u3093\u3058\u3085\u3093",
                        "voiceActorId": 2,
                        "voiceActorName": "Kenichi",
                        "voiceDescription": "Tokyo accent",
                        "file": "21553-subject-4253.ogg"
                    }
                ],
                "mnemonic": "\n{splitParent}This is a jukugo word, which usually means on'yomi readings from the kanji. If you know the readings of your kanji you'll know how to read this as well.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u753a\u540d\u306f\u4e94\u5341\u97f3\u9806\u306b\u306a\u3089\u3093\u3067\u3044\u307e\u3059\u3002",
                    "en": "The town names are listed in aiueo order."
                },
                {
                    "ja": "\u3053\u306e\u540d\u307c\u3067\u306f\u3001\u5b66\u751f\u306e\u540d\u524d\u306f\u540d\u5b57\u3067\u4e94\u5341\u97f3\u9806\u306b\u8a18\u3055\u3044\u3055\u308c\u3066\u3044\u307e\u3059\u3002",
                    "en": "In this list, the students\u2019 names are placed in aiueo order by surname."
                },
                {
                    "ja": "\u65e5\u672c\u3067\u521d\u3081\u3066\u4e94\u5341\u97f3\u9806\u306b\u914d\u5217\u3055\u308c\u305f\u56fd\u8a9e\u8f9e\u5178\u306f\u3001\u300e\u548c\u8a13\u681e\u300f\u3067\u3059\u3002",
                    "en": "The first Japanese dictionary arranged in Japanese syllabary order was the \"Wakun no shiori.\""
                }
            ],
            "collocations": []
        }

{
            "mnemonic": "A {tooltip:Kanji:cat}'s {tooltip:Kanji:tongue} is for some reason associated with an {tooltip:Vocabulary:aversion to hot foods}. I guess I haven't seen a cat drinking up boiling milk, but whatever. Just imagine a cat licking up something super hot and freaking out. Cats don't like hot things, which is why this is an aversion to hot foods.",
            "hints": "",
            "meanings": {
                "Primary": "Aversion To Hot Foods",
                "Word Type": "noun"
            },
            "vocabReadings": {
                "readings": [
                    {
                        "primary": true,
                        "reading": "\u306d\u3053\u3058\u305f"
