                    }
                ],
                "mnemonic": "\n{splitParent}Since this word is made up of a single kanji, it should use the kun'yomi reading. When learning the kanji, you didn't learn that reading, so here's a mnemonic to help you with this word: You take your {tooltip:Kanji:cloth} and put it on top of your head. It's there because right at {tooltip:Reading:noon} ({span:lang=ja:\u306c\u306e}) the sun is in the middle of the sky and burns your scalp. So, you cover it with a cloth. Imagine yourself setting an alarm for noon to help you to focus on the noon part.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u305d\u306e\u5e03\u3001\u65b0\u3057\u3044\u5e03\u306b\u5909\u3048\u3066\u3082\u3089\u3048\u308b\u304b\u306a\uff1f",
                    "en": "Can you change out this cloth for a new one?"
                },
                {
                    "ja": "\u5e03\u304c\u7d61\u3093\u3058\u3083\u3063\u3066\u3001\u30c1\u30e3\u30c3\u30af\u304c\u3046\u307e\u304f\u958b\u304b\u306a\u3044\u306e\u3088\u3002",
                    "en": "The cloth got caught in my zipper and it won't move right."
                },
                {
                    "ja": "\u5e03\u304a\u3080\u3064\u306e\u65b9\u304c\u7d19\u304a\u3080\u3064\u3088\u308a\u3082\u5065\u5eb7\u306b\u3044\u3044\u3068\u805e\u3044\u305f\u3053\u3068\u304c\u3042\u308a\u307e\u3059\u3002",
