{
            "mnemonic": "This is a single kanji with an {span:lang=ja:\u3044} on the end, meaning you know it's probably an adjective. What's the adjective form of {tooltip:Kanji:easy}? It's also {tooltip:Vocabulary:easy}.",
            "hints": "",
            "meanings": {
                "Primary": "Easy",
                "Alternative": "Simple To Do",
                "Word Type": "\u3044 adjective"
            },
            "vocabReadings": {
                "readings": [
                    {
                        "primary": true,
                        "reading": "\u3084\u3055\u3057\u3044"
                    }
                ],
                "pronunciationAudios": [
                    {
                        "gender": "male",
                        "pronunciation": "\u3084\u3055\u3057\u3044",
                        "voiceActorId": 2,
                        "voiceActorName": "Kenichi",
                        "voiceDescription": "Tokyo accent",
                        "file": "21000-subject-4208.ogg"
