                "mnemonic": "\n{splitParent}This is a jukugo word, which usually means on'yomi readings from the kanji. If you know the readings of your kanji you'll know how to read this as well.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u5165\u56e3\u3059\u308b\u305f\u3081\u306e\u7533\u3057\u3053\u307f\u66f8\u306f\u3001\u7d30\u304b\u3044\u6d3b\u5b57\u3067\u3044\u3093\u3055\u3064\u3055\u308c\u3066\u3044\u307e\u3057\u305f\u3002",
                    "en": "The application for the enrollment was printed in small type."
                },
                {
                    "ja": "\u305d\u306e\u6559\u56e3\u306b\u5165\u56e3\u3057\u3066\u3082\u3001\u4f55\u306e\u5f97\u306b\u3082\u306a\u3089\u306a\u3044\u3088\u3002",
                    "en": "You won't gain anything out of joining that religious organization."
                },
                {
                    "ja": "\u5341\u6708\u4e8c\u5341\u4e09\u65e5\u91d1\u66dc\u65e5\u3001Tofugu\u91ce\u7403\u30c1\u30fc\u30e0\u306f\u3001Tofugu\u30aa\u30d5\u30a3\u30b9\u3067\u5165\u56e3\u30c6\u30b9\u30c8\u3092\u5b9f\u65bd\u3057\u307e\u3059\u3002",
