                    "ja": "\u3053\u306e\u52a9\u8a5e\u306b\u3064\u3044\u3066\u306e\u8aac\u660e\u306f\u3001\u7d30\u304b\u3044\u70b9\u304c\u3044\u304f\u3064\u304b\u3057\u3087\u3046\u308a\u3083\u304f\u3055\u308c\u3066\u3044\u307e\u3059\u3002",
