{
            "mnemonic": "An {tooltip:Kanji:automatic} {tooltip:Kanji:part of speech} is an {tooltip:Vocabulary:intransitive verb}. Intransitive verbs are actions that just happen, aka you're not the one doing the action or thing. These are words like {span:lang=ja:\u4ed8\u304f} or {span:lang=ja:\u6d88\u3048\u308b}, where you aren't doing the action. That's why they're automatic!",
            "hints": "",
            "meanings": {
                "Primary": "Intransitive Verb",
                "Word Type": "noun"
            },
            "vocabReadings": {
                "readings": [
                    {
                        "primary": true,
                        "reading": "\u3058\u3069\u3046\u3057"
