            "contextSentences": [
                {
                    "ja": "\u4eca\u306f\u539f\u5b50\u529b\u306e\u662f\u975e\u306b\u3064\u3044\u3066\u8a71\u3092\u3057\u3066\u3044\u308b\u3093\u3060\u3002\u95a2\u4fc2\u7121\u3044\u8a71\u3092\u6301\u3061\u51fa\u3057\u3066\u982d\u3092\u6df7\u4e71\u3055\u305b\u306a\u3044\u3067\u304f\u308c\u3002",
