            "contextSentences": [
                {
                    "ja": "\u5b87\u5b99\u3067\u306e\u751f\u6d3b\u306b\u306f\u3001\u3044\u3044\u52a0\u6e1b\u3042\u304d\u3066\u3057\u307e\u3044\u307e\u3057\u305f\u3002",
