                    "ja": "\u30a2\u30eb\u30d0\u30a4\u30c8\u306b\u304a\u3046\u307c\u3059\u308b\u305f\u3081\u306b\u3001\u5c65\u6b74\u66f8\u3092\u4f5c\u6210\u3057\u307e\u3057\u305f\u3002",
