            "contextSentences": [
                {
                    "ja": "\u725b\u306b\u3085\u3046\u3092\u4e8c\u30ab\u30c3\u30d7\u52a0\u3048\u3066\u3001\u3086\u3063\u304f\u308a\u304b\u304d\u56de\u3057\u3066\u304f\u3060\u3055\u3044\u3002",
                    "en": "Please add two cups of milk and stir slowly."
