            },
            "contextSentences": [
                {
                    "ja": "\u4f1a\u793e\u3092\u9996\u306b\u306a\u3063\u305f\u3089\u9023\u7d61\u3059\u308b\u3088\u3002",
                    "en": "I'll get in touch with you after I'm fired."
                },
                {
                    "ja": "\u30b3\u30a6\u30a4\u30c1\u3068\u306f\u3048\u3093\u3092\u5207\u308a\u305f\u3044\u306e\u3067\u3001\u91d1\u8f2a\u3056\u3044\u9023\u7d61\u3057\u3066\u3053\u306a\u3044\u3067\u304f\u3060\u3055\u3044\u3002",
                    "en": "I want to cut ties with you, Koichi, so please never contact me again."
                },
                {
                    "ja": "\u3054\u3081\u3093\u3001\u884c\u304b\u306a\u304d\u3083\u3002\u4e88\u5b9a\u3092\u8abf\u3079\u3066\u3001\u5f8c\u3067\u6298\u308a\u8fd4\u3057\u9023\u7d61\u3059\u308b\u3088\u3002",
