                    "ja": "\u91d1\u7389\u3092\u637b\u3063\u3066\u3057\u307e\u3044\u3001\u75db\u307f\u304c\u4e94\u6642\u9593\u4ee5\u4e0a\u3082\u7d9a\u3044\u3066\u3044\u307e\u3059\u3002",
