                {
                    "ja": "\u30d3\u30bf\u30df\u30f3C\u304c\u8db3\u308a\u3066\u306a\u3044\u304b\u3089\u304b\u3001\u6700\u8fd1\u820c\u304c\u3042\u308c\u3066\u308b\u3093\u3060\u3088\u306d\u3002",
