                },
                {
                    "ja": "\u3088\u304f\u6bcd\u89aa\u306b\u9023\u308c\u3089\u308c\u3066\u3001\u652f\u3048\u3093\u30bb\u30f3\u30bf\u30fc\u3078\u884c\u3063\u3066\u3044\u305f\u306e\u3092\u899a\u3048\u3066\u3044\u307e\u3059\u3002",
                    "en": "I remember my mom used to take me along to the support center."
                },
                {
                    "ja": "\u30d5\u30b0\u3092\u52d5\u7269\u4fdd\u8b77\u65bd\u8a2d\u306b\u9023\u308c\u3066\u3044\u304f\u3057\u304b\u3042\u308a\u307e\u305b\u3093\u306d\u3002",
