            "contextSentences": [
                {
                    "ja": "\u8ca1\u5e03\u3092\u5bb6\u306b\u5fd8\u308c\u305f\u304a\u304b\u3052\u3067\u3001\u5341\u30c9\u30eb\u5f97\u3092\u3057\u307e\u3057\u305f\u3002",
