                    "ja": "\u3053\u306e\u82e5\u8005\u306f\u3059\u3054\u3044\u3088\u3002\u5927\u7269\u306b\u306a\u308b\u524d\u306b\u30b5\u30a4\u30f3\u3092\u3082\u3089\u3063\u3066\u304a\u3044\u305f\u65b9\u304c\u3044\u3044\u3088\u3002",
