                "mnemonic": "\n{splitParent}You'll want to know the words {span:lang=ja:\u501f\u308a\u308b} and {span:lang=ja:\u624b} to be able to read this one. Combine them to know the reading.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u305d\u3046\u306f\u8a00\u3063\u3066\u3082\u3001\u501f\u308a\u624b\u304c\u898b\u3064\u304b\u3089\u306a\u3044\u53ef\u80fd\u6027\u3082\u3042\u308a\u307e\u3059\u3088\u306d\uff1f",
