            },
            "contextSentences": [
                {
                    "ja": "\u5f13\u77e2\u3067\u30b7\u30ab\u3092\u4ed5\u7559\u3081\u308b\u306b\u306f\u3001\u306b\u3093\u305f\u3044\u304c\u3044\u308a\u307e\u3059\u3002",
