                {
                    "ja": "\u3053\u306e\u6a5f\u68b0\u3092\u305d\u3046\u4f5c\u3059\u308b\u306e\u306f\u78ba\u304b\u306b\u96e3\u3057\u305d\u3046\u3060\u306d\u3002",
                    "en": "It seems like it might be difficult to operate this machine."
                },
                {
                    "ja": "\u78ba\u304b\u306bTofugu\u306f\u3001\u4f1d\u7d71\u7684\u306a\u65e5\u672c\u8a9e\u5b66\u7fd2\u696d\u754c\u306b\u30c0\u30d6\u30eb\u30d1\u30f3\u30c1\u3092\u98df\u3089\u308f\u305b\u307e\u3057\u305f\u3002",
