                    "ja": "\u72af\u7f6a\u306b\u307e\u304d\u3053\u307e\u308c\u3066\u547d\u3092\u843d\u3068\u3057\u305d\u3046\u306b\u306a\u308a\u307e\u3057\u305f\u304c\u3001\u5371\u6a5f\u4e00\u3071\u3064\u306e\u6240\u3067\u52a9\u304b\u308a\u307e\u3057\u305f\u3002",
