                    "ja": "\u901a\u5831\u3092\u53d7\u3051\u3066\u3001\u8b66\u5bdf\u306f\u72af\u7f6a\u306e\u73fe\u5834\u306b\u98db\u3093\u3067\u884c\u3063\u305f\u3002",
