                "pronunciationAudios": [
                    {
                        "gender": "female",
                        "pronunciation": "\u308f\u3056\u308f\u3044",
                        "voiceActorId": 1,
                        "voiceActorName": "Kyoko",
                        "voiceDescription": "Tokyo accent",
