            "contextSentences": [
                {
                    "ja": "\u6a5f\u5185\u3067\u306f\u304a\u624b\u6301\u3061\u306e\u96fb\u5b50\u6a5f\u5668\u306e\u96fb\u3052\u3093\u306f\u304a\u5207\u308a\u306b\u306a\u308b\u304b\u6a5f\u5185\u30e2\u30fc\u30c9\u306b\u3054\u305b\u3063\u5b9a\u304f\u3060\u3055\u3044\u307e\u3059\u3088\u3046\u3001\u3054\u5354\u529b\u304a\u9858\u3044\u7533\u3057\u4e0a\u3052\u307e\u3059\u3002",
                    "en": "Please turn off all personal electronic devices or set them to airplane mode on this plane. Thank you for your cooperation."
