            "contextSentences": [
                {
                    "ja": "\u305d\u3082\u305d\u3082\u3001\u3053\u306e\u753a\u306b\u306f\u6c34\u5bb3\u9632\u6b62\u5bfe\u3055\u304f\u304c\u5b58\u5728\u3057\u3066\u3044\u306a\u304b\u3063\u305f\u3093\u3060\u3088\u3002",
