            },
            "contextSentences": [
                {
                    "ja": "\u79c1\u306f\u3001\u98db\u884c\u6a5f\u3067\u65c5\u884c\u3092\u3057\u305f\u7d4c\u9a13\u304c\u3042\u308a\u307e\u305b\u3093\u3002",
                    "en": "I've never had the experience of traveling by plane."
                },
                {
                    "ja": "\u53cb\u9054\u3092\u52a9\u3051\u3088\u3046\u3068\u3057\u305f\u3089\u3001\u4eca\u5ea6\u306f\u975e\u96e3\u306e\u307b\u3053\u5148\u304c\u81ea\u5206\u306b\u5411\u3044\u3066\u3057\u307e\u3046\u3068\u3044\u3046\u7d4c\u9a13\u3092\u3057\u305f\u3053\u3068\u304c\u3042\u308b\u4eba\u306f\u3044\u307e\u3059\u304b\uff1f",
                    "en": "Has anyone else had the experience where you try to help a friend and then you get blamed instead?"
                },
                {
                    "ja": "\u300c\u305d\u3046\u3060\u3001\u7d50\u5a5a\u30ab\u30a6\u30f3\u30bb\u30ea\u30f3\u30b0\u306f\u8a66\u3057\u3066\u307f\u305f\u306e\uff1f\u300d \u300c\u3082\u3061\u308d\u3093\u3001\u3068\u3063\u304f\u306b\u7d4c\u9a13\u6e08\u307f\u3060\u308f\u3088\u3002\u3067\u3082\u3001\u4e0a\u624b\u304f\u3044\u304b\u306a\u304b\u3063\u305f\u308f\u3002\u300d",
