                {
                    "ja": "\u4eca\u65e5\u5b66\u6821\u3067\u3001\u300c\u707d\u96e3\u306f\u52c7\u6c17\u3092\u8a66\u3059\u8a66\u91d1\u77f3\u3067\u3042\u308b\u3002\u300d\u3068\u3044\u3046\u3053\u3068\u308f\u3056\u3092\u7fd2\u3044\u307e\u3057\u305f\u3002",
