                {
                    "ja": "\u3069\u3046\u3057\u3066\u3042\u3044\u3064\u306f\u3042\u3093\u306a\u306b\u707d\u96e3\u306b\u898b\u821e\u308f\u308c\u3066\u3070\u304b\u308a\u3044\u308b\u306e\u304b\u306a\uff1f\u672c\u5f53\u306b\u5076\u7136\u306a\u306e\u304b\u3001\u305d\u308c\u3068\u3082\u3042\u3044\u3064\u81ea\u4f53\u306b\u4f55\u304b\u554f\u984c\u304c\u3042\u308b\u3093\u3060\u308d\u3046\u304b\u3002",
