                {
                    "ja": "\u4e3b\u5f79\u304c\u6025\u75c5\u306b\u306a\u3063\u305f\u3093\u3060\u3051\u3069\u3001\u4ee3\u5f79\u304c\u898b\u3064\u304b\u3089\u306a\u304f\u3066\u306d\u3002\u307e\u3055\u306b\u60aa\u5922\u3060\u3063\u305f\u3088\u3002",
