                {
                    "ja": "\u3053\u3053\u307e\u3067\u6765\u308c\u3070\u3001\u3066\u304d\u306e\u59a8\u5bb3\u306e\u5371\u967a\u306f\u307b\u307c\u7121\u3044\u3060\u308d\u3046\u3002",
