            "contextSentences": [
                {
                    "ja": "\u304a\u304f\u6b6f\u306b\u4e00\u500b\u3001\u5927\u304d\u306a\u7a74\u304c\u7a7a\u3044\u3066\u3044\u308b\u306d\u3002",
