                {
                    "ja": "\u305d\u306e\u30a4\u30c1\u30b4\u306f\u3001\u4e00\u500b\u767e\u5186\u306b\u3082\u304b\u304b\u308f\u3089\u305a\u3001\u98db\u3076\u3088\u3046\u306b\u58f2\u308c\u307e\u3057\u305f\u3002",
                    "en": "Those strawberries were one hundred yen each, but they flew off the shelves."
                },
                {
                    "ja": "\u30d3\u30a8\u30c8\u306f\u30b7\u30e5\u30fc\u30af\u30ea\u30fc\u30e0\u304c\u3068\u3063\u3066\u3082\u597d\u304d\u306a\u306e\u3067\u3001\u6bce\u65e5\u5c11\u306a\u304f\u3068\u3082\u4e00\u500b\u306f\u98df\u3079\u307e\u3059\u3002",
