                "mnemonic": "\n{splitParent}This is a jukugo word, which usually means on'yomi readings from the kanji. If you know the readings of your kanji you'll know how to read this as well.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u5728\u5916\u3057\u7523\u306f\u3069\u306e\u3088\u3046\u306b\u304b\u3093\u7406\u3057\u3066\u3044\u307e\u3059\u304b\uff1f",
                    "en": "How do you manage your overseas assets?"
                },
                {
                    "ja": "\u5728\u5916\u307b\u3046\u4eba\u306e\u5b89\u3074\u306f\u3052\u3093\u5728\u78ba\u306b\u3093\u4e2d\u3067\u3059\u3002",
                    "en": "We are currently checking on the safety of Japanese residents abroad."
                },
                {
                    "ja": "\u5728\u5916\u6295\u7968\u3092\u3059\u308b\u524d\u306b\u3001\u7533\u3057\u8fbc\u307f\u7528\u7d19\u3092\u65e5\u672c\u5927\u4f7f\u9928\u304b\u65e5\u672c\u9818\u4e8b\u9928\u306b\u63d0\u51fa\u3059\u308b\u5fc5\u8981\u304c\u3042\u308a\u307e\u3059\u3002",
                    "en": "Before casting an overseas ballot, you have to submit an application to the Japanese embassy or the Japanese consulate."
                }
            ],
