                {
                    "ja": "\u4eca\u6708\u306e\u3055\u304c\u304f\u6b8b\u4f59\u304c\u304f\u306f\u73fe\u6642\u70b9\u3067\u3044\u304f\u3089\u306b\u306a\u3063\u3066\u3044\u307e\u3059\u304b\uff1f",
