{
            "mnemonic": "If you have {tooltip:Kanji:guilt} then you have committed a {tooltip:Vocabulary:sin} or {tooltip:Vocabulary:crime}. Come here and confess to Father Koichi.",
            "hints": "",
            "meanings": {
                "Primary": "Sin",
                "Alternative": "Crime",
                "Word Type": "independent noun"
            },
            "vocabReadings": {
                "readings": [
