                {
                    "ja": "\u30b3\u30a6\u30a4\u30c1\u306f\u3001\u9b5a\u306e\u5c3e\u3092\u898b\u305f\u3060\u3051\u3067\u9b5a\u306e\u7a2e\u985e\u3092\u8a00\u3046\u306e\u304c\u7279\u6280\u3067\u3059\u3002",
