                {
                    "ja": "\u4eca\u306b\u898b\u3066\u306a\u3055\u3044\u3002\u3042\u306e\u30d5\u30b0\u5c11\u5e74\u306f\u304d\u3063\u3068\u9762\u5012\u3092\u5f15\u304d\u8d77\u3053\u3059\u308f\u3088\u3002",
