            "contextSentences": [
                {
                    "ja": "\u6c34\u5bb3\u88ab\u707d\u8005\u9054\u306f\u3001\u9632\u6c34\u306e\u5bb6\u5177\u3092\u305d\u308d\u3048\u3066\u304a\u3051\u3070\u3088\u304b\u3063\u305f\u3068\u53e3\u3092\u305d\u308d\u3048\u3066\u8a00\u3044\u307e\u3057\u305f\u3002",
