                    "ja": "\u5929\u6c17\u4e88\u5831\u3092\u4e8b\u524d\u306b\u30c1\u30a7\u30c3\u30af\u3059\u308b\u306e\u304c\u9762\u5012\u304f\u3055\u304b\u3063\u305f\u3093\u3067\u3059\u3002",
