                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "None",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Imagine how many trees Ken examined before he found you both. Picture him putting his face really close to each one, then shedding a single tear when he realized this squid wasn't in it.",
                "mnemonic": "You're sticking your face in really, really close to {tooltip:Kanji:examine} this little squid in the tree when {tooltip:Reading:Ken} ({span:lang=ja:\u3051\u3093}) the samurai appears behind you. \"There you are, squid! Thank you citizen, I've been looking all over for my little chum.\""
            }
        }

{
            "mnemonic": "You have a scene going on inside your {tooltip:Radical:head}. It is of a pair of {tooltip:Radical:horns} on the {tooltip:Radical:ground} atop a {tooltip:Radical:mountain}. No. It is not just one pair of horns. It is many. So many that they create a giant {tooltip:Kanji:hill} atop the mountain, which is already pretty high.",
            "hints": "Imagine this hill of horns on top of this mountain. This hill of horns makes it possible for you to get just high enough to touch the top of the sky.",
            "meanings": {
                "Primary": "Hill"
            },
            "kanjiReadings": {
