                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "You try to ask the judge what his ruling is, but he just hits you on the shins again!",
                "mnemonic": "The {tooltip:Kanji:judge} is not happy with you. He tells you to come closer and when you do, he takes his gavel and hits you in the {tooltip:Reading:shin}s ({span:lang=ja:\u3057\u3093}). Ouch!"
            }
        }

{
            "mnemonic": "The {tooltip:Radical:leader} of the {tooltip:Radical:cow} tribe is too important to deal with small {tooltip:Kanji:matter}s and trivial {tooltip:Kanji:affair}s.",
            "hints": "Picture this hoity-toity cow leader who thinks he\u2019s too good for small matters and affairs. See him acting all fancy like he\u2019s better than everyone else. The cow even moos with a fake British accent. How pretentious.",
            "meanings": {
                "Primary": "Matter",
                "Alternative": "Affair"
