                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Picture Ken the samurai scooping poop for the leader of the cows, because that's a matter of poop and state.",
                "mnemonic": "All of his {tooltip:Kanji:affair}s are taken care of by {tooltip:Reading:Ken} ({span:lang=ja:\u3051\u3093}) the samurai, who he hired as his underling."
            }
        }

{
            "mnemonic": "{tooltip:Radical:Building}s hold {tooltip:Radical:festival}s on special {tooltip:Kanji:occasion}s.",
            "hints": "A festival can't be happening all the time. Then it wouldn't be special, it would just be a party building, so they can only happen on special occasions.",
            "meanings": {
                "Primary": "Occasion"
            },
            "kanjiReadings": {
