                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u3068",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Picture it: you're standing in a kayak with this cow, trying to untie the rope around their neck by getting your sword to cut it at the right angle. You can't hurt the cow or knock over the kayak. Can you solve it in time?!",
                "mnemonic": "You're trying to {tooltip:Kanji:untie} this cow from the {tooltip:Reading:kay}ak ({span:lang=ja:\u304b\u3044}) you're both currently in. Some jerk tied the cow to this kayak and sent it toward a waterfall. If you don't {tooltip:Kanji:solve} this riddle fast, you'll both go with the kayak over the falls!"
            }
        }

{
            "mnemonic": "Taking out your {tooltip:Radical:thread}, you sew together the {tooltip:Radical:public}'s {tooltip:Radical:heart}s to make them {tooltip:Kanji:whole} again.",
            "hints": "The world has been in turmoil and the public has been suffering, but it's time to stop splitting our hearts apart and fighting. It's time to be whole again.",
            "meanings": {
                "Primary": "Whole"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u305d\u3046",
                        "primary": true
