                    "ja": "\u305d\u306e\u30de\u30e9\u30bd\u30f3\u9078\u624b\u306f\u3001\u30b4\u30fc\u30eb\u306e\u76f4\u524d\u3067\u75b2\u308c\u304d\u3063\u3066\u5012\u308c\u3066\u3057\u307e\u3044\u307e\u3057\u305f\u3002",
