                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u304a\u3055",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "You have to pull very slowly, or the shoes will fall off the stool. But you really, really want to obtain these particular shoes (they're really sweet), so you keep scooting them toward you.",
                "mnemonic": "Today you want to {tooltip:Kanji:obtain} a new pair of {tooltip:Reading:shoe}s ({span:lang=ja:\u3057\u3085\u3046}). You tie your vines around the stool they're on, and slowly inch them toward the door."
            }
        }

{
            "mnemonic": "There is a {tooltip:Radical:tsunami} coming, so you stand on your {tooltip:Radical:roof} holding a {tooltip:Radical:leaf}, wearing {tooltip:Radical:fins}, and standing before a {tooltip:Radical:rice paddy} full of people. These are your neighbors and they're here to watch you {tooltip:Kanji:perform}.",
            "hints": "This {tooltip:Kanji:performance} will distract all of you from the impending tsunami. You wave the leaf and dance with the fins. It's a wonderful performance.",
