                    }
                ],
                "mnemonic": "\n{splitParent}Since this word has okurigana (hiragana attached to the kanji) you know that it's probably going to be the kun'yomi reading.\n{splitParent}Lucky for you, the kanji readings for transitive and intransitive verbs are almost always the same. Once you learn one, you know them both! This reading is the same as {span:lang=ja:\u52a0\u3048\u308b}. To help you distinguish between the two, remember that most verbs ending in {span:lang=ja:\u308f\u308b} are intransitive.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u3082\u3046\u3059\u3050\u65b0\u3057\u3044\u30ad\u30e3\u30e9\u30af\u30bf\u30fc\u304c\u52a0\u308f\u308b\u3088\uff01",
                    "en": "A new character will be added soon!"
                },
                {
                    "ja": "\u30b5\u30eb\u304c\u30d0\u30ec\u30dc\u30fc\u30eb\u306e\u8a66\u5408\u306b\u52a0\u308f\u3063\u305f\u3002",
                    "en": "A monkey joined in the volleyball match."
                },
                {
