                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u306e",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "The angel really should have mentioned ninjutsu earlier. Then maybe you would have gone straight to a dojo to learn instead of falling into a ninjutsu trap yourself. The angel definitely failed its mission.",
                "mnemonic": "\"I forgot to {tooltip:Kanji:mention}, you have to study nin{tooltip:Reading:jutsu} ({span:lang=ja:\u3058\u3085\u3064})!\" the angel yells. But it's too late, there are ninjas jumping out of the bushes around you and taking you hostage."
            }
        }

{
            "mnemonic": "On the {tooltip:Radical:ground} there's a {tooltip:Radical:ceremony} where everyone keeps {tooltip:Radical:stop}ping. This stopping ceremony is being performed by the {tooltip:Kanji:military}. They'll march one direction, then stop and turn, then march another direction, then stop again.",
            "hints": "The military really seems to have a thing for stopping a lot during their ceremonies.",
            "meanings": {
                "Primary": "Military"
            },
            "kanjiReadings": {
                "readings": [
