            }
        }

{
            "mnemonic": "There is a {tooltip:Radical:lantern} on top of a {tooltip:Radical:knife} in the {tooltip:Radical:dirt}. You walk up to take the knife and lantern when you realize it's just a {tooltip:Kanji:model}. It all looked real from far away, but now that you're up close you can see none of it is real.",
            "hints": "Why would anyone make a model that looks like a lantern and a knife sticking into the ground?",
            "meanings": {
                "Primary": "Model",
                "Alternative": "Type"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u3051\u3044",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u304b\u305f",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Haven't you seen any of those crazy cakes modeled after things like movies, towns, giants hams, and purses? They're all the rage. Next time you make a cake try to make it look like a model lantern and knife with fake cake dirt and everything.",
                "mnemonic": "You touch the {tooltip:Kanji:model} and see that it's made of {tooltip:Reading:ca}ke ({span:lang=ja:\u3051\u3044})! Someone really into lanterns and knives must have been given this model cake as a birthday present! Though they left it out here so they probably didn't like it."
            }
        }

{
            "mnemonic": "You have an {tooltip:Radical:animal} for a {tooltip:Radical:husband} with {tooltip:Radical:horns} that are {tooltip:Kanji:narrow}. This animal husband of yours is a goat. A goat with narrow horns. Why is this animal your husband? You\u2019re weird, that\u2019s why.",
            "hints": "Imagine yourself married to this animal husband with horns that are narrow. It\u2019s a strange marriage. Listen to the goat making its goat noises as it clomps around your home. Now hug your goat husband and feel its soft fluffy coat against your skin.",
            "meanings": {
                "Primary": "Narrow"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u304d\u3087\u3046",
                        "primary": false
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u305b\u307e, \u305b\u3070",
                        "primary": true
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "But that doesn\u2019t mean you can\u2019t imagine the semantics. The finer points of the relationship. Go ahead, imagine all the weird stuff that comes with the territory for having a goat as a husband. Use all that weird stuff to remember this kanji and its reading. Want an example? Just imagine the goat doing dishes! Goats don\u2019t have hands! Hahahahaha!!",
                "mnemonic": "I\u2019m not even going to get into the {tooltip:Reading:sema}ntics ({span:lang=ja:\u305b\u307e}) of how this weird relationship of yours works. Nope, this reading explanation is on the straight and {tooltip:Kanji:narrow}. Need to know basis. Classified. All that junk. There will be no discussion of the semantics between you and your goat lover."
            }
        }

{
            "mnemonic": "On your {tooltip:Radical:bamboo} {tooltip:Radical:roof} is a {tooltip:Radical:bear}. It is pulling the bamboo off, because it wants to use it to make a long {tooltip:Kanji:pipe}.",
            "hints": "Bamboo is great for pipes, and the only place for the bear to get it is your roof. So, that's why it's there.",
