                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Comrade, what the heck\n{linebreak}I want to get my car back\n{linebreak}I thought we were friends.",
                "mnemonic": "You feel really weird about this whole situation so you write your {tooltip:Kanji:comrade} a {tooltip:Reading:hai}ku ({span:lang=ja:\u306f\u3044}). It's really all you can do, since your car is long gone."
            }
        }

{
            "mnemonic": "There\u2019s a {tooltip:Radical:tsunami} coming and your {tooltip:Radical:older brother} is in no {tooltip:Kanji:condition} to escape. Your older brother has brittle bone syndrome so there\u2019s no way he\u2019ll be able to escape the tsunami in time in his condition.",
            "hints": "Imagine your poor brother and the condition he is in. His glass bones and paper skin make it impossible for him to move very fast. Imagine the sad face he makes when he realizes his fate.",
            "meanings": {
                "Primary": "Condition"
            },
            "kanjiReadings": {
                "readings": [
