                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "None",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "This is also, incidentally, where the tsunami's condition is the worst, so you better get to {span:lang=ja:\u304d\u3087\u3046\u3068} quick!",
                "mnemonic": "His {tooltip:Kanji:condition} gets worse and you have to travel all the way to his home in {span:lang=ja:\u304d\u3087\u3046\u3068} to get him out."
            }
        }

{
            "mnemonic": "If you {tooltip:Radical:poop} on the {tooltip:Radical:root}s of a {tooltip:Radical:building}, the {tooltip:Radical:sound} will {tooltip:Kanji:echo} all the way through the building, and each and every person in there will know what you did.",
            "hints": "Hear the poop echo. You know what a poop usually sounds like, now imagine that sound again, but louder and with an echo. How could anyone not notice?",
            "meanings": {
                "Primary": "Echo",
                "Alternatives": "Reverberation, Resound"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u304d\u3087\u3046",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u3072\u3073",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Welp. {span:lang=ja:\u304d\u3087\u3046\u3068} knows you pooped. That will echo through your memories for the rest of your life. I hope you're happy.",
                "mnemonic": "The {tooltip:Kanji:echo} doesn't stop there, this building's roots extend throughout the entire city of {span:lang=ja:\u304d\u3087\u3046\u3068}. The echo reverberates and soon everyone in {span:lang=ja:\u304d\u3087\u3046\u3068} is listening, horrified, to your poop."
            }
        }

{
