                    "ja": "\u65b0\u3057\u3044\u4eba\u4e8b\u90e8\u9577\u306f\u3001\u5f37\u5236\u7684\u306a\u30b5\u30fc\u30d3\u30b9\u6b8b\u696d\u306b\u95a2\u3059\u308b\u554f\u984c\u3092\u9bae\u3084\u304b\u306b\u89e3\u6c7a\u3057\u3066\u306e\u3051\u305f\u3002",
