                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Try to imagine feeling this way about your ray gun. It's so lovely.",
                "mnemonic": "\"{tooltip:Kanji:Lovely}\" is the name of my {tooltip:Reading:ray} ({span:lang=ja:\u308c\u3044}) gun. It's more lovely than any other thing."
            }
        }

{
            "mnemonic": "The {tooltip:Radical:odd} radical and the {tooltip:Kanji:odd} kanji are the same. They're both... really {tooltip:Kanji:strange}.",
            "hints": "Remember how odd this one is?",
            "meanings": {
                "Primary": "Odd",
                "Alternative": "Strange"
            },
