            }
        }

{
            "mnemonic": "A {tooltip:Radical:tsunami} that's {tooltip:Radical:blue} is {tooltip:Kanji:pure}. Some tsunami are other colors, like brown or red because they aren't pure, they'll full of trash and poop and other horrible things. But a blue tsunami is completely pure!",
            "hints": "Picture this pure blue tsunami. You can see every crystal clear drop of water in it.",
            "meanings": {
                "Primary": "Pure"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u305b\u3044, \u3057\u3087\u3046, \u3057\u3093",
