                        "file": "12619-subject-5163.ogg"
                    },
                    {
                        "gender": "female",
                        "pronunciation": "\u305b\u3081\u308b",
                        "voiceActorId": 1,
                        "voiceActorName": "Kyoko",
                        "voiceDescription": "Tokyo accent",
                        "file": "32519-subject-5163.ogg"
                    }
                ],
                "mnemonic": "\n{splitParent}Since this word consists of a kanji with hiragana attached, you can bet that it will use the kun'yomi reading. You didn't learn that reading with this kanji, so here's a mnemonic to help you: When you (I'm talking about you) attack something, you don't use weapons or thinking or anything silly like that. No, you use your intense {tooltip:Reading:se}xiness ({span:lang=ja:\u305b}). Bam! So sexy. Attack!\n"
            },
            "contextSentences": [
                {
                    "ja": "\u305d\u306e\u30d4\u30c3\u30c1\u30e3\u30fc\u306f\u30d0\u30c3\u30bf\u30fc\u3092\u5909\u5316\u7403\u3067\u653b\u3081\u308b\u3053\u3068\u304c\u591a\u3044\u3002",
                    "en": "That pitcher often assaults batters with curve balls."
                }
            ],
            "collocations": []
        }

{
