            "contextSentences": [
                {
                    "ja": "\u30a8\u30b3\u30d0\u30c3\u30b0\u3092\u8cb7\u3046\u305f\u3081\u306b\u5341\u4e8c\u6642\u9593\u3082\u884c\u5217\u306b\u4e26\u3076\u306a\u3093\u3066\u4fe1\u3058\u3089\u308c\u306a\u3044\u3088\u3002",
