{
            "mnemonic": "{tooltip:Radical:Say} {tooltip:Radical:good luck} to one person enough and they'll be {tooltip:Kanji:stuffed} full of that luck.",
            "hints": "Better safe than sorry. Don't just say good luck once, make sure they're stuffed!",
            "meanings": {
                "Primary": "Stuffed"
            },
            "kanjiReadings": {
                "readings": [
