                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u3064, \u3065",
                        "primary": true
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Picture a person with the actual words \"good luck\" stuffed into their body.",
                "mnemonic": "You {tooltip:Kanji:stuffed} them by saying good luck {tooltip:Reading:two} ({span:lang=ja:\u3064}) whole times!"
            }
        }

{
            "mnemonic": "The {tooltip:Radical:servant} sits on a {tooltip:Radical:stool}, holding a piece of {tooltip:Radical:thread}, looking very {tooltip:Kanji:tense}. ",
            "hints": "You walk by this tense servant and pause for a moment. They raise their tense eyes up at you and you can see they're shaking.",
            "meanings": {
                "Primary": "Tense"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u304d\u3093",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "None",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Imagine how tense you would be if you were about to try to murder the King! Your entire body would tense up, maybe to the point that you wouldn't be able to actually go through with it.",
                "mnemonic": "You ask the servant why they're so {tooltip:Kanji:tense}, and they say they've been assigned to assassinate the {tooltip:Reading:Kin}g ({span:lang=ja:\u304d\u3093}) of England with this piece of thread."
            }
        }

{
            "mnemonic": "At the {tooltip:Radical:gate}, you {tooltip:Radical:kiss} {tooltip:Kanji:the cabinet} members, one by one. In order to gain access to this government building, you have to kiss all the members of the cabinet at the gate. What a strange ritual.",
            "hints": "Imagine kissing all the members of the cabinet. A lot of them are old men. Imagine kissing all of them at the gate. Eww.",
            "meanings": {
                "Primary": "The Cabinet",
                "Alternative": "Cabinet"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u304b\u304f",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "None",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Imagine yourself sneaking past the cabinet members, finding your cock, grabbing it, and getting out of there. You\u2019ve recovered your rooster! The day is won.",
                "mnemonic": "You need to kiss each member of {tooltip:Kanji:the cabinet} to gain access to their building. And you need to get into the building to recover your {tooltip:Reading:cock} ({span:lang=ja:\u304b\u304f}). Your prize winning cock has been captured by a member of the cabinet and you need to infiltrate their headquarters and recover your rooster!"
            }
        }

{
            "mnemonic": "Your {tooltip:Radical:leader} sees your bare {tooltip:Radical:foot} and {tooltip:Kanji:urge}s you to put a sock on it.",
            "hints": "Imagine your leader's face when he sees your bare foot, and just how emphatic he is as he urges you to put a sock on it. He's really worried your foot's going to get cold!",
            "meanings": {
                "Primary": "Urge"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u305d\u304f",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u3046\u306a\u304c",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Feel this sock on your foot. It feels great. Wiggle your toes around inside the sock as you think about how glad you are that you did as your leader urged. Note that this kanji also has the same reading as {span:lang=ja:\u8db3}, so keep that in mind too!",
                "mnemonic": "As {tooltip:Kanji:urge}d, you put a {tooltip:Reading:sock} ({span:lang=ja:\u305d\u304f}) on your foot. Ahh, that feels so much better. What a great thing, this sock."
            }
        }

{
            "mnemonic": "When a {tooltip:Radical:yakuza}'s {tooltip:Radical:knife} {tooltip:Radical:boil}s, you know something very {tooltip:Kanji:violent} and {tooltip:Kanji:intense} is about to happen.",
