            }
        }

{
            "mnemonic": "In the {tooltip:Radical:ground} of the {tooltip:Radical:rice paddy} is a {tooltip:Radical:treasure}. You pull it out of the mucky ground. This will {tooltip:Kanji:renew} your life for the better. {tooltip:Kanji:Again}, this treasure will change your life!",
            "hints": "Pull out the treasure. Think about all the things you will be able to renew in your life. Your car. Your boat. Your house. You lost it all but now you'll be able to get it back.",
            "meanings": {
                "Primary": "Again",
                "Alternative": "Renew"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u3053\u3046",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u3055\u3089, \u3075",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Yell at {span:lang=ja:\u3053\u3046\u3044\u3061} to give your treasure back. Then, fall to the muck as you realize you won't be able to renew your life anymore.",
                "mnemonic": "{tooltip:Kanji:Again}, you are going to {tooltip:Kanji:renew} your life! Everything will be better. Then, the person who caused all this grief grabs your treasure and runs. {span:lang=ja:\u3053\u3046\u3044\u3061} is running off with the treasure that was supposed to renew your life!"
            }
        }

{
            "mnemonic": "A {tooltip:Radical:demon} on a {tooltip:Radical:jet} is pretty {tooltip:Kanji:alluring}. Demons themselves are pretty intriguing, but put one on a jet? Now that\u2019s alluring.",
            "hints": "See this demon flying around in his jet. Do you feel allured? You should. Hear the roar of the jet engine as the demon cackles.",
            "meanings": {
                "Primary": "Alluring"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u307f",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "None",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "The demon won\u2019t be so alluring once you see him scarfing down humans, tearing the meat from their bones. How gross.",
                "mnemonic": "This {tooltip:Kanji:alluring} demon on a jet wants one thing and one thing only. {tooltip:Reading:Me}at ({span:lang=ja:\u307f}). Human meat. This demon needs human meat to survive so he is taking his jet into the city to feast on some meat."
            }
        }

{
            "mnemonic": "You fly {tooltip:Radical:north} to the {tooltip:Radical:moon} and break your {tooltip:Kanji:back} when you finally land on it. You weren\u2019t braced for impact so when you hit the moon, your back took all of the impact.",
            "hints": "Imagine flying north to the moon. Feel the force of being rocketed through space on your journey. Now feel your spine telescope and your back break. It really hurts.",
            "meanings": {
                "Primary": "Back",
                "Alternative": "Height"
            },
            "kanjiReadings": {
                "readings": [
