                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u3042\u305a",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Imagine trying to make a deposit to your bank after getting hit in the face with a yo-yo. You can hardly see what you're shoving your money into. You hope it isn't the hands of the kid that hit you!",
                "mnemonic": "You go to the bank to make the {tooltip:Kanji:deposit} and there is a kid standing in your way playing with a {tooltip:Reading:yo}-yo ({span:lang=ja:\u3088}). You try to squeeze past and he hits you in the face with the yo-yo! Now you can't see! Now you can't make the deposit!"
            }
        }

{
            "mnemonic": "If you are {tooltip:Radical:anti} {tooltip:Radical:one sided} paper you should bind them all up into an {tooltip:Kanji:edition}.",
            "hints": "One sided paper is just anti everything. It's bad for the environment. It's bad for easy reading. Put all those one sided papers together into one, big edition instead.",
            "meanings": {
                "Primary": "Edition"
            },
            "kanjiReadings": {
