            }
        }

{
            "mnemonic": "You're in {tooltip:Radical:prison} and all you have is a {tooltip:Radical:spoon}. You use that prison spoon to scoop up nice {tooltip:Kanji:scent}s and {tooltip:Kanji:fragrance}s out of the air when you have outdoor time and bring them back into your cell.",
            "hints": "It smells really bad in prison, but your prison spoon is full of all of the lovely scents you remember from when you were free.",
