            }
        }

{
            "mnemonic": "This is a very complicated and tall radical. It has a lid on top to keep the explosiveness in. It also contains a treasure, at least for the people who will receive what's inside. Also, it has a cow, which will be used for milk on Mars. This is a {tooltip:Radical:rocket} filled with goodies for space people.",
            "hints": "",
            "meanings": {
                "Primary": "Rocket"
            }
        }

{
            "mnemonic": "There's a {tooltip:Radical:mountain} coming out of the {tooltip:Radical:ground} that you want to climb, but your {tooltip:Radical:forehead} needs a {tooltip:Radical:towel} for all your sweat. You don't have a towel, so you take off your {tooltip:Kanji:belt} and tie it around your forehead.",
            "hints": "The belt is easy to tighten and it catches all the sweat before it can fall into your eyes. It isn't quite as absorbent as a towel though.",
            "meanings": {
                "Primary": "Belt"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u305f\u3044",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u304a\u3073",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "It works! Your belt tied in a tie is the perfect invention!",
                "mnemonic": "The {tooltip:Kanji:belt} isn't absorbent enough, so you wrap it in your {tooltip:Reading:tie} ({span:lang=ja:\u305f\u3044}) and then tie the whole thing around your forehead again."
            }
        }

{
            "mnemonic": "The {tooltip:Radical:canopy} {tooltip:Radical:guy} is a guy who stands in the {tooltip:Kanji:corridor} trying to sell people canopies.",
            "hints": "You walk through this corridor every day, and the canopy guy always accosts you with canopy sales. You wish there was another corridor you could take, but it's the only way to get where you want to go.",
            "meanings": {
                "Primary": "Corridor"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u308d\u3046",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "None",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "The roe salesman in the corridor is worse than the canopy salesman. They're both insistent, but the roe salesman smells bad.",
                "mnemonic": "You take the {tooltip:Kanji:corridor}, but this time the canopy guy is gone. In his place is a new salesman. This one is trying to sell you {tooltip:Reading:roe} ({span:lang=ja:\u308d\u3046})."
            }
        }

{
            "mnemonic": "The {tooltip:Radical:rocket} {tooltip:Radical:turkey} has several points which will {tooltip:Kanji:detach} during takeoff.",
            "hints": "Imagine the rocket turkey taking off. Just like a regular rocket, as it goes up, used pieces of the turkey rocket detach and fall back to the ground.",
            "meanings": {
                "Primary": "Detach"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u308a",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u306f\u306a",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "The reeds catch on fire - probably best not to fire off turkey rockets so close to these fields of reeds. Imagine the launch site completely surrounded by reeds.",
                "mnemonic": "When the rocket turkey parts {tooltip:Kanji:detach}, they fall to the ground onto a bed of {tooltip:Reading:ree}ds {tooltip:Reading:\u308a}."
            }
        }

{
            "mnemonic": "You {tooltip:Radical:loiter} around a {tooltip:Radical:tombstone} to measure its {tooltip:Kanji:diameter}. You\u2019re doing this to each tombstone, and if you loiter around long enough, you\u2019ll soon know the diameter of every tombstone.",
            "hints": "Imagine loitering around a tombstone. You're leaning on it. You're staring at nothing. Oh, and you're also measuring its diameter.",
            "meanings": {
                "Primary": "Diameter"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u3051\u3044",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "None",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "These carefully measured tombstone-diameter cakes are your special way of saying thanks to the ghosts for letting you loiter around their graves.",
                "mnemonic": "You need to know the {tooltip:Kanji:diameter} of each tombstone so you can make {tooltip:Reading:ca}kes ({span:lang=ja:\u3051\u3044}) for each one. But the cakes can't be wider than the tombstones, or they'll flop off onto the ground."
            }
        }

{
            "mnemonic": "You see a {tooltip:Radical:bully} take an {tooltip:Radical:insect} and {tooltip:Kanji:dissolve} it in some acid. Bullies are messed up, mean people. They do awful things that normal kids and people wouldn't do... like dissolve a living creature.",
            "hints": "Actually... try to forget this one. Don't think about a bully dissolving things in acid. Think happy thoughts. Like... the bully getting dissolved instead and all the little insects coming back to life and being happy.",
            "meanings": {
                "Primary": "Dissolve"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u3086\u3046",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "None",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "When you first read this and you pictured the bully dissolving the insect, you pictured them as a youth, right? See? It makes complete sense.",
                "mnemonic": "The only bullies heartless enough to {tooltip:Kanji:dissolve} insects like this are youths ({tooltip:Reading:\u3086\u3046}). Do you really think an adult would melt a harmless critter? No. Only inexperienced youths could be so cruel."
            }
        }

{
            "mnemonic": "You have some {tooltip:Radical:dirt} next to a {tooltip:Radical:pool} that has an extra {tooltip:Radical:drop} of water in it because you need them to be {tooltip:Kanji:equal}. If there's too much dirt outside the pool and not enough water inside, it's gonna look weird. We can't have that.",
            "hints": "Imagine seeing a pool that isn't equal. It's like a tiny kiddy pool with an inch of water. And it's surrounded by mounds of dirt. No no no, this won't do\u2014add more water to make them equal.",
            "meanings": {
                "Primary": "Equal"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u304d\u3093",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u3072\u3068",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Okay, so the existence of a king kind of makes things not, well, equal, for all people. But at least aesthetically everything will be!",
                "mnemonic": "You spend a few hours making sure the water-to-dirt ratio is perfectly {tooltip:Kanji:equal}, not for yourself, but because the {tooltip:Reading:Kin}g ({span:lang=ja:\u304d\u3093}) of England told you to. You may agree that equality is important, but it's the King's responsibility to keep things that way. Which is why he ordered you, small peon, to do the equalizing work for him."
            }
        }

{
            "mnemonic": "The {tooltip:Radical:building}s are at a {tooltip:Radical:surplus}. Because of that, we will need to {tooltip:Kanji:exclude} some of them from our future plans. Also, we'll need to {tooltip:Kanji:remove} some buildings too.",
            "hints": "Say you're looking at a map of the city, with all the buildings laid out on it. There are too many, so you start marking which ones to exclude from the building plans. You also remove some buildings from the map all together.",
            "meanings": {
                "Primary": "Exclude",
                "Alternative": "Remove"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u3058\u3087, \u3058",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u306e\u305e",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "She's pointing out buildings to exclude / remove with great ferocity. \"Remove this one. Exclude this one. Oh, and remove this one too.\"",
                "mnemonic": "Working with you on this project to {tooltip:Kanji:exclude} buildings from the plan, as well as {tooltip:Kanji:remove} buildings that already exist is little {tooltip:Reading:Jo}-Anne ({span:lang=ja:\u3058\u3087})."
            }
        }

{
            "mnemonic": "You want to {tooltip:Radical:change} your {tooltip:Radical:shellfish} into {tooltip:Kanji:freight} so you can transport it. That means packing them up into giant freight containers.",
            "hints": "Imagine changing your shellfish from loose, wet form, to solid freight form. It's actually a lot of hard work.",
            "meanings": {
                "Primary": "Freight"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u304b",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "None",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Picture all of this freight stacked on top of your car. As you drive the car, every turn you make feels slow and heavy from the freight weight.",
                "mnemonic": "To move this {tooltip:Kanji:freight}, you need a {tooltip:Reading:ca}r ({span:lang=ja:\u304b}). You strap all of the freight containers to the top of your car, stacked nice and high and precarious, so you can move it."
            }
        }

{
            "mnemonic": "A {tooltip:Radical:child} shares his {tooltip:Radical:lineage} with a {tooltip:Kanji:grandchild}. The child passes his lineage down to his child and then that child\u2019s child is the grandchild and between them all a lineage is shared.",
            "hints": "Look at this family tree. See the child, and then the grandchild. Trace the lineage with your finger as you observe.",
            "meanings": {
                "Primary": "Grandchild"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u305d\u3093",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u307e\u3054",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Just remember that a son is all you really want. You need a son to carry on the family name and the lineage. So make sure that your child and your grandchild are both sons.",
                "mnemonic": "The {tooltip:Reading:son} ({span:lang=ja:\u305d\u3093}) of a son is a {tooltip:Kanji:grandchild}. In this case, a grandson. Easy."
            }
        }

{
            "mnemonic": "There's a strange patch of {tooltip:Radical:dirt} in this {tooltip:Radical:greenhouse} that's actually a {tooltip:Kanji:grave}. Dig around a little and you'll find the marker buried in there. If you dig deeper you'll probably find less pleasant things.",
            "hints": "I guess it makes sense to have a grave in a greenhouse. The heat will help the body decompose, then that nice, rich dirt will help the flowers grow.",
            "meanings": {
                "Primary": "Grave"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u307c",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u306f\u304b",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Hold the grave bow in your hands. It smells like dirt and wood. Maybe no one will notice if you take it... though you may end up haunted by whoever is buried in this grave.",
                "mnemonic": "You decide to dig even deeper into the {tooltip:Kanji:grave} out of curiosity and you find a {tooltip:Reading:bow} ({span:lang=ja:\u307c}) and some arrows. This must be the grave of a great archer! But you probably shouldn't keep digging around in this grave looking for more stuff."
            }
        }

{
            "mnemonic": "You {tooltip:Radical:poop} twice on a sleeping {tooltip:Radical:drunkard} {tooltip:Radical:person} and you find yourself wondering {tooltip:Kanji:how many} more times you can poop on them and wonder {tooltip:Kanji:how much} they can take before they realize what\u2019s going on.",
            "hints": "You\u2019ve already pooped twice on this drunkard, how many more times can you do it? How much do you think this person can take? Just imagine yourself doing this.",
            "meanings": {
                "Primary": "How Many",
                "Alternative": "How Much"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u304d",
                        "primary": false
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u3044\u304f",
                        "primary": true
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Imagine yourself as you eke out that last poop. Really concentrate on eking it out so you can get away in time. Flex your butt muscles for added effect.",
                "mnemonic": "As you continue thinking about {tooltip:Kanji:how much} poop this drunkard can take and {tooltip:Kanji:how many} more poops you can drop on him, he begins to wake up. Quickly, you {tooltip:Reading:eke} ({span:lang=ja:\u3044\u304f}) out one last poop before you scurry away. You eke that poop out just in time to make your escape."
            }
        }

{
            "mnemonic": "{tooltip:Radical:Wolverine} is doing a {tooltip:Radical:construction} job and he\u2019s using his {tooltip:Radical:mouth} to {tooltip:Radical:measure} so he knows how many folks he needs to {tooltip:Kanji:inquire} about helping him with the job. Using one\u2019s mouth is a strange way to measure something, but that\u2019s just how Wolverine does things. Once he measures it all out, he\u2019ll know how many construction workers he needs to inquire about working for him.",
            "hints": "Imagine Wolverine going around, measuring the construction site with his mouth. Look at him with his mouth wide open, wandering around the site deep in thought. What a weirdo.",
            "meanings": {
                "Primary": "Inquire"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u3058\u3093",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u305f\u305a, \u3072\u308d",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Look down at your ripped up jeans. You\u2019re so fashionable now! Just like good old \u201890s Wolvie.",
                "mnemonic": "You decide to {tooltip:Kanji:inquire} as to why Wolverine is using his mouth to measure out this construction site. As you get closer you notice his cool ripped {tooltip:Reading:jean}s ({span:lang=ja:\u3058\u3093}). Instead you inquire how he got such a fresh style. He looks you up and down, pulls out his claws, and tears yours up to match his. You\u2019ve completely forgotten what it was you were asking, but who cares! Look how great you look!"
            }
        }

{
            "mnemonic": "Bring {tooltip:Radical:thread} to the {tooltip:Radical:library} to {tooltip:Kanji:knit}. Libraries are quiet and generally pretty empty nowadays, so it's the perfect place to relax and do some knitting. Of course, if you find thread lying around in a library you know what to do now.",
            "hints": "Picture yourself sitting on a rocking chair in the library knitting away. It's quiet and peaceful and the light is warming you just right. Ahh, bliss!",
            "meanings": {
                "Primary": "Knit"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u3078\u3093",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u3042",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Imagine the granny or grampy you are (and must be to have hens and want to knit in peace in a library). You're tired of these hens eating your thread while you try to knit sweaters for all your grandbabies so you come to the library.",
                "mnemonic": "You need to come to the library to {tooltip:Kanji:knit} because if you try to do it at home all your {tooltip:Reading:hen}s ({span:lang=ja:\u3078\u3093}) will try to eat the thread. Hens love eating things that look like worms, like hay, string, and thread. So it's important to get far away from them before you start to knit."
            }
        }

{
            "mnemonic": "A {tooltip:Radical:building} made from a {tooltip:Radical:womb} must be placed upon the {tooltip:Kanji:land}.",
            "hints": "Why must it be placed upon the land? If it were put in water, it would dissolve too quickly. So, you put your womb building on the land, instead.",
            "meanings": {
                "Primary": "Land"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u308a\u304f",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "None",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "It's made of biological materials, so of course it will reek.",
                "mnemonic": "The {tooltip:Kanji:land} around your womb building will, unfortunately, {tooltip:Reading:reek} ({span:lang=ja:\u308a\u304f}) though.\n"
            }
        }

{
            "mnemonic": "If you want to get your {tooltip:Radical:fingers} in the {tooltip:Radical:pi} {tooltip:Radical:tree}, you're going to have to {tooltip:Kanji:look for} it. This isn't a tree made of pie, or growing fully-baked pies. It's a pi tree, one that exists infinitely. It's the most rare tree in the world. And if you want to stick your fingers in it, you have to {tooltip:Kanji:search for} it far and wide!",
            "hints": "Imagine it like a quest from a book or movie. You have a band of travelers, and you're all out searching for it together!",
            "meanings": {
                "Primary": "Look For",
                "Alternative": "Search For"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u305f\u3093",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u3055\u304c, \u3055\u3050",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Feel the sun's rays on your skin as you search and search and search for the tree. Watch as your skin gets darker, crispier, and hmm, smells like cooked meats. Now that's a good tan.",
                "mnemonic": "You try to {tooltip:Kanji:look for} the pi tree for so long that you can't help but get a very deep {tooltip:Reading:tan} ({span:lang=ja:\u305f\u3093}). You can't search for anything inside, and you definitely can't find the pi tree inside, so you spend a lot of time outside in the bright sun."
            }
        }

{
            "mnemonic": "You put a {tooltip:Radical:lid} on a dish you're cooking, made up of the {tooltip:Radical:mouth}s and {tooltip:Radical:forehead}s of a {tooltip:Radical:pig}. Unknown to most, these are the juiciest, most delicious parts of a pig. And dang, they are the most {tooltip:Kanji:luxurious}, too.",
            "hints": "Mix those pig mouths and foreheads in your pot. Think of how luxurious your soup looks.",
            "meanings": {
                "Primary": "Luxurious"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u3054\u3046",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "None",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "\"Can I have some of your luxurious soup?\" Grandpa Koichi asks. \"It smells so swell.\"",
