                {
                    "ja": "\u5de5\u4e8b\u306e\u305b\u3044\u3067\u3044\u3064\u3082\u306e\u30e9\u30f3\u30cb\u30f3\u30b0\u306e\u30b3\u30fc\u30b9\u304c\u5ef6\u3073\u305f\u3002",
                    "en": "Because of construction work, my usual running route has been extended."
                },
                {
                    "ja": "\u6771\u4eac\u30aa\u30ea\u30f3\u30d4\u30c3\u30af\u306f\u7fcc\u5e74\u306b\u5ef6\u3073\u305f\u304c\u30ad\u30e3\u30f3\u30bb\u30eb\u306b\u306a\u308b\u304b\u3082\u3057\u308c\u306a\u3044\u3002",
                    "en": "The Tokyo Olympics were delayed to the following year, but they might get canceled."
                },
                {
                    "ja": "\u4e0a\u53f8\u306e\u305b\u3044\u3067\u4f1a\u8b70\u304c\u5ef6\u3073\u308b\u306e\u304c\u5acc\u3044\u3067\u3059\u3002",
