            "contextSentences": [
                {
                    "ja": "\u3069\u3093\u306a\u306b\u304f\u3088\u304f\u3088\u5606\u3044\u3066\u3082\u3001\u6b7b\u3093\u3060\u4eba\u306f\u3082\u3046\u623b\u3063\u3066\u306f\u6765\u306a\u3044\u3093\u3060\u304b\u3089\u3001\u5f7c\u5973\u306e\u3053\u3068\u306f\u3055\u3063\u3055\u3068\u5fd8\u308c\u3066\u3001\u4ee3\u308f\u308a\u306b\u79c1\u3068\u7d50\u5a5a\u3057\u3066\u3088\u3002",
