        }

{
            "mnemonic": "A {tooltip:Radical:scooter} sits at the entrance where people {tooltip:Radical:enter}. You jump on and are flung inside! Because a lot of other people did the same thing, it's really {tooltip:Kanji:crowded} in here.",
            "hints": "Imagine going to your favorite store. There's a scooter on and waiting at the entrance. You can't see inside, so when you are scooted inside by the scooter, you just get thrown into a packed room. So many other people on scooters! It's too crowded!",
            "meanings": {
                "Primary": "Crowded"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "None",
                        "primary": false
                    },
                    {
                        "name": "Kun\u2019yomi",
