                    }
                ],
                "hints": "Imagine a {span:lang=ja:\u5b50} at the head of a huge conference table. \"I know how to make our stores crowded again!\" they shout before showing everyone their plan drawn in Crayons.",
                "mnemonic": "Whoever came up with the scooter entrance idea, that made your favorite store so {tooltip:Kanji:crowded}? Only a {span:lang=ja:\u5b50} ({span:lang=ja:\u3053}) could come up with something like this. They don't really think about the dangers and legal implications of using a scooter to launch people into a crowded space."
            }
        }

{
            "mnemonic": "If you want to {tooltip:Radical:go} to {tooltip:Radical:Korea} you'll need a good {tooltip:Kanji:defense}.",
            "hints": "Things in Korea haven't been on the safest side lately, so make sure you have some ways to defend yourself before you go.",
            "meanings": {
                "Primary": "Defense"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u3048\u3044",
