        }

{
            "mnemonic": "Taking a piece of {tooltip:Radical:thread} you {tooltip:Radical:blame} the {tooltip:Kanji:exploits} of your past on poor judgment. You tie this thread around your finger to remind you of all the exploits you accomplished in your day. Most of them weren\u2019t actually on purpose, so you blame them on poor judgment and accident.",
            "hints": "Think up what exploits you accomplished. What sort of things might you have done, but not quite on purpose? Think about how it feels to be exalted for such exploits that were but mere accidents.",
            "meanings": {
                "Primary": "Exploits"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u305b\u304d",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "None",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Imagine setting this sexy fashion trend on accident. Imagine what you were wearing when you got dressed in the dark. Probably a pretty strange, mismatched outfit.",
                "mnemonic": "One of your {tooltip:Kanji:exploits} was when you got dressed in the dark and were wearing funny clothes and everyone thought that it was {tooltip:Reading:sexy} ({span:lang=ja:\u305b\u304d}). The newspapers and fashion agencies couldn\u2019t get enough of your sexy style."
            }
        }

{
            "mnemonic": "The {tooltip:Radical:eye}'s {tooltip:Radical:root} is the {tooltip:Kanji:eyeball}.",
            "hints": "Go ahead and feel your eyeballs moving around in your head. Your eyes aren't just the part on the surface, they're the whole balls in there, attached at the root.",
