                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Actually imagine reading through the preface of your favorite book. Except, there's a preface that just goes into great detail about Jo-Anne and doesn't seem related at all to the book.",
                "mnemonic": "You read the {tooltip:Kanji:preface}. It just goes on and on and on about {tooltip:Reading:Jo}-Anne ({span:lang=ja:\u3058\u3087}), a short lady the author loves very much."
            }
        }

{
            "mnemonic": "You count {tooltip:Radical:nine} of them in the {tooltip:Radical:tree}, each {tooltip:Radical:turkey} holding something {tooltip:Kanji:random} or {tooltip:Kanji:miscellaneous}. There are nine turkeys in the tree and they\u2019re all holding random, miscellaneous things. How odd.",
            "hints": "Look at the turkeys in the tree. There are nine of them and they are all gobbling up a storm. Hear them gobble as you imagine what random, miscellaneous things they are holding.",
            "meanings": {
                "Primary": "Random",
                "Alternative": "Miscellaneous"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u3056\u3064, \u305e\u3046",
