{
            "mnemonic": "A {tooltip:Radical:grain} is {tooltip:Radical:certain} to keep a {tooltip:Kanji:secret}.",
            "hints": "Imagine telling a piece of grain your deepest, darkest secret.",
            "meanings": {
                "Primary": "Secret"
            },
            "kanjiReadings": {
