                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "This works both ways too. If someone tells you a secret, that same heat fills you up. Now whether this heat is from embarrassment or the rush of getting to be part of a secret is up to you to figure out.",
                "mnemonic": "If someone finds out your {tooltip:Kanji:secret} (not from the grain though, it will certainly keep it) then your entire face will fill with {tooltip:Reading:hea}t ({span:lang=ja:\u3072})."
            }
        }

{
            "mnemonic": "If you see a {tooltip:Radical:grass}y {tooltip:Radical:cliff} with an {tooltip:Radical:elf} under it in {tooltip:Radical:winter}, it's because their parents are so {tooltip:Kanji:strict}. When elf kids misbehave they're supposed to go stand under grassy cliffs to think about what they've done.",
            "hints": "Only really, really strict parents would make their kids do that in the middle of winter! It's cold!",
            "meanings": {
                "Primary": "Strict"
            },
            "kanjiReadings": {
                "readings": [
