{
            "mnemonic": "In its {tooltip:Radical:scooter}, a {tooltip:Radical:cat pirate} scoots up to {tooltip:Kanji:welcome} you!",
            "hints": "\"Nya! Welcome to my ship, grab a scooter and scoot on up here, we're about to start the welcome ceremonya!\"",
            "meanings": {
                "Primary": "Welcome"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u3052\u3044",
