            }
        }

{
            "mnemonic": "If you see {tooltip:Radical:icicle}s hanging off of a {tooltip:Radical:samurai}'s {tooltip:Radical:clothes}, don't worry, those are just part of his winter {tooltip:Kanji:attire}. Samurai have to travel and fight in all sorts of conditions, so it only makes sense that they have attire for every season.",
            "hints": "Picture a samurai in his winter attire. His helmet is white and fuzzy and he has decorative icicles hanging down off of his armor.",
            "meanings": {
                "Primary": "Attire"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u305d\u3046, \u3057\u3087\u3046",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u3088\u305d\u304a",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Picture the kind of attire you'd wear as a samurai to reflect your soul. Mine would be bright pink and covered in horses and bananas and daisies to show that I have a happy, kind soul and that I don't want to be killed by anyone else.",
                "mnemonic": "{tooltip:Kanji:Attire} like this is important because it reflects your {tooltip:Reading:soul} ({span:lang=ja:\u305d\u3046}). The samurai is wearing clothing with icicles because that's how his heart feels too: frozen over because he has to fight in this horrible winter weather."
            }
        }

{
            "mnemonic": "If {tooltip:Radical:someone} is holding {tooltip:Radical:flowers}, they're probably an {tooltip:Kanji:author}. Authors really love flowers, because they help them think of flowery language they can use to sound smart in their books.",
            "hints": "Imagine a time when a book you were reading used flowery language and you couldn't understand. Imagine the annoyance with the author for using words that are hard to understand.",
            "meanings": {
                "Primary": "Author"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u3061\u3087",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u3044\u3061\u3058\u308b, \u3042\u3089\u308f",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Picture the author trying to use chopsticks to move around a little flower. It looks like they're having a hard time, but people will do anything to be a great author, I suppose.",
                "mnemonic": "Unfortunately, the {tooltip:Kanji:author} is allergic to flowers. They are only allergic to touching them though, so the author is holding the flowers with a pair of {tooltip:Reading:cho}psticks ({span:lang=ja:\u3061\u3087}), really close to their face. Using the chopsticks, they can still use the flowers to think of fancy, author-ly words without touching them."
            }
        }

{
            "mnemonic": "There's a {tooltip:Radical:lid} on your {tooltip:Radical:village}, so you {tooltip:Radical:kick} it over on its {tooltip:Kanji:backside} to see what's on its {tooltip:Kanji:underside}.",
            "hints": "You've been curious about what's on the lid (and your village's) backside for years, and you finally can't take it anymore so you kick the lid as hard as you can!",
            "meanings": {
