                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Up, back down, back up, back down. Move your head up and down to keep up with the sun\u2019s movements. Will it ever rise like normal?",
                "mnemonic": "See the sun come up over the {tooltip:Kanji:desert}, then go {tooltip:Reading:back} ({span:lang=ja:\u3070\u304f}) down. Up, back down, back up, back down. You stand here for days watching because you're so depressed. Stop being so {tooltip:Kanji:vague} in your approach, sun! You\u2019re weirding everyone out!"
            }
        }

{
