                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "None",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "The city and moon\n{linebreak}Inside my lung, forgotten.\n{linebreak}Where is the answer?{splitParent}Or just think of your own haiku. Be creative!",
                "mnemonic": "Having a moon and city inside your {tooltip:Kanji:lung} inspires you to write a {tooltip:Reading:hai}ku ({span:lang=ja:\u306f\u3044}). Perhaps the city and moon are just metaphorical. Either way, a haiku is the best way to go about things here."
            }
        }

{
            "mnemonic": "To {tooltip:Radical:say} what's in a {tooltip:Radical:samurai}'s {tooltip:Radical:heart} you start a {tooltip:Kanji:magazine}. You go around writing about and interviewing all the samurai so you can share what they say to everyone who wants to read!",
