        }

{
            "mnemonic": "The {tooltip:Radical:horns} of the creatures who drink {tooltip:Radical:alcohol} have a {tooltip:Radical:measurement} so large that they are {tooltip:Kanji:revered} the world over. The horns are revered both for their size and potency. The horns can be used in medicine, so they are very valuable, those alcoholic monster horns.",
            "hints": "Look at one of these revered horns. Pick it up and feel its weight. It measures very large. Your arms are getting tired from the weight.",
            "meanings": {
                "Primary": "Revered"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u305d\u3093",
                        "primary": true
