                        "file": "44262-subject-9005.ogg"
                    }
                ],
                "mnemonic": "\n{splitParent}You've already learned all these readings. You should be able to read this on your own. And no, that's not a far-fetched argument, or a lame excuse for not writing a mnemonic.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u305d\u308c\u306f\u5c41\u7406\u5c48\u3067\u306f\u306a\u304f\u4e8b\u5b9f\u3067\u3042\u308b\u3002",
                    "en": "That's not an illogical argument, it's a fact."
                },
                {
                    "ja": "\u5c41\u7406\u5c48\u3092\u3053\u306d\u308b\u4eba\u306f\u5acc\u3044\u3067\u3059\u3002",
                    "en": "I don't like people who make far-fetched arguments."
                },
                {
                    "ja": "\u5c41\u7406\u5c48\u3092\u8a00\u3046\u306e\u306f\u3084\u3081\u3066\u3001\u3084\u308b\u3079\u304d\u3053\u3068\u3092\u3084\u308a\u307e\u3057\u3087\u3046\u3002",
                    "en": "Let's stop making lame excuses and get on with what we have to do!"
                }
            ],
            "collocations": []
        }

