        }

{
            "mnemonic": "Make your {tooltip:Radical:barracks} out of {tooltip:Radical:thread} so it will be {tooltip:Kanji:pure}. If you build it out of clay or bricks or wood, it will inevitably have some dirt in it. Build it out of thread to keep it pure of... well, impurities.",
            "hints": "Imagine a barracks pure white, like pure snow, made of pure thread.",
            "meanings": {
                "Primary": "Pure"
            },
            "kanjiReadings": {
