        }

{
            "mnemonic": "Your {tooltip:Radical:mouth} is wearing a {tooltip:Radical:mask} so people won't realize you're the one being so {tooltip:Kanji:boisterous}. You want to be loud and rowdy, but you don't want anyone to know it's you. If you cover your mouth with this mask, people won't know you're the one being so boisterous.",
            "hints": "Go put a mask on right now, cover everything around your mouth so it's hard to tell who you are. Now go outside and be as boisterous as possible!",
            "meanings": {
                "Primary": "Boisterous"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u305d",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "None",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Using your boisterous mouth, taste the disgusting soapy soap. The soap bubbles are already filling your mouth and stinging your tongue. This is the punishment for boisterous hooligans.",
                "mnemonic": "You're being anonymously {tooltip:Kanji:boisterous} outside when suddenly someone shoves {tooltip:Reading:so}ap ({span:lang=ja:\u305d}) in your mouth! \"I don't know who you are, but you're much too boisterous! Wash your mouth out with that soap!\" they yell."
            }
        }

{
            "mnemonic": "There is a {tooltip:Radical:circumference} around someone's {tooltip:Radical:hair}, as in, you can see a circle drawn around the top of their head. As you examine it closer, and pull at it a bit, you realize that someone has {tooltip:Kanji:carve}d the hair off someone's head!",
            "hints": "Their hair has literally been carved out of their head, and you discovered it. Of course, the nastiness, the smell, and the feel should be applied to your imagination to make the mnemonic stronger.",
            "meanings": {
                "Primary": "Carve"
            },
            "kanjiReadings": {
