                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Picture all of the sheep finally going slowly because there is yummy cheese all over the road.",
                "mnemonic": "You follow the flag, but the sheep refuse to {tooltip:Kanji:slow} down so you have to get creative. You place {tooltip:Reading:chee}se ({span:lang=ja:\u3061}) every ten feet or so, that way the sheep slow down to bend down on their scooters and take a bite."
            }
        }

{
            "mnemonic": "A {tooltip:Radical:tsunami} carries a {tooltip:Radical:cross} into your {tooltip:Kanji:soup}. Hey tsunami, I was eating that soup!",
            "hints": "Picture a bowl of soup, but now there is a cross and some tsunami water in it.",
            "meanings": {
                "Primary": "Soup"
            },
            "kanjiReadings": {
