                },
                {
                    "ja": "\u6388\u696d\u6599\u306e\u652f\u6255\u3044\u304c\u6ede\u3063\u3066\u3044\u308b\u3063\u3066\u8a00\u308f\u308c\u305f\u3093\u3067\u3059\u304c\u3001\u3061\u3083\u3093\u3068\u6255\u3063\u3066\u307e\u3059\u3088\u3002",
                    "en": "I was told that my tuition fees were overdue, but I've been paying them."
                },
                {
                    "ja": "\u5bb6\u4e3b\u304c\u516d\u30f6\u6708\u9593\u5bb6\u8cc3\u304c\u6ede\u3063\u3066\u3044\u308b\u7537\u306e\u5bb6\u306b\u51fa\u5411\u304f\u3068\u3001\u7537\u306f\u5bb6\u306e\u4e2d\u3067\u6b7b\u3093\u3067\u3044\u305f\u3002",
