                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "None",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "I guess this stick was formerly a cucumber tree. Or maybe it just tried so hard it pooped a cucumber. I don't care which one is true, you pick whatever you want to believe.",
                "mnemonic": "It's working, it's working! The stick is returning to its {tooltip:Kanji:former} state and... w-wuh? It sprouted a {tooltip:Reading:cu}cumber ({span:lang=ja:\u304d\u3085\u3046})."
            }
        }

{
            "mnemonic": "A {tooltip:Radical:boat} will have at least one {tooltip:Radical:weapon}, {tooltip:Kanji:generally}.",
