                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u304a\u304d",
                        "primary": true
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "You really regret saying oki doki this time. You don\u2019t want to surf on a tsunami in the middle of the open sea. Imagine doing so. It\u2019s terrifying and wet and you don\u2019t even know how to surf. You\u2019re going to die.",
                "mnemonic": "Someone dares you to go out to the {tooltip:Kanji:open sea} and surf on the middle of the tsunami. \u201c{tooltip:Reading:Oki} ({span:lang=ja:\u304a\u304d}) doki,\u201d you reply. You can\u2019t refuse a dare. Every time someone dares you to do something, you always respond with \u201coki doki\u201d."
            }
        }

{
            "mnemonic": "Stick your {tooltip:Radical:fingers} in your {tooltip:Radical:mohawk} and {tooltip:Kanji:pluck} each hair out, one by one.",
