                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "As you feel the sexy, confident feelings return, you see traces of the ink on your carpet, all the way from the door to the bed. Dang it.",
                "mnemonic": "Turns out the {tooltip:Kanji:traces} of red ink were from a {tooltip:Reading:sexy} ({span:lang=ja:\u305b\u304d}) rave you were at last night. Everyone around you looked so sexy, with their glow-in-the-dark paint, so you decided to put some of the red ink on your feet so everyone could see your sexy dancing."
            }
        }

{
