        }

{
            "mnemonic": "The {tooltip:Radical:door} in that {tooltip:Radical:direction} is among a {tooltip:Kanji:cluster} of doors. You run in the direction of the cluster and one door stands out to you. You enter it.",
            "hints": "Imagine seeing all these doors, this cluster of doors. You feel confused at which one to enter but finally pick one. Hear the door creak as you open it.",
            "meanings": {
                "Primary": "Cluster"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u307c\u3046",
