                    }
                ],
                "hints": "Be contrary to the evildoers of the past and be like Kyaku instead.",
                "mnemonic": "Don't be the type of person who acts {tooltip:Kanji:contrary} to how they should and instead be like {tooltip:Reading:Kyaku} ({span:lang=ja:\u304d\u3083\u304f}) the customer. They're always so nice and polite and they don't give diseases to entire populations of people."
            }
