                    }
                ],
                "hints": "Moles will do anything for cheese, but honestly, wouldn't we all?",
                "mnemonic": "To get the mole to {tooltip:Kanji:do} what you want, just give it a nice big hunk of {tooltip:Reading:chee}se ({span:lang=ja:\u3061})."
            }
