            }
        }

{
            "mnemonic": "Where do you put your {tooltip:Radical:fingers} when you're on an {tooltip:Radical:escalator}? On the {tooltip:Kanji:handle}! Okay, so maybe it's not a handle and more of a railing, but for the sake of this kanji, picture a handle instead.",
            "hints": "Imagine being on an escalator and wrapping your fingers around a small handle on your way up or down. It's still a bit precarious, truth be told.",
            "meanings": {
                "Primary": "Handle"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u304d\u3085\u3046",
                        "primary": false
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u3042\u3064\u304b",
                        "primary": true
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "{span:lang=ja:\u6691\u304b}? Is the handle hot? Think about it. Is it? What does your imagination tell you?",
                "mnemonic": "You put your hand on the {tooltip:Kanji:handle} and an old person leans in close to you and says, \"{tooltip:Reading:\u6691\u304b}?\" ({span:lang=ja:\u3042\u3064\u304b}). He wants to know if the handle is ... hot? Before you can respond he says it again, and again! \u201c{span:lang=ja:\u6691\u304b\uff1f\uff01 \u6691\u304b\uff1f\uff01\uff1f\uff01 \u6691\u304b\uff1f\uff01\uff1f\uff01\uff1f\uff01}\u201d he's shouting as you slowly ride the escalator away from him."
            }
        }

{
            "mnemonic": "If there\u2019s a {tooltip:Radical:drop} on your {tooltip:Radical:head} and the {tooltip:Radical:rice} is {tooltip:Radical:big}, you know you\u2019re in the {tooltip:Kanji:interior}. And by interior, I mean you\u2019re actually inside someone. The rice is big because you\u2019ve shrunk to a tiny size and are inside someone\u2019s stomach. The drop on your head is actually digestive fluid.",
            "hints": "Imagine being in the interior of someone\u2019s tummy. See the big pieces of rice all around you as drops of stomach fluid continue to drop down on your head.",
            "meanings": {
                "Primary": "Interior"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u304a\u3046",
                        "primary": false
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u304a\u304f",
                        "primary": true
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "If you\u2019re unfamiliar with this Oklahoma song, check it out on YouTube. Imagine being in the interior of someone\u2019s belly as you hear this song booming all around you.",
                "mnemonic": "While you\u2019re in the {tooltip:Kanji:interior} of this guy, you hear him break out in song. He starts singing \u201c{tooltip:Reading:Ok}lahoma\u201d ({span:lang=ja:\u304a\u304f}) at the top of his lungs. The big pieces of rice slosh around as he sings and dances. \u201cOOOOk-lahoma, where the wind comes sweepin' down the plain!\u201d"
            }
        }

{
            "mnemonic": "A {tooltip:Radical:leader} with {tooltip:Radical:horns} takes a {tooltip:Radical:lantern} and searches for people to {tooltip:Kanji:join} him. He needs more people to join his cause so he can get his horns removed. He\u2019s embarrassed of them which is why he only travels at night, hence the lantern.",
            "hints": "Imagine this shady leader approaching you in the night. The lantern light shines in your face. Would you join him?",
            "meanings": {
                "Primary": "Join"
            },
            "kanjiReadings": {
