                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u3042\u308f",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "The last thing you wanted to do was join that guy so you hid in a haystack to avoid him.",
                "mnemonic": "The leader guy approaches you out of the darkness, his lantern held high. Oh no, not that guy. You've heard about his horn problem and you don't want to {tooltip:Kanji:join} him. You look around and spot a large {tooltip:Reading:hay}stack ({span:lang=ja:\u3078\u3044}). You quickly jump into it and hide from him."
            }
        }

{
            "mnemonic": "Under the {tooltip:Radical:moon} beneath a {tooltip:Radical:tree} there is a {tooltip:Radical:hat} filled with {tooltip:Radical:water}. You stare down into the water and decide to stick your {tooltip:Kanji:knee} in it.",
            "hints": "Feel the water splash over your knee as you stick it into this hat. It fits really well, the hat is the perfect size for your knee. Now look up at the moonlight filtering through the tree above.",
            "meanings": {
                "Primary": "Knee"
            },
            "kanjiReadings": {
