                        "primary": true
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Imagine the heat then the zap going through your knee. It isn't a nice heat, it's a hot heat, then BZZZT zap! Your knee was heat zapped pretty bad.",
