                {
                    "ja": "\u4eca\u5e74\u30a2\u30c3\u30d7\u30eb\u793e\u306f\u3001\u819d\u982d\u8a8d\u8a3c\u306e\u958b\u767a\u3092\u59cb\u3081\u308b\u3089\u3057\u3044\u3002",
