                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Picture all the jewels you were able to buy because you allocated your funds correctly. Imagine swimming in these jewels. Like a rich duck.",
                "mnemonic": "If you {tooltip:Kanji:allocate} your funds correctly you'll be able to buy as many precious {tooltip:Reading:jew}els ({span:lang=ja:\u3058\u3085\u3046}) as you want! However, jewels are expensive, so if you don't allocate any money, you won't be able to afford any. Ever."
            }
        }

{
            "mnemonic": "There's a {tooltip:Radical:tsunami} coming and you can't {tooltip:Radical:stop} the {tooltip:Radical:explosion} of {tooltip:Kanji:bitter}ness in your mouth. You're scared. Your mouth tastes bitter and {tooltip:Kanji:astringent}.",
            "hints": "You're reluctant to face this bitter end at the hands of a tsunami.",
            "meanings": {
                "Primary": "Bitter",
                "Alternatives": "Astringent, Reluctant"
            },
            "kanjiReadings": {
                "readings": [
