                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Try to stuff some of the jewels into your bitter mouth before the tsunami stops you.",
                "mnemonic": "With the {tooltip:Kanji:bitter} taste in your mouth, you {tooltip:Kanji:reluctant}ly gather up all of your {tooltip:Reading:jew}els ({span:lang=ja:\u3058\u3085\u3046}) and wait for the tsunami to take you away. At least with your jewels with you, there may be some hope of selling them and building a better life if you make it."
            }
        }

{
            "mnemonic": "A {tooltip:Radical:mountain} {tooltip:Radical:branch} will {tooltip:Kanji:branch off} from the rest.",
            "hints": "Picture this part of the mountain, branching off from the rest, into a mysterious path of its own.",
