{
            "mnemonic": "The {tooltip:Radical:dirt} next to your {tooltip:Radical:village} is where you {tooltip:Kanji:bury} the dead. People don't live forever, so every village has a patch of dirt specifically used for burying dead things.",
            "hints": "Imagine the village where you grew up. Can you see the dirt area where all your ancestors were buried?",
            "meanings": {
                "Primary": "Bury"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u307e\u3044",
                        "primary": false
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u3046, \u3046\u305a",
                        "primary": true
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Imagine crying as you bury your pet uni. Your tears can't save it now. (Though it is a bit ironic, since it needed salt water.)",
                "mnemonic": "You don't just {tooltip:Kanji:bury} dead relatives here. You also buried your dead pet {tooltip:Reading:u}ni ({span:lang=ja:\u3046}) in that dirt. You thought having an uni as a pet would be a good idea. Too bad uni need water to survive."
            }
        }

{
            "mnemonic": "You take {tooltip:Radical:gold} in exchange for executing {tooltip:Radical:orders} to construct a {tooltip:Kanji:buzzer}. You are a {tooltip:Kanji:small bell} maker and someone orders you to make one into a buzzer in exchange for some gold. This is how you make a living.",
            "hints": "Imagine the gold, heavy in your pockets, as you construct this buzzer with your bare hands. Feel the cool metal clink around in your hands as you put it together.",
            "meanings": {
                "Primary": "Buzzer",
                "Alternative": "Small Bell"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
