{
            "mnemonic": "The {tooltip:Radical:excuse} radical and the {tooltip:Kanji:excuse} kanji are exactly the same! Dandy!",
            "hints": "Know your radicals, stop making excuses.",
            "meanings": {
                "Primary": "Excuse"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u3081\u3093",
