                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u307e\u306c\u304b",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Imagine all the men you\u2019ve talked to in your life. Think of every excuse they\u2019ve told you. Think of the worst excuse you\u2019ve ever heard. Remember that.",
                "mnemonic": "Who always makes {tooltip:Kanji:excuse} after excuse? {tooltip:Reading:Men} ({span:lang=ja:\u3081\u3093})! They have an excuse for everything. Why didn\u2019t you take out the trash? Why did you forget my birthday? It\u2019s just excuse after excuse with men. So I\u2019ve heard, anyway."
            }
        }

{
            "mnemonic": "Your {tooltip:Radical:buddy} the {tooltip:Radical:sheep} is part of a {tooltip:Kanji:flock}. A flock of sheep. Your sheep buddy is a member of a flock.",
            "hints": "Imagine following your sheep buddy back to his flock. Feel the soft fur of all the sheep around you as they baa peacefully.",
            "meanings": {
                "Primary": "Flock"
            },
            "kanjiReadings": {
                "readings": [
