                    }
                ],
                "mnemonic": "\n{splitParent}The reading is the same as {span:lang=ja:\u5f15\u304f}, which is \"to pull.\" When you play a stringed instrument, you are pulling the string in a direction to make it vibrate and create a sound. So, \"to pull\" and \"to play a stringed instrument\" share a reading. It's a bit more of a stretch for instruments with keyboards, but pianos do at least have strings...\n"
            },
            "contextSentences": [
                {
                    "ja": "\u7f8e\u9999\u3061\u3083\u3093\u306f\u3001\u30a6\u30af\u30ec\u30ec\u3092\u5f3e\u304f\u3068\u5fc3\u304c\u4f11\u307e\u308b\u3068\u8a00\u3063\u3066\u3044\u305f\u3088\u3002",
