            }
        }

{
            "mnemonic": "A {tooltip:Radical:horse} goes to his favorite {tooltip:Radical:district} to {tooltip:Kanji:gallop} around. This district has lots of cool buildings and lights to look at, so this horse loves to gallop around there.",
            "hints": "Hear the horse clip clopping around the district as it continues to gallop. Clip clop, clop clip clop!",
            "meanings": {
                "Primary": "Gallop"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
