            "contextSentences": [
                {
                    "ja": "\u5408\u5531\u56e3\u3067\u6b4c\u3046\u5a18\u306e\u4e00\u751f\u61f8\u547d\u306a\u59ff\u306b\u611f\u52d5\u3057\u307e\u3057\u305f\u3002",
