                        "primary": true
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Imagine reaching into the shallows and saving the geoducks as they scream, \u201cSave me! Save me!\u201d into your ear.",
                "mnemonic": "After being washed through the {tooltip:Kanji:rapids} and into the {tooltip:Kanji:shallows}, the living geoducks are screaming \u201c{tooltip:Reading:Save} ({span:lang=ja:\u305b}) me! Save me!\u201d They need to be saved from the water, and you are the only one who can save them. You gotta run over and help them out."
            }
        }

{
            "mnemonic": "Your {tooltip:Radical:mouth} is {tooltip:Radical:showy} so it makes everybody around you {tooltip:Kanji:rowdy}.",
            "hints": "Your mouth is showy because it's covered in grills and bright red lipstick. People get rowdy because you're a celebrity and your showy mouth is your signature look, and everyone's so excited to see your mouth in person.",
