            }
        }

{
            "mnemonic": "You're digging in the {tooltip:Radical:dirt} when you find a {tooltip:Radical:tiger} and a {tooltip:Radical:cactus}. You keep digging until you realize that these are a part of some big {tooltip:Kanji:ruins}. They're the ruins of tiger and cactus statues. It looks like whoever used to live here worshiped tigers and cacti. Or maybe they ate them. But now their whole civilization is just ruins.",
            "hints": "Imagine looking through these ruins. Picture the broken tiger and cactus statues. Try to imagine the people who used to live here before it turned to ruins.",
            "meanings": {
                "Primary": "Ruins"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u304d\u3087",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "None",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Picture the ruins of Little Kyoto. Try to imagine what it was like before the whole place fell apart. Maybe they would have lived on if they hadn't been doing things with sharp cacti and bitey tigers.",
                "mnemonic": "Well, as it turns out, these are the {tooltip:Kanji:ruins} of Little {tooltip:Reading:Kyo}to ({span:lang=ja:\u304d\u3087}), the city that existed before the modern day one. And it looks like the citizens of Little Kyoto faced their end a long time ago."
            }
        }

{
            "mnemonic": "The {tooltip:Radical:alcohol} you take a {tooltip:Radical:measurement} most carefully of is {tooltip:Kanji:sake}. Sake is very important to the alcohol culture in Japan, so you must make sure to measure it out to the precise amount.",
            "hints": "Imagine this sake as you measure it out. Hear it pouring out of the bottle as you catch the whiff of sweet alcohol in the air.",
            "meanings": {
                "Primary": "Sake"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u3061\u3085\u3046, \u3061\u3085",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u304b\u3082",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Imagine Chewbacca drinking sake all the time while Han Solo told him he needed to stop and get help, but Chewbacca just did his yell thing and drank more sake.",
                "mnemonic": "You know who enjoyed {tooltip:Kanji:sake} a lot? {tooltip:Reading:Chew}bacca ({span:lang=ja:\u3061\u3085\u3046}). He was always drinking, which is concerning when you think about all the driving he did."
            }
        }

{
            "mnemonic": "You find some {tooltip:Radical:fingers} from {tooltip:Radical:long ago}. They must have been {tooltip:Kanji:set aside} by their previous owners. They definitely weren't cut off or anything, someone just decided they didn't want them anymore and set them aside.",
            "hints": "What would have to happen for you to set aside your own fingers? Try to imagine it right now.",
            "meanings": {
                "Primary": "Set Aside"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u305d",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "None",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Think of all the things you do with your fingers. Now picture how they would look if you had never ever cleaned them with soap. Uhg, disgusting. You should just set them aside here, and find some new ones.",
                "mnemonic": "I know why they {tooltip:Kanji:set aside} their fingers long ago, it's because there was no {tooltip:Reading:so}ap ({span:lang=ja:\u305d}). If you didn't have soap to clean your fingers you wouldn't want to keep them for very long..."
            }
        }

{
            "mnemonic": "Something you {tooltip:Radical:say} to someone you {tooltip:Radical:become} attached to should be said with {tooltip:Kanji:sincerity}. You need to speak with sincerity when you say things to someone who will eventually become your significant other, for example.",
            "hints": "Imagine saying something with sincerity to someone you want to become important to you. Say something like, \u201cI love you\u201d out loud. Say it with the utmost sincerity.",
            "meanings": {
                "Primary": "Sincerity"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u305b\u3044",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u307e\u3053\u3068",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Say, \"I love you,\" again and watch your saber beating in time with your heart. If you weren't sincere it would fade and grow dull.",
                "mnemonic": "When you say something with complete, unabashed {tooltip:Kanji:sincerity} your special {tooltip:Reading:sa}ber ({span:lang=ja:\u305b\u3044}) starts to pulse with the beating of your heart. It shows the person you want to become close to that you truly are sincere!"
            }
        }

{
            "mnemonic": "A {tooltip:Radical:tiger} has {tooltip:Radical:legs} that belong to a {tooltip:Kanji:tiger}. You know, a tiger has the legs of a tiger. This is common knowledge. Nothing new here.",
            "hints": "Look at the tiger running with his tiger legs. So majestic. So fierce.",
            "meanings": {
                "Primary": "Tiger"
            },
            "kanjiReadings": {
                "readings": [
