                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Picture Genghis Khan aboard a monstrous warship. He's carefully watching the sea and land that he's conquered.",
                "mnemonic": "This huge {tooltip:Kanji:warship} is run by Genghis {tooltip:Reading:Khan} ({span:lang=ja:\u304b\u3093}), the famous warlord. Really, what did you expect? Who else is strong enough to captain a warship but him?"
            }
        }

{
            "mnemonic": "You use your {tooltip:Radical:fingers} to dig through the {tooltip:Radical:trash} in the light of the {tooltip:Radical:moon} in {tooltip:Radical:winter} because you're going through {tooltip:Kanji:withdrawal}. You need your fix and you need it now, so you're willing to freeze your fingers off digging through moonlit trash to get it.",
            "hints": "Imagine withdrawal this bad, that you're in the trash like this. Close your eyes and feel the cold, smell the stink.",
            "meanings": {
                "Primary": "Withdrawal"
            },
            "kanjiReadings": {
