            }
        }

{
            "mnemonic": "Each {tooltip:Radical:tree} needs its {tooltip:Radical:drum} {tooltip:Radical:measurement} done before you can say it's really made of {tooltip:Kanji:wood}.",
            "hints": "There are a lot of hoodlums out there that try to dress as trees and confuse people. So make sure you measure their drum before you cut one down or tell someone your secrets under it.",
            "meanings": {
                "Primary": "Wood"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u3058\u3085",
