                    }
                ],
                "mnemonic": "\n{splitParent}You never wrap things once, you always wrap them twice. And then you double that. It's a {tooltip:Reading:two two} ({span:lang=ja:\u3064\u3064}) wrapping technique.\n{splitParent}{span:lang=ja:\u3064\u3064\u3080} is the reading we want you to focus on, but it's good to know that {span:lang=ja:\u5305\u3080} can be read as {span:lang=ja:\u304f\u308b\u3080} as well. {span:lang=ja:\u304f\u308b\u3080} is used when you wrap something up carefully and protectively, like a baby in a blanket. {span:lang=ja:\u3064\u3064\u3080} on the other hand, has broader use and is commonly used for wrapping things like presents.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u7761\u7720\u85ac\u3092\u30d3\u30cb\u30fc\u30eb\u30e9\u30c3\u30d7\u3067\u5305\u307f\u307e\u3057\u305f\u3002",
