                    }
                ],
                "hints": "Han Solo's bamboo example comes to life and runs off.",
                "mnemonic": "One last {tooltip:Kanji:example} for you. Now I'm going to take this bamboo and whittle it into an example of {tooltip:Reading:Han} ({span:lang=ja:\u306f\u3093}) Solo!"
