        }

{
            "mnemonic": "Someone's {tooltip:Radical:fingers} touch your {tooltip:Radical:tongue} and {tooltip:Kanji:fasten} it together. You can't talk. All you can do is make sad tongue-less sounds as you try to figure out who would fasten your tongue like this.",
            "hints": "Try to fasten your own tongue with your fingers right now. You probably can't do it, right? That's because your fingers are too big and your tongue is too slippery.",
            "meanings": {
                "Primary": "Fasten"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u304b\u3064",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u304f\u304f",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "In this case, many cats fastened your tongue. You should probably be nicer to cats from now on so this doesn't happen again.",
                "mnemonic": "Only one creature could use its fingers to {tooltip:Kanji:fasten} your tongue like this: {tooltip:Reading:cats} ({span:lang=ja:\u304b\u3064}). Cats are notorious for fastening tongues so that people can't speak. Haven't you ever heard the phrase, \"Cat got your tongue?\""
            }
        }

{
            "mnemonic": "Under the {tooltip:Radical:canopy}, you use a {tooltip:Radical:tree} for your {tooltip:Kanji:floor}. It also becomes your {tooltip:Kanji:bed}, because hey, what is a floor but the original bed?",
            "hints": "You lay it down, cut it into slats, and voila! A floor! And a bed!",
