                    }
                ],
                "hints": "Now you have absolutely nothing. Not even a {tooltip:Kanji:consolation} flag.",
                "mnemonic": "Even though you weren't happy with the flag, you were even more frustrated to watch an {tooltip:Reading:ea}gle ({span:lang=ja:\u3044}) swoop down and grab the flag and fly away with it."
            }
