                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "None",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Picture a line of people enrolling for new classes, sports, citizenship, etc. The moment they've enrolled they poof into the perfect, sexy person (in your eyes).",
                "mnemonic": "If you {tooltip:Kanji:enroll} in something new people will find you very {tooltip:Reading:sexy} ({span:lang=ja:\u305b\u304d}). This was true long ago too. There's nothing sexier than trying to improve yourself."
            }
        }

{
            "mnemonic": "If the {tooltip:Radical:rain} touches your {tooltip:Radical:foot} and gives it a little rain {tooltip:Radical:kiss}, you know that part of your foot is {tooltip:Kanji:expose}d to the elements. You can also see some {tooltip:Kanji:dew} forming on your exposed foot. So that's what rain kisses are!",
            "hints": "Ugh, you shouldn't have bought these open toed shoes, at least not during rainy season!",
            "meanings": {
