                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "You wonder how long this road will go. With exposed toes, your feet are going to get all wet with dew if you can't get off this blasted road.",
                "mnemonic": "You run along the {tooltip:Reading:ro}ad ({span:lang=ja:\u308d}), trying to get out of the rain, but the road keeps going and going, with walls on both sides."
            }
