                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u3081\u305a\u3089",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Not sure how it got there, but you'll make a pretty penny from this. The king only had one chin, so that's about as {tooltip:Kanji:rare} as they come.",
