                },
                {
                    "ja": "\u6fe1\u308c\u8863\u3060\u3063\u305f\u3068\u4fe1\u3058\u3066\u304f\u308c\u305f\u306e\u306f\u3001\u98fc\u3044\u72ac\u3060\u3051\u3060\u3063\u305f\u3002",
