                {
                    "ja": "\u3046\u3061\u306e\u72ac\u306f\u3001\u30d5\u30e9\u30d5\u30fc\u30d7\u3092\u30b8\u30e3\u30f3\u30d7\u3057\u3066\u6f5c\u308b\u6280\u3092\u8eab\u306b\u3064\u3051\u307e\u3057\u305f\u3002",
