                ],
                "mnemonic": "\n{splitParent}Since this word has okurigana (hiragana attached to the kanji) you know that it's probably going to be the kun'yomi reading.\n{splitParent}Lucky for you, the kanji readings for transitive and intransitive verbs are almost always the same. Once you learn one, you know them both! This reading is the same as {span:lang=ja:\u88c2\u304f}.\n"
            },
            "contextSentences": [
                {
                    "ja": "\u6700\u8fd1\u306f\u6bce\u671d\u3001\u88c2\u3051\u308b\u30c1\u30fc\u30ba\u3092\u98df\u3079\u3066\u3044\u307e\u3059\u3002",
