                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u304b",
                        "primary": true
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "If you go to any of those fancy (and not so fancy) gamble-places, they always have a car sitting in the middle of the room. Usually rotating, really slowly, to make you want it more, making you gamble more.",
                "mnemonic": "If you win this {tooltip:Kanji:gamble} you'll have enough shellfish to buy a brand new {tooltip:Reading:ca}r ({span:lang=ja:\u304b})!"
            }
        }

{
            "mnemonic": "Coming down with the {tooltip:Radical:rain} is {tooltip:Radical:two} {tooltip:Radical:spikes}. They go right through two {tooltip:Kanji:ghost}s.",
            "hints": "The ghosts are pinned to the ground by the spikes, unable to move. ",
            "meanings": {
                "Primary": "Ghost"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u308c\u3044, \u308a\u3087\u3046",
