            }
        }

{
            "mnemonic": "If you've been to the {tooltip:Radical:moon} in the {tooltip:Radical:past}, you had to get the special {tooltip:Radical:stamp} on your {tooltip:Kanji:leg}.",
            "hints": "This leg stamp not only proved you went, but lets everyone around you know you've been to the moon before!",
