                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u3080\u3059\u3081",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "When you think of \"miss,\" remember the time that Jourm asked you to call him \"Miss Jourm.\" You thought he was a big, ten foot tall guy, but now he suddenly wants you to call him Miss Jourm. Okay, that's up to Jourm so you should respect that.",
                "mnemonic": "\"Call me {tooltip:Kanji:Miss} {tooltip:Reading:Jou}rm ({span:lang=ja:\u3058\u3087\u3046}),\" Jourm says to you."
            }
        }

{
            "mnemonic": "If you're showing me your \"{tooltip:Radical:spirit} {tooltip:Radical:fruit}\" then you are just {tooltip:Kanji:naked}. You're {tooltip:Kanji:nude}.",
            "hints": "You know what I mean by \"spirit fruit\" \u2013\u2013 yep, it's out there and you're naked.",
