        }

{
            "mnemonic": "An {tooltip:Radical:axe} is sticking in the {tooltip:Radical:ground} on top of a {tooltip:Radical:mountain}. It's sticking into the very {tooltip:Kanji:peak}. Because why would you bother to stick your axe anywhere else on the mountain to prove you climbed it? ",
            "hints": "Picture that axe, jammed into the mountain's {tooltip:Kanji:peak}. The person who did that must have been really cool to get all the way up there.",
            "meanings": {
                "Primary": "Peak"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u304c\u304f",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u305f\u3051",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
