                    "ja": "\u7126\u308b\u306a\u3088\u3002\u5c0f\u4fbf\u306b\u884c\u304d\u305f\u3044\u4ee5\u5916\u306f\u3001\u6025\u3050\u5fc5\u8981\u306f\u306a\u3044\u3088\u3002\u4e00\u65e5\u4e00\u65e5\u3092\u7740\u5b9f\u306b\u306a\u3002",
