                        "voiceActorName": "Kenichi",
                        "voiceDescription": "Tokyo accent",
                        "file": "43122-subject-9008.ogg"
                    }
                ],
                "mnemonic": "\n{splitParent}We all know it's not okay to {tooltip:Vocabulary:to torment} each other. So how about we all {tooltip:Reading:sign a} ({span:lang=ja:\u3055\u3044\u306a}) contract saying that we'll never torment anyone ever again?\n"
            },
            "contextSentences": [
                {
                    "ja": "\u7121\u529b\u611f\u306b\u82db\u307e\u308c\u3066\u308b\u3093\u3088\u3002",
                    "en": "I'm tormented by feelings of helplessness."
                },
                {
                    "ja": "\u3046\u3060\u308b\u3088\u3046\u306a\u6691\u3055\u304c\u79c1\u9054\u3092\u82db\u3080\u3002",
                    "en": "The sweltering heat torments us."
                },
                {
                    "ja": "\u88ab\u5bb3\u8005\u306f\u307e\u305f\u4f55\u304b\u60aa\u3044\u3053\u3068\u304c\u8d77\u3053\u308b\u306e\u3067\u306f\u306a\u3044\u304b\u3068\u3044\u3046\u4e0d\u5b89\u306b\u82db\u307e\u308c\u3066\u3044\u307e\u3057\u305f\u3002",
                    "en": "The victims were tormented by the anxiety that something else bad would happen."
                }
            ],
