{
            "mnemonic": "A {tooltip:Kanji:well} {tooltip:Kanji:door} is just a {tooltip:Vocabulary:well}. It's the door that goes into the well hole, making it a well.",
            "hints": "",
            "meanings": {
                "Primary": "Well",
                "Word Type": "noun"
            },
            "vocabReadings": {
                "readings": [
                    {
