                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u3042\u308f",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Watch helplessly as your home, now trapped in a bubble, floats away into the sky.",
                "mnemonic": "One of the biggest {tooltip:Kanji:bubbles} heads straight for your {tooltip:Reading:ho}me ({span:lang=ja:\u307b\u3046}), engulfs it, and picks it up into the air!"
            }
        }

{
            "mnemonic": "Some {tooltip:Radical:grains} get stuck in his {tooltip:Radical:cleat}, and {tooltip:Radical:Wolverine}'s {tooltip:Radical:heart} grows {tooltip:Kanji:calm}. Wolverine had been screaming and yelling and stomping around, but when the grains entered his cleat he realized where he was. He was finally able to calm down.",
            "hints": "He's calm now because he stomped right into a farmer's field (thus the rice) and if he didn't calm down he'd probably ruin it.",
            "meanings": {
                "Primary": "Calm"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u304a\u3093",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u304a\u3060",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Picture Wolverine sitting calmly in this field, onions causing tears to stream down his cheeks as he reflect on what he's done.",
                "mnemonic": "Now that Wolverine is {tooltip:Kanji:calm}, tears come to his eyes. Being calm has given him perspective on what his anger has done. Oh, wait no. There are just some {tooltip:Reading:on}ions ({span:lang=ja:\u304a\u3093}) in his cleats too, and they're making calm tears trickle down his eyes."
            }
        }

{
            "mnemonic": "You see a {tooltip:Radical:child} with an {tooltip:Radical:umbrella} in front of you. Suddenly, they fall straight down into a {tooltip:Kanji:cavity} in the road. It's a big {tooltip:Kanji:hole}!",
            "hints": "You run over to where the child fell. They are just fine! Because they had an umbrella, they were able to float to the bottom.",
            "meanings": {
                "Primary": "Cavity",
                "Alternative": "Hole"
            },
            "kanjiReadings": {
