                "mnemonic": "\"Into my {tooltip:Kanji:cavity} you go!\" yells a voice. It is {span:lang=ja:\u3053\u3046\u3044\u3061}. "
            }
        }

{
            "mnemonic": "This {tooltip:Radical:tree} is very {tooltip:Radical:odd}, to say the least. The shape is all crazy, like a lightning bolt stuck into the ground, or something. Oh wait, look at this. I can sit on it really nicely. It's just like a {tooltip:Kanji:chair}!",
            "hints": "Imagine this odd tree {tooltip:Kanji:chair} being the most comfortable chair you've ever sat on. It's shaped perfectly for you, and the moss makes it soft. Wow, what a chair.",
            "meanings": {
                "Primary": "Chair"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u3044",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "None",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Feel the fear and regret. You should have known not to sit in this \"chair\". Mother nature never forgives, and now you don't have eyeballs.",
                "mnemonic": "But, this odd tree {tooltip:Kanji:chair} is also home to an {tooltip:Reading:ea}gle ({span:lang=ja:\u3044}). It swoops down upon you as you sit down, gouging your eyes out."
            }
        }

{
            "mnemonic": "If you pick certain {tooltip:Radical:rice} or {tooltip:Radical:flowers} you'll be put in {tooltip:Radical:prison}. The most famous of these is the {tooltip:Kanji:chrysanthemum}. Chrysanthemums are super important in Japan because they're the symbol of the imperial family. They're even on the cover of Japanese passports. If you get caught picking a chrysanthemum, you're going to prison.",
            "hints": "Chrysanthemums are really important to the Japanese people. Please don't ever pick them (or rice, because that's stealing food, someone planted that)!",
            "meanings": {
                "Primary": "Chrysanthemum"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u304d\u304f",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "None",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Imagine holding a chrysanthemum in your hands while you get kicked over and over and over in prison. Was it worth it?",
                "mnemonic": "If you go to prison for {tooltip:Kanji:chrysanthemum} picking, everyone in the prison is going to {tooltip:Reading:kick} ({span:lang=ja:\u304d\u304f}) you nonstop. You broke the chrysanthemum picking law, so kicking is your punishment. And believe me, you don't want these kicks."
            }
        }

{
            "mnemonic": "A {tooltip:Radical:tsunami} causes the {tooltip:Radical:capital} to become very {tooltip:Kanji:cool}. The capital was already a pretty cool temperature, but with the addition of the water from the tsunami, the capital is now very cool.",
            "hints": "Imagine being in the capital. The tsunami hits and now you are all wet. You are also very cool because the water is not warm. You are cool and wet. How sad.",
            "meanings": {
                "Primary": "Cool"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u308a\u3087\u3046",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u3059\u305a",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Imagine rowing in your row boat. The more you row, the less cool it gets. Feel your arms strain as you do so. It\u2019s all worth it!",
                "mnemonic": "You don\u2019t like how {tooltip:Kanji:cool} it is in the capital now so you decide to get in your {tooltip:Reading:row} ({span:lang=ja:\u308a\u3087\u3046}) boat and row away to some place that is not so cool. Get in your row boat and row away!"
            }
        }

{
            "mnemonic": "The {tooltip:Radical:white} {tooltip:Radical:thread} in your {tooltip:Radical:towel} comes from {tooltip:Kanji:cotton}. We use cotton to make lots of things, like clothes and bedsheets. But white towels are always made from soft, fluffy cotton.",
            "hints": "Imagine shoving your face into a nice, clean, white cotton towel. Mmm, so fresh.",
            "meanings": {
                "Primary": "Cotton"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u3081\u3093",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u308f\u305f",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Picture all of the men lined up, making towels out of pure white cotton. They're all rubbing their faces in the soft cotton whenever they can.",
                "mnemonic": "This {tooltip:Kanji:cotton} is made by {tooltip:Reading:men} ({span:lang=ja:\u3081\u3093})."
            }
        }

{
            "mnemonic": "Below the {tooltip:Radical:canopy} of {tooltip:Radical:tree}s is a {tooltip:Radical:demon}. This demon is a {tooltip:Kanji:devil}.",
            "hints": "You thought the devil hangs out in hell, but he actually hangs out under this canopy of trees.",
