                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Into the trees is where all mamas go missing. And so the devil searches for his mama under this canopy of trees.",
                "mnemonic": "Why is the {tooltip:Kanji:devil} under a canopy of trees? Because he's looking for his {tooltip:Reading:ma}ma ({span:lang=ja:\u307e})."
            }
        }

{
            "mnemonic": "You need to bring {tooltip:Radical:charcoal} under this {tooltip:Radical:roof} to heat the {tooltip:Kanji:dormitory}. You live in this dormitory with a bunch of other kids, and you all have to take turns bringing in the charcoal from outside to heat it.",
            "hints": "Imagine looking at a dormitory chore wheel and seeing it's your turn to carry in the charcoal this week. Bleh!",
            "meanings": {
                "Primary": "Dormitory"
            },
            "kanjiReadings": {
                "readings": [
