                        "primary": false
                    }
                ],
                "hints": "Imagine looking down on {span:lang=ja:\u3068\u3046\u304d\u3087\u3046} from atop this magnificent pillar. The sun is rising behind you, slowly illuminating the city below.",
                "mnemonic": "That {tooltip:Kanji:pillar} happens to be in the center of {span:lang=ja:\u3068\u3046\u304d\u3087\u3046}. If you need to find east (which is where {span:lang=ja:\u3068\u3046\u304d\u3087\u3046} is), you just look for the pillar."
            }
        }

{
            "mnemonic": "\"{tooltip:Radical:Say} '{tooltip:Radical:big},' {tooltip:Radical:ground} {tooltip:Radical:beggar}! Have {tooltip:Kanji:pride}!\" ",
            "hints": "You are trying to tell a beggar on the ground to say they are big, because you want to make the beggar feel a little pride. \"Have pride in your job as a beggar!\" you tell them.",
            "meanings": {
                "Primary": "Pride"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u3053",
                        "primary": true
                    },
                    {
                        "name": "Kun\u2019yomi",
