                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Imagine dipping each of your toes into the paint-dirt, one by one, to paint each of them a different color. Why are you doing this?",
                "mnemonic": "You touch the {tooltip:Kanji:paint} in the dirt with your {tooltip:Reading:toe} ({span:lang=ja:\u3068}) to see if it's still wet. It is. The paint is still very wet and now your toe looks like a tiny rainbow."
            }
        }

{
            "mnemonic": "Your {tooltip:Radical:shellfish} are worth a {tooltip:Radical:fortune} because you decided to {tooltip:Kanji:paste} your fortune to the shellfish.",
            "hints": "Picture all of your riches, your money, your jewels. They're all pasted directly onto all of your shellfish!",
            "meanings": {
                "Primary": "Paste"
            },
            "kanjiReadings": {
