                        "primary": true
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Especially big snakes. They're really, really hebi.",
                "mnemonic": "Why don't you just bring a {tooltip:Kanji:snake} up to the roof yourself? Because snakes are {tooltip:Reading:heavy} ({span:lang=ja:\u3078\u3073})."
            }
