{
            "mnemonic": "Bite a {tooltip:Radical:tree}'s {tooltip:Radical:root} with your {tooltip:Radical:fang} to get an {tooltip:Kanji:approximation} on its age. It won't be exact, this isn't scientific or anything, but it will be pretty close.",
            "hints": "Once you have an approximation on the age, you'll be able to come up with an approximation on how much it's worth too.",
            "meanings": {
                "Primary": "Approximation"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u304c\u3044",
                        "primary": true
                    },
                    {
