                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u306f\u304b",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Watch as the conspiratorial tree and all it's gossiping friends are bowled over by your bowling ball. Phew. You're safe from the trees.{splitParent}For now.",
                "mnemonic": "Now you're getting it! That tree is trying to {tooltip:Kanji:conspire} against you and take you down. Take your {tooltip:Reading:bow}ling ({span:lang=ja:\u307c\u3046}) ball and bowl it and all its friends down!"
            }
        }

{
            "mnemonic": "On the {tooltip:Radical:roof} there's some type of {tooltip:Radical:turkey} {tooltip:Radical:bird}, but thinner and longer. You look closer and realize it's a {tooltip:Kanji:crane}.",
            "hints": "Picture the beautiful black and white crane dancing gracefully on the roof. Now that you know what it is, you feel a little bad about calling it a turkey bird.",
            "meanings": {
                "Primary": "Crane"
            },
            "kanjiReadings": {
                "readings": [
                    {
