                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u3064\u308b",
                        "primary": true
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "The crane keeps saying you're too rude whenever other people come close so they know what kind of person you are. Yikes, you really shouldn't have gotten on this crane's bad side.",
                "mnemonic": "The {tooltip:Kanji:crane} leans down toward you from its roof perch and squawks, \"{tooltip:Reading:Too ru}de ({span:lang=ja:\u3064\u308b})!\" You're shocked! You didn't know the crane could speak English, but even worse, it knew you called it a turkey bird."
            }
        }

{
            "mnemonic": "You use your {tooltip:Radical:fingers} and a {tooltip:Radical:stone} to begin {tooltip:Kanji:cultivation} of the land. You use your fingers to till the soil, the stone to flatten the ground, and you carefully poke the seeds into the dirt and then use the stone to smash them further down.",
            "hints": "Imagine being in a field, using your fingers and a stone to cultivate the whole thing, by hand.",
            "meanings": {
                "Primary": "Cultivation"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u305f\u304f",
