                    "ja": "\u5927\u5909\u3060\u3002\u304a\u57ce\u306e\u790e\u3068\u306a\u308b\u77f3\u304c\u8ab0\u304b\u306b\u58ca\u3055\u308c\u3066\u3057\u307e\u3063\u305f\u3002\u4e00\u523b\u3082\u65e9\u304f\u907f\u96e3\u3057\u306a\u3044\u3068\u57ce\u304c\u5d29\u308c\u308b\u305e\uff01",
