        }

{
            "mnemonic": "There is a {tooltip:Radical:tsunami} coming up over a {tooltip:Radical:cliff} made of {tooltip:Radical:dirt}. You can see this happening very far away because it's right on the {tooltip:Kanji:horizon}.",
