                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u307f\u306d",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Picture your beautiful summit home. You know, George Washington had one of these too. So. That's cool, I guess.",
