                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u307e\u305f",
                        "primary": true
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Imagine your friends getting more and more annoyed with your constant stool-sitting habits! They really don't get it. What is the matter with you?! Why can't you just stand like everyone else? Don't you know sitting is the \"new smoking\"!?",
                "mnemonic": "Your friends are starting to worry about you, because you're always sitting on that stool. \"What is the {tooltip:Reading:matter} ({span:lang=ja:\u307e\u305f}) with you?\" they scream! You might want to imagine that all your friends have Jamaican and/or British accents to make this one fit a bit better!"
            }
        }

{
            "mnemonic": "We must {tooltip:Radical:stop} the {tooltip:Radical:moon}. That, at least, we can come to an {tooltip:Kanji:agreement} on.",
            "hints": "There are a group of people pointing at pictures of the moon coming closer to earth. They are the world's leaders, and although they don't get along normally, this new attack from the moon has united them in agreement: we must stop the moon.",
            "meanings": {
                "Primary": "Agreement",
                "Alternative": "Consent"
            },
            "kanjiReadings": {
