                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "The world has united against the moon, and they have made Emperor {span:lang=ja:\u3053\u3046\u3044\u3061} their temporary leader.",
                "mnemonic": "\"We have {tooltip:Kanji:agreement},\" the world's leaders all say. \"We will work together to stop the moon, and we have {tooltip:Kanji:agreement} on who we will follow, Emperor {span:lang=ja:\u3053\u3046\u3044\u3061}."
            }
        }

{
            "mnemonic": "If you want to have a {tooltip:Radical:tsunami} at your {tooltip:Radical:wedding}, you need to make sure you have it at the {tooltip:Kanji:bay}. Anywhere more inland, and the tsunami won't reach it in time.",
            "hints": "Picture the tsunami coming towards your beautiful wedding as you stand by the bay. It's not safe, but it's memorable!",
            "meanings": {
                "Primary": "Bay"
            },
            "kanjiReadings": {
                "readings": [
