                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Imagine getting a call from the Shougun himself. He's come to your house before, but he's never asked you to eat with him. This is huge!",
                "mnemonic": "You are {tooltip:Kanji:call}ed to come {tooltip:Kanji:eat} by the {tooltip:Reading:Shou}gun ({span:lang=ja:\u3057\u3087\u3046}). He's been really impressed with you lately and he wants to chat over drinks, he says on the phone."
            }
        }

{
            "mnemonic": "You try to put your {tooltip:Radical:toe} inside a {tooltip:Radical:shellfish}, but it just won't open. That's because this shellfish has sworn an oath of {tooltip:Kanji:chastity}.",
            "hints": "\"No, I won't open up until I meet the toe I will marry,\" it says to you.",
            "meanings": {
                "Primary": "Chastity"
            },
            "kanjiReadings": {
