            }
        }

{
            "mnemonic": "The {tooltip:Radical:buddy} {tooltip:Radical:building} is in the next {tooltip:Kanji:county}. If it was in your county then it wouldn't be a buddy, it would be a neighbor. You're aware of this building, but they aren't that close, so they're just a buddy.",
            "hints": "Imagine looking at a map of your county and the surrounding ones. All of the buildings in the counties next to yours are buddy buildings!",
            "meanings": {
                "Primary": "County",
                "Alternative": "District"
            },
            "kanjiReadings": {
                "readings": [
                    {
