                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "You wouldn't expect it, but he actually allowed many types of cultures, religions, and peoples to exist under his reign. The Mongols had an exceptional amount of tolerance for the time.",
                "mnemonic": "{tooltip:Kanji:Tolerance} is one thing that Genghis {tooltip:Reading:Khan} ({span:lang=ja:\u304b\u3093}) had a surprising amount of."
            }
        }

