                        "primary": false
                    }
                ],
                "hints": "Now draw Randy Savage in the columns on your graph paper. He just seems to fit there now.",
                "mnemonic": "Out of the tree {tooltip:Kanji:column}s bursts professional wrestler {tooltip:Reading:Ran}dy ({span:lang=ja:\u3089\u3093}) Savage! \"Oooh I'm talking about columns that I like mmmm oh yeaah. The Macho Man loves columns MMm OOHH YEAAH~!\""
            }
        }

{
            "mnemonic": "Your {tooltip:Radical:forehead} is the {tooltip:Radical:origin} for the {tooltip:Radical:measurement} for your {tooltip:Kanji:crown}! If you measure somewhere else on your head for a crown it won't fit.",
            "hints": "Imagine someone putting a tape measure around your forehead and taking careful measurements for your crown. They better not mess up, or you'll have them put to death!",
            "meanings": {
                "Primary": "Crown",
                "Alternative": "Cap"
            },
            "kanjiReadings": {
                "readings": [
