                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "None",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "What kind of monster is on your family crest? Picture it in your mind right now. Now tweet to us @wanikaniapp because I really want to know what you came up with!!",
                "mnemonic": "Your {tooltip:Kanji:family crest} is of a {tooltip:Reading:mon}ster! And the writing says \"Our Family Monster.\""
            }
        }

{
            "mnemonic": "You see a {tooltip:Radical:building} with a {tooltip:Radical:lip ring} and it's just so cute you have to {tooltip:Kanji:flatter} it. \"That lip ring looks wonderful on you, Building{span:lang=ja:\u3055\u3093},\" you say.",
            "hints": "Flattering buildings is just as nice as flattering people, as long as they're okay with it.",
            "meanings": {
