            }
        }

{
            "mnemonic": "When you meet the {tooltip:Radical:leader} {tooltip:Radical:dog} you have to {tooltip:Kanji:bow} to show your respect. Dogs are pretty great, so the leader of all dogs must be the greatest! You should bow really deeply to this one.",
            "hints": "Picture yourself bowing to the leader dog. Leader dog is so cool!",
            "meanings": {
                "Primary": "Bow",
                "Alternative": "Lay"
            },
            "kanjiReadings": {
                "readings": [
