                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u305f\u3066\u307e\u3064, \u307e\u3064, \u307b\u3046",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Dedicate yourself to doing things in your home! Haha, who are we kidding, you already did that.{splitParent}We love you, nerd. \u2661",
                "mnemonic": "You decide to {tooltip:Kanji:dedicate} yourself to your {tooltip:Reading:ho}me ({span:lang=ja:\u307b\u3046}). You don't want to be outside in the dry spring air, so you focus on home activities. You can clean the kitchen, build a shelf, or dedicate your time to your home internet system."
            }
        }

{
            "mnemonic": "You got off your {tooltip:Radical:scooter} to load some {tooltip:Radical:charcoal} onto it, when it suddenly took off to a {tooltip:Kanji:distant} place! That's some powerful charcoal.",
            "hints": "Your scooter is charcoal powered, but it looks like you put too much in there and it drove off somewhere distant without you. If you look really carefully, you can just see it, a distant speck on the horizon.",
