                    }
                ],
                "mnemonic": "\n{splitParent}The reading for this word is an exception but it's the same in Japanese as it is in English. So if you just remember it's {tooltip:Reading:Yayoi} ({span:lang=ja:\u3084\u3088\u3044}) in English, you'll remember the Japanese too!\n"
            },
            "contextSentences": [
