                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "As you know, Jourm infiltrated your village and pretended to be a large, simple farmhand, only to bring destruction down upon you. After he was done, he sat down and drank a brew with his Viking buddies.",
                "mnemonic": "A {tooltip:Kanji:brew} of alcohol is what {tooltip:Reading:Jou}rm ({span:lang=ja:\u3058\u3087\u3046}) loves most after a long day."
