{
            "mnemonic": "An altered {tooltip:Radical:bird} is a {tooltip:Kanji:crow}! They look like birds but they're bigger and darker and smarter!",
            "hints": "See that bird? Wait, that's not just a bird, it's a crow!",
            "meanings": {
                "Primary": "Crow"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u3046\u304a",
