                        "primary": true
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "How many crows have you caressed today?",
                "mnemonic": "If you can't tell just from looking at it that it's a {tooltip:Kanji:crow} and not a bird, walk up to it and {tooltip:Reading:caress} ({span:lang=ja:\u304b\u3089\u3059}) it with your hand! If it caresses you back, it's a crow! If it freaks out and flies away or pecks your face, it's a normal bird. Crows are really smart and like affection. That's what makes them so cool!"
            }
        }

{
            "mnemonic": "An {tooltip:Radical:elf} who ventures outside in {tooltip:Radical:winter} has a lot of {tooltip:Kanji:daring}. Elf ears are very, very delicate, and the winter cold can really mess them up. So if you see an elf adventuring in winter, know that that particular elf is a really daring dude.",
            "hints": "Imagine how much daring it would take to go outside in winter knowing you could be freezing your precious elf ears off.",
            "meanings": {
                "Primary": "Daring"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
                        "reading": "\u304b\u3093",
