                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u3042",
                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Do you think you have the same amount of daring as an elf going out in winter and Genghis Khan? Tell the truth.",
                "mnemonic": "The amount of {tooltip:Kanji:daring} you'd need is about equal to the amount Genghis {tooltip:Reading:Khan} ({span:lang=ja:\u304b\u3093}) had. And he was really daring!"
            }
        }

{
            "mnemonic": "Even if you {tooltip:Radical:have} a {tooltip:Radical:building}, it will eventually turn back into {tooltip:Radical:dirt}. Everything will {tooltip:Kanji:degenerate} eventually. A brick falls off here, a door comes loose there. Nothing can last forever.",
            "hints": "Imagine a time lapse video of a building degenerating.",
            "meanings": {
