                        "primary": false
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Bats attacking bats. Who will win on this season of Survivor?",
                "mnemonic": "As you {tooltip:Kanji:attack} the innocent trees with your chains and sticks, a bunch of {tooltip:Reading:bats} ({span:lang=ja:\u3070\u3064}) come flying out and attack YOU! You have your own kind of bats so now you're all trying to fell the bats with YOUR bats!"
            }
        }

{
