                    }
                ],
                "hints": "If you hire a guard to stand at your gate and conduct an inspection of your neighborhood, make sure you tell him not to use an etch a sketch!",
                "mnemonic": "His {tooltip:Kanji:inspection} is complete, but it looks like he's used an {tooltip:Reading:etch} ({span:lang=ja:\u3048\u3064}) a sketch to record all the results. That's not really helpful. If you shake it all the inspection results will disappear!"
            }
        }

{
            "mnemonic": "You're riding your {tooltip:Radical:scooter} toward your {tooltip:Radical:yurt} as fast as you can because someone is trying to get in there to {tooltip:Radical:boil} your water and you want to {tooltip:Kanji:intercept} them.",
            "hints": "If you manage to intercept them before they can go in there to boil things, you'll be able to pick up all the clothes and comic books you left on the floor. You really don't want anyone to see those.",
            "meanings": {
                "Primary": "Intercept"
            },
            "kanjiReadings": {
                "readings": [
