                    }
                ],
                "hints": "\"Let me out of this net!\" says Ra. \"You arranged and spread it out just right so I couldn't see it!\"",
                "mnemonic": "You {tooltip:Kanji:spread out} your net and {tooltip:Kanji:arrange} it just so. You expect it to catch a turkey, but instead you catch the ancient Egyptian god {tooltip:Reading:Ra} ({span:lang=ja:\u3089})."
            }
        }

{
            "mnemonic": "You have to put {tooltip:Radical:flowers} in a {tooltip:Radical:bright} place if you want them to {tooltip:Kanji:sprout}. If they're left in the shade they'll just rot.",
            "hints": "Picture your flowers sprouting out of the ground in the bright spring sun.",
            "meanings": {
                "Primary": "Sprout"
            },
            "kanjiReadings": {
