            }
        }

{
            "mnemonic": "Deep in your {tooltip:Radical:soul}, you feel like you want to pull your {tooltip:Radical:fang}s out by the {tooltip:Radical:root}, but instead you let out a loud {tooltip:Kanji:sigh}. You're one of the only people you know that has fangs, and it weighs heavily on your soul.",
            "hints": "Imagine all of the other people staring and pointing, the kids making fun of you, no one seeing you as equal. And just... sigh. Deep down, you want to get rid of your fangs, but you can't do it.",
            "meanings": {
                "Primary": "Sigh"
            },
            "kanjiReadings": {
                "readings": [
