            }
        }

{
            "mnemonic": "You meet a {tooltip:Radical:woman} whose {tooltip:Radical:mouth} is {tooltip:Radical:big} and you instantly know this is the person you want to {tooltip:Kanji:marry}.",
            "hints": "When you think about the person you want to marry, picture their mouth wide in a big, beautiful smile, a wide-open laugh. That's the lady for you, alright!",
