                },
                {
                    "ja": "\u5bb6\u3067\u306f\u5a01\u5f35\u3063\u3066\u3044\u308b\u304c\u3001\u5916\u3067\u306f\u5f93\u9806\u306b\u306a\u308b\u4eba\u306e\u3053\u3068\u3092\u300c\u5185\u5f01\u6176\u300d\u3068\u8a00\u3046\u3002",
