{
            "mnemonic": "Remember how you learned that {span:lang=ja:\u51f9\u51f8} means \"uneven?\" Well spin something uneven around and it's still {tooltip:Vocabulary:uneven}! Just kinda backwards, just like this word!",
            "hints": "",
            "meanings": {
                "Primary": "Uneven",
                "Alternatives": "Rough, Rugged",
                "Word Type": "noun, \u3059\u308b verb, \u306a adjective, \u306e adjective"
            },
            "vocabReadings": {
                "readings": [
                    {
                        "primary": true,
                        "reading": "\u3067\u3053\u307c\u3053"
