                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Wearing nothing but shoes is also really uncomfortable too, so it's actually part of the criminal's punishment. They don't seem to know that though.",
                "mnemonic": "The {tooltip:Kanji:criminal} is only wearing {tooltip:Reading:shoe}s ({span:lang=ja:\u3057\u3085\u3046}). They're completely naked otherwise. They have to wear shoes because the mouth jail would be too slippery for them to stand otherwise."
            }
        }

{
            "mnemonic": "You ate some {tooltip:Radical:grain}s that made you so {tooltip:Radical:sick} it feels like a {tooltip:Radical:knife} is stabbing in your guts and all your poop is falling out. This is called {tooltip:Kanji:diarrhea}. Everyone's had diarrhea before, so you should know this feeling by now.",
            "hints": "Imagine back to the last time you ate something bad and it gave you diarrhea. It felt like someone was sticking you with a knife, didn't it?",
            "meanings": {
                "Primary": "Diarrhea",
                "Alternative": "Diarrhoea"
            },
            "kanjiReadings": {
                "readings": [
                    {
                        "name": "On\u2019yomi",
