            }
        }

{
            "mnemonic": "Have you heard the tale of the {tooltip:Radical:woman} who fell in love with a {tooltip:Radical:coat rack} during a full {tooltip:Radical:moon} and made him her {tooltip:Kanji:groom}? It's a true story! She even had a wedding ceremony and had more coat racks sitting in the grooms side. The moon will make people do craaaazy things.",
            "hints": "Imagine what it would be like to fall in love with a coat rack and make it YOUR groom.",
            "meanings": {
                "Primary": "Groom"
            },
            "kanjiReadings": {
                "readings": [
