                    },
                    {
                        "name": "Kun\u2019yomi",
                        "reading": "\u3080\u3053",
                        "primary": true
                    },
                    {
                        "name": "Nanori",
                        "reading": "None",
                        "primary": false
                    }
                ],
                "hints": "Could you love a moose coat enough to marry it? ",
                "mnemonic": "The best part of the story is that the only coat on the coat rack {tooltip:Kanji:groom} was a {tooltip:Reading:moo}se {tooltip:Reading:co}at ({span:lang=ja:\u3080\u3053}). So the groom was a really skinny stick with a giant moose hair coat hanging down it. "
            }
        }

{
            "mnemonic": "This {tooltip:Radical:cage} is full of {tooltip:Radical:flowers} on the {tooltip:Radical:right} side to {tooltip:Kanji:hide} the fact that you're in here too.",
            "hints": "You don't really want to be in this cage, but there were some things you didn't want to do today, so you hid. Luckily these flowers block the right side of the cage and hide you completely.",
            "meanings": {
                "Primary": "Hide"
            },
